		["{npc:658}: read the {quest:98581}"] = "{npc:658} : lisez {quest:98581}",
		["{npc:6806}, inside"] = "{npc:6806}, à l'intérieur",
		["{npc:713}, next to {npc:658}"] = "{npc:713}, à côté de {npc:658}",
		["{npc:714}'s camp is at the west end of the valley. {item:10438} lies in the snow south of it, his Chest by the troll cave and his Bucket of Bolts east of the cave: grab them as you pass."] = "Le camp de {npc:714} est à l'extrémité ouest de la vallée. {item:10438} est dans la neige au sud du camp, le Coffre de Felix près de la grotte des trolls et le Seau de boulons de Felix à l'est de la grotte : ramassez-les en passant.",
		["{npc:786} and {npc:12738} camp at the south-west edge of the valley, below the troll cave."] = "{npc:786} et {npc:12738} campent au bord sud-ouest de la vallée, sous la grotte des trolls.",
		["{npc:808} is inside the troll cave east of {npc:786}'s camp, not on the hill above it: go in at the mouth and follow the tunnel to the back."] = "{npc:808} est à l'intérieur de la grotte des trolls à l'est du camp de {npc:786}, pas sur la colline au-dessus : entrez par l'ouverture et suivez le tunnel jusqu'au fond.",
		["{npc:836}, inside {area:77}; below ground"] = "{npc:836}, dans {area:77} ; sous terre",
		["{npc:837}, inside {area:77}"] = "{npc:837}, à l'intérieur de {area:77}",
		["{npc:837}, the priest trainer"] = "{npc:837}, le maître des prêtres",
		["{npc:8416}, at the door on the way out; inside"] = "{npc:8416}, à la porte en sortant ; à l'intérieur",
		["{npc:8416}, by the door of {area:77}; inside"] = "{npc:8416}, près de la porte de {area:77} ; à l'intérieur",
		["{npc:8508}, on the dock"] = "{npc:8508}, sur le quai",
		["{npc:895}, the hunter trainer"] = "{npc:895}, le maître des chasseurs",
		["{npc:912}, the warrior trainer; inside"] = "{npc:912}, le maître des guerriers ; à l'intérieur",
		["{npc:916}, the rogue trainer"] = "{npc:916}, le maître des voleurs",
		["{npc:926}, the paladin trainer"] = "{npc:926}, le maître des paladins",
		["{object:660964}, by the mailbox in {object:171524}"] = "{object:660964}, près de la boîte aux lettres de {object:171524}",
		["{quest:1688}: her choker and The Binding are on {zone:1436}'s east-Elwynn loop"] = "{quest:1688} : son collier et Le Lien se font sur la boucle est d'Elwynn de {zone:1436}",
		["{zone:1453} flight master"] = "Maître de vol de {zone:1453}",
} end)()
t.guides["forever/alliance/gnome/01-dun-morogh"] = (function() return {
		["Back east through {area:131}: {npc:1252} by Eric's campfire takes the {quest:287} report, and {npc:1269} the cogs and gears. The Shaman quest here waits for level 10: a Shaman still short of it finishes on the Ice Claw Bears (7-8), Snow Leopards and Large Crag Boars in the fields just south of {area:131}."] = "Retour vers l'est par {area:131} : {npc:1252}, près du feu de camp d'Eric, reçoit le rapport de {quest:287}, et {npc:1269} les rouages et engrenages. La quête de chaman ici demande le niveau 10 : un chaman qui ne l'a pas encore le termine sur les Ours Griffeglace (7-8), Léopards des neiges et Grands sangliers des rochers dans les champs juste au sud de {area:131}.",
		["Back north to {area:77} on the way to the tunnel: {npc:2756} stands by {npc:8416} at its door. Gozwin's camp is in the hills just north-west; the {npc:269075} (level 6) prowls around it."] = "Revenez vers le nord jusqu'à {area:77} en allant au tunnel : {npc:2756} se tient près de {npc:8416} à sa porte. Le camp de Gozwin est dans les collines juste au nord-ouest ; le {npc:269075} (niveau 6) rôde autour.",
		["Back north to {npc:257808}'s camp above the tunnel. {npc:257808} gives you the {item:6636}. Climb to the peak above his camp, drink the Sapta beside the Spirit Stone and defeat the {npc:5893}, then place its {item:6655} in the {object:61934}, atop the Shrine of Eternal Flame."] = "Retour au nord jusqu'au camp de {npc:257808}, au-dessus du tunnel. {npc:257808} vous donne {item:6636}. Montez au sommet au-dessus de son camp, buvez le Sapta à côté de la Pierre de l'esprit et vainquez {npc:5893}, puis placez sa {item:6655} dans {object:61934}, au sommet de l'autel de la Flamme éternelle.",
		["Back through the tunnel to {npc:257597}' cave above the farm, then west along the road to {zone:1455}."] = "Repassez le tunnel jusqu'à la grotte de {npc:257597}, au-dessus de la ferme, puis suivez la route vers l'ouest jusqu'à {zone:1455}.",
		["Back to the tunnel post"] = "Retour au poste du tunnel",
		["Back to the {area:136}, the wendigo cave south-west of {area:131} where {npc:271546} camps. Flintfire's shipments lie on the cave floor, {npc:278166} is missing deep inside, and {quest:98326} (level 9) keeps the {item:280426} at the back.\nCareful: Wendigos, Elder Wendigos and Wendigo Shamans (up to level 8) stand close together inside the cave, so fights easily pull several at once; drawing them out one at a time with ranged attacks avoids this."] = "Retour à {area:136}, la grotte des wendigos au sud-ouest de {area:131} où campe {npc:271546}. Les cargaisons de Flintfire jonchent le sol de la grotte, {npc:278166} a disparu tout au fond, et {quest:98326} (niveau 9) garde le {item:280426} au fond.\nAttention : les Wendigos, Sages wendigos et Wendigos chamans (jusqu'au niveau 8) se tiennent serrés dans la grotte, les combats en attirent donc facilement plusieurs à la fois ; attirez-les un par un avec des attaques à distance pour l'éviter.",
		["Back to the {area:925}"] = "Retour à {area:925}",
		["Back to {area:77}"] = "Retour à {area:77}",
		["Back to {npc:257446} in {area:77}. He gives you the {item:6635}: take the rubble-marked path that climbs west from the south of the valley to the Spirit Stone on the ridge, drink the Sapta beside it and speak to the {npc:5891}, then bring its {item:6656} back to Teo."] = "Retournez voir {npc:257446} à {area:77}. Il vous donne {item:6635} : prenez le chemin bordé d'éboulis qui monte vers l'ouest depuis le sud de la vallée jusqu'à la Pierre de l'esprit sur la crête, buvez le Sapta à côté et parlez à {npc:5891}, puis rapportez son {item:6656} à Teo.",
		["Back to {npc:257597}"] = "Retour auprès de {npc:257597}",
		["Below ground"] = "Sous terre",
		["Brewnall: kill these as you meet them"] = "Brassetout : tuez-les au passage",
		["Catch {npc:13016}"] = "Attrapez : {npc:13016}",
		["Crag Boars and Young Black Bears roam the fields from Rumbleshot's camp north-east to {area:131} and the depot: kill them on the walk back."] = "Les Sangliers des rochers et les Jeunes ours noirs parcourent les champs depuis le camp de Rumbleshot au nord-est jusqu'à {area:131} et au dépôt : tuez-les sur le chemin du retour.",
		["Druid trainer"] = "Maître des druides",
		["East along the hills to the mine at the north end of the loch: the Miners' League crates sit in its tunnels, among more Tunnel Rats. Shamans: the Tunnel Rat Geomancers (level 12-13) here carry the {item:5026}.\nCareful: the Tunnel Rat Geomancers (12-13) cast from range in the narrow tunnels: pull them one at a time."] = "À l'est le long des collines jusqu'à la mine au nord du loch : les caisses de la Ligue des mineurs sont dans ses tunnels, parmi d'autres Rats des tunnels. Chamans : les Géomanciens Rat des tunnels (niveau 12-13) ici portent le {item:5026}.\nAttention : les Géomanciens Rat des tunnels (12-13) lancent des sorts à distance dans les tunnels étroits : attirez-les un par un.",
		["East back into {object:171524}: the {area:2257} leaves from its east end. Ride it to {zone:1453}."] = "Revenez vers l'est jusqu'à {object:171524} : le {area:2257} part de son extrémité est. Prenez-le jusqu'à {zone:1453}.",
		["East from the {object:32372} into {object:171524}: the {object:660964} lie by its mailbox. From here the guide goes once round the city: north to the {object:32383}, west to the {object:32362}, south through the Commons to the {object:171709}, east through the {object:32359} and back to {object:171524} for the tram."] = "À l'est de la {object:32372}, vers {object:171524} : les {object:660964} se trouvent près de sa boîte aux lettres. D'ici, le guide fait une fois le tour de la ville : au nord vers {object:32383}, à l'ouest vers {object:32362}, au sud par la Grande Cour jusqu'à {object:171709}, à l'est par {object:32359} et retour à {object:171524} pour le tram.",
		["East to the {object:32359}: the warrior trainers and {npc:11865} in the {object:32390}, the hunter trainers beside it."] = "À l'est vers {object:32359} : les maîtres des guerriers et {npc:11865} dans {object:32390}, les maîtres des chasseurs juste à côté.",
		["Farsen camps on the ridge overlooking the {area:134} from the west. Talk to him for his farsight."] = "Farsen campe sur la crête qui domine la {area:134} à l'ouest. Parlez-lui pour sa vision lointaine.",
		["Feather Charms, from the Frostmane Novices"] = "Charmes de plume, sur les Novices Frostmane",
		["Firewood"] = "Bois de chauffage",
		["Follow the road east past the depot to {area:138}."] = "Suivez la route vers l'est après le dépôt jusqu'au {area:138}.",
		["Follow the road north-east from {area:131} to the depot below the {zone:1455} road."] = "Suivez la route vers le nord-est depuis {area:131} jusqu'au dépôt, sous la route de {zone:1455}.",
		["Follow the road north-east from {area:131} to the depot: the whole east of {zone:1426} is one sweep from here."] = "Suivez la route vers le nord-est depuis {area:131} jusqu'au dépôt : tout l'est de {zone:1426} se fait d'une traite à partir d'ici.",
		["Follow the road through the tunnel and north-east to {area:131}. Start outside: {npc:1252} and Eric's campfire are in front of the {area:2102}.\n{npc:1872} works the forge west of the distillery.\nThen go in: {npc:6806}, the innkeeper, {npc:1226} and {npc:1267}. {npc:1699}'s {skill:185} lesson waits for the return with the ribs, when the copper is there for it."] = "Suivez la route à travers le tunnel puis vers le nord-est jusqu'à {area:131}. Commencez dehors : {npc:1252} et le feu de camp d'Eric sont devant la {area:2102}.\n{npc:1872} travaille à la forge à l'ouest de la brasserie.\nEntrez ensuite : {npc:6806}, l'aubergiste, {npc:1226} et {npc:1267}. La leçon de {skill:185} de {npc:1699} attend le retour avec les côtes, quand vous aurez le cuivre nécessaire.",
		["From the {object:28027} south-west to {object:2098}: {npc:1646}'s compass is in his old house in {zone:1436}, on the way. The flight master and the {object:2096} are south of the square."] = "Depuis {object:28027}, au sud-ouest jusqu'à {object:2098} : la boussole de {npc:1646} est dans son ancienne maison en {zone:1436}, sur le chemin. Le maître de vol et {object:2096} sont au sud de la place.",
		["Frostmane Troll Whelps fill the slopes south and east of {npc:786}'s camp."] = "Des Jeunes trolls Frostmane ({npc:706}) peuplent les pentes au sud et à l'est du camp de {npc:786}.",
		["Gretchen camps just outside the {area:136}, the wendigo cave south-west of {area:131}. The den comes after {area:137}, once its level 8 Elder Wendigos and Shamans are no longer above you."] = "Gretchen campe juste devant la {area:136}, la grotte des wendigos au sud-ouest de {area:131}. La tanière viendra après {area:137}, quand ses Sages wendigos et Chamans de niveau 8 ne seront plus au-dessus de vous.",
		["Head back out of {zone:1455} and east along the road to {area:212}. {npc:6177} lies dead by its shore: use the {item:6866} on him. The Dark Iron Spies sneaking around the lake carry the script."] = "Ressortez de {zone:1455} et suivez la route vers l'est jusqu'au {area:212}. {npc:6177} gît, mort, sur sa rive : utilisez le {item:6866} sur lui. Les Espions Sombrefer qui se faufilent autour du lac portent le texte.",
		["Heal and fortify {npc:12427}"] = "Soignez et fortifiez {npc:12427}",
		["Ice Claw Bears, Elder Crag Boars and Snow Leopards roam the hills around the lake and {area:137}."] = "Les Ours Griffeglace, les Anciens sangliers des rochers et les Léopards des neiges parcourent les collines autour du lac et de {area:137}.",
		["Iceclaw Bear Pendants, from the Frostmane Troll Whelps on the slopes above the camp"] = "Pendentifs d'ours griffeglace ({item:264356}), sur les Jeunes trolls Frostmane ({npc:706}) des pentes au-dessus du camp",
		["Inside {area:77}"] = "À l'intérieur de {area:77}",
		["Kill the Crag Boars on the way: their ribs drop before you have {npc:1267}'s quest and count toward it. Back in the distillery: {npc:1699} teaches {skill:185}, then the ribs go to {npc:1267}."] = "Tuez les Sangliers des rochers en chemin : leurs côtes tombent avant que vous ayez la quête de {npc:1267} et comptent pour elle. De retour à la brasserie : {npc:1699} enseigne la {skill:185}, puis les côtes vont à {npc:1267}.",
		["Last: some classes' trainers stand outside"] = "Pour finir : les maîtres de certaines classes se tiennent dehors",
		["Leave {zone:1453} by the main gate and follow the road south to {area:87}: east Elwynn comes before {zone:1436}."] = "Quittez {zone:1453} par la grande porte et suivez la route vers le sud jusqu'à {area:87} : l'est d'Elwynn passe avant {zone:1436}.",
		["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {zone:1436}: fill {item:7207} at its base."] = "Quittez {zone:1453} par la porte principale. La cascade du {quest:1861} se trouve au sud-ouest des portes, sur le chemin de la {zone:1436} à l'ouest : remplissez la {item:7207} à son pied.",
		["Leper Gnomes wander the {area:133} road north of {area:137} and carry the cogs and gears. {area:135} comes next, in the hills south-west of the village.\nCareful: the Leper Gnomes (8-10) walk the road in twos and threes, and many players died here: pull them one at a time."] = "Les Gnomes lépreux errent sur la route de {area:133} au nord de {area:137} et portent les rouages et engrenages. {area:135} vient ensuite, dans les collines au sud-ouest du village.\nAttention : les Gnomes lépreux (8-10) parcourent la route par deux ou trois, et beaucoup de joueurs sont morts ici : attirez-les un par un.",
		["Level 4 spells"] = "Sorts de niveau 4",
		["North of the {object:32372}: {npc:258098}, the shaman trainer, stands at the south end of the {object:32383}, the rogue and warlock trainers and {npc:6120} just north of him."] = "Au nord de la {object:32372} : {npc:258098}, le maître des chamans, se tient à l'extrémité sud de {object:32383}, les maîtres des voleurs et des démonistes et {npc:6120} juste au nord de lui.",
		["North through the hills west of the road to {npc:1343} at the {area:925}. The Tunnel Rat kobolds dig in the hills on the way; Elder Black Bears, Mountain Boars and Forest Lurkers roam the same ground."] = "Vers le nord à travers les collines à l'ouest de la route, jusqu'à {npc:1343} à {area:925}. Les kobolds Rat des tunnels creusent dans les collines en chemin ; des Anciens ours noirs, des Sangliers des montagnes et des Rôdeuses des forêts parcourent les mêmes terres.",
		["North up the road to {area:144}. {npc:1340} walks the road through town, {npc:1963} stands outside the {area:2101}, {npc:1681} on the east side of town; {npc:1572} keeps the gryphons."] = "Remontez la route vers le nord jusqu'à {area:144}. {npc:1340} parcourt la route qui traverse la ville, {npc:1963} se tient devant {area:2101}, {npc:1681} du côté est de la ville ; {npc:1572} s'occupe des griffons.",
		["On the road back west to {zone:1455}."] = "Sur la route du retour vers l'ouest, vers {zone:1455}.",
		["Ragged Young Wolves roam the snow just south of {area:77}."] = "Les Jeunes loups décharnés rôdent dans la neige juste au sud de {area:77}.",
		["Ride the tram to {zone:1453}: {npc:13018} waits on the {zone:1453} platform. {npc:5413} stands in the {object:28027}, just outside the tram."] = "Prenez le tram jusqu'à {zone:1453} : {npc:13018} attend sur le quai de {zone:1453}. {npc:5413} se tient dans {object:28027}, juste à la sortie du tram.",
		["Rockjaw Ambushers by {area:212}, north of the quarry, and Rockjaw Backbreakers further east drop the {quest:95214}. Dark Iron Spies sneak around the lake shore east of the quarry; one of them drops the {item:274268}."] = "Les Embusqués Mâcheroc près du {area:212}, au nord de la carrière, et les Backbreakers Mâcheroc plus à l'est lâchent la {quest:95214}. Des Espions Sombrefer se faufilent sur la rive du lac à l'est de la carrière ; l'un d'eux lâche la {item:274268}.",
		["Rockjaw Skullthumpers, Bonesnappers and Ambushers share the quarry and the slopes north of it; the Ambushers drop the {item:268548}."] = "Les Brise-crâne, les Brise-os et les Embusqués Mâcheroc se partagent la carrière et les pentes au nord de celle-ci ; les Embusqués laissent tomber {item:268548}.",
		["Rockjaw Troggs and Burly Rockjaw Troggs dig all over the valley floor south of {area:77}."] = "Les Troggs Mâcheroc et les Troggs Mâcheroc forcenés creusent partout dans le fond de la vallée, au sud de {area:77}.",
		["Sit by Eric's campfire (type /sit) and wait for the buff. With a profession learned, Eric also offers its Camping 101, which its trainer takes: blacksmithing with {npc:1241} and {skill:129} with {npc:2326} in {area:131}, mining and engineering at {area:189}."] = "Asseyez-vous près du feu de camp d'Eric (tapez /asseoir) et attendez l'amélioration. Si vous avez appris un métier, Eric propose aussi le Camping 101 correspondant, que rend son maître : forge avec {npc:1241} et {skill:129} avec {npc:2326} à {area:131}, minage et ingénierie au {area:189}.",
		["Small Crag Boars graze around {npc:714}'s camp and along the west side of the valley."] = "Les Petits sangliers des rochers paissent autour du camp de {npc:714} et le long du côté ouest de la vallée.",
		["Snow Leopards and boars roam the snow between the ranch and the quarry. Blacksmiths: Copper Bars come from smelting {item:2770} or the trade vendors."] = "Les Léopards des neiges et les sangliers parcourent la neige entre la ferme et la carrière. Forgerons : les Barres de cuivre s'obtiennent en fondant du {item:2770} ou auprès des marchands d'artisanat.",
		["South down the road past the tunnel post into {area:923}: the Stonesplinter Seers (level 13-14) stand among the troggs in its middle. Stay out of the far south end, where Shamans and Bonesnappers (level 15-16) camp, and keep clear of Headsplitter (15) on his walk. The Seers come with other troggs and cast from range: pull one at a time."] = "Descendez la route vers le sud après le poste du tunnel jusqu'à {area:923} : les Prophètes Brisepierre (niveau 13-14) se tiennent parmi les troggs au milieu. Évitez l'extrémité sud, où campent Chamans et Brise-os (niveau 15-16), et tenez-vous à l'écart de Fendcrâne (15) lors de sa ronde. Les Prophètes sont accompagnés d'autres troggs et lancent des sorts à distance : attirez-les un par un.",
		["South down the road to {area:144}, finishing the ears, meat and ichor on the way. {npc:1340} walks the road through town."] = "Descendez la route vers le sud jusqu'à {area:144}, en terminant les oreilles, la viande et l'ichor en chemin. {npc:1340} arpente la route qui traverse la ville.",
		["South through the Commons: {npc:1274} stands in the {object:171709} with King Magni."] = "Au sud par la Grande Cour : {npc:1274} se tient dans {object:171709} avec le roi Magni.",
		["Stonesplinter troggs"] = "Troggs Brisepierre",
		["The Fire Spirit Stone"] = "La pierre de l'esprit du feu",
		["The Scalding Mornbrew lasts five minutes: go straight north to {npc:836} inside {area:77}."] = "Le Thé brûlant de Durnan dure cinq minutes : allez droit au nord jusqu'à {npc:836}, à l'intérieur de {area:77}.",
		["The boars"] = "Les sangliers",
		["The firewood lies in the snow around the frozen lake by the refuge."] = "Le bois de chauffage est dans la neige autour du lac gelé, près du refuge.",
		["The paladin, priest and mage trainers are in the {object:32386}, in the {object:32362}."] = "Les maîtres des paladins, des prêtres et des mages sont dans {object:32386}, dans {object:32362}.",
		["The pilots stand at the depot; {npc:1269} is on the road back west, north of {area:131}."] = "Les pilotes se tiennent au dépôt ; {npc:1269} est sur la route du retour vers l'ouest, au nord de {area:131}.",
		["The quarry lies just east of Farsen's ridge."] = "La carrière se trouve juste à l'est de la crête de Farsen.",
		["The quarry troggs"] = "Les troggs de la carrière",
		["The three rifles lie in the snow around the frozen lake by the refuge. Minor Ice Elementals drift around the lake and along the way: kill them as you go for {quest:99160}.\nFinish off the Minor Ice Elementals around the small lake just west of the refuge if you are still short."] = "Les trois fusils reposent dans la neige autour du lac gelé près du refuge. Des Élémentaires de glace mineurs dérivent autour du lac et le long du chemin : tuez-les en passant pour {quest:99160}.\nAchevez les Élémentaires de glace mineurs autour du petit lac juste à l'ouest du refuge s'il vous en manque encore.",
		["The troggs"] = "Les troggs",
		["The troll cave"] = "La grotte des trolls",
		["The tunnel"] = "Le tunnel",
		["The tunnel post"] = "Le poste du tunnel",
		["The west hills and the {area:925}"] = "Les collines de l'ouest et {area:925}",
		["The {area:133} road"] = "La route de {area:133}",
		["The {area:2257}"] = "{area:2257}",
		["The {item:2676} grows in baskets up on {area:802}, the snowy slope north of the road between {area:131} and Brewnall: climb from the road west of {area:131}. The Frostmane Seers camped on the ridge drop it too."] = "L'{item:2676} pousse dans des paniers sur la {area:802}, la pente enneigée au nord de la route entre {area:131} et Brassetout : grimpez depuis la route à l'ouest de {area:131}. Les Prophètes Frostmane installés sur la crête en laissent aussi tomber.",
		["The {item:6652}"] = "{item:6652}",
		["The {item:6775}"] = "{item:6775}",
		["The {object:176785} sits next to {npc:271546}, south of the {area:136}."] = "La {object:176785} se trouve à côté de {npc:271546}, au sud de la {area:136}.",
		["The {object:269} in the basement"] = "{object:269}, au sous-sol",
		["The {object:270} in the distillery; below ground"] = "Le {object:270} dans la brasserie ; sous terre",
		["Tram to {zone:1453}"] = "Tram pour {zone:1453}",
		["Upstairs"] = "À l'étage",
		["West from the {object:32383} into the {object:32362}: {npc:5149}, {npc:6179} and {npc:6178} are in the {object:32386}, Tiza and Muiredon on its upper floor: the stairs up start just north-east of {npc:5149}. {npc:6175}, a beggar, wanders the city. He asks for ten {item:2589}: the troggs and trolls of {zone:1426} drop it, and the Auction House sells it."] = "À l'ouest de {object:32383}, entrez dans la {object:32362} : {npc:5149}, {npc:6179} et {npc:6178} sont dans {object:32386}, Tiza et Muiredon à son étage : l'escalier commence juste au nord-est de {npc:5149}. {npc:6175}, un mendiant, erre dans la ville. Il demande dix {item:2589} : les troggs et les trolls de {zone:1426} en laissent tomber, et l'hôtel des ventes en vend.",
		["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Pendant que vous y êtes : apprenez le maniement des bâtons auprès de {npc:11867} ({object:2096}, 10 pièces d'argent) ; l'arme de mêlée d'un Chasseur vaut surtout par ses caractéristiques, et les armes à deux mains en portent le plus.",
		["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "Pendant que vous y êtes : apprenez le maniement des bâtons auprès de {npc:11867} ({object:2096}, 10 pièces d'argent) ; un bâton apporte plus de caractéristiques de sorts qu'une arme à une main pendant la progression.",
		["While you're here: learn Swords from {npc:11867} ({object:2096}, 10 silver); a sword in the main hand levels a Rogue steadily."] = "Pendant que vous y êtes : apprenez le maniement des épées auprès de {npc:11867} ({object:2096}, 10 pièces d'argent) ; une épée en main droite fait progresser un Voleur régulièrement.",
		["While you're here: learn {spell:197} from {npc:11865} ({object:32359}, 10 silver); two-handers level a Paladin fastest."] = "Pendant que vous y êtes : apprenez {spell:197} auprès de {npc:11865} ({object:32359}, 10 pièces d'argent) ; les armes à deux mains font progresser un Paladin le plus vite.",
		["While you're here: learn {spell:197} from {npc:11865} ({object:32359}, 10 silver); two-handers level a Warrior fastest."] = "Pendant que vous y êtes : apprenez {spell:197} auprès de {npc:11865} ({object:32359}, 10 pièces d'argent) ; les armes à deux mains font progresser un Guerrier le plus vite.",
		["While you're here: learn {spell:199} from {npc:11865} ({object:32359}, 10 silver); two-handers level a Warrior fastest."] = "Pendant que vous y êtes : apprenez {spell:199} auprès de {npc:11865} ({object:32359}, 10 pièces d'argent) ; les armes à deux mains font progresser un Guerrier le plus vite.",
		["While you're here: learn {spell:202} from {npc:11867} ({object:2096}, 10 silver); two-handers level a Paladin fastest."] = "Pendant que vous y êtes : apprenez {spell:202} auprès de {npc:11867} ({object:2096}, 10 pièces d'argent) ; les armes à deux mains font progresser un Paladin le plus vite.",
		["While you're here: learn {spell:202} from {npc:11867} ({object:2096}, 10 silver); two-handers level a Warrior fastest."] = "Pendant que vous y êtes : apprenez {spell:202} auprès de {npc:11867} ({object:2096}, 10 pièces d'argent) ; les armes à deux mains font progresser un Guerrier le plus vite.",
		["You start in front of {area:77}, the stone hall at the north end of the valley. {npc:658} waits outside the door."] = "Vous commencez devant {area:77}, la salle de pierre au nord de la vallée. {npc:658} attend devant la porte.",
		["Young wolves"] = "Jeunes loups",
		["talk to the trainer"] = "parlez au maître",
