t.guides["forever/alliance/human/01-elwynn-forest"] = (function() return {
		["\"Auntie\" Bernice Stonefield"] = "\"Tatie\" Bernice Stonefield",
		["Back to {npc:6122}. Use the {item:6928} at the summoning circle in the {object:2164}'s cellar and defeat the voidwalker it calls."] = "Retournez voir {npc:6122}. Utilisez l'{item:6928} sur le cercle d'invocation dans la cave de l'{object:2164} et vainquez le marcheur du Vide qu'elle appelle.",
		["Back to {zone:1429}"] = "Retour dans la {zone:1429}",
		["Billy plays in the {area:64}, east of the mine."] = "Billy joue dans les {area:64}, à l'est de la mine.",
		["Chunks of Boar Meat"] = "Morceaux de viande de sanglier",
		["Class trainer"] = "Maître de classe",
		["Crystal Kelp Fronds"] = "Feuilles de Varech cristallin",
		["Defias Rogue Wizards camp on the shores of {area:86}; they drop the Red Linen Bandanas too. {object:56} lies in the murloc village on the north-east shore.\nCareful: the Rogue Wizards cast from range and a {npc:6866} (10) walks the shore with them: pull them one at a time."] = "Les Sorciers-voleurs défias campent sur les rives du {area:86} ; ils laissent aussi tomber les Masques rouges en lin. Le {object:56} gît dans le village murloc de la rive nord-est.\nAttention : les Sorciers-voleurs lancent des sorts à distance et un {npc:6866} (10) arpente la rive avec eux : attirez-les un par un.",
		["Defias Thugs camp in the clearing east of the Abbey and along the valley's east side."] = "Les Nervis défias campent dans la clairière à l'est de l'abbaye et le long du flanc est de la vallée.",
		["Druid trainer"] = "Maître des druides",
		["Follow the hills south to the tower, on the road west."] = "Suivez les collines vers le sud jusqu'à la tour, sur la route de l'ouest.",
		["Follow the hills south to the tower."] = "Suivez les collines vers le sud jusqu'à la tour.",
		["Follow the road east past the {area:91} to the bridge. Finish the Prowlers and Young Forest Bears around the river south of it."] = "Suivez la route vers l'est au-delà de la {area:91} jusqu'au pont. Achevez les Rôdeurs et les Jeunes ours des forêts autour de la rivière, au sud du pont.",
		["Follow the road north from {area:87} into {zone:1453}. {npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}; she gives you a flask for the {quest:1861} waterfall."] = "Suivez la route vers le nord depuis {area:87} jusqu'à {zone:1453}. {npc:5497} se tient dans le Sanctuaire du Sorcier, la tour du {object:2101} ; elle vous remet une flasque pour la cascade du {quest:1861}.",
		["Follow the road north from {area:87} into {zone:1453}. {npc:6122} waits in the cellar of the {object:2164}, in the {object:2101}."] = "Suivez la route vers le nord depuis {area:87} jusqu'à {zone:1453}. {npc:6122} attend dans la cave de l'{object:2164}, dans le {object:2101}.",
		["Follow the road south out of the valley to {area:87}. {npc:240} stands outside the smithy on the west side of the road, {npc:241} by the road south of it, and {npc:295} and {npc:253} in the Lion's Pride Inn across the road."] = "Suivez la route vers le sud pour sortir de la vallée jusqu'à {area:87}. {npc:240} se tient devant la forge, du côté ouest de la route, {npc:241} au bord de la route au sud de celle-ci, et {npc:295} et {npc:253} dans l'auberge de la Fierté du lion, de l'autre côté de la route.",
		["Follow the road south out of {area:87} to the {area:64}. {npc:251} waits by the house."] = "Suivez la route vers le sud en sortant de {area:87} jusqu'aux {area:64}. {npc:251} attend près de la maison.",
		["Follow the road south to the {area:120}, on the way into {zone:1436}. {npc:963} stands outside the barracks; {npc:955} stands inside. He has {quest:91738} only while you carry the {item:247824}: talk to him and it goes straight to the hand-in."] = "Suivez la route vers le sud jusqu'à {area:120}, à l'entrée de {zone:1436}. {npc:963} se tient devant la caserne ; {npc:955} est à l'intérieur. Il ne propose {quest:91738} que tant que vous portez le {item:247824} : parlez-lui et la quête passe directement au rendu.",
		["Follow the road west back to {area:87}; {npc:6306} stands on the lake shore before town. {npc:377} (priests), {npc:328} (mages) and {npc:917} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "Suivez la route vers l'ouest pour revenir à {area:87} ; {npc:6306} se tient sur la rive du lac avant la ville. {npc:377} (prêtres), {npc:328} (mages) et {npc:917} (voleurs) se tiennent à l'étage de l'auberge : montez par l'escalier intérieur, la flèche ne distingue pas les étages.",
		["Fun with Elementals: {npc:248464}"] = "Les Joyeux Élémentaires : {npc:248464}",
		["He stands by the river west of the farm."] = "Il se tient près de la rivière, à l'ouest de la ferme.",
		["Head back out through {area:87} and east along the road to the {area:62}. {npc:881} (level 9) stands by its farmhouse."] = "Repassez par {area:87} et allez vers l'est le long de la route jusqu'à {area:62}. {npc:881} (niveau 9) se tient près de la ferme.",
		["Head east out of {area:87} along the lake shore. {npc:383} stands on the shore north-east of town."] = "Sortez de {area:87} vers l'est en longeant la rive du lac. {npc:383} se tient sur la rive au nord-est de la ville.",
		["Heal and fortify {npc:12423}"] = "Soignez et fortifiez {npc:12423}",
		["If you skipped {quest:91740}, grind here to level 8.85 to stay on the route's plan."] = "Si vous avez passé {quest:91740}, tuez des monstres ici jusqu'au niveau 8.85 pour suivre le plan de l'itinéraire.",
		["If you skipped {quest:91775}, grind here to level 8.39 to stay on the route's plan."] = "Si vous avez passé {quest:91775}, tuez des monstres ici jusqu'au niveau 8.39 pour suivre le plan de l'itinéraire.",
		["Inside"] = "À l'intérieur",
		["Inside {area:34}"] = "Dans la {area:34}",
		["It lies by the river north-west of the logging camp."] = "Il gît près de la rivière, au nord-ouest du camp de bûcherons.",
		["Large Candles"] = "Grandes bougies",
		["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {zone:1436}: fill {item:7207} at its base."] = "Quittez {zone:1453} par la porte principale. La cascade du {quest:1861} se trouve au sud-ouest des portes, sur le chemin de la {zone:1436} à l'ouest : remplissez la {item:7207} à son pied.",
		["Level 8.39"] = "Niveau 8.39",
		["Level 8.85"] = "Niveau 8.85",
		["Lost Books: Kobold Miners and Tunnelers"] = "Livres perdus : Mineurs kobolds et Tunneliers kobolds",
		["Mages: {npc:198}, the mage trainer, stands upstairs in the Abbey: take the stairs inside, the arrow cannot tell the floors apart."] = "Mages : {npc:198}, le maître des mages, se tient à l'étage de l'abbaye : montez par l'escalier intérieur, la flèche ne distingue pas les étages.",
		["Murlocs and Murloc Streamrunners hold the east shore; the Junk Piles lie in their camp. Careful: the murlocs stand close together, so a fight easily pulls two or three at once: pull them one at a time from the edge of the camp, and don't chase one into the next group."] = "Les Murlocs et les Ruisseliers murlocs occupent la rive est ; les Tas de camelote se trouvent dans leur camp. Attention : les murlocs sont proches les uns des autres, un combat en attire donc facilement deux ou trois à la fois : attirez-les un par un depuis le bord du camp, et ne poursuivez pas un murloc jusque dans le groupe suivant.",
		["North-east of the logging camp. Defias Rogue Wizards camp on the shores of the lake.\nCareful: the Rogue Wizards cast from range and a {npc:6866} (10) walks the shore with them: pull them one at a time."] = "Au nord-est du camp de bûcherons. Les Sorciers-voleurs défias campent sur les rives du lac.\nAttention : les Sorciers-voleurs lancent des sorts à distance et un {npc:6866} (10) arpente la rive avec eux : attirez-les un par un.",
		["Painted Gnoll Armbands"] = "Brassards peints de gnoll",
		["Red Burlap Bandanas"] = "Masques rouges",
		["Red Linen Bandanas"] = "Masques rouges en lin",
		["Riverpaw Runts and Outrunners hold the hills south of the garrison, along the {zone:1436} border."] = "Des Rivepatte chétifs et des Estafettes Rivepatte tiennent les collines au sud de la garnison, le long de la frontière de {zone:1436}.",
		["Riverpaw gnolls camp in the hills west of {area:86}; the {quest:91725} lie in their camps."] = "Les gnolls Rivepatte campent dans les collines à l'ouest du {area:86} ; les {quest:91725} se trouvent dans leurs camps.",
		["Shaman trainer"] = "Maître des chamans",
		["She stands by her cart at the vineyard east of the Abbey."] = "Elle se tient près de sa charrette, dans la vigne à l'est de l'abbaye.",
		["Shiny Red Apples, from {npc:894}, for the {quest:91736}"] = "Pommes rouges brillantes, auprès de {npc:894}, pour l'{quest:91736}",
		["Sit (/sit) by his campfire until you have {spell:1229451}"] = "Asseyez-vous (/sit) près de son feu de camp jusqu'à obtenir {spell:1229451}",
		["South down the road to the {area:64}."] = "Descendez la route vers le sud jusqu'aux {area:64}.",
		["Subdue the voidwalker"] = "Soumettez le marcheur du Vide",
		["Tame {npc:1922}"] = "Apprivoisez : {npc:1922}",
		["Tame {npc:524}"] = "Apprivoisez : {npc:524}",
		["Tame {npc:822}"] = "Apprivoisez : {npc:822}",
		["The Defias camp"] = "Le camp défias",
		["The Fishing Traps sit along the west shore of the lake."] = "Les Pièges à poissons se trouvent le long de la rive ouest du lac.",
		["The Stonefield farm is west of the mine. Ma and \"Auntie\" Bernice stand by the house.\nShe sits inside the farmhouse."] = "La ferme des Stonefield se trouve à l'ouest de la mine. M'man et « Tantine » Bernice se tiennent près de la maison.\nElle est assise dans la ferme.",
		["The bridge"] = "Le pont",
		["The camp is north-east of the bridge. Bundles of Wood lie around the camp and in the woods north of it.\nCareful: Elmpaw, a level 12 elite gnoll, walks the woods and hills from the logging camp north to {area:86} and the gnoll camps: keep clear of him when you see him coming."] = "Le camp se trouve au nord-est du pont. Des Fagots de bois traînent autour du camp et dans les bois au nord.\nAttention : Patte-d'orme, un gnoll élite de niveau 12, parcourt les bois et les collines entre le camp de bûcherons et le {area:86} et les camps gnolls au nord : écartez-vous de son chemin quand vous le voyez arriver.",
		["The crates of grapes lie in the vineyards behind the Defias. {npc:103} waits by the cabin at the east end of the valley."] = "Les caisses de raisin se trouvent dans les vignes derrière les Défias. {npc:103} attend près de la cabane, au bout est de la vallée.",
		["The gnoll camps"] = "Les camps gnolls",
		["The kobold camp"] = "Le camp kobold",
		["The lake shore"] = "La rive du lac",
		["The mine is south-west of the gnoll camps. {item:247816} lie near the entrance; Kobold Geomancers hold the tunnels.\nCareful: {npc:471} (7-10), the Mine Spiders (7-9) and {npc:248474} (7) are elites deep in the mine: pull the kobolds one at a time near the entrance and back out if an elite comes; they're easier with a friend."] = "La mine se trouve au sud-ouest des camps gnolls. Les {item:247816} traînent près de l'entrée ; les Géomanciens kobolds occupent les tunnels.\nAttention : {npc:471} (7-10), les Araignées minières (7-9) et {npc:248474} (7) sont des élites au fond de la mine : attirez les kobolds un par un près de l'entrée et ressortez si un élite arrive ; ils sont plus faciles avec un ami.",
		["The mine is west of the vineyards. Kobold Miners and Tunnelers fill both levels; {npc:248464}, a named kobold, holds the picture book in the lower tunnels. {npc:248464} is elite: grouping up is advised."] = "La mine se trouve à l'ouest des vignes. Les Mineurs kobolds et les Tunneliers kobolds occupent les deux niveaux ; {npc:248464}, un kobold nommé, détient le livre d'images dans les tunnels inférieurs. {npc:248464} est élite : il est conseillé de former un groupe.",
		["The murlocs on the east shore drop the kelp. Skinners: Gray Forest Wolves roam the woods between the lake and the {area:91}; Prowlers further east give pelts too.\nCareful: {npc:276180}, a level 11 rare murloc, walks the river by {npc:261}' bridge, east of the Prowlers' woods: leave him be."] = "Les murlocs de la rive est laissent tomber le varech. Dépeceurs : les Loups forestiers gris rôdent dans les bois entre le lac et la {area:91} ; les Rôdeurs plus à l'est donnent aussi des peaux.\nAttention : {npc:276180}, un murloc rare de niveau 11, arpente la rivière près du pont de {npc:261}, à l'est des bois des Rôdeurs : laissez-le tranquille.",
		["The vineyards and {npc:103}"] = "Les vignes et {npc:103}",
		["The {area:88}"] = "Le {area:88}",
		["The {area:91}"] = "La {area:91}",
		["The {item:247813}, Axe and Toolbox lie in the river south of the bridge. {npc:330}, a big boar, roots in the {area:62} west of the river with her {npc:390}: pull the piglets away first. Kill Young Forest Bears on the way; the Prowlers (level 9-10) wait for the walk back to {npc:261}, after the logging camp and the mine. Careful: {npc:248278} is a level 11 elite on the murloc shore. Only go for his head with a group; otherwise leave him: it's optional."] = "La {item:247813}, la Hache et la Boîte à outils se trouvent dans la rivière au sud du pont. {npc:330}, une grosse truie, fouille le {area:62} à l'ouest de la rivière avec son {npc:390} : attirez d'abord les porcelets à l'écart. Tuez des Jeunes ours des forêts en chemin ; les Rôdeurs (niveau 9-10) attendront le retour vers {npc:261}, après le camp de bûcherons et la mine. Attention : {npc:248278} est un élite de niveau 11 sur la rive des murlocs. N'allez chercher sa tête qu'en groupe ; sinon, laissez-le : c'est facultatif.",
		["The {quest:91736}"] = "L'{quest:91736}",
		["The {quest:91736} stands north of the {area:120}. Click it with four Shiny Red Apples in your bags: it takes them and gives you a {item:247824} on the spot (the quest never shows in your quest log). Keep the Applejack for {npc:955}: don't drink it."] = "L'{quest:91736} se trouve au nord de la {area:120}. Cliquez dessus avec quatre Pommes rouges brillantes dans vos sacs : il les prend et vous donne aussitôt un {item:247824} (la quête n'apparaît jamais dans votre journal de quêtes). Gardez le cidre pour {npc:955} : ne le buvez pas.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:248464} (level 6 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {npc:248464} (élite de niveau 6) demande un groupe de 2. Passez-le si vous êtes seul : l'itinéraire vous fait regagner l'expérience en tuant des monstres.",
		["Walk into the mine"] = "Entrez dans la mine",
		["Walk through the mine"] = "Traversez la mine",
		["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "Pendant que vous y êtes : apprenez le maniement des bâtons auprès de {npc:11867} ({object:2096}, 10 pièces d'argent) ; un bâton apporte plus de caractéristiques de sorts qu'une arme à une main pendant la progression.",
		["Wolves"] = "Loups",
		["You start in front of the Abbey. {npc:823} stands at the foot of the steps, {npc:197} inside the hall, {npc:951} and {npc:247229} in the library to the right, {npc:196} outside the north-west corner."] = "Vous commencez devant l'abbaye. {npc:823} se tient au pied des marches, {npc:197} dans la grande salle, {npc:951} et {npc:247229} dans la bibliothèque à droite, {npc:196} dehors, à l'angle nord-ouest.",
		["Young Wolves and Timber Wolves roam the fields right around the Abbey."] = "Les Jeunes loups et les Loups des bois rôdent dans les champs tout autour de l'abbaye.",
		["grind on {npc:1922}"] = "tuez en boucle : {npc:1922}",
		["grind on {npc:40}"] = "tuez en boucle : {npc:40}",
		["his kobold tracker shows the kobolds to click on the road to {area:87}"] = "son traqueur de kobolds montre les kobolds à cliquer sur la route de {area:87}",
		["talk to the trainer"] = "parlez au maître",
		["{area:18}: kill these as you meet them"] = "{area:18} : tuez-les au passage",
		["{area:34}: kill these as you meet them"] = "{area:34} : tuez-les au passage",
		["{area:54}: kill these as you meet them"] = "{area:54} : tuez-les au passage",
		["{area:64}: kill these as you meet them"] = "{area:64} : tuez-les au passage",
		["{item:247824}, from the still"] = "{item:247824}, de l'alambic",
		["{item:286215}: Stonetusk Boars"] = "{item:286215} : Sangliers Brocheroc",
		["{item:6785}: the {object:83763} in the Defias camp"] = "{item:6785} : les {object:83763} dans le camp défias",
		["{item:981}; below ground"] = "{item:981} ; sous terre",
		["{npc:12423} kneels wounded by a tree on the west shore of {area:18}, among the Fishing Traps. Cast {spell:613} (Rank 2) on him, then {spell:1243}: Rank 1 of {spell:613} does not count. He walks off once both land and is back in about 3 minutes."] = "{npc:12423} est agenouillé, blessé, près d'un arbre sur la rive ouest du {area:18}, parmi les Pièges à poissons. Lancez-lui {spell:613} (rang 2), puis {spell:1243} : le rang 1 de {spell:613} ne compte pas. Il s'en va une fois les deux sorts reçus et revient au bout d'environ 3 minutes.",
		["{npc:1430} cooks in the inn's kitchen. {npc:377} (priests), {npc:328} (mages) and {npc:917} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "{npc:1430} cuisine dans la cuisine de l'auberge. {npc:377} (prêtres), {npc:328} (mages) et {npc:917} (voleurs) se tiennent à l'étage de l'auberge : montez par l'escalier intérieur, la flèche ne distingue pas les étages.",
		["{npc:1430}: Camping 101 asks you to learn it; below ground"] = "{npc:1430} : Camping 101 vous demande de l'apprendre ; sous terre",
		["{npc:1632} takes it once your {skill:165} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:1632} prend la quête une fois votre compétence {skill:165} à 20 : récoltez ou fabriquez d'ici là, le guide continue en attendant.",
		["{npc:1632}, beside {npc:6306}"] = "{npc:1632}, à côté de {npc:6306}",
		["{npc:1651} takes it once your {skill:356} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:1651} prend la quête une fois votre compétence {skill:356} à 20 : récoltez ou fabriquez d'ici là, le guide continue en attendant.",
		["{npc:1922}: tame it with the {item:15908}"] = "{npc:1922} : apprivoisez-le avec le {item:15908}",
		["{npc:197}, inside"] = "{npc:197}, à l'intérieur",
		["{npc:198}, the mage trainer, inside the Abbey"] = "{npc:198}, le maître des mages, dans l'abbaye",
		["{npc:2329} takes it once your {skill:129} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:2329} prend la quête une fois votre compétence {skill:129} à 20 : récoltez ou fabriquez d'ici là, le guide continue en attendant.",
		["{npc:2329}, in the Lion's Pride Inn"] = "{npc:2329}, à l'auberge de la Fierté du lion",
		["{npc:240}, while William brews"] = "{npc:240}, pendant que William prépare la potion",
		["{npc:247229}, in the library; inside"] = "{npc:247229}, dans la bibliothèque ; à l'intérieur",
		["{npc:248242} and {npc:248248} stand at the foot of the tower."] = "{npc:248242} et {npc:248248} se tiennent au pied de la tour.",
		["{npc:248278} is a level 11 elite on the murloc shore south of the bridge: grouping up is encouraged, look for people to do it with. {quest:91740} needs a group of 2. Skip it if you are alone: the route has you grind the XP back. Right-click the head for its quest."] = "{npc:248278} est un élite de niveau 11 sur la rive des murlocs au sud du pont : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {quest:91740} demande un groupe de 2. Passez-la si vous êtes seul : l'itinéraire vous fait regagner l'expérience en tuant des monstres. Faites un clic droit sur la tête pour sa quête.",
		["{npc:248415} stands behind the Abbey, by the stables. {npc:198}, the mage trainer, stands upstairs in the Abbey: take the stairs inside, the arrow cannot tell the floors apart."] = "{npc:248415} se tient derrière l'abbaye, près des écuries. {npc:198}, le maître des mages, se tient à l'étage de l'abbaye : montez par l'escalier intérieur, la flèche ne distingue pas les étages.",
		["{npc:248415}, by the Abbey"] = "{npc:248415}, près de l'abbaye",
		["{npc:251507} stands with the {area:87} trainers. Each of her quests hands you a {item:15908}: use it on the beast she names, then bring the rod back to her. Rockhide Boars and Young Forest Bears roam the hills south of the {area:64}, Gray Forest Wolves the woods east of {area:18}."] = "{npc:251507} se tient avec les maîtres de {area:87}. Chacune de ses quêtes vous remet un {item:15908} : utilisez-le sur la bête qu'elle désigne, puis rapportez-lui le bâton. Les Sangliers Rochecuir et les Jeunes ours des forêts rôdent dans les collines au sud des {area:64}, les Loups forestiers gris dans les bois à l'est du {area:18}.",
		["{npc:253}, back in the inn"] = "{npc:253}, de retour dans l'auberge",
		["{npc:253}, inside"] = "{npc:253}, à l'intérieur",
		["{npc:257446} in {zone:1426}; {area:87} has no shaman trainer"] = "{npc:257446} à {zone:1426} ; {area:87} n'a pas de maître des chamans",
		["{npc:258930}, beside her: {spell:5149}"] = "{npc:258930}, à côté d'elle : {spell:5149}",
		["{npc:261} guards the bridge on the road east; {npc:248265} stands just across it."] = "{npc:261} garde le pont sur la route de l'est ; {npc:248265} se tient juste de l'autre côté.",
		["{npc:263399} camps north-east of the inn. With a profession learned, he also offers its Camping 101, which its trainer takes: skinning, leatherworking and fishing on the lake shore, {skill:129} and blacksmithing in {area:87}."] = "{npc:263399} campe au nord-est de l'auberge. Si vous avez appris un métier, il propose aussi son Camping 101, que reçoit le maître de ce métier : dépeçage, travail du cuir et pêche sur la rive du lac, {skill:129} et forge à {area:87}.",
		["{npc:263399}: for {npc:1632} on the lake shore"] = "{npc:263399} : pour {npc:1632} sur la rive du lac",
		["{npc:263399}: for {npc:1651} on the lake shore"] = "{npc:263399} : pour {npc:1651} sur la rive du lac",
		["{npc:263399}: for {npc:2329} in the Lion's Pride Inn"] = "{npc:263399} : pour {npc:2329} à l'auberge de la Fierté du lion",
		["{npc:263399}: for {npc:514} at the {area:87} smithy"] = "{npc:263399} : pour {npc:514} à la forge de {area:87}",
		["{npc:263399}: for {npc:6306} on the lake shore"] = "{npc:263399} : pour {npc:6306} sur la rive du lac",
		["{npc:278}, inside"] = "{npc:278}, à l'intérieur",
		["{npc:295}, inside"] = "{npc:295}, à l'intérieur",
		["{npc:328}: {npc:5497} in {zone:1453} takes it"] = "{npc:328} : {npc:5497} à {zone:1453} la reçoit",
		["{npc:375}, the priest trainer"] = "{npc:375}, la maîtresse des prêtres",
		["{npc:375}, the priest trainer: {npc:377} in {area:87} takes it"] = "{npc:375}, la maîtresse des prêtres : {npc:377} à {area:87} la reçoit",
		["{npc:377} (priests), {npc:328} (mages) and {npc:917} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "{npc:377} (prêtres), {npc:328} (mages) et {npc:917} (voleurs) se tiennent à l'étage de l'auberge : montez par l'escalier intérieur, la flèche ne distingue pas les étages.",
		["{npc:377}, upstairs"] = "{npc:377}, à l'étage",
		["{npc:377}, upstairs: {item:16605}"] = "{npc:377}, à l'étage : {item:16605}",
		["{npc:377}: heal {npc:12423} at {area:18}"] = "{npc:377} : soignez {npc:12423} au {area:18}",
		["{npc:377}: {npc:376} in {zone:1453} takes it"] = "{npc:377} : {npc:376} à {zone:1453} la reçoit",
		["{npc:459}, outside the Abbey"] = "{npc:459}, devant l'abbaye",
		["{npc:476} walks around {area:54}: look inside the circle on the map"] = "{npc:476} se promène autour de {area:54} : cherchez dans le cercle sur la carte",
		["{npc:514} takes it once your {skill:164} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:514} prend la quête une fois votre compétence {skill:164} à 20 : récoltez ou fabriquez d'ici là, le guide continue en attendant.",
		["{npc:514}, at the smithy across the road"] = "{npc:514}, à la forge de l'autre côté de la route",
		["{npc:524}: tame it with the {item:15908}"] = "{npc:524} : apprivoisez-le avec le {item:15908}",
		["{npc:5504} in {zone:1453}; {area:87} has no druid trainer"] = "{npc:5504} dans {zone:1453} ; {area:87} n'a pas de maître des druides",
		["{npc:6121}: {npc:6122} in {zone:1453} takes it"] = "{npc:6121} : {npc:6122} à {zone:1453} la reçoit",
		["{npc:6306} takes it once your {skill:393} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:6306} prend la quête une fois votre compétence {skill:393} à 20 : récoltez ou fabriquez d'ici là, le guide continue en attendant.",
		["{npc:6306}, inside"] = "{npc:6306}, à l'intérieur",
		["{npc:6306}, on the lake shore east of town; inside"] = "{npc:6306}, sur la rive du lac à l'est du village ; à l'intérieur",
		["{npc:6306}, {npc:383} and {npc:1651} stand on the shore of {area:18} east of town."] = "{npc:6306}, {npc:383} et {npc:1651} se tiennent sur la rive du {area:18}, à l'est du village.",
		["{npc:6306}: skinners only, the pelts are skinned; inside"] = "{npc:6306} : dépeceurs seulement, les peaux se dépècent ; à l'intérieur",
		["{npc:6774}, by the stables south of the Abbey"] = "{npc:6774}, près des écuries au sud de l'abbaye",
		["{npc:6} dig in the vineyards north-east of the Abbey. Now and then one drops a {quest:91741}: right-click it."] = "Les {npc:6} creusent dans les vignes au nord-est de l'abbaye. De temps en temps, l'une d'elles laisse tomber un {quest:91741} : faites un clic droit dessus.",
		["{npc:80} walks around {area:34}: look inside the circle on the map"] = "{npc:80} se promène autour de {area:34} : cherchez dans le cercle sur la carte",
		["{npc:822}: tame it with the {item:15908}"] = "{npc:822} : apprivoisez-le avec le {item:15908}",
		["{npc:823}, at the Abbey steps"] = "{npc:823}, au pied des marches de l'abbaye",
		["{npc:823}, back at the Abbey steps"] = "{npc:823}, de retour au pied des marches de l'abbaye",
		["{npc:894} sells the Shiny Red Apples for the {quest:91736}. Apples looted from kobolds and crates count too: the purchase ticks itself once you have four."] = "{npc:894} vend les Pommes rouges brillantes pour l'{quest:91736}. Les pommes ramassées sur les kobolds et dans les caisses comptent aussi : l'achat se coche tout seul dès que vous en avez quatre.",
		["{npc:911}, the warrior trainer; inside"] = "{npc:911}, le maître des guerriers ; à l'intérieur",
		["{npc:915}, the rogue trainer"] = "{npc:915}, le maître des voleurs",
		["{npc:925}, the paladin trainer"] = "{npc:925}, le maître des paladins",
		["{npc:952}, upstairs"] = "{npc:952}, à l'étage",
		["{npc:955}: he wants your {item:247824}; inside"] = "{npc:955} : il veut votre {item:247824} ; à l'intérieur",
		["{npc:963}: for {npc:234} at {area:108}"] = "{npc:963} : pour {npc:234} à {area:108}",
		["{object:694855} grows in the fields around the vineyards and the Stonefield farm; Stonetusk Boars around them give the blood.\nStonetusk Boars graze between the vineyards and the farm."] = "L'{object:694855} pousse dans les champs autour des vignes et de la ferme des Stonefield ; les Sangliers Brocheroc des environs fournissent le sang.\nLes Sangliers Brocheroc paissent entre les vignes et la ferme.",
		["{quest:76}'s entrance"] = "Entrée de {quest:76}",
		["{quest:87} is inside the {area:57}, not on the hill above it: go in at the mouth and keep left to the back of the mine floor; don't take the stairs up. Defias Bandits around the vineyards drop a {item:1972} now and then: right-click it.\nCareful: {npc:248464} (6), a kobold deep in the mine, is elite, and {npc:79} (10, rare) walks the tunnels: pull the kobolds one at a time."] = "{quest:87} se trouve dans la {area:57}, pas sur la colline au-dessus : entrez par l'ouverture et gardez votre gauche jusqu'au fond du niveau inférieur de la mine ; ne prenez pas l'escalier qui monte. Les Bandits défias autour des vignes laissent tomber de temps en temps un {item:1972} : faites un clic droit dessus.\nAttention : {npc:248464} (6), un kobold au fond de la mine, est un élite, et {npc:79} (10, rare) parcourt les tunnels : attirez les kobolds un par un.",
		["{quest:91733} and {npc:330}"] = "{quest:91733} et {npc:330}",
		["{zone:1429}: kill these as you meet them"] = "{zone:1429} : tuez-les au passage",
} end)()
t.guides["forever/alliance/nightelf/01-teldrassil"] = (function() return {
		["/sit by {npc:265811}'s campfire until you get {spell:1229451}"] = "/sit près du feu de camp de {npc:265811} jusqu'à obtenir {spell:1229451}",
		["Back at {area:256}"] = "Retour à {area:256}",
		["Back out of the city gate and east along the road: {quest:1683} stands south of it, by {area:736}. Bring his horn back to {quest:1684}."] = "Ressortez par la porte de la ville et suivez la route vers l'est : {quest:1683} se tient au sud de celle-ci, près de {area:736}. Rapportez sa corne à {quest:1684}.",
		["Back to the moonwell."] = "Retour au puits de lune.",
		["Back to the top of {area:256}. The {object:654846} lies beside him."] = "Retour au sommet d'{area:256}. Le {object:654846} se trouve à côté de lui.",
		["Back upstairs to {npc:3567} with the webwoods done and {npc:272116}'s moss."] = "Remontez à l'étage voir {npc:3567}, les tissebois éliminées et la mousse de {npc:272116} en poche.",
		["Befouled Webwoods"] = "Tissebois souillées",
		["Below ground"] = "Sous terre",
		["Bloodfeather harpies"] = "Harpies Plumesang",
		["Cast {spell:18960}"] = "Lancez {spell:18960}",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}; the {quest:5929} sits in the woods to the north-west. Learn {area:493}'s flight path from {npc:10897}, south of the lake, for later trips. Then {npc:11800} in {area:2361} flies Druids straight to {area:702} from her gossip: hers is no flight path to learn. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Lancez {spell:18960}. {npc:11802} se trouve à {area:2361} ; {quest:5929} se trouve dans les bois au nord-ouest. Apprenez le trajet aérien de {area:493} auprès de {npc:10897}, au sud du lac, pour vos prochains voyages. Ensuite, {npc:11800} à {area:2361} emmène les druides directement au {area:702} via son dialogue : ce n'est pas un trajet aérien à apprendre. {npc:11802} se tient à l'étage de son bâtiment : montez par l'intérieur, la flèche ne distingue pas les étages.",
		["Crawler Legs: the Tide Crawlers"] = "Pattes de clampant : les Clampants des marées",
		["Each of Dazalar's quests hands you a {item:15908}: use it on the beast he names, then bring the rod back to him in {area:186}. Webwood Lurkers creep around the village, Nightsaber Stalkers and Strigid Screechers roam the woods south of it."] = "Chaque quête de Dazalar vous remet un {item:15908} : utilisez-le sur la bête qu'il nomme, puis rapportez-lui le bâton à {area:186}. Les Rôdeuses Tissebois rampent autour du village, les Rôdeurs sabre-de-nuit et les Hurleurs Strigid parcourent les bois au sud.",
		["East along the road to {area:186}."] = "Vers l'est le long de la route jusqu'à {area:186}.",
		["Escort {npc:275744} out of the barrow; {npc:2081} in {area:186} takes the report."] = "Escortez {npc:275744} hors du refuge ; {npc:2081} à {area:186} reçoit le rapport.",
		["Fandral in {zone:1457} takes it"] = "Fandral à {zone:1457} la prend",
		["Fel Cones lie under the trees all around {area:186} and {npc:2150}: pick them up on the road east and hand them to {npc:2150} on the way to {npc:7234}."] = "Les Gangrenoix gisent sous les arbres tout autour de {area:186} et de {npc:2150} : ramassez-les sur la route vers l'est et remettez-les à {npc:2150} en chemin vers {npc:7234}.",
		["Fishers only: {npc:10216} stands on the pier. His {item:12238} is fished from the pier itself."] = "Pêcheurs uniquement : {npc:10216} se tient sur la jetée. Son {item:12238} se pêche depuis la jetée même.",
		["Fly back to {area:702} from {npc:3841}, hand {item:16263} to {npc:10118} on the dock, then fly back to {area:442}."] = "Reprenez un vol pour le {area:702} auprès de {npc:3841}, remettez la {item:16263} à {npc:10118} sur le quai, puis revenez en vol à {area:442}.",
		["Fly to {area:702} once more and take the portal up to {npc:4217}, then fly back to {area:442}."] = "Reprenez un vol pour {area:702} et le portail pour monter voir {npc:4217}, puis revenez en vol à {area:442}.",
		["Follow the road south-west out of {area:188}. {npc:2150} sits beside it just east of {area:186}."] = "Suivez la route vers le sud-ouest hors de {area:188}. {npc:2150} est assis au bord, juste à l'est de {area:186}.",
		["Gnarlpine Ambushers hide along the road west of {area:258}."] = "Les Embusqués Pin-tordu se cachent le long de la route à l'ouest de {area:258}.",
		["Gnarlpine Mystics and {npc:7234} camp north-east of {area:260}. {npc:7234} drops the {item:8049}: open it for the jewel.\nCareful: {npc:7234} waits near the camp fire with mystics around him, so pulling him without adds is hard."] = "Des Mystiques Pin-tordu et {npc:7234} campent au nord-est du {area:260}. {npc:7234} laisse tomber le {item:8049} : ouvrez-le pour obtenir le joyau.\nAttention : {npc:7234} attend près du feu de camp entouré de mystiques, il est donc difficile de l'attirer seul.",
		["Gnarlpine Shamans"] = "Chamans Pin-tordu",
		["Go back down to {area:702} and fly to {area:442}. The {object:177525} stands in the hills just east of the village: use the {item:15208} there, defeat Lunaclaw and speak to the {npc:12144}."] = "Redescendez à {area:702} et prenez un vol pour {area:442}. La {object:177525} se dresse dans les collines juste à l'est du village : utilisez-y la {item:15208}, vainquez Lunegriffe et parlez à l'{npc:12144}.",
		["Grells"] = "Grells",
		["Grells (level 2-3) carry {item:3297} in the woods west of the tree, by the totems. The {npc:1989} further north are level 3-4: the Grells by the totems are enough."] = "Les Grells (niveau 2-3) portent de la {item:3297} dans les bois à l'ouest de l'arbre, près des totems. Les {npc:1989} plus au nord sont de niveau 3-4 : les Grells près des totems suffisent.",
		["Heal and fortify {npc:12429}"] = "Soignez et fortifiez {npc:12429}",
		["Into the city through the gate. {quest:922} is just south of the {area:1658} at the north end, {npc:7316} in the west, {npc:7313} and {npc:8396} in the Temple of the Moon at the south end. On the way back out, use Dalia's {item:279378} at the bank and at the city gate; the other two owls wait for your last visit."] = "Entrez dans la ville par la porte. {quest:922} est juste au sud de l'{area:1658}, à l'extrémité nord, {npc:7316} à l'ouest, {npc:7313} et {npc:8396} dans le temple de la Lune, à l'extrémité sud. En ressortant, utilisez le {item:279378} de Dalia à la banque et à la porte de la ville ; les deux autres chouettes attendent votre dernière visite.",
		["Lead {quest:938} to the moonwell"] = "Ramenez {quest:938} au puits de lune",
		["Learn the flight path from {npc:3841} where you land. {npc:4200}'s fish stall is just north of her, by the docks.\nThe boat docks west of the village. The flight master stands on the hill south of the inn; the quest givers are spread along the main street."] = "Apprenez le trajet aérien auprès de {npc:3841}, là où vous atterrissez. L'étal de poissons de {npc:4200} se trouve juste au nord d'elle, près des quais.\nLe bateau accoste à l'ouest du village. La maîtresse de vol se tient sur la colline au sud de l'auberge ; les donneurs de quêtes sont répartis le long de la rue principale.",
		["Leave {area:188} by the path south-east of {area:256}: {npc:6780} stands beside it, where it goes down towards the road to {area:186}."] = "Quittez {area:188} par le chemin au sud-est d'{area:256} : {npc:6780} se tient à côté, là où il descend vers la route de {area:186}.",
		["Level 12 spells while you're in the Temple of the Moon: the priest trainers stand beside {npc:11401}."] = "Sorts de niveau 12 pendant que vous êtes dans le Temple de la Lune : les maîtres des prêtres se tiennent à côté de {npc:11401}.",
		["Level 12 spells while you're in the {area:1658}: the hunter, rogue and druid trainers all stand in it."] = "Sorts de niveau 12 pendant que vous êtes à {area:1658} : les maîtres des chasseurs, des voleurs et des druides s'y trouvent tous.",
		["Level 12 spells while you're on the {area:1660}: the warrior trainers stand beside {quest:1684}."] = "Sorts de niveau 12 pendant que vous êtes sur la {area:1660} : les maîtres des guerriers se tiennent à côté de {quest:1684}.",
		["Mangy Nightsabers and Thistle Boars roam north of {area:256}, on the way to the cave. {npc:1994} sits deep inside. {npc:8584} waits in the trees west of the cave mouth."] = "Des Sabres-de-nuit galeux et des Sangliers des chardons parcourent le nord d'{area:256}, sur le chemin de la grotte. {npc:1994} se tient tout au fond. {npc:8584} attend dans les arbres à l'ouest de l'entrée de la grotte.",
		["Nightsabers"] = "Sabres-de-nuit sauvages",
		["North to {area:257}"] = "Au nord vers {area:257}",
		["North-east from Ursal's den, back to {area:186}. {npc:6094} takes a {item:159} with the fronds and the vial: if you drank yours, buy another from {npc:6736} in this inn before you hand in."] = "Au nord-est depuis la tanière d'Ursal, retour à {area:186}. {npc:6094} prend une {item:159} avec les frondes et la fiole : si vous avez bu la vôtre, achetez-en une autre à {npc:6736} dans cette auberge avant de rendre la quête.",
		["North-west of Dolanaar, on the way to the {area:264}, Befouled Webwoods creep through the woods; {npc:272116} prowls at their east edge and carries the {item:281023}.\n{npc:272116} is elite (level 12): grouping up is advised. Clear the webwoods around him first and pull him on his own."] = "Au nord-ouest de Dolanaar, sur le chemin de {area:264}, les Tissebois souillées rampent dans les bois ; {npc:272116} rôde à leur lisière est et porte la {item:281023}.\n{npc:272116} est un élite (niveau 12) : il est conseillé de se grouper. Éliminez d'abord les tissebois autour de lui, puis attirez-le seul.",
		["On the way back south to the glade: {npc:272046} (level 12) flies on the slopes north-west of the moonwell, among Bloodfeather Matriarchs (11). Pull the harpies around her first."] = "Sur le chemin du retour vers la clairière au sud : {npc:272046} (niveau 12) vole sur les pentes au nord-ouest du puits de lune, parmi les Matriarches Plumesang (11). Attirez d'abord les harpies autour d'elle.",
		["Portal to {quest:940}"] = "Portail vers {quest:940}",
		["Priest trainer"] = "Maître des prêtres",
		["Sentinel Arynia again"] = "De nouveau la sentinelle Arynia",
		["South from the glade to the road: Shayla walks the road west of {area:186}, from where the path down from the glade meets it south-west to the bend at about 38,54 and back."] = "Au sud de la clairière jusqu'à la route : Shayla parcourt la route à l'ouest de {area:186}, depuis l'endroit où le chemin qui descend de la clairière la rejoint, vers le sud-ouest jusqu'au virage vers 38,54, puis revient.",
		["South of the pools. The {object:6751} grows by the Hold; the furbolgs around it drop the rest of the fangs.\nCareful: the Gnarlpine Avengers (9-10) and Augurs here stand close together and many players died at the Hold: pull them one at a time."] = "Au sud des bassins. La {object:6751} pousse près du Camp des Pins-tordus ; les furbolgs alentour laissent tomber le reste des crocs.\nAttention : les Vengeurs Pin-tordu (9-10) et les Augures sont proches les uns des autres et beaucoup de joueurs sont morts au camp : attirez-les un par un.",
		["South-east of Dolanaar, to {npc:2080}. Lasher Sproutlings wander around him on the shore."] = "Au sud-est de Dolanaar, vers {npc:2080}. Les Jeunes pousses de flagellant errent autour de lui sur la rive.",
		["South-west from {area:259}, past the {area:478}: Ursal prowls the far south of the island.\nCareful: Gnarlpine of roughly level 9-11 crowd the camp and sit close together, so it is easy to pull several at once. Take them on singly before you engage Ursal."] = "Au sud-ouest du {area:259}, après les {area:478} : Ursal rôde à l'extrême sud de l'île.\nAttention : des Pin-tordu de niveau 9-11 environ se pressent dans le camp, serrés les uns contre les autres, il est donc facile d'en attirer plusieurs à la fois. Affrontez-les un par un avant d'engager Ursal.",
		["South-west of Starbreeze, south of {npc:2150}. {npc:2080} tends his saplings on the shore; Lasher Sproutlings and Timberlings wander around him, and the {quest:919} grow among them."] = "Au sud-ouest de Brise-d'étoiles, au sud de {npc:2150}. {npc:2080} soigne ses jeunes arbres sur la rive ; des Jeunes pousses de flagellant et des Sylvains errent autour de lui, et les {quest:919} poussent parmi eux.",
		["South-west of the barrow. The moonwell sits by the pools."] = "Au sud-ouest du refuge. Le puits de lune se trouve près des bassins.",
		["Speak with the {quest:5929}"] = "Parlez à l'{quest:5929}",
		["Take the antidote from {npc:8583} at the foot of {area:256} only now, on the way down: it lasts five minutes. {npc:8584} waits north-west, by the cave: go straight on to him."] = "Ne prenez l'antidote auprès de {npc:8583}, au pied d'{area:256}, que maintenant, en redescendant : il dure cinq minutes. {npc:8584} attend au nord-ouest, près de la grotte : allez directement le voir.",
		["Take the portal down to {area:702}. {npc:10118} stands on the dock, {npc:3838} by the hippogryphs. Once you have {quest:6342}, talk to {npc:3838} again and choose the flight to {area:442}: it is free and lands beside {npc:4200}. If the flight map opens instead, close it and talk to him again holding Shift."] = "Prenez le portail pour descendre au {area:702}. {npc:10118} se tient sur le quai, {npc:3838} près des hippogriffes. Une fois {quest:6342} en poche, parlez de nouveau à {npc:3838} et choisissez le vol pour {area:442} : il est gratuit et se pose à côté de {npc:4200}. Si la carte des vols s'ouvre à la place, fermez-la et parlez-lui de nouveau en maintenant Maj.",
		["Take the road north-west from {area:186} again; she still lies beside it, on the way to {zone:1457}."] = "Reprenez la route vers le nord-ouest depuis {area:186} ; elle gît toujours au bord de la route, en direction de {zone:1457}.",
		["The Bloodfeather harpies nest on the slopes west and north of the glade. {quest:938}, an injured sabercat, lies by the glade's west wall among them: lead her back to Sentinel Arynia at the moonwell before her time runs out.\nCareful: The harpies stand packed together, so extra ones often join a fight. Casters are mixed in among them."] = "Les harpies Plumesang nichent sur les pentes à l'ouest et au nord de la clairière. {quest:938}, une dame-sabre blessée, gît parmi elles près de la paroi ouest de la clairière : ramenez-la à la Sentinelle Arynia, au puits de lune, avant la fin du temps imparti.\nAttention : les harpies se tiennent serrées, alors d'autres se joignent souvent au combat. Des lanceuses de sorts sont mêlées à elles.",
		["The WANTED poster outside the inn"] = "L'affiche AVIS DE RECHERCHE devant l'auberge",
		["The barrow is south of the road. {npc:275744} is held inside, {npc:7317} sleeps in its depths, and the four relic chests sit in the lower rooms. Its furbolgs drop Shayla's fangs.\nCareful: the barrow's Gnarlpine Defenders, Augurs and Shamans (7-9) stand in threes in the narrow tunnels: pull each group back toward the entrance before you go deeper."] = "Le refuge se trouve au sud de la route. {npc:275744} y est retenue, {npc:7317} dort dans ses profondeurs, et les quatre coffres à reliques se trouvent dans les salles inférieures. Ses furbolgs lâchent les crocs pour Shayla.\nAttention : les Défenseurs, Augures et Chamans Pins-tordus du refuge (7-9) se tiennent par trois dans les tunnels étroits : ramenez chaque groupe vers l'entrée avant d'aller plus loin.",
		["The grells west of the tree"] = "Les grells à l'ouest de l'arbre",
		["The moonwell"] = "Le puits de lune",
		["The moonwell is in the middle of the glade. The {object:6752} grows at its north end."] = "Le puits de lune se trouve au milieu de la clairière. La {object:6752} pousse à son extrémité nord.",
		["The moonwell sits north of {area:256}."] = "Le puits de lune se trouve au nord d'{area:256}.",
		["The road to {zone:1457}"] = "La route de {zone:1457}",
		["The road west to the {area:264} runs through {area:186}: hand {npc:3567} the jewel on the way."] = "La route vers l'ouest jusqu'à {area:264} traverse {area:186} : remettez le joyau à {npc:3567} en chemin.",
		["The trainers stand upstairs inside {area:256}, along the ramp that winds up the tree: {npc:3593} and {npc:3594} on the first level, {npc:3595} above them, {npc:3596} and {npc:3597} at the top. The arrow cannot tell the levels apart."] = "Les maîtres de classe se tiennent dans les étages d'{area:256}, le long de la rampe qui monte en spirale dans l'arbre : {npc:3593} et {npc:3594} au premier niveau, {npc:3595} au-dessus d'eux, {npc:3596} et {npc:3597} au sommet. La flèche ne distingue pas les niveaux.",
		["The {area:265}"] = "La {area:265}",
		["The {area:478}"] = "{area:478}",
		["The {object:177525}"] = "{object:177525}",
		["The {object:4406} lie at the back of {area:257}: take the central path, then left where it splits, up to the high ledge. Hyacinth Mushrooms drop from Grells, Moonpetal Lilies grow by the ponds north of {area:256}."] = "Les {object:4406} se trouvent au fond de {area:257} : prenez le chemin central, puis à gauche à l'embranchement, jusqu'à la haute corniche. Les Champignons jacinthe tombent des Grells, les Lys pétale de lune poussent près des étangs au nord d'{area:256}.",
		["The {object:6752} grows at the glade's north end, on the way: then north along the island's northern edge by {area:266}, {npc:7319}, a level 12 spider, lurks."] = "La {object:6752} pousse à l'extrémité nord de la clairière, sur le chemin : ensuite, au nord, le long de la bordure nord de l'île près du {area:266}, rôde {npc:7319}, une araignée de niveau 12.",
		["Tide Crawlers scuttle along the shore below the village; {quest:983} stands on the beach just south of the docks. Darkshore Threshers swim in the shallows. The {object:175207} lies on the shore just south of the village."] = "Les Clampants des marées grouillent sur la côte en contrebas du village ; {quest:983} se trouve sur la plage juste au sud des quais. Les Batteurs de Sombrivage nagent dans les hauts-fonds. La {object:175207} gît sur la côte juste au sud du village.",
		["Upstairs"] = "À l'étage",
		["Use the {item:18152} at the moonwell"] = "Utilisez la {item:18152} au puits de lune",
		["Use the {item:5185} at the moonwell"] = "Utilisez la {item:5185} au puits de lune",
		["Use the {item:5619} at the moonwell"] = "Utilisez la {item:5619} au puits de lune",
		["Use the {item:5621} at the moonwell"] = "Utilisez la {item:5621} au puits de lune",
		["Walk Lynessa out and keep her alive"] = "Accompagnez Lynessa dehors et gardez-la en vie",
		["Warrior trainer"] = "Maître des guerriers",
		["Webwood Lurkers"] = "Rôdeuses Tissebois",
		["Webwood Spiders; below ground"] = "Araignées Tissebois ; sous terre",
		["West along the road toward the city. Shayla walks this stretch of road, from the arrow south-west to the bend at about 38,54 and back: if she isn't at the arrow, follow the road south-west. Every Gnarlpine furbolg drops fangs: the ambushers on this road, the barrow's and {area:261}'s all count."] = "Vers l'ouest le long de la route, en direction de la ville. Shayla parcourt ce tronçon de route, de la flèche vers le sud-ouest jusqu'au virage vers 38,54, puis revient : si elle n'est pas à la flèche, suivez la route vers le sud-ouest. Tous les furbolgs Pin-tordu laissent tomber des crocs : les embusqués de cette route, ceux du refuge et ceux du {area:261} comptent tous.",
		["West from the webwoods to the {area:265}, then north along it to the glade: the timberlings along its banks drop the Mossy Tumors.\nCareful: {npc:272116}, a level 12 elite, prowls the east edge of the Befouled Webwoods north-west of {area:186}: if you are alone, keep clear of the webwoods and go round him."] = "Vers l'ouest depuis les tissebois jusqu'à la {area:265}, puis vers le nord en la longeant jusqu'à la clairière : les sylvins le long de ses rives laissent tomber les Tumeurs moussues.\nAttention : {npc:272116}, un élite de niveau 12, rôde à la lisière est des Tissebois souillées au nord-ouest de {area:186} : si vous êtes seul, évitez les tissebois et contournez-le.",
		["While you're here: learn Staves from {npc:11866} ({area:1660}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Tant que vous y êtes : apprenez les Bâtons auprès de {npc:11866} ({area:1660}, 10 pièces d'argent) ; l'arme de mêlée d'un chasseur compte surtout pour ses caractéristiques, et les armes à deux mains en portent le plus.",
		["While you're here: learn Staves from {npc:11866} ({area:1660}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "Tant que vous y êtes : apprenez les Bâtons auprès de {npc:11866} ({area:1660}, 10 pièces d'argent) ; un bâton porte plus de caractéristiques de sorts qu'une arme à une main pendant la montée de niveau.",
		["With a profession learned, {npc:265811} also offers its Camping 101, which its trainer takes: alchemy and herbalism beside {npc:6286}, {skill:129} with {npc:6094} in the inn, skinning and leatherworking at the Maneweavers' camp on the road west."] = "Une fois un métier appris, {npc:265811} propose aussi son Camping 101, que rend son maître : l'alchimie et l'herboristerie à côté de {npc:6286}, {skill:129} avec {npc:6094} dans l'auberge, le dépeçage et le travail du cuir au camp des Tisse-crinière sur la route à l'ouest.",
		["You start at the foot of {area:256}, the great tree of {area:188}."] = "Vous commencez au pied d'{area:256}, le grand arbre de {area:188}.",
		["Young Nightsabers and Young Thistle Boars (level 1-2) roam around {area:256}: start with them. The Gnarlpine Totems stand in the woods west of the tree, where the Grells (2-3) roam: take them once the beasts are done."] = "Les Jeunes sabres-de-nuit et les Jeunes sangliers des chardons (niveau 1-2) rôdent autour d'{area:256} : commencez par eux. Les Totems pin-tordu se dressent dans les bois à l'ouest de l'arbre, où rôdent les Grells (2-3) : occupez-vous-en une fois les bêtes terminées.",
		["talk to the trainer"] = "parlez au maître",
		["talk to {npc:3838} again: free with {quest:6342}"] = "parlez de nouveau à {npc:3838} : gratuit avec {quest:6342}",
		["the city gate"] = "la porte de la ville",
		["the same {object:673378}: Fandral in {zone:1457} takes it"] = "le même {object:673378} : Fandral, à {zone:1457}, le prend",
		["the tunnel mouth below {area:3425}, on the way south"] = "l'entrée du tunnel sous {area:3425}, sur le chemin du sud",
		["{area:1658} trainers"] = "Maîtres de {area:1658}",
		["{area:186} again"] = "De nouveau {area:186}",
		["{area:188}: kill these as you meet them"] = "{area:188} : tuez-les au passage",
		["{area:258}'s mouth"] = "Entrée de {area:258}",
		["{area:262}'s entrance"] = "Entrée de {area:262}",
