		["Flight path here: {area:702} (Vesprystus)."] = "Trajet aérien ici : {area:702} (Vesprystus).",
		["Flight paths here: {area:2897} (Andruk), {area:431} (Vhulgra)."] = "Trajets aériens ici : {area:2897} (Andruk), {area:431} (Vhulgra).",
		["Flight paths here: {area:392} (Bragok), Crossroads (Devrak), {area:378} ({npc:10378})."] = "Trajets aériens ici : {area:392} (Bragok), la Croisée (Devrak), {area:378} ({npc:10378}).",
		["Fly to {area:378} and walk south through the {zone:1413} to the {area:485} down into {zone:1441}."] = "Prenez un vol pour {area:378} et traversez les {zone:1413} vers le sud jusqu'à {area:485}, qui descend dans {zone:1441}.",
		["Follow {zone:1439}'s coast road south into {zone:1440}. {area:415} is the Alliance town."] = "Suivez la route côtière de {zone:1439} vers le sud jusque dans {zone:1440}. {area:415} est la ville de l'Alliance.",
		["Follow {zone:1440}'s road north-west to the coast and into {zone:1439}, Alliance country with guards at {area:442}."] = "Suivez la route de {zone:1440} vers le nord-ouest jusqu'à la côte et dans {zone:1439}, territoire de l'Alliance gardé à {area:442}.",
