t.guides["forever/horde/02-the-barrens"] = (function() return {
		["Assist {npc:261366}: stay by him when {npc:261367} and the {area:21} marines come up the ridge"] = "Aidez {npc:261366} : restez près de lui quand {npc:261367} et les soldats de marine de {area:21} montent la crête",
		["At the {area:2362}"] = "Au {area:2362}",
		["At the {object:147538}: summons {quest:882}"] = "À l'arbre mort : invoque {quest:882}",
		["Back down to {npc:11857}."] = "Redescendez jusqu'à {npc:11857}.",
		["Back east over the bridge and up the trail to {npc:5900}'s shrine again. {npc:5900} makes {item:6636} from the tar and pouch. Use it by the brazier next to him to reveal the {npc:5893}, kill it for the {item:6655}, then place the ember in the brazier."] = "Retournez vers l'est par le pont et remontez le sentier jusqu'au sanctuaire de {npc:5900}. {npc:5900} fabrique {item:6636} avec le goudron et la bourse. Utilisez-le près du brasero à côté de lui pour révéler {npc:5893}, tuez-la pour obtenir {item:6655}, puis placez la braise dans le brasero.",
		["Back north along the beach to {area:392}."] = "Revenez vers le nord par la plage jusqu'à {area:392}.",
		["Back north into the Bristleback camps. Any Bristleback can drop a tusk for {npc:3432}, so collect them while you kill these for {npc:3430}. Keep one {item:5075}."] = "Retournez vers le nord dans les camps Dos-hirsute. N'importe quel Dos-hirsute peut lâcher une défense pour {npc:3432}, alors ramassez-les pendant que vous tuez ceux-ci pour {npc:3430}. Gardez un {item:5075}.",
		["Back north into {area:378} before the antennae fade: {npc:6394} is inside."] = "Retournez au nord au {area:378} avant que les antennes ne disparaissent : {npc:6394} est à l'intérieur.",
		["Back north into {area:378} on the way to the Crossroads: Jorn takes the thunderhawk wings."] = "Revenez vers le nord jusqu'au {area:378} sur le chemin de la Croisée : Jorn prend les ailes de faucon-tonnerre.",
		["Back out of the caverns and up to the cave above the entrance."] = "Ressortez des cavernes et montez jusqu'à la grotte au-dessus de l'entrée.",
		["Back to the Razormane camp. Geomancers and Defenders hold its eastern half; {npc:3438} walks among them. Careful: Razormane Flesheaters and Berserkers (18-19) are elites in the camp's north-east, near {npc:3438} and the supply crates, and {npc:267307} (20, elite) lies in the cave under {area:1699} beside them: pull {npc:3438} and the quilboar away from them one at a time, and leave the cave alone unless you are in a group."] = "Retour au camp Tranchecrin. Les Géomanciennes et les Défenseurs tiennent sa moitié est ; {npc:3438} se promène parmi eux. Attention : les Dévoreuses et les Berserkers tranchecrin (18-19) sont des élites au nord-est du camp, près de {npc:3438} et des caisses de ravitaillement, et {npc:267307} (20, élite) se trouve dans la grotte sous {area:1699}, à côté d'eux : attirez {npc:3438} et les hurans un par un loin d'eux, et laissez la grotte tranquille sauf si vous êtes en groupe.",
		["Bristleback Geomancers"] = "Géomanciennes Dos-hirsute",
		["Bristleback camps"] = "Camps Dos-hirsute",
		["Cast {spell:18960}"] = "Lancez {spell:18960}",
		["Cast {spell:18960}. {npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart."] = "Lancez {spell:18960}. {npc:11802} se tient à l'étage de son bâtiment à {area:2361} : montez par l'intérieur, la flèche ne distingue pas les étages.",
		["Crossroads flight master"] = "Maître de vol de la Croisée",
		["Cure {npc:12296}"] = "Soignez : {npc:12296}",
		["Dogran is chained up in the quilboar camp west of the road."] = "Dogran est enchaîné dans le camp huran à l'ouest de la route.",
		["Down the {area:458} to {area:378} again."] = "Redescendez la {area:458} jusqu'au {area:378}.",
		["East along the road to {npc:4049} and {npc:11857}'s camp, on the way back out of Stonetalon."] = "Suivez la route vers l'est jusqu'au camp de {npc:4049} et {npc:11857}, sur le chemin de la sortie des Serres-Rocheuses.",
		["East from the keg toward {quest:881}: {npc:3682} camps below the hills, and his errands lie in the plains beside his camp."] = "À l'est du tonneau, en direction de {quest:881} : {npc:3682} campe sous les collines, et ses commissions se trouvent dans les plaines à côté de son camp.",
		["East from {npc:261366} toward the {area:382}: {npc:9316} stands at the camp on the road north of the Crossroads."] = "À l'est depuis {npc:261366} en direction de {area:382} : {npc:9316} se tient au camp sur la route au nord de la Croisée.",
		["East of Ziz, the Venture Company is clear-cutting {area:461}; one of the Operators carries the blueprints."] = "À l'est de Ziz, la KapitalRisk rase la {area:461} ; l'un des Opérateurs porte les plans.",
		["East to the beach, at the south end of the pirate camp: the crate of boots and the fragile crate with the lens sit there, and {npc:3467} (16) stands beside them."] = "À l'est jusqu'à la plage, à l'extrémité sud du camp pirate : la caisse de bottes et la caisse fragile avec la lentille s'y trouvent, et le {npc:3467} (16) se tient à côté.",
		["Fill the {item:7766} at the quilboar watering hole"] = "Remplissez l'{item:7766} au point d'eau des huttiers",
		["Finish the Plainstrider Beaks"] = "Finir les Becs de trotteur des plaines",
		["Finish the Raptor Heads"] = "Finir les Têtes de raptor",
		["Fly from the Crossroads to {area:1638} and train your level 20 ranks: {npc:3033} is on {area:1639}. {spell:499} and {spell:526} follow in {zone:1450} on the same trip, then {npc:11798} flies you back here and on to {area:392}."] = "Prenez un vol depuis la Croisée jusqu'aux {area:1638} et apprenez vos rangs du niveau 20 : {npc:3033} est sur la {area:1639}. {spell:499} et {spell:526} suivent à {zone:1450} lors du même voyage, puis {npc:11798} vous ramène ici en vol et continue jusqu'à {area:392}.",
		["Fly from the Crossroads to {area:1638}. {quest:853} waits in the {area:2197}, the cave under {area:1640}: hand in the spores there first, while their time runs. Then {npc:3033} trains you on {area:1639}."] = "Volez de la Croisée à {area:1638}. {quest:853} attend dans {area:2197}, la grotte sous la {area:1640} : rendez-y d'abord les spores, tant que leur temps court. Ensuite, {npc:3033} vous entraîne sur la {area:1639}.",
		["Fly from {zone:1456} on to {area:392}."] = "Prenez un vol depuis les {zone:1456} jusqu'à {area:392}.",
		["Fly from {zone:1456} straight on to {area:392}."] = "Prenez un vol depuis les {zone:1456} directement jusqu'à {area:392}.",
		["Fly on to {area:392} from Doras on the tower in the {object:172982}."] = "Continuez en vol jusqu'à {area:392} depuis Doras, sur la tour de la {object:172982}.",
		["Fly to Crossroads"] = "Prendre un vol pour la Croisée",
		["Fly to {area:1637}"] = "Prendre un vol pour {area:1637}",
		["Fly to {area:392}"] = "Prendre un vol pour {area:392}",
		["Follow the road on west from {npc:4049} into Stonetalon. The troll village of {area:2539} sits at the entrance of the canyon."] = "Continuez sur la route vers l'ouest depuis {npc:4049} jusque dans les Serres-Rocheuses. Le village troll de {area:2539} se trouve à l'entrée du canyon.",
		["Follow the {area:458} south to {area:378}."] = "Suivez la {area:458} vers le sud jusqu'au {area:378}.",
		["For your {area:718} run: {npc:3446}'s next errand, {quest:1491}."] = "Pour votre expédition dans {area:718} : la mission suivante de {npc:3446}, {quest:1491}.",
		["For your {area:718} run: {npc:5767} and {npc:5768} stand in a hidden cave in the rocks above the entrance, at the north end of the oasis' west shore: climb up from the west side. Follow the arrow up."] = "Pour votre expédition dans {area:718} : {npc:5767} et {npc:5768} se tiennent dans une grotte cachée dans les rochers au-dessus de l'entrée, à l'extrémité nord de la rive ouest de l'oasis : grimpez par le côté ouest. Suivez la flèche vers le haut.",
		["Grimtotem camp"] = "Le camp Totem sinistre",
		["He gives you the {item:15826}"] = "Il vous donne le {item:15826}",
		["He offers {quest:1838} next (1838, level 30): it needs {area:1717} and sends you all over Kalimdor and the Eastern Kingdoms. The Warrior class guide {quest:1838} covers it."] = "Il propose ensuite {quest:1838} (1838, niveau 30) : elle demande {area:1717} et vous envoie partout en Kalimdor et dans les Royaumes de l'Est. Le guide de classe Guerrier {quest:1838} la couvre.",
		["Head north from the Crossroads to {area:384} and fill the {item:15842} at the {object:19464}, then back to {npc:3448} in the Crossroads. No {skill:182}? {npc:3490} beside him sells {item:2449}, three at a time until he restocks."] = "Allez vers le nord depuis la Croisée jusqu'au {area:384} et remplissez l'{item:15842} au {object:19464}, puis retournez voir {npc:3448} à la Croisée. Pas d'{skill:182} ? {npc:3490}, à côté de lui, vend de la {item:2449}, trois à la fois jusqu'à son réapprovisionnement.",
		["In from the north gate: {npc:3464} first, {npc:3338} by the inn, then up to {npc:3449} and {npc:3429} on the tower platform, where the flight master stands."] = "Entrez par la porte nord : d'abord {npc:3464}, {npc:3338} près de l'auberge, puis montez voir {npc:3449} et {npc:3429} sur la plateforme de la tour, où se tient le maître de vol.",
		["In the camp, Water Seekers and Thornweavers hold the western half, Hunters the middle; the supply crates sit at its eastern end.\nPlainstriders here count toward the beaks.\nCareful: Razormane Flesheaters and Berserkers (18-19) are elites; they stand in the camp's north-east, beside the supply crates: pull the quilboar away from them one at a time."] = "Dans le camp, les Sourciers et les Tisseuses d'épines tiennent la moitié ouest, les Chasseurs le milieu ; les caisses de ravitaillement sont à son extrémité est.\nLes Trotteurs des plaines d'ici comptent pour les becs.\nAttention : les Dévoreuses et les Berserkers tranchecrin (18-19) sont des élites ; ils se tiennent au nord-est du camp, à côté des caisses de ravitaillement : attirez les hurans un par un loin d'eux.",
		["Inside"] = "À l'intérieur",
		["Keep it: the {object:107045} is beside {area:272}, on the {area:287} guide"] = "Gardez-la : le {object:107045} est à côté de {area:272}, dans le guide de {area:287}",
		["Keep it: {npc:12696} in {zone:1440}, next guide"] = "Gardez-la : {npc:12696} en {zone:1440}, guide suivant",
		["Keep it: {npc:5875} in {zone:1454}, on the next guide's {zone:1454} stop"] = "Gardez-la : {npc:5875} à {zone:1454}, lors de la halte à {zone:1454} du guide suivant",
		["Keep it: {quest:3923} is in {zone:1454}'s {object:172958}, on the {zone:1454} trip at 20"] = "Gardez-le : {quest:3923} se fait dans la {object:172958} d'{zone:1454}, lors du passage à {zone:1454} au niveau 20",
		["Keep {npc:3446}'s {quest:865} and {npc:3467} for the next {area:392} stop, at 18: Scytheclaws you meet on the plains before then drop the horns too."] = "Gardez {quest:865} de {npc:3446} et le {npc:3467} pour la prochaine halte à {area:392}, au niveau 18 : les Faucheurs que vous croisez dans les plaines d'ici là lâchent aussi les cornes.",
		["Kolkar camp"] = "Camp kolkar",
		["Leave {zone:1454} by the main gate and follow the road south through {zone:1411}, then west over the {area:814} bridge: {npc:5810} stands at {area:379} just above it, on the road to the Crossroads."] = "Quittez {zone:1454} par la grande porte et suivez la route vers le sud à travers {zone:1411}, puis vers l'ouest par le pont de la {area:814} : {npc:5810} se tient au {area:379}, juste au-dessus, sur la route de la Croisée.",
		["Level 20"] = "Niveau 20",
		["Lost Barrens Kodos roam the plains around the Kolkar camp north-west of {npc:3389}; herbalists pick {item:2449} there too."] = "Des Kodos égarés des Tarides parcourent les plaines autour du camp kolkar au nord-ouest de {npc:3389} ; les herboristes y cueillent aussi de la {item:2449}.",
		["North to the {area:383}: {quest:876} leads the Witchwing harpies in the hills to the west.\nCareful: The route in passes stealthed Harpy Ambushers and an elite harpy that patrols."] = "Vers le nord, à {area:383} : {quest:876} mène les harpies Witchwing dans les collines à l'ouest.\nAttention : le chemin passe près de Harpies embusquées invisibles et d'une harpie d'élite qui patrouille.",
		["North up the road from {area:2539}: {npc:11858} and his Grimtotem Brutes hold the bend in the road, and the Deepmoss Creepers and Venomspitters lurk in the webs on both sides of the path all the way up."] = "Remontez la route vers le nord depuis {area:2539} : {npc:11858} et ses Brutes Totem sinistre tiennent le virage de la route, et les Rampants de Mousseprofonde et les Crache-venin guettent dans les toiles des deux côtés du chemin jusqu'en haut.",
		["North up the {area:458} to the Crossroads: {npc:3448} at the south gate, {npc:3432} by the inn, {npc:3428} west of the north gate."] = "Remontez la {area:458} vers le nord jusqu'à la Croisée : {npc:3448} à la porte sud, {npc:3432} près de l'auberge, {npc:3428} à l'ouest de la porte nord.",
		["North up the {area:458} to the Crossroads: {npc:3448} at the south gate, {npc:3432} by the inn, {npc:3428} west of the north gate. Keep the {item:5075}: {npc:3430} takes it on the next stop in {area:378}."] = "Remontez la {area:458} vers le nord jusqu'à la Croisée : {npc:3448} à la porte sud, {npc:3432} près de l'auberge, {npc:3428} à l'ouest de la porte nord. Gardez l'{item:5075} : {npc:3430} la prendra lors du prochain passage au {area:378}.",
		["North-west to the {area:383}: the Witchwing Slayers hold their western end; they wear the rings.\nCareful: Some stealthed harpy ambushers wait in the area and stay hidden until you get close. A level 19 elite harpy also patrols there."] = "Au nord-ouest jusqu'à {area:383} : les Tueuses Ensorçaile en tiennent l'extrémité ouest ; ce sont elles qui portent les anneaux.\nAttention : des harpies embusquées et camouflées attendent dans la zone et restent cachées jusqu'à ce que vous approchiez. Une harpie élite de niveau 19 patrouille aussi par là.",
		["On the top floor"] = "Au dernier étage",
		["On the way back down the {area:1076}, {npc:11856} is held in {npc:11858}'s hut at the bend in the road. Once you take her quest she walks straight off south-east to {area:2538}, the burned village, without waiting: stay close, or the quest fails.\nCareful: Three Grimtotems ambush her at the burned village and go for her, not you: pull them off her and kill their caster quickly."] = "En redescendant {area:1076}, {npc:11856} est retenue dans la hutte de {npc:11858}, au tournant de la route. Une fois sa quête acceptée, elle part directement vers le sud-est jusqu'à {area:2538}, le village incendié, sans vous attendre : restez près d'elle, sinon la quête échoue.\nAttention : trois Totem sinistre lui tendent une embuscade au village incendié et s'en prennent à elle, pas à vous : détournez-les d'elle et tuez vite leur lanceur de sorts.",
		["On the way back down the {area:458} to {area:378}: the Razormane Raiders among the Bristleback camps, either side of the road north of the camp, carry {item:277277}. Hand them to {npc:3432} on your last Crossroads stop."] = "En redescendant la {area:458} vers le {area:378} : les Pillards Tranchecrin, parmi les camps Dos-hirsute de part et d'autre de la route au nord du camp, portent les {item:277277}. Remettez-les à {npc:3432} lors de votre dernière halte à la Croisée.",
		["Plainstrider Beaks as you go"] = "Becs de trotteur des plaines en chemin",
		["Plainstriders roam the plains all over the {zone:1413}, and about one in four drops a beak: kill the ones you pass on the way."] = "Les Trotteurs des plaines parcourent les plaines partout dans les {zone:1413}, et environ un sur quatre lâche un bec : tuez ceux que vous croisez en chemin.",
		["Raptor Heads as you go"] = "Têtes de raptor en chemin",
		["Raptor nests"] = "Nids de raptors",
		["Razormane camp"] = "Camp Tranchecrin",
		["Razormane camp: {npc:3429}'s quilboar"] = "Camp Tranchecrin : les huttiers de {npc:3429}",
		["Savannah Patriarchs roam the plains east of {npc:3682}'s camp, and the Sprung Traps lie among them."] = "Les Patriarches de la savane rôdent dans les plaines à l'est du camp de {npc:3682}, et les Pièges à ressort se trouvent parmi eux.",
		["Savannah lions"] = "Lions de la savane",
		["South along the beach past the pirate camp to {area:385}, on the coast. The Theramore Marines and Preservers (15-16) drop the medals; {npc:3393} (20) and the two cannoneers (19) stand in the keep and on its walls.\nCareful: Each named target is linked to a healer and guards, and Fairmount has three extra marines with her. Killing the healer first makes the fight easier."] = "Vers le sud le long de la plage, après le camp des pirates, jusqu'à {area:385}, sur la côte. Les Soldats de marine et les Préservateurs de Theramore (15-16) lâchent les médailles ; {npc:3393} (20) et les deux canonniers (19) se tiennent dans le donjon et sur ses murs.\nAttention : chaque cible nommée est liée à un soigneur et à des gardes, et Fairmount a trois soldats de marine de plus avec elle. Tuer d'abord le soigneur facilite le combat.",
		["South down the road to the Crossroads: {npc:3449} stands on the tower platform, {npc:3448} at the south gate."] = "Descendez la route vers le sud jusqu'à la Croisée : {npc:3449} se tient sur la plateforme de la tour, {npc:3448} à la porte sud.",
		["South-east on the way back to the Crossroads: {quest:881}, a white lion, prowls the plains north of the Razormane camp.\nCareful: Savannah Huntresses roam around the lair. They respawn quickly and often join the fight alongside {quest:881}, so clear them out before you blow the horn.\nSunscale raptors here count toward the heads."] = "Au sud-est, sur le chemin du retour vers la Croisée : {quest:881}, un lion blanc, rôde dans les plaines au nord du camp Tranchecrin.\nAttention : des Chasseresses des savanes errent autour du repaire. Elles réapparaissent vite et rejoignent souvent le combat aux côtés de {quest:881} : éliminez-les avant de souffler dans la corne.\nLes raptors Solécaille d'ici comptent pour les têtes.",
		["South-west from {area:392} across the plains to the {area:1697}: the three nests sit together south-west of the oasis, and Sunscale Scytheclaws guard them. Each nest needs a {item:5165}: kill Sunscale raptors (most drop one) until you have three, then use a feather at each nest."] = "Au sud-ouest de {area:392}, traversez les plaines jusqu'à {area:1697} : les trois nids se trouvent ensemble au sud-ouest de l'oasis, et des Faucheurs solécaille les gardent. Chaque nid demande une {item:5165} : tuez des raptors solécaille (la plupart en laissent tomber une) jusqu'à en avoir trois, puis utilisez une plume à chaque nid.",
		["Speak to {npc:3389} again to start the attack: the Kolkar charge the bunkers just west of him in waves. Fight beside the grunts until {npc:9456} (elite, 20) arrives with two bodyguards, usually from the south, then click the banner over his body."] = "Parlez de nouveau à {npc:3389} pour lancer l'attaque : les kolkars chargent les bunkers juste à l'ouest de lui, par vagues. Combattez aux côtés des grunts jusqu'à l'arrivée de {npc:9456} (élite, 20) avec deux gardes du corps, en général par le sud, puis cliquez sur la bannière au-dessus de son corps.",
		["Still short of seven? Plainstriders are thickest on the plains north of the Crossroads, along the road north."] = "Pas encore les sept ? Les Trotteurs des plaines sont les plus nombreux dans les plaines au nord de la Croisée, le long de la route du nord.",
		["Still short of twelve? Sunscale Lashtails and Screechers roam the plains north-east of the Crossroads, on the way back south from {quest:881}'s lair."] = "Pas encore les douze ? Les Flagellants et les Hurleurs solécaille parcourent les plaines au nord-est de la Croisée, sur le chemin du retour vers le sud depuis le repaire de {quest:881}.",
		["Sunscale Scytheclaws hunt the plains around the {area:1697}; they drop the horns. {npc:3446} takes them back in {area:392}; any still missing come with {npc:3682}'s hills later.\nSouth-east toward the coast: the stolen silver lies in a raptor nest north-west of {area:385}."] = "Les Faucheurs solécaille chassent dans les plaines autour de {area:1697} ; ils lâchent les cornes. {npc:3446} les reprend à {area:392} ; celles qui manquent encore viendront plus tard avec les collines de {npc:3682}.\nAu sud-est vers la côte : l'argent volé se trouve dans un nid de raptor au nord-ouest du {area:385}.",
		["Sunscale raptors roam the plains north and east of the Crossroads, and about three in four drop a head: kill the ones you pass on the way. Careful: Sunscale Screechers call nearby allies within 30 yd once below 30% health."] = "Les raptors Solécaille parcourent les plaines au nord et à l'est de la Croisée, et environ trois sur quatre lâchent une tête : tuez ceux que vous croisez en chemin. Attention : les Hurleurs solécaille appellent leurs alliés à moins de 30 m une fois sous 30 % de vie.",
		["Tauren: the {npc:11957} waits on the southern hill above the bridge. Skyborne: the {npc:272054} stands south of the twin bridges. Then the dens east of the lake: leave your form, click the statue at the entrance for five minutes of stealth, keep clear of the spirits inside and take one of each relic; the {item:280680} lies at the foot of the white cat statue. Careful: the spirits are Territorial Terrans (level 60) that kill whoever they see: stay off their paths, and click the statue again before the stealth runs out."] = "Taurens : le {npc:11957} attend sur la colline sud au-dessus du pont. Éolides : l'{npc:272054} se tient au sud des ponts jumeaux. Ensuite, les tanières à l'est du lac : quittez votre forme, cliquez sur la statue à l'entrée pour cinq minutes de camouflage, évitez les esprits à l'intérieur et prenez une relique de chaque ; la {item:280680} se trouve au pied de la statue de chat blanc. Attention : les esprits sont des Territorial Terrans (niveau 60) qui tuent quiconque ils voient : restez hors de leurs trajets, et cliquez de nouveau sur la statue avant la fin du camouflage.",
		["The Bristleback quilboar camps spread over the plains north of {area:378}, either side of the {area:458}. {npc:3432}'s wife lies at their north edge, on your way south. Leave the quilboar for now: {npc:3430} in {area:378} wants the same camps cleared. {quest:883}, a grey kodo (level 22), sometimes wanders here: his hoof starts a quest. Leave him alone below level 21."] = "Les camps des huttiers Dos-hirsute s'étendent sur les plaines au nord du {area:378}, de part et d'autre de la {area:458}. La femme de {npc:3432} gît à leur lisière nord, sur votre chemin vers le sud. Laissez les huttiers pour l'instant : {npc:3430}, au {area:378}, veut qu'on nettoie ces mêmes camps. {quest:883}, un kodo gris (niveau 22), erre parfois par ici : son sabot lance une quête. Laissez-le tranquille avant le niveau 21.",
		["The Grimtotem camp is just north of {npc:11857}, a short walk off the road: Ruffians and Mercenaries stand among the tents."] = "Le camp Totem sinistre se trouve juste au nord de {npc:11857}, à quelques pas de la route : des Voyous et des Mercenaires se tiennent parmi les tentes.",
		["The Razormane camp lies east of the Crossroads. Warriors: the {object:58369} stands in the camp. Shamans: the quilboar drop the {item:5026}.\nCareful: The chest stands next to a broken wagon, guarded by a pair of Razormanes, including hunters that can pull more quilboar into the fight."] = "Le camp Tranchecrin se trouve à l'est de la Croisée. Guerriers : le {object:58369} se trouve dans le camp. Chamans : les huttiers lâchent le {item:5026}.\nAttention : le coffre est à côté d'un chariot cassé, gardé par deux Tranchecrin, dont des chasseurs qui peuvent attirer d'autres huttiers dans le combat.",
		["The Venture Co. Overseers and Enforcers at the mine in the north-east corner of the zone drop the {item:5097}."] = "Les Surveillants de la KapitalRisk et Massacreurs de la KapitalRisk de la mine au nord-est de la zone laissent l'{item:5097}.",
		["The antennae vanish fifteen minutes after they drop: kill the Silithid Swarmers and Creepers at the Silithid Mounds in the {area:390}, south of {area:378}, until you have five, then take them straight to {npc:6394} in {area:378}, before the thunderhawks. Careful: Silithid Swarmers (level 21-22) cast {npc:4196} both in and out of combat, which brings several small adds; Silithid Creepers (level 20-21) periodically cast {npc:5781} in combat, which spawns extra adds. A {npc:3253} (24, rare) also wanders the mounds: leave it."] = "Les antennes disparaissent quinze minutes après être tombées : tuez les Grouillants et les Rampants silithides aux Antres des silithides du {area:390}, au sud du {area:378}, jusqu'à en avoir cinq, puis apportez-les directement à {npc:6394} au {area:378}, avant les faucons-tonnerre. Attention : les Grouillants silithides (niveau 21-22) lancent {npc:4196} en combat comme hors combat, ce qui fait venir plusieurs petits renforts ; les Rampants silithides (niveau 20-21) lancent régulièrement {npc:5781} en combat, ce qui fait apparaître des renforts supplémentaires. Un {npc:3253} (24, rare) erre aussi sur les antres : laissez-le.",
		["The next guide goes north-east across the {zone:1413} to the {area:1703} and {zone:1440}."] = "Le guide suivant traverse les {zone:1413} vers le nord-est jusqu'au {area:1703}, puis en {zone:1440}.",
		["The pirates camp on the beach south of {area:392}: the piles of complicated parts lie in the sand among them. {npc:3467} (16) stands at the camp's southern end: leave him for the next {area:392} stop."] = "Les pirates campent sur la plage au sud de {area:392} : les tas de pièces compliquées sont dans le sable au milieu d'eux. Le {npc:3467} (16) se tient à l'extrémité sud du camp : laissez-le pour la prochaine halte à {area:392}.",
		["The pools lie just north of {npc:3389}. Walk into the water to explore them; the Laden Mushrooms for Helbrim grow around them. Kill every Kolkar you pass for bracers. {npc:3394} stands in the Kolkar camp west of the pools."] = "Les bassins se trouvent juste au nord de {npc:3389}. Entrez dans l'eau pour les explorer ; les Champignons chargés pour Helbrim poussent autour. Tuez chaque kolkar sur votre passage pour les brassards. {npc:3394} se tient dans le camp kolkar à l'ouest des bassins.",
		["The road climbs north as the {area:1076}. {quest:1483} has a hut where the road forks east to {area:461}."] = "La route grimpe vers le nord : c'est {area:1076}. {quest:1483} a une cabane là où la route bifurque vers l'est en direction de {area:461}.",
		["The tool buckets with the slugs lie around the Venture Co. drill site in the {area:382}."] = "Les seaux à outils avec les rondelles se trouvent autour du site de forage de la KapitalRisk, dans {area:382}.",
		["The {area:2363}"] = "{area:2363}",
		["The {object:172960} is the canyon under the {object:172982}."] = "{object:172960} est le canyon sous {object:172982}.",
		["The {object:177794} lies at the north edge of the {area:382}, by the Venture Co. tower. It holds the {item:15883} for {quest:30}."] = "{object:177794} se trouve au bord nord de {area:382}, près de la tour de la KapitalRisk. Il contient le {item:15883} pour {quest:30}.",
		["The {object:4141} stands at the Venture Co. research site west of the {area:382}. Close the three valves around the drill, use the console again, then take the {item:5089} from {npc:3471} beside it.\nCareful: Several guards stand within aggro range of the valves, respawn in under about 3 minutes, and run at low health to bring back help; nearby mobs also join if you use a valve while they are close."] = "La {object:4141} se trouve sur le site de recherche de la KapitalRisk, à l'ouest de {area:382}. Fermez les trois vannes autour de la foreuse, utilisez à nouveau la console, puis prenez la {item:5089} sur l'{npc:3471}, juste à côté.\nAttention : plusieurs gardes se tiennent à portée d'aggro des vannes, réapparaissent en moins de 3 minutes environ et fuient à faible vie pour ramener de l'aide ; les monstres proches se joignent aussi au combat si vous utilisez une vanne près d'eux.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:209797} (level 20 elite) needs a group of 2. Skip it if you are alone."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {npc:209797} (élite de niveau 20) demande un groupe de 2. Passez-le si vous êtes seul.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:267307} (level 20 elite) needs a group of 3 and sits deep in the cave under {area:1699}, past the Razormane Flesheaters and Berserkers (18-19, elite). Skip it if you are alone."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {npc:267307} (élite de niveau 20) demande un groupe de 3 et se tient au fond de la grotte sous {area:1699}, après les Dévoreuses et les Berserkers tranchecrin (18-19, élites). Passez-le si vous êtes seul.",
		["Thunderhawk Cloudscrapers circle over the plains south of the camp."] = "Les Faucons-tonnerre des nuages tournoient au-dessus des plaines au sud du camp.",
		["Thunderheads graze on the plains just south of {area:378}. {quest:884}, a blue thunder lizard (level 24), roams among them: his Tailspike starts a quest. Leave him alone below level 23."] = "Les Têtes-tonnerre paissent dans les plaines juste au sud du {area:378}. {quest:884}, un lézard-tonnerre bleu (niveau 24), erre parmi eux : sa pointe caudale lance une quête. Laissez-le tranquille avant le niveau 23.",
		["To {area:2539}"] = "Vers {area:2539}",
		["To {npc:3389}"] = "Vers {npc:3389}",
		["Train your level 20 ranks in {area:1637} now: fly from {npc:3615} on the Crossroads' tower."] = "Apprenez maintenant vos rangs du niveau 20 à {area:1637} : prenez un vol auprès de {npc:3615}, sur la tour de la Croisée.",
		["Train your level 20 ranks: {npc:246344} teaches Paladins in {area:1638}; {zone:1454} has no Paladin trainer. You have no flight path there yet: fly to {area:378}, head west through {zone:1412} and up a lift, and take the flight path from {npc:2995} on the central rise."] = "Apprenez vos rangs du niveau 20 : {npc:246344} forme les Paladins aux {area:1638} ; {zone:1454} n'a pas de maître Paladin. Vous n'avez pas encore ce trajet aérien : volez jusqu'au {area:378}, allez vers l'ouest à travers {zone:1412} et montez par un ascenseur, puis prenez le trajet auprès de {npc:2995} sur la mesa centrale.",
		["Twitching Antennae"] = "Antennes frémissantes",
		["Twitching Antennae from the silithid"] = "Antennes mobiles sur les silithides",
		["Underwater"] = "Sous l'eau",
		["Upstairs"] = "À l'étage",
		["Venture Co. Loggers, all over the clear-cut"] = "Bûcherons de la KapitalRisk, partout dans la coupe rase",
		["Warriors: take {quest:1824} from {npc:6394} now: it runs for 30 minutes from the accept. The antennae come first, at the Silithid Mounds south of the camp, then straight back to {npc:6394}; the thunderhawks after."] = "Guerriers : prenez maintenant {quest:1824} auprès de {npc:6394} : elle dure 30 minutes à partir de son acceptation. Les antennes d'abord, aux Antres des silithides au sud du camp, puis retournez directement voir {npc:6394} ; les faucons-tonnerre ensuite.",
		["West from the burned village to {area:2539}: {npc:12816} stands just outside it, before the village."] = "À l'ouest du village incendié, jusqu'à {area:2539} : {npc:12816} se tient juste à l'extérieur, avant le village.",
		["West from the mine to {npc:9316}'s camp, then south down the road to the Crossroads."] = "À l'ouest de la mine jusqu'au camp de {npc:9316}, puis descendez la route vers le sud jusqu'à la Croisée.",
		["West to the {area:383}. Any Witchwing harpy drops a talon: keep to the eastern slopes, where the Witchwing Harpies and Roguefeathers (14-15) nest; the Slayers and Windcallers (16-17) hold the western hills. Savannah Prowlers hunt the plains between {npc:3389} and the hills: take their claws on the way.\nCareful: There are 2 Witchwing Ambushers (level 17-18). They stay stealthed with Sneak while out of combat."] = "Vers l'ouest jusqu'à {area:383}. N'importe quelle harpie Ensorçaile lâche une serre : restez sur les pentes est, où nichent les Harpies et les Plumes-folles Ensorçaile (14-15) ; les Tueuses et les Implorevent (16-17) tiennent les collines ouest. Les Rôdeurs des savanes chassent dans les plaines entre {npc:3389} et les collines : prenez leurs griffes en chemin.\nAttention : il y a 2 Embusquées Ensorçaile (niveau 17-18). Elles restent camouflées grâce à Furtivité tant qu'elles ne sont pas en combat.",
		["West to {npc:3389}'s watch post on the Kolkar border."] = "À l'ouest vers le poste de guet de {npc:3389}, à la frontière kolkar.",
		["While you are in the camp: {npc:3429}'s Water Seekers and Thornweavers in its western half, the Hunters in the middle, the supply crates at its eastern end.\nCareful: Razormane Flesheaters and Berserkers (18-19) are elites; they stand in the camp's north-east, beside the supply crates: pull the quilboar away from them one at a time."] = "Tant que vous êtes dans le camp : les Sourciers et les Tisseuses d'épines de {npc:3429} dans sa moitié ouest, les Chasseurs au milieu, les caisses de ravitaillement à son extrémité est.\nAttention : les Dévoreuses et les Berserkers tranchecrin (18-19) sont des élites ; ils se tiennent au nord-est du camp, à côté des caisses de ravitaillement : attirez les hurans un par un loin d'eux.",
		["Wizzlecrank drives his shredder out of the camp: stay with him and kill whatever attacks him. {npc:3442} takes it in {area:392}.\nCareful: The route leads west and climbs a ramp. Once you reach the top, two Venture Company mobs ambush you."] = "Wizzlecrank sort du camp avec son déchiqueteur : restez avec lui et tuez tout ce qui l'attaque. {npc:3442} le récupère à {area:392}.\nAttention : la route mène vers l'ouest et monte une rampe. Une fois en haut, deux monstres de la KapitalRisk vous tendent une embuscade.",
		["You arrive from {area:379}. {npc:3489} and {npc:3338} stand by the inn, Helbrim and {npc:3464} by the north gate; {npc:3615}, {npc:3429} and {npc:3449} on the tower platform."] = "Vous arrivez du {area:379}. {npc:3489} et {npc:3338} se tiennent près de l'auberge, Helbrim et {npc:3464} près de la porte nord ; {npc:3615}, {npc:3429} et {npc:3449} sur la plateforme de la tour.",
		["Zhevra Runners graze along the road east toward {area:392}: take their hooves on the way out."] = "Les Messagers zhévras paissent le long de la route vers l'est en direction de {area:392} : prenez leurs sabots en sortant.",
		["grind on {npc:3263}"] = "tuez des {npc:3263}",
		["the Crossroads"] = "la Croisée",
		["{area:1076}: kill these as you meet them"] = "{area:1076} : tuez-les au passage",
		["{area:1697}: kill these as you meet them"] = "{area:1697} : tuez-les au passage",
		["{area:380} is your base for this guide. Everyone you need stands within a few steps of the inn: {npc:3338} by the inn, Helbrim and {npc:3464} by the north gate, then up the tower to {npc:3615}, the wind rider master, {npc:3429} and {npc:3449}, and {npc:3448} at the south gate on the way out."] = "{area:380} est votre base pour ce guide. Tous ceux dont vous avez besoin se tiennent à quelques pas de l'auberge : {npc:3338} près de l'auberge, Helbrim et {npc:3464} près de la porte nord, puis en haut de la tour {npc:3615}, le maître des coursiers du vent, {npc:3429} et {npc:3449}, et {npc:3448} à la porte sud en sortant.",
		["{area:385}: kill these as you meet them"] = "{area:385} : tuez-les au passage",
		["{area:392} flight master"] = "Maître de vol de {area:392}",
		["{area:392}: {area:718} quests"] = "{area:392} : quêtes de {area:718}",
		["{area:718} is a dungeon for a group of five, about levels 17 to 24, and a full run takes about an hour. Its mouth is just north of {npc:3396}'s shore, at the north end of {area:387}, under {npc:5767}'s cave.\nIn the caves before the portal: {npc:3655}, stealthed, with the {item:5334} (he moves between a few spots and comes back slowly: leave him if he's gone). Inside: the Deviates for {npc:5768}, and their hides for {npc:5767} (they drop rarely: one run may not be enough, so leave the rest for another run), {item:6464} from the Ectoplasms. After the four Fanglords, the {npc:3678} at the entrance leads you to Naralex: {npc:3654} drops the {item:10441}: its quest (someone in {area:392}, then {npc:8418} above the caverns) is not on this route; the Dungeons page's hand-in guide takes it."] = "{area:718} est un donjon pour un groupe de cinq, vers les niveaux 17 à 24, et une expédition complète prend environ une heure. Son entrée se trouve juste au nord de la rive de {npc:3396}, à l'extrémité nord de {area:387}, sous la grotte de {npc:5767}.\nDans les grottes avant le portail : {npc:3655}, camouflé, avec le {item:5334} (il se déplace entre quelques endroits et réapparaît lentement : laissez-le s'il n'est pas là). À l'intérieur : les Déviants pour {npc:5768}, et leurs peaux pour {npc:5767} (elles tombent rarement : une expédition peut ne pas suffire, alors gardez le reste pour une autre expédition), {item:6464} sur les Ectoplasmes. Après les quatre Seigneurs du Croc, le {npc:3678} à l'entrée vous mène à Naralex : {npc:3654} lâche le {item:10441} : sa quête (quelqu'un à {area:392}, puis {npc:8418} au-dessus des cavernes) ne fait pas partie de cet itinéraire ; le guide des rendus de la page Donjons s'en charge.",
		["{item:10338}, from any zhevra; Zhevra Chargers graze around the tree"] = "{item:10338}, sur n'importe quel zhévra ; des Étalons zhévra paissent autour de l'arbre",
		["{item:15877}, from a {object:177785} in the lake"] = "{item:15877}, dans un {object:177785} au fond du lac",
		["{item:2449} from {npc:3490}; herbalists pick it on the plains"] = "{item:2449} auprès de {npc:3490} ; les herboristes en cueillent dans les plaines",
		["{item:6464}: the Ectoplasms"] = "{item:6464} : les Ectoplasmes",
		["{npc:11798} in {area:2361} flies druids there"] = "{npc:11798} à {area:2361} y emmène les druides",
		["{npc:11799}, at the {area:2362}"] = "{npc:11799}, à {area:2362}",
		["{npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart."] = "{npc:11802} se tient à l'étage de son bâtiment à {area:2361} : montez par l'intérieur, la flèche ne distingue pas les étages.",
		["{npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart. The Shrine Baubles lie on the bed of {area:656} and fade within minutes: swim one straight to the {area:2362} on the north-west shore, use it there and speak to {npc:11799}. {quest:28} runs on a timer: no teleport or Hearthstone until {npc:11799} has it."] = "{npc:11802} se tient à l'étage de son bâtiment à {area:2361} : montez par l'intérieur, la flèche ne distingue pas les étages. Les Colifichets du sanctuaire reposent au fond du {area:656} et disparaissent en quelques minutes : nagez avec l'un d'eux directement jusqu'au {area:2362}, sur la rive nord-ouest, utilisez-le là-bas et parlez à {npc:11799}. {quest:28} est minutée : ni téléportation ni pierre de foyer tant que {npc:11799} ne l'a pas.",
		["{npc:11802}: the welcome from {npc:3033}"] = "{npc:11802} : l'accueil de {npc:3033}",
		["{npc:11856}, inside {npc:11858}'s hut"] = "{npc:11856}, dans la hutte de {npc:11858}",
		["{npc:11857}: keep it, {npc:11864} at {area:460} in the {zone:1413} & Stonetalon guide"] = "{npc:11857} : gardez-la, {npc:11864} à {area:460}, dans le guide {zone:1413} et Serres-Rocheuses",
		["{npc:11858} waits up the {area:1076}"] = "{npc:11858} attend en haut du {area:1076}",
		["{npc:12296}: use the {item:15826} on them; they roam the plains all around the Crossroads"] = "{npc:12296} : utilisez l'{item:15826} sur elles ; elles parcourent les plaines tout autour de la Croisée",
		["{npc:12816}: the spiders along the {area:1076}"] = "{npc:12816} : les araignées le long du {area:1076}",
		["{npc:16227}, beside {npc:3442}"] = "{npc:16227}, à côté de {npc:3442}",
		["{npc:261366}, the hermit on the ridge behind {npc:3682}: on the next {area:383} visit, with {npc:3452}"] = "{npc:261366}, l'ermite sur la crête derrière {npc:3682} : lors de la prochaine visite de {area:383}, avec {npc:3452}",
		["{npc:261366}, the hermit, stands on the ridge behind {npc:3682}'s camp."] = "{npc:261366}, l'ermite, se tient sur la crête derrière le camp de {npc:3682}.",
		["{npc:262119} and his marines hold the wrecked caravan south of {npc:261366}. The marines are linked: pulling one calls the rest. Pull from the edge and run; they leash short, so you can thin the camp one at a time before tackling the Corporal."] = "Le {npc:262119} et ses soldats de marine tiennent la caravane détruite au sud de {npc:261366}. Les soldats sont liés : en attirer un fait venir les autres. Attirez-les depuis le bord et courez ; ils abandonnent vite la poursuite, vous pouvez donc éclaircir le camp un par un avant d'affronter le caporal.",
		["{npc:267310} stands on the north-east side of the Crossroads. {quest:97003} is a group quest: {npc:267307} is a level 20 elite boar in the Razormane's {area:1699} cave, east of the town, where the route goes back for {npc:3438} later."] = "{npc:267310} se tient dans la partie nord-est de la Croisée. {quest:97003} est une quête de groupe : {npc:267307} est un sanglier élite de niveau 20 dans la grotte de {area:1699} des Tranchecrin, à l'est de la ville, où l'itinéraire revient plus tard pour {npc:3438}.",
		["{npc:3338} by the inn first, then Helbrim by the north gate, {npc:3429} and {npc:3449} on the tower platform, {npc:3432} by the inn, and {npc:3448} at the south gate last. His seed test waits for the {npc:3395} pass at the {area:388}: go straight on north-west to the {area:383}. After the spores Helbrim offers {quest:853}, a delivery to {zone:1456} within 45 minutes: this route doesn't go there, so leave it (Druids take it on the next Crossroads stop, right before their flight to {zone:1456})."] = "{npc:3338} près de l'auberge d'abord, puis Helbrim près de la porte nord, {npc:3429} et {npc:3449} sur la plateforme de la tour, {npc:3432} près de l'auberge, et {npc:3448} à la porte sud en dernier. Son test des graines attend le passage pour {npc:3395} à {area:388} : continuez tout droit vers le nord-ouest jusqu'à {area:383}. Après les spores, Helbrim propose {quest:853}, une livraison à {zone:1456} en moins de 45 minutes : cet itinéraire n'y va pas, laissez-la donc (les druides la prennent à l'arrêt suivant à la Croisée, juste avant leur vol pour {zone:1456}).",
		["{npc:3338}: the raptor nests south of the Crossroads"] = "{npc:3338} : les nids de raptors au sud de la Croisée",
		["{npc:3354} is in the {object:172958}, {npc:5892} in the {object:172957}."] = "{npc:3354} est dans la {object:172958}, {npc:5892} dans la {object:172957}.",
		["{npc:3389}: {npc:3395} comes out when you kill the Kolkar at the {area:388}, later"] = "{npc:3389} : {npc:3395} apparaît quand vous tuez les kolkars à {area:388}, plus tard",
		["{npc:3390}: 45 minutes, for Zamah on the {zone:1456} step next"] = "{npc:3390} : 45 minutes, pour Zamah à l'étape suivante, à {zone:1456}",
		["{npc:3390}: {quest:1358}, from Zinge"] = "{npc:3390} : {quest:1358}, de la part de Zinge",
		["{npc:3391} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{npc:3391} se tient à l'étage de son bâtiment : montez par l'intérieur, la flèche ne distingue pas les étages.",
		["{npc:3391}, upstairs"] = "{npc:3391}, à l'étage",
		["{npc:3391}: the crates lie at the south end of the beach camp, on the next {area:392} stop at 18"] = "{npc:3391} : les caisses se trouvent à l'extrémité sud du camp de la plage, lors de la prochaine halte à {area:392} au niveau 18",
		["{npc:3395} doesn't wander on his own: he comes out when you kill the Kolkar centaurs at the {area:388}, south-east of the Crossroads. Keep killing them around the oasis until he appears. Test {npc:3448}'s seeds at the bubbling fissure on the oasis' east bank while you are there."] = "{npc:3395} ne se promène pas seul : il apparaît quand vous tuez les centaures kolkars à {area:388}, au sud-est de la Croisée. Continuez à les tuer autour de l'oasis jusqu'à ce qu'il apparaisse. Testez les graines de {npc:3448} à la fissure bouillonnante sur la rive est de l'oasis pendant que vous y êtes.",
		["{npc:3396} leads the Kolkar on the west shore of {area:387}, south of {npc:3389}. He walks that shore, from about 46,36 in the north to 46,42 in the south: if he isn't at the arrow, follow the shore until you meet him. Hand his head to {npc:3389} on your last Crossroads stop. Oasis Snapjaws crawl in the oasis' water there: their shells are for {npc:3448}."] = "{npc:3396} mène les Kolkar sur la rive ouest de {area:387}, au sud de {npc:3389}. Il parcourt cette rive, d'environ 46,36 au nord à 46,42 au sud : s'il n'est pas à la flèche, suivez la rive jusqu'à le trouver. Rendez sa tête à {npc:3389} lors de votre dernier arrêt à la Croisée. Des Gueules d'acier des oasis rampent là dans l'eau de l'oasis : leurs carapaces sont pour {npc:3448}.",
		["{npc:3428}'s {quest:868} waits for this guide's last Crossroads stop: its eggs come on the next {zone:1413} guide's walk south, at about 25."] = "{quest:868} de {npc:3428} attend la dernière halte de ce guide à la Croisée : ses œufs viennent lors de la descente vers le sud du prochain guide des {zone:1413}, vers le niveau 25.",
		["{npc:3428}, west of the north gate: keep {quest:868}, its eggs lie on the next {zone:1413} guide's walk south from {area:378}, at about 25"] = "{npc:3428}, à l'ouest de la porte nord : gardez {quest:868}, ses œufs se trouvent sur le trajet vers le sud depuis le {area:378} du prochain guide de {zone:1413}, vers le niveau 25",
		["{npc:3429}, at the top of the tower"] = "{npc:3429}, en haut de la tour",
		["{npc:3429}, on the tower, from level 17. Keep it: Kadrak at the {area:1703}, next guide"] = "{npc:3429}, sur la tour, dès le niveau 17. Gardez-la : Kadrak au {area:1703}, guide suivant",
		["{npc:3430}, in the cage"] = "{npc:3430}, dans la cage",
		["{npc:3432} offers {quest:95774} once {quest:4921} is handed in"] = "{npc:3432} propose {quest:95774} une fois {quest:4921} rendue",
		["{npc:3432}: his wife lies at the north edge of the Bristleback camps, later"] = "{npc:3432} : sa femme gît à la lisière nord des camps Dos-hirsute, plus tard",
		["{npc:3439} stands inside the Venture Co. camp in the {area:382}; {npc:3445} carries the key."] = "Le {npc:3439} se trouve dans le camp de la KapitalRisk, dans {area:382} ; le {npc:3445} porte la clé.",
		["{npc:3442} in {area:392}: on the next {area:392} stop"] = "{npc:3442} à {area:392} : lors de la prochaine étape à {area:392}",
		["{npc:3442}: keep it, {quest:1483} is on the {area:1076} in Stonetalon, at the end of this guide"] = "{npc:3442} : gardez-la, {quest:1483} se trouve sur le {area:1076}, dans les Serres-Rocheuses, à la fin de ce guide",
		["{npc:3442}: the console is in the {area:382}, later"] = "{npc:3442} : la console est dans {area:382}, plus tard",
		["{npc:3442}: {npc:9316} stands on the road north of the Crossroads, on the way to the {area:382}"] = "{npc:3442} : {npc:9316} se tient sur la route au nord de la Croisée, sur le chemin du {area:382}",
		["{npc:3448}: the Oasis Snapjaws at {area:387}, with {npc:3396} after the {zone:1454} trip"] = "{npc:3448} : les Gueules d'acier des oasis à {area:387}, avec {npc:3396} après le voyage à {zone:1454}",
		["{npc:3448}: the bubbling fissure at the {area:388}, on the {npc:3395} pass"] = "{npc:3448} : la fissure bouillonnante à {area:388}, lors du passage pour {npc:3395}",
		["{npc:3449}, on the tower: {quest:876} leads the harpies in the {area:383}"] = "{npc:3449}, sur la tour : {quest:876} mène les harpies des {area:383}",
		["{npc:3449}: the harpies come later, in the {area:383}"] = "{npc:3449} : les harpies viendront plus tard, dans {area:383}",
		["{npc:3464}, by the Crossroads' north gate"] = "{npc:3464}, près de la porte nord de la Croisée",
		["{npc:3464}: the {quest:3281}, in a raptor nest north-west of {area:385}"] = "{npc:3464} : l'{quest:3281}, dans un nid de raptor au nord-ouest du {area:385}",
		["{npc:3465} is chained inside the hold. Talk to him to start the escort and stay close: Theramore soldiers attack on the way out. He walks you back to {area:392}."] = "{npc:3465} est enchaîné dans le fort. Parlez-lui pour lancer l'escorte et restez près de lui : des soldats de Theramore attaquent à la sortie. Il vous ramène à {area:392}.",
		["{npc:3615}, on the tower"] = "{npc:3615}, sur la tour",
		["{npc:4049} and {npc:11857} share the camp on the road west to Stonetalon."] = "{npc:4049} et {npc:11857} partagent le camp sur la route de l'ouest vers les Serres-Rocheuses.",
		["{npc:4049}'s camp"] = "Camp de {npc:4049}",
		["{npc:4049}: the Venture loggers at {area:461}"] = "{npc:4049} : les bûcherons de la KapitalRisk à la {area:461}",
		["{npc:4049}: {quest:1063}, Magatha in {zone:1456}, on the next guide's way back from Zoram'gar"] = "{npc:4049} : {quest:1063}, Magatha aux {zone:1456}, sur le chemin du retour de Zoram'gar dans le prochain guide",
		["{npc:4197} lives in {area:2539}, the troll village just inside Stonetalon at the end of the road west from {npc:3389}."] = "{npc:4197} vit à {area:2539}, le village troll juste à l'entrée des Serres-Rocheuses, au bout de la route qui part vers l'ouest depuis {npc:3389}.",
		["{npc:4201}, inside"] = "{npc:4201}, à l'intérieur",
		["{npc:4201}: for {npc:3442}, beside {area:392}'s flight master at the end of the {zone:1413} & Stonetalon guide"] = "{npc:4201} : pour {npc:3442}, à côté du maître de vol de {area:392}, à la fin du guide {zone:1413} et Serres-Rocheuses",
		["{npc:4276}'s defence is hard alone at this level: grouping up is encouraged, look for people to do it with. Skip it if you are alone.\n{npc:4276} mines at the bottom of the {area:2160} on the east side of the crag, past its kobolds (levels 19-23). Talk to him, then keep him alive for five minutes while he mines: a dozen or more kobolds come at him in waves, melee fighters first, then casters, and the mine's own kobolds respawn into the fight. If he dies, the quest fails."] = "La défense de {npc:4276} est difficile seul à ce niveau : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. Passez-la si vous êtes seul.\n{npc:4276} creuse au fond de la {area:2160}, du côté est de la falaise, après ses kobolds (niveaux 19-23). Parlez-lui, puis gardez-le en vie pendant cinq minutes pendant qu'il mine : une douzaine de kobolds ou plus l'attaquent par vagues, d'abord des combattants au corps à corps, puis des lanceurs de sorts, et les kobolds de la mine réapparaissent dans le combat. S'il meurt, la quête échoue.",
		["{npc:4276}, below ground"] = "{npc:4276}, sous terre",
		["{npc:5767} and {npc:5768}"] = "{npc:5767} et {npc:5768}",
		["{npc:5878} camps beside the road east of the Crossroads."] = "{npc:5878} campe au bord de la route à l'est de la Croisée.",
		["{npc:5878} camps beside the road east toward {area:392}."] = "{npc:5878} campe au bord de la route à l'est, vers {area:392}.",
		["{npc:5899}'s hut stands on the ridge above the quilboar watering hole, south of {area:378}: fill the {item:7766} at the watering hole below it."] = "La hutte de {npc:5899} se dresse sur la crête au-dessus du point d'eau des huttiers, au sud du {area:378} : remplissez l'{item:7766} au point d'eau en contrebas.",
		["{npc:5901} waits on the hill south of {area:392}, on your way north."] = "{npc:5901} attend sur la colline au sud de {area:392}, sur votre route vers le nord.",
		["{npc:5907}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:5907} : {npc:2523}, votre {item:5176} et le {item:263412}",
		["{npc:5909}, a few steps away"] = "{npc:5909}, à quelques pas",
		["{npc:6018} stands in the {object:172961} on the city's west side."] = "{npc:6018} se tient dans {object:172961}, à l'ouest de la ville.",
		["{npc:6018} stands in the {object:172961}, on the city's west side."] = "{npc:6018} se tient dans la {object:172961}, à l'ouest de la ville.",
		["{npc:6018}: {npc:4606} in the {zone:1458}, two guides on"] = "{npc:6018} : {npc:4606} à {zone:1458}, dans deux guides",
		["{npc:6394}, inside"] = "{npc:6394}, à l'intérieur",
		["{quest:1483}, inside"] = "{quest:1483}, à l'intérieur",
		["{quest:1492}, on the dock"] = "{quest:1492}, sur le quai",
		["{quest:1492}: the emerald comes from the {area:381}, later"] = "{quest:1492} : l'émeraude vient de la {area:381}, plus tard",
		["{quest:2458}: {npc:7233}, by the {area:382} on the next guide's walk north"] = "{quest:2458} : {npc:7233}, près du {area:382}, sur le trajet vers le nord du guide suivant",
		["{quest:30}, carried: one half pendant in the {area:382} in this guide, the other underwater off Silverpine on the way to {area:287} at 21; the pendant is handed in after {area:287}"] = "{quest:30}, à garder : une moitié de pendentif dans le {area:382} dans ce guide, l'autre sous l'eau au large de la forêt des Pins-Argentés sur le chemin d'{area:287} au niveau 21 ; le pendentif se rend après {area:287}",
		["{quest:3923} stands by the {object:172958}'s water, east of the Drag."] = "{quest:3923} se tient au bord de l'eau de la {object:172958}, à l'est de la Herse.",
		["{quest:6127}: {area:384}, next guide"] = "{quest:6127} : {area:384}, guide suivant",
		["{quest:809}, beside {npc:3337}: from {npc:3216} in {zone:1454}"] = "{quest:809}, à côté de {npc:3337} : de la part de {npc:3216} à {zone:1454}",
		["{quest:853}, in the {area:2197}"] = "{quest:853}, dans {area:2197}",
		["{quest:865}, if still open: Sunscale Scytheclaws prowl among the lions below {npc:3682}'s camp"] = "{quest:865}, si elle est encore ouverte : les Sunscale Scytheclaws rôdent parmi les lions sous le camp de {npc:3682}",
		["{quest:882}, a big Sunscale raptor, only comes to a fresh kill: loot a {item:10338} from a zhevra, then use it at the {object:147538} north-west of {area:392}, north of the road to the Crossroads, and be ready when he arrives."] = "{quest:882}, un grand raptor solécaille, ne vient que sur une proie fraîche : prenez une {item:10338} sur un zhévra, puis utilisez-la près de {object:147538} au nord-ouest de {area:392}, au nord de la route de la Croisée, et soyez prêt quand il arrive.",
		["{zone:1413}: kill these as you meet them"] = "{zone:1413} : tuez-les au passage",
		["{zone:1454} class quests"] = "Quêtes de classe à {zone:1454}",
		["{zone:1454} flight master"] = "Maître de vol d'{zone:1454}",
		["{zone:1454}'s level 20 class quests come right after the Crossroads, and they are offered only from 20. Still short of 20? The Bristleback Geomancers (19-20) hold {area:1700} around you: kill them until level 20. Or, with a group, run the {area:718} dungeon instead."] = "Les quêtes de classe du niveau 20 à {zone:1454} viennent juste après la Croisée, et ne sont proposées qu'à partir du niveau 20. Pas encore niveau 20 ? Les Géomanciennes Dos-hirsute (19-20) occupent {area:1700} autour de vous : tuez-en jusqu'au niveau 20. Ou, en groupe, faites plutôt le donjon des {area:718}.",
		["{zone:1456} flight master"] = "Maître de vol des {zone:1456}",
} end)()
t.guides["forever/horde/03-silverpine-forest"] = (function() return {
		["Allister's Ambermill Investigations is for the ride through Silverpine at 22; leave it."] = "Les enquêtes d'Allister sur Moulambre sont pour la traversée de la forêt des Pins-Argentés au niveau 22 ; laissez-les.",
		["Back down the road past the zeppelin towers and east to {npc:1495}'s camp: {npc:267009} stands beside her."] = "Redescendez la route en passant les tours du zeppelin, puis à l'est jusqu'au camp de {npc:1495} : {npc:267009} se tient à côté d'elle.",
		["Back out through the portal: {npc:3216} stands beside it."] = "Ressortez par le portail : {npc:3216} se tient à côté.",
		["Class trainer"] = "Maître de classe",
		["Follow the lake shore south from the murlocs: the {object:1593} lies at the ferry landing."] = "Suivez la rive du lac vers le sud depuis les murlocs : le {object:1593} se trouve à l'embarcadère du bac.",
		["Follow the lake shore south-east from the Yoricks' house: the Vile Fin Shredders and Tidehunters along it drop the murloc eyes."] = "Suivez la rive du lac vers le sud-est depuis la maison des Yorick : les Déchiqueteurs Aileron noir et les Chasse-marée Aileron noir qui la longent lâchent les yeux de murloc.",
		["Follow the road north-east to the Yoricks' house at {area:238}."] = "Suivez la route vers le nord-est jusqu'à la maison des Yorick, à {area:238}.",
		["Follow the road south. The {object:1627} sits beside it, north of Pyrewood. Careful: Dalaran Apprentices (13) stand around the crate: pull them one at a time before you open it."] = "Suivez la route vers le sud. {object:1627} se trouve au bord, au nord de Bois-du-Bûcher. Attention : des Apprentis de Dalaran (13) se tiennent autour de la caisse : attirez-les un par un avant de l'ouvrir.",
		["For your {area:2437} run: the {object:172960} is the canyon under the {object:172982}; {npc:3216} stands at its far end, next to the {area:2437} portal."] = "Pour votre expédition dans {area:2437} : {object:172960} est le canyon sous {object:172982} ; {npc:3216} se tient tout au fond, à côté du portail de {area:2437}.",
		["From the ferry back west up the road to the {area:228}."] = "Depuis le bac, remontez la route vers l'ouest jusqu'à {area:228}.",
		["Inside"] = "À l'intérieur",
		["Mottled Worgs"] = "Worgs chamarrés",
		["Mottled Worgs prowl the hills around the house."] = "Les Worgs chamarrés rôdent sur les collines autour de la maison.",
		["North again to the Yoricks' house."] = "Retournez au nord jusqu'à la maison des Yorick.",
		["North of the {area:228}. {npc:1983} haunts the {area:240}: kill it, then walk across the field. Careful: {npc:1983} (14) rises once you have killed rot hide gnolls in the field: fight her with full health."] = "Au nord de {area:228}. {npc:1983} hante le {area:240} : tuez-le, puis traversez le champ. Attention : {npc:1983} (14) apparaît une fois que vous avez tué des gnolls Poil-Putride dans le champ : affrontez-la avec toute votre vie.",
		["On the road north, the farmhouse at {area:227}: go upstairs, the {object:1571} lie on the floor in the back room. Looting them brings a {npc:1770}."] = "Sur la route du nord, la ferme du {area:227} : montez à l'étage, les {object:1571} sont par terre dans la pièce du fond. Les ramasser fait venir un {npc:1770}.",
		["Speak with {npc:10181}, in the {object:36126}: {quest:93739}"] = "Parlez à {npc:10181}, dans {object:36126} : {quest:93739}",
		["Speak with {npc:10540}, in Grommash Hold"] = "Parlez à {npc:10540}, dans le fort Grommash",
		["Speak with {npc:3230}, in Grommash Hold"] = "Parlez à {npc:3230}, dans le fort Grommash",
		["Take the road north toward {zone:1420}: the Yoricks' house at {area:238} is on the way. {quest:425} lurks a short walk west of it."] = "Prenez la route du nord vers {zone:1420} : la maison des Yorick, à {area:238}, est sur le chemin. {quest:425} rôde à courte distance à l'ouest.",
		["Talk to {npc:10181}"] = "Parlez à {npc:10181}",
		["Talk to {npc:10540}"] = "Parlez à {npc:10540}",
		["Talk to {npc:3230}"] = "Parlez à {npc:3230}",
		["The cattails and speargrass grow along the water in the {object:172958}, east of the Drag."] = "Les massettes et les herbes-lances poussent au bord de l'eau dans {object:172958}, à l'est de la Herse.",
		["The cultists camp a short walk south-east of {npc:267009}. Dark Neophytes and Dark Enforcers drop the Necrotic Crystal Fragments; more fragments, black crystals, lie on the ground among the tents."] = "Les cultistes campent à quelques pas au sud-est de {npc:267009}. Les Néophytes et les Massacreurs sombres lâchent les Fragments de cristal nécrotique ; d'autres fragments, des cristaux noirs, sont au sol parmi les tentes.",
		["The {object:172960} is the canyon under the {object:172982}; {quest:829} stands at its far end."] = "{object:172960} est le canyon sous {object:172982} ; {quest:829} se tient tout au fond.",
		["Train while you are in the city: Druids and Paladins have no trainer here. Troll Priests: train with {npc:6018} in the {object:172961}, who takes {quest:5654}."] = "Entraînez-vous pendant que vous êtes en ville : les Druides et les Paladins n'ont pas de maître ici. Prêtres trolls : entraînez-vous auprès de {npc:6018}, dans la {object:172961}, qui prend {quest:5654}.",
		["Vile Fin murlocs"] = "Murlocs Aileron noir",
		["Walk in by the main gate. {npc:3310}, the wind rider master, stands on the tower in the {object:172982}; {npc:6929} keeps the inn below it, {npc:268701} stands by the bank. Bind here: the Hearthstone brings you back from {zone:1421} beside the zeppelin towers and the road to the {zone:1413}."] = "Entrez par la grande porte. {npc:3310}, le maître des coursiers du vent, se tient sur la tour dans la {object:172982} ; {npc:6929} tient l'auberge en dessous, {npc:268701} se tient près de la banque. Liez-vous ici : la Pierre de foyer vous ramène de {zone:1421} à côté des tours des zeppelins et de la route des {zone:1413}.",
		["Walk in through the main gate. {npc:268701} stands in the {object:172982}."] = "Entrez par la grande porte. {npc:268701} se tient dans la {object:172982}.",
		["While you're here: learn Staves from {npc:2704} ({object:172958}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Pendant que vous y êtes : apprenez le maniement des bâtons auprès de {npc:2704} ({object:172958}, 10 pièces d'argent) ; l'arme de mêlée d'un Chasseur vaut surtout par ses caractéristiques, et les armes à deux mains en portent le plus.",
		["While you're here: learn Staves from {npc:2704} ({object:172958}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "Pendant que vous y êtes : apprenez le maniement des bâtons auprès de {npc:2704} ({object:172958}, 10 pièces d'argent) ; un bâton apporte plus de caractéristiques de sorts qu'une arme à une main pendant la progression.",
		["While you're here: learn {spell:197} from {npc:11868} ({object:172958}, 10 silver); two-handers level a Paladin fastest."] = "Pendant que vous y êtes : apprenez {spell:197} auprès de {npc:11868} ({object:172958}, 10 pièces d'argent) ; les armes à deux mains font progresser un Paladin le plus vite.",
		["While you're here: learn {spell:197} from {npc:11868} ({object:172958}, 10 silver); two-handers level a Warrior fastest."] = "Pendant que vous y êtes : apprenez {spell:197} auprès de {npc:11868} ({object:172958}, 10 pièces d'argent) ; les armes à deux mains font progresser un Guerrier le plus vite.",
		["Zeppelin to {zone:1454}"] = "Zeppelin pour {zone:1454}",
		["Zeppelin to {zone:1458}"] = "Zeppelin pour {zone:1458}",
		["{area:159} is a short walk north up the road from the zeppelin towers: {npc:1738} stands by the road into town, {npc:1518} in the apothecary's house on the west side of the square; Paladins: {npc:246152} trains you in town."] = "{area:159} est à quelques pas au nord en remontant la route depuis les tours du zeppelin : {npc:1738} se tient au bord de la route qui entre en ville, {npc:1518} dans la maison de l'apothicaire, côté ouest de la place ; Paladins : {npc:246152} vous entraîne en ville.",
		["{area:159} is a short walk north up the road from the zeppelin towers; {npc:1499} is in the town hall."] = "{area:159} est à quelques pas au nord en remontant la route depuis les tours du zeppelin ; {npc:1499} est dans l'hôtel de ville.",
		["{area:227} farmhouse"] = "Ferme du {area:227}",
		["{area:228} is the Forsaken crypt-town in the middle of the forest. Everyone you need stands around the crypt entrance; {npc:2226}, the bat handler, is just east of it."] = "{area:228} est la ville-crypte des Réprouvés, au milieu de la forêt. Tous ceux dont vous avez besoin se tiennent autour de l'entrée de la crypte ; {npc:2226}, le maître des chauves-souris, est juste à l'est.",
		["{npc:10181} holds court in the {object:36126}."] = "{npc:10181} tient sa cour dans le {object:36126}.",
		["{npc:11044}, in the Apothecarium"] = "{npc:11044}, dans l'Apothicarium",
		["{npc:11046}, the alchemy trainer, stands next door to {npc:3348}."] = "{npc:11046}, le maître des alchimistes, se tient juste à côté de {npc:3348}.",
		["{npc:11046}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:11046} : Camping 101, au feu de camp de Brakk en {zone:1411}",
		["{npc:11066}, the enchanting trainer, works in the Drag."] = "{npc:11066}, le maître des enchanteurs, travaille dans la Herse.",
		["{npc:11066}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:11066} : Camping 101, au feu de camp de Brakk en {zone:1411}",
		["{npc:1499} in {area:159}, on the way to the zeppelin at the end"] = "{npc:1499} à {area:159}, sur le chemin du zeppelin à la fin",
		["{npc:1518}, inside"] = "{npc:1518}, à l'intérieur",
		["{npc:1937}: Zinge in the {zone:1458}, on the way to the zeppelin at the end"] = "{npc:1937} : Zinge à {zone:1458}, sur le chemin du zeppelin à la fin",
		["{npc:1937}: for Quinn, on the road north at the end"] = "{npc:1937} : pour Quinn, sur la route du nord à la fin",
		["{npc:1938}, just north of Allister"] = "{npc:1938}, juste au nord d'Allister",
		["{npc:1938}: his books lie in the {area:227} farmhouse, on the walk north"] = "{npc:1938} : ses livres sont dans la ferme du {area:227}, sur le trajet vers le nord",
		["{npc:1951}, inside"] = "{npc:1951}, à l'intérieur",
		["{npc:1952}, below ground"] = "{npc:1952}, sous terre",
		["{npc:1978} waits north-east of the house. Escort him back to {npc:1950}; worgs attack on the way."] = "{npc:1978} attend au nord-est de la maison. Escortez-le jusqu'à {npc:1950} ; des worgs attaquent en chemin.",
		["{npc:1978}, inside"] = "{npc:1978}, à l'intérieur",
		["{npc:2226}: {npc:4556} in the {zone:1458}, at the end of this guide; no need to buy the flight"] = "{npc:2226} : {npc:4556} à {zone:1458}, à la fin de ce guide ; inutile de payer le vol",
		["{npc:246152}, in {area:159}"] = "{npc:246152}, à {area:159}",
		["{npc:260093}, the {area:1497}'s paladin trainer"] = "{npc:260093}, le maître des paladins de {area:1497}",
		["{npc:268684} and {npc:268682} sit behind Grommash Hold in the {object:172957}; the Smooth Boulders lie around them."] = "{npc:268684} et {npc:268682} sont assis derrière le fort Grommash, dans la {object:172957} ; les Rochers lisses se trouvent autour d'eux.",
		["{npc:2855}, the tailoring trainer, is in the {object:172958}."] = "{npc:2855}, le maître des tailleurs, se trouve dans {object:172958}.",
		["{npc:2855}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:2855} : Camping 101, au feu de camp de Brakk en {zone:1411}",
		["{npc:3230}, in Grommash Hold"] = "{npc:3230}, dans le fort Grommash",
		["{npc:3348} and {npc:3347} run the alchemy shop in the Drag; {npc:11046} is next door."] = "{npc:3348} et {npc:3347} tiennent la boutique d'alchimie de la Herse ; {npc:11046} est juste à côté.",
		["{npc:3365}, the leatherworking trainer, works in the {object:172958}."] = "{npc:3365}, le maître des travailleurs du cuir, travaille dans {object:172958}.",
		["{npc:3365}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:3365} : Camping 101, au feu de camp de Brakk en {zone:1411}",
		["{npc:3404}, the herbalism trainer, keeps her shop in the Drag."] = "{npc:3404}, la maîtresse des herboristes, tient sa boutique dans la Herse.",
		["{npc:3404}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:3404} : Camping 101, au feu de camp de Brakk en {zone:1411}",
		["{npc:4047}: {npc:4049}, on the road into Stonetalon in the next guide"] = "{npc:4047} : {npc:4049}, sur la route qui entre dans les Serres-Rocheuses, au guide suivant",
		["{npc:4551}, the bat handler"] = "{npc:4551}, le maître des chauves-souris",
		["{npc:4551}: keep {item:16210}, Podrig takes it on the next stop at the {area:228}, at 22"] = "{npc:4551} : gardez {item:16210}, Podrig le prendra à la prochaine étape, à {area:228}, au niveau 22",
		["{npc:4556}, the weapon merchant beside the bat handler"] = "{npc:4556}, le marchand d'armes à côté du maître des chauves-souris",
		["{npc:4586}, the engineering trainer, works in the {zone:1458}."] = "{npc:4586}, le maître des ingénieurs, travaille à {zone:1458}.",
		["{npc:4586}: Camping 101, from {npc:265812}'s campfire in Tirisfal"] = "{npc:4586} : Camping 101, au feu de camp de {npc:265812} à Tirisfal",
		["{npc:4598}, the mining trainer, works in the {zone:1458}."] = "{npc:4598}, le maître des mineurs, travaille à {zone:1458}.",
		["{npc:4598}: Camping 101, from {npc:265812}'s campfire in Tirisfal"] = "{npc:4598} : Camping 101, au feu de camp de {npc:265812} à Tirisfal",
		["{npc:4605}, the blacksmithing trainer, works in the {zone:1458}."] = "{npc:4605}, le maître des forgerons, travaille à {zone:1458}.",
		["{npc:4605}: Camping 101, from {npc:265812}'s campfire in Tirisfal"] = "{npc:4605} : Camping 101, au feu de camp de {npc:265812} à Tirisfal",
		["{npc:4949} stands in Grommash Hold. He offers {quest:98024} and {quest:93739} once {quest:95350} is handed in."] = "{npc:4949} se tient dans le fort Grommash. Il propose {quest:98024} et {quest:93739} une fois {quest:95350} rendue.",
		["{npc:4949}, inside Grommash Hold"] = "{npc:4949}, dans le fort Grommash",
		["{npc:4949}: keep it, Thork at the Crossroads in the {zone:1413} guide"] = "{npc:4949} : gardez-la, Thork à la Croisée dans le guide des {zone:1413}",
		["{npc:4949}: {quest:93739}, a tour of the Horde's leaders"] = "{npc:4949} : {quest:93739}, une tournée des chefs de la Horde",
		["{npc:5204}, in the Apothecarium"] = "{npc:5204}, dans l'Apothicarium",
		["{npc:5204}: Helbrim at the Crossroads, in the next guide"] = "{npc:5204} : Helbrim à la Croisée, au guide suivant",
		["{npc:7088}, the skinning trainer, stands in the {object:172958}."] = "{npc:7088}, le maître des dépeceurs, se tient dans {object:172958}.",
		["{npc:7088}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:7088} : Camping 101, au feu de camp de Brakk en {zone:1411}",
		["{object:1571}; upstairs"] = "{object:1571} ; à l'étage",
		["{object:1661} lies under the {area:153}, beside the zeppelin towers. {npc:2050} stands at the inn by the way down; {npc:7683} on the way down to the Apothecarium, where {npc:11044} and {npc:5204} stand beside {npc:2055}."] = "{object:1661} se trouve sous les {area:153}, à côté des tours du zeppelin. {npc:2050} se tient à l'auberge en descendant ; {npc:7683} sur le chemin de l'Apothicarium, où {npc:11044} et {npc:5204} se tiennent à côté de {npc:2055}.",
		["{object:173016} is a few steps north."] = "{object:173016} est à quelques pas au nord.",
		["{quest:264} is handed in at {object:24776}, a grave a few steps south of the crypt entrance, not to a person."] = "{quest:264} se rend à {object:24776}, une tombe à quelques pas au sud de l'entrée de la crypte, et non à un personnage.",
		["{quest:829}: {quest:809} stands at {area:379}, on the next guide's road to the Crossroads"] = "{quest:829} : {quest:809} se tient au {area:379}, sur la route de la Croisée du prochain guide",
		["{quest:829}: {quest:832}, from the {item:4903} in {zone:1411}"] = "{quest:829} : {quest:832}, grâce à l'{item:4903} de {zone:1411}",
		["{zone:1454}'s {object:172982}"] = "{object:172982} d'{zone:1454}",
} end)()
t.guides["forever/horde/04-the-barrens"] = (function() return {
		["A few steps east of {npc:14242}'s tree, a small camp: two Encroaching Soldiers and the {npc:268623} for Logmar. The {npc:268623} is elite: grouping up is advised."] = "À quelques pas à l'est de l'arbre de {npc:14242}, un petit camp : deux Soldats envahissants et le {npc:268623} pour Logmar. Le {npc:268623} est un élite : il est conseillé de se grouper.",
		["Back down the {area:1076} to {npc:4201}' hut, then east along the road toward {area:461}: {npc:4074} patrols the road just east of the fork, {npc:4073} the slopes further north-east below the crag. Both are lone shredder robots; they roam, so follow the road until you meet them."] = "Redescendez le {area:1076} jusqu'à la hutte de {npc:4201}, puis allez vers l'est par la route en direction de {area:461} : {npc:4074} patrouille sur la route juste à l'est de l'embranchement, {npc:4073} sur les pentes plus au nord-est, sous l'escarpement. Ce sont deux robots déchiqueteurs solitaires ; ils se déplacent, suivez donc la route jusqu'à les croiser.",
		["Back west to {npc:4201}' hut, on the way down to {area:2539}."] = "Retournez à l'ouest jusqu'à la hutte de {npc:4201}, en descendant vers {area:2539}.",
		["Bael'dun fortress"] = "Forteresse de Bael'dun",
		["Crossroads flight master"] = "Maître de vol de la Croisée",
		["East along the road from {area:2539} to {npc:4049}'s camp."] = "Vers l'est par la route depuis {area:2539} jusqu'au camp de {npc:4049}.",
		["Fly to Crossroads"] = "Prendre un vol pour la Croisée",
		["Fly to {area:1638}"] = "Voler jusqu'aux {area:1638}",
		["Fly to {area:1638} (without its flight path the arrow goes by {area:378} and {zone:1412}): two of its elders give quests worked on this guide's and the next guide's walks, and {npc:3419} takes Lydon's toxin."] = "Volez jusqu'aux {area:1638} (sans ce trajet aérien, la flèche passe par le {area:378} et {zone:1412}) : deux de ses anciens donnent des quêtes réalisées pendant les trajets de ce guide et du suivant, et l'{npc:3419} prend la toxine de Lydon.",
		["Fly to {area:378}"] = "Voler jusqu'au {area:378}",
		["Fly to {area:378}: {npc:2995} on {zone:1456}'s central rise, or the Crossroads' wind rider master if you start this guide there."] = "Volez jusqu'au {area:378} : {npc:2995}, sur le plateau central des {zone:1456}, ou le maître des coursiers du vent de la Croisée si vous commencez ce guide là-bas.",
		["Fly to {area:392}"] = "Voler jusqu'à {area:392}",
		["Follow the road north toward {area:467}. Antlered Coursers graze along the way; the Sap Beasts, Twilight Runners and Fey Dragons roam the woods below the Peak, and the Cenarion druids hold the grove there."] = "Suivez la route vers le nord en direction du {area:467}. Des Coursiers à ramure ({npc:4018}) paissent en chemin ; Bêtes de sève ({npc:4020}), Coureurs crépusculaires ({npc:4067}) et Dragons-faë ({npc:4016}) parcourent les bois sous le pic, et les druides cénariens tiennent le bosquet là-bas.",
		["Follow the road on west past {npc:4049}'s camp into Stonetalon: {npc:3995} waits below ground in {area:2539}, at the foot of the {area:1076}."] = "Continuez sur la route vers l'ouest après le camp de {npc:4049} jusqu'aux Serres-Rocheuses : {npc:3995} attend sous terre à {area:2539}, au pied de {area:1076}.",
		["Follow the road west past Regthar's bunkers: {npc:4049} camps beside it at the edge of Stonetalon."] = "Suivez la route vers l'ouest après les bunkers de Regthar : {npc:4049} campe à côté, à l'orée des Serres-Rocheuses.",
		["Gaea Dirt Mounds"] = "Monticules de poussière de Gaea ({object:177929})",
		["Gaea Seeds"] = "Graines de Gaea ({item:16205})",
		["Keep {npc:4202} (27) and {npc:4049}'s robots: {area:461} comes in one trip on the way back down from Sun Rock."] = "Gardez {npc:4202} (27) et les robots de {npc:4049} : {area:461} se fait en une seule fois, sur le chemin du retour depuis le Roc-Soleil.",
		["North up the road to {area:378}: your hearthstone takes you there if it is ready."] = "Remontez la route vers le nord jusqu'au {area:378} : votre Pierre de foyer vous y emmène si elle est prête.",
		["On down the {area:1076} to {area:2539}."] = "Continuez à descendre {area:1076} jusqu'à {area:2539}.",
		["On east to {area:461}, past where {npc:4073} roams: {quest:1096} (27) stands at the top of the Venture Co. tower. Clear the Venture Co. on the way up. His Mechanical Arm is for Ziz."] = "Continuez vers l'est jusqu'à {area:461}, au-delà de la zone où erre {npc:4073} : la cible de {quest:1096} (27) se tient en haut de la tour de la KapitalRisk. Éliminez les membres de la KapitalRisk en montant. Son Bras mécanique est pour Ziz.",
		["On the way back east to {npc:3341}: Hecklefang Stalkers and {npc:3238} lizards roam the plain between the ridge and his camp. Careful: Qiraji Lieutenants (28, elite) sometimes stand on that plain: give them a wide berth."] = "En revenant vers l'est jusqu'à {npc:3341} : des Traqueuses Jappecroc et des lézards {npc:3238} parcourent la plaine entre la crête et son camp. Attention : des Lieutenants qiraji (28, élites) se tiennent parfois dans cette plaine : passez loin d'eux.",
		["On up the {area:1076} from {npc:4201}' hut to {area:460}."] = "Remontez le {area:1076} depuis la hutte de {npc:4201} jusqu'à {area:460}.",
		["Place the {item:5638} on the {object:19594}"] = "Placez le {item:5638} sur la {object:19594}",
		["South of Camp Taurajo, on the road to {npc:3341}, the Silithid Mounds dot the {area:390}; the eggs lie in them, and Silithid Swarmers come out to defend them.\nCareful: Silithid Swarmers in the area release many tiny adds that interrupt spells; damage shields such as Thorns kill them in one hit."] = "Au sud du camp Taurajo, sur la route de {npc:3341}, les Antres des silithides parsèment le {area:390} ; les œufs s'y trouvent, et des Grouillants silithides en sortent pour les défendre.\nAttention : les Grouillants silithides de la zone libèrent de nombreux petits monstres qui interrompent les sorts ; les boucliers de dégâts comme Épines les tuent en un coup.",
		["South of Gann, the Bael'dun dwarves dig at {area:359}. Excavators and Foremen work the pit; {npc:3392} (26) carries the journal: pull him alone.\nCareful: Excavators (level 21-22) and Foremen (level 22-23) run off for help once they fall to 15% health, so more dwarves can join the fight."] = "Au sud de Gann, les nains de Bael'dun creusent à {area:359}. Des Excavateurs et des Contremaîtres travaillent dans la fosse ; le {npc:3392} (26) porte le journal : attirez-le seul.\nAttention : les Excavateurs (niveau 21-22) et les Contremaîtres (niveau 22-23) fuient chercher de l'aide une fois à 15 % de vie, d'autres nains peuvent donc rejoindre le combat.",
		["South-west of Sun Rock lies the burned {area:465}. Plant the Gaea Seeds in the dirt mounds on the valley floor; the fire elementals drop {item:16312}. Bloodfury Harpies and Ambushers nest on the north side, Slayers and Roguefeathers to the south. Careful: the Burning Destroyers, Scorched Basilisks and Bloodfury Storm Witches here are level 27 and the valley floor is crowded: pull one at a time and keep to its edges."] = "Au sud-ouest de Roche-Soleil s'étend le {area:465}. Plantez les Graines de Gaea dans les monticules de terre au fond de la vallée ; les élémentaires de feu lâchent {item:16312}. Harpies et Embusquées Rougefurie nichent au nord, Tueuses et Volplumes au sud. Attention : les Destructeurs ardents, les Basilics cramoisis et les Sorcières des tempêtes Rougefurie sont ici de niveau 27 et le fond de la vallée est bondé : attirez-les un par un et restez sur ses bords.",
		["The Bael'dun Soldiers, Riflemen and Officers guard the fortress on the east side of the dig; all three items drop from them. {npc:3414} (30) and his Officers stand on the bottom floor: work the soldiers and riflemen on the upper levels and keep away from him.\nCareful: Riflemen (level 24-25) Shoot from 5-30 yd, so nearby ones can join a fight from range."] = "Les Soldats, les Fusiliers et les Officiers de Bael'dun gardent la forteresse du côté est des fouilles ; les trois objets viennent d'eux. {npc:3414} (30) et ses Officiers se tiennent à l'étage inférieur : occupez-vous des soldats et des fusiliers aux étages supérieurs et restez loin de lui.\nAttention : les Fusiliers (niveau 24-25) utilisent Tir de 5 à 30 m, ceux qui sont proches peuvent donc rejoindre un combat à distance.",
		["The Gaea Seeds lie in the grass around the southern shore of {area:464}, north of Sun Rock.\nCareful: Pridewings around the lake can aggro as a linked group."] = "Les Graines de Gaea se trouvent dans l'herbe autour de la rive sud du {area:464}, au nord du Roc-Soleil.\nAttention : les Fièrailes autour du lac peuvent attaquer en groupe lié.",
		["The dwarves' flying machine sits on its platform inside the dig site. Use the {item:5021} that {npc:3341} gave you on it."] = "La machine volante des nains repose sur sa plateforme dans le site de fouilles. Utilisez dessus le {item:5021} que {npc:3341} vous a donné.",
		["The flight lands at {area:378}'s wind rider master. {npc:3433} stands at the north edge of the camp, {npc:3387} and {npc:3430} (in the cage) in the middle."] = "Le vol atterrit chez le maître des coursiers du vent du {area:378}. {npc:3433} se tient au bord nord du camp, {npc:3387} et {npc:3430} (dans la cage) au milieu.",
		["The flying machine"] = "La machine volante",
		["The next guide flies to {area:2897}: hearth to {area:378} if your hearthstone is ready, or walk on east to the Crossroads' flight master."] = "Le guide suivant prend un vol pour l'{area:2897} : utilisez votre Pierre de foyer pour le {area:378} si elle est prête, ou continuez à pied vers l'est jusqu'au maître de vol de la Croisée.",
		["The road west"] = "La route de l'ouest",
		["The road west past {npc:4049}'s camp"] = "La route de l'ouest après le camp de {npc:4049}",
		["The {object:19594} is the platform just south-east of {npc:4202}'s tower: place Zamah's {item:5638} on it. Zamah takes it back on the next guide's {zone:1456} stop."] = "La {object:19594} est la plateforme juste au sud-est de la tour de {npc:4202} : placez-y le {item:5638} de Zamah. Zamah le reprend lors de l'arrêt aux {zone:1456} du prochain guide.",
		["The {object:667362} grows on the bottom of {area:464}, off the same southern shore: dive to the plants and the Dried Mirkweed Piles; both give pods. Watch your breath."] = "Le {object:667362} pousse au fond du {area:464}, au large de la même rive sud : plongez jusqu'aux plantes et aux Tas d'obscurcie séchée ; les deux donnent des cosses. Surveillez votre souffle.",
		["To {area:378}"] = "Vers le {area:378}",
		["Up the {area:1076} to {npc:4201}' hut, where the road forks east to {area:461}: {npc:3442}'s orders are for him."] = "Montez {area:1076} jusqu'à la hutte de {npc:4201}, là où la route bifurque vers l'est en direction de {area:461} : les ordres de {npc:3442} sont pour lui.",
		["West of Gann, the Razormane hold {area:1701}. {npc:3436} is on the east side, {npc:3434} to the south, {npc:3435} at the west end. Lok (25) and the Warfrenzies (24-25) are a few levels above you; {npc:5859}, a rare elite, sometimes walks the ridge: leave him. Pathfinders and Stalkers drop the Backstabber, Seers the Wand, Warfrenzies the War Shield. {quest:885}, a rare red wind serpent, flies over the ridge: its feather starts a quest.\nCareful: Razormane Stalkers move around in stealth and hit with {spell:1752}, so they can join a fight without warning."] = "À l'ouest de Gann, les Tranchecrin tiennent la {area:1701}. {npc:3436} est à l'est, {npc:3434} au sud, {npc:3435} à l'extrémité ouest. Lok (25) et les Frénétiques Tranchecrin (24-25) ont quelques niveaux de plus que vous ; {npc:5859}, un élite rare, parcourt parfois la crête : laissez-le. Les Guides Tranchecrin et Traqueurs Tranchecrin laissent le Poignard de Tranchecrin, les Prophètes Tranchecrin la Baguette Tranchecrin carbonisée, les Frénétiques le Bouclier Tranchecrin. {quest:885}, une serpent des vents rouge et rare, survole la crête : sa plume lance une quête.\nAttention : les Traqueurs Tranchecrin se déplacent camouflés et frappent avec {spell:1752} : ils peuvent se joindre à un combat sans prévenir.",
		["{area:378} flight master"] = "Maître de vol du {area:378}",
		["{area:465}: kill these as you meet them"] = "{area:465} : tuez-les au passage",
		["{area:718} quests still in your log: {npc:3446} stands beside the WANTED poster, Bigglefuzz on the dock by the flight master."] = "Quêtes de {area:718} encore dans votre journal : {npc:3446} se tient à côté de l'affiche AVIS DE RECHERCHE, Bigglefuzz sur le quai près du maître de vol.",
		["{item:277936}, from any Bloodfury harpy"] = "{item:277936}, sur n'importe quelle harpie Rougefurie",
		["{item:5736}, from {quest:1096}"] = "{item:5736}, sur {quest:1096}",
		["{npc:11860}: Glittering Sunstones from the Bloodfury harpies"] = "{npc:11860} : Héliolites lumineuses ({item:277936}) sur les harpies Rougefurie",
		["{npc:11860}: Grish is at the {area:1718}, on the next guide's way into {zone:1441}"] = "{npc:11860} : Grish est au {area:1718}, sur le chemin du prochain guide vers {zone:1441}",
		["{npc:11861}, beside {npc:11862}"] = "{npc:11861}, à côté de {npc:11862}",
		["{npc:11862}, up on the ledge"] = "{npc:11862}, en haut sur la corniche",
		["{npc:11862}: {npc:12736} at Zoram'gar, next guide"] = "{npc:11862} : {npc:12736} à Zoram'gar, guide suivant",
		["{npc:11864} stands by the bonfire inside Sun Rock: Makaba's news that Kaya is alive is for her."] = "{npc:11864} se tient près du feu de camp à l'intérieur de Roche-Soleil : la nouvelle de Makaba selon laquelle Kaya est vivante lui est destinée.",
		["{npc:14242}, up in the tree just east of {npc:3341}"] = "{npc:14242}, dans l'arbre juste à l'est de {npc:3341}",
		["{npc:2995}, the wind rider master, stands on the central rise: take his flight path if you don't have it. {npc:3024} and {npc:4721} stand a short walk east of him."] = "{npc:2995}, le maître des coursiers du vent, se tient sur le plateau central : prenez son trajet aérien si vous ne l'avez pas. {npc:3024} et {npc:4721} se tiennent à quelques pas à l'est de lui.",
		["{npc:3024}: the {object:667362} grows in {area:464}, by Sun Rock"] = "{npc:3024} : le {object:667362} pousse dans le {area:464}, près de Roche-Soleil",
		["{npc:3341} walks around {area:1701}: look inside the circle on the map"] = "{npc:3341} se promène autour de {area:1701} : cherchez dans le cercle sur la carte",
		["{npc:3341} walks the road south toward {area:359}, between about 46,75 and 46,81: if he isn't at the arrow, follow the road until you meet him. {npc:14242} sits up in the tree just east of the road at 47.9,77.5."] = "{npc:3341} parcourt la route vers le sud en direction de {area:359}, entre environ 46,75 et 46,81 : s'il n'est pas à la flèche, suivez la route jusqu'à le rencontrer. {npc:14242} est perché dans l'arbre juste à l'est de la route, en 47.9,77.5.",
		["{npc:3375} walks around {area:359}: look inside the circle on the map"] = "{npc:3375} se promène autour de {area:359} : cherchez dans le cercle sur la carte",
		["{npc:3419} stands in the {area:2197}, the caves under {area:1640}, west of {npc:2995}."] = "L'{npc:3419} se tient dans les {area:2197}, les grottes sous {area:1640}, à l'ouest de {npc:2995}.",
		["{npc:3419}: the {item:5638} goes on the {object:19594} at {area:461}, on this guide's Windshear trip"] = "{npc:3419} : le {item:5638} se place sur la {object:19594} à {area:461}, lors de l'expédition de ce guide au pic Tondevent",
		["{npc:3428}, west of the north gate"] = "{npc:3428}, à l'ouest de la porte nord",
		["{npc:3429}, at the top of the tower"] = "{npc:3429}, en haut de la tour",
		["{npc:3430}, in the cage"] = "{npc:3430}, dans la cage",
		["{npc:3433}, at the north edge of the camp"] = "{npc:3433}, au bord nord du camp",
		["{npc:3442} stands beside the flight master you land at. His new orders go back to {npc:4201} on the {area:1076}, later in this guide."] = "{npc:3442} se tient à côté du maître de vol où vous atterrissez. Ses nouveaux ordres sont à rapporter à {npc:4201} sur {area:1076}, plus loin dans ce guide.",
		["{npc:3442}: for {npc:4201}, on the way up the {area:1076}"] = "{npc:3442} : pour {npc:4201}, en montant {area:1076}",
		["{npc:3442}: {quest:1094}, from {npc:4201}"] = "{npc:3442} : {quest:1094}, de la part de {npc:4201}",
		["{npc:3665}, on the dock"] = "{npc:3665}, sur le quai",
		["{npc:3995}, below ground"] = "{npc:3995}, sous terre",
		["{npc:4049}: {npc:4074} and {npc:4073} roam east of {npc:4201}, on the way back down from Sun Rock"] = "{npc:4049} : {npc:4074} et {npc:4073} errent à l'est de {npc:4201}, sur le chemin du retour depuis le Roc-Soleil",
		["{npc:4128} walks around {area:1156}: look inside the circle on the map"] = "{npc:4128} se promène autour de {area:1156} : cherchez dans le cercle sur la carte",
		["{npc:4198}'s next quest, Ordanus, is on the Alliance side of {zone:1440}. Skip it."] = "La quête suivante de {npc:4198}, Ordanus, se trouve du côté Alliance d'{zone:1440}. Passez-la.",
		["{npc:4198}, outside the gate"] = "{npc:4198}, devant la porte",
		["{npc:4201}, inside"] = "{npc:4201}, à l'intérieur",
		["{npc:4201}: {npc:4202}, at the top of the Venture Co. tower on {area:461}"] = "{npc:4201} : {npc:4202}, en haut de la tour de la KapitalRisk sur {area:461}",
		["{npc:4721}: the phial comes from {zone:1440}, next guide"] = "{npc:4721} : la fiole vient d'{zone:1440}, guide suivant",
		["{npc:5899}'s hut stands on the ridge above the quilboar watering hole, south of {area:378}, on the way to {area:359}."] = "La hutte de {npc:5899} se dresse sur la crête au-dessus du point d'eau des hurans, au sud de {area:378}, sur la route de {area:359}.",
		["{npc:5899}: the blue waterskin is filled in {zone:1440}, next guide"] = "{npc:5899} : l'outre bleue se remplit dans {zone:1440}, au guide suivant",
		["{npc:5899}: the red waterskin from {area:272}"] = "{npc:5899} : l'outre rouge de {area:272}",
		["{npc:5911} stands by the flight master. His {npc:268623} (23) is elite: grouping up is advised; the two Encroaching Soldiers are not."] = "{npc:5911} se tient près du maître de vol. Son {npc:268623} (23) est un élite : il est conseillé de se grouper ; les deux Soldats envahissants n'en sont pas.",
		["{npc:5911}, beside the flight master"] = "{npc:5911}, à côté du maître de vol",
		["{npc:5911}: the soldiers and the pillager camp just east of {npc:3341}, on the way south"] = "{npc:5911} : les soldats et le camp du pillard juste à l'est de {npc:3341}, sur le chemin du sud",
		["{quest:873}, a big threshadon, swims in the shallows off the {area:391}, east of {npc:3388}."] = "{quest:873}, un grand battrodon, nage dans les hauts-fonds au large de {area:391}, à l'est de {npc:3388}.",
		["{quest:874} camps on the shore just north of {area:392}'s flight master."] = "{quest:874} campe sur le rivage juste au nord du maître de vol de {area:392}.",
		["{zone:1442}: kill these as you meet them"] = "{zone:1442} : tuez-les au passage",
} end)()
t.guides["forever/horde/05-stonetalon-mountains"] = (function() return {
		["Back on the road south. Where it turns east into {area:287}, {npc:2214} waits at {area:285}."] = "De nouveau sur la route vers le sud. Là où elle tourne vers l'est dans {area:287}, {npc:2214} attend à {area:285}.",
		["Back to the outpost."] = "Retournez à l'avant-poste.",
		["Back to {npc:12867} at the lumber camp, on the road north to Splintertree."] = "Retour auprès de {npc:12867} au camp de bûcherons, sur la route du nord vers le Poste de Bois-brisé.",
		["Back up to {npc:2995} on the central rise and fly to {area:1637}."] = "Remontez voir {npc:2995} sur la butte centrale et volez jusqu'à {area:1637}.",
		["Below ground"] = "Sous terre",
		["Down the road through Silverpine to the {area:228}: from the zeppelin towers, south through Tirisfal; from the {object:177844}, south-east from the coast to the road. {npc:2121} and {npc:1937} stand by the crypt entrance."] = "Descendez la route à travers la forêt des Pins argentés jusqu'au {area:228} : depuis les tours des zeppelins, vers le sud à travers Tirisfal ; depuis le {object:177844}, vers le sud-est depuis la côte jusqu'à la route. {npc:2121} et {npc:1937} se tiennent près de l'entrée de la crypte.",
		["Druid trainer"] = "Maître des druides",
		["Every Wrathtail naga along the strand north of the outpost drops heads."] = "Chaque naga Irequeue de la grève au nord de l'avant-poste lâche des têtes.",
		["Fly to {area:1637}"] = "Prendre un vol pour {area:1637}",
		["Fly to {area:1637} from the {area:2897} flight master."] = "Volez jusqu'à {area:1637} depuis le maître de vol de {area:2897}.",
		["Fly to {area:1638}"] = "Volez jusqu'aux {area:1638}",
		["Fly to {area:378}"] = "Volez jusqu'à {area:378}",
		["For your {area:153} run: the zeppelin lands beside the ruins. Walk into the {zone:1458} through them and down to the {object:36126}: {npc:266484} stands there, near {npc:10181}."] = "Pour votre expédition dans {area:153} : le zeppelin atterrit à côté des ruines. Entrez dans {zone:1458} en les traversant et descendez jusqu'au {object:36126} : {npc:266484} s'y tient, près de {npc:10181}.",
		["For your {area:236} run, at the end of the {area:287} guide: {npc:1952} stands below ground in the crypt."] = "Pour votre expédition dans {area:236}, à la fin du guide de {area:287} : {npc:1952} se tient sous terre, dans la crypte.",
		["From Seereth's camp head north-east across the {zone:1413} to the road north of the Crossroads; Rogues coming from Fizzule's tower head west to it. {npc:8582} stands on the watch tower of the {area:1703} where the road enters {zone:1440}."] = "Depuis le camp de Seereth, allez vers le nord-est à travers {zone:1413} jusqu'à la route au nord de la Croisée ; les voleurs qui viennent de la tour de Fizzule y vont vers l'ouest. {npc:8582} se tient sur la tour de guet du {area:1703}, là où la route entre en {zone:1440}.",
		["From the zeppelin towers, run south into Silverpine and west past the {area:240} to the coast: the {object:177844} lies at the bottom of very deep water there, beside an air fissure where you can breathe. Watch your breath on the way down. It holds the {item:15882} for Trial of the Sea Lion. Then on to the {area:228}."] = "Depuis les tours du zeppelin, courez vers le sud jusque dans la forêt des Pins argentés et vers l'ouest après le {area:240} jusqu'à la côte : le {object:177844} repose au fond d'une eau très profonde, à côté d'une fissure d'air où vous pouvez respirer. Surveillez votre souffle en descendant. Il contient la {item:15882} pour l'Épreuve du lion de mer. Puis continuez jusqu'au {area:228}.",
		["From {area:378} follow the road west through the gate into {zone:1412}, then north past {area:222} to {zone:1456}; a lift at the foot of the bluffs takes you up."] = "Depuis le {area:378}, suivez la route vers l'ouest et passez la porte vers {zone:1412}, puis allez au nord après {area:222} jusqu'aux {zone:1456} ; un ascenseur au pied des pitons vous fait monter.",
		["Head west along the main road across {zone:1440}, past {area:415} (Alliance: keep to the road), to the coast. {area:2897} is on the {area:414} in the north-west: {npc:12719} and {npc:12717} stand around it, the {npc:12863} beside the flight master. Its other quests, Thistlefur's among them, are for the next visit, at 26."] = "Allez vers l'ouest sur la route principale à travers {zone:1440}, en passant {area:415} (Alliance : restez sur la route), jusqu'à la côte. {area:2897} se trouve sur {area:414} au nord-ouest : {npc:12719} et {npc:12717} se tiennent tout autour, le {npc:12863} à côté du maître de vol. Ses autres quêtes, dont celle de Poil-de-Chardon, sont pour la prochaine visite, au niveau 26.",
		["If you did {quest:2478} with a group, {npc:3401} in the {object:172960} takes it now."] = "Si vous avez fait {quest:2478} en groupe, {npc:3401}, dans {object:172960}, la prend maintenant.",
		["Into {area:287}"] = "Vers {area:287}",
		["Into {zone:1440}"] = "Vers {zone:1440}",
		["Naga brazier"] = "Brasero naga",
		["Naga heads"] = "Têtes de nagas",
		["On the roads around {area:233}, step into the town's outskirts: Protectors guard them and Mages the town; both drop pendants. Careful: each Mage (15) fights with a {npc:2540} (15) beside it: pull one Mage at a time from the outskirts. Stay out of the middle, where {npc:2120} (22) stands."] = "Sur les routes autour de {area:233}, avancez jusqu'aux abords du village : les Protecteurs gardent les abords et les Mages le village ; tous deux lâchent des pendentifs. Attention : chaque Mage (15) combat avec un {npc:2540} (15) à ses côtés : attirez un Mage à la fois depuis les abords. Évitez le centre, où se tient l'{npc:2120} (22).",
		["On the way north from Seereth's camp, keep east of the road to the Venture Co. tower north of the {area:382}. Before you go near Fizzule, use {item:8051} to fire two flares, then target him and /salute: he attacks anyone who comes in without signalling first."] = "En allant vers le nord depuis le camp de Seereth, restez à l'est de la route jusqu'à la tour de la KapitalRisk au nord du {area:382}. Avant de vous approcher de Fizzule, utilisez le {item:8051} pour tirer deux fusées éclairantes, puis ciblez-le et tapez /salute : il attaque quiconque s'approche sans avoir d'abord fait le signal.",
		["On the way west, {npc:267214} is stuck in a ravine south of the main road, south-east of {area:415}. Shadowhorn Stags and Ashenvale Bears roam the woods all around it."] = "En allant vers l'ouest, {npc:267214} est coincé dans un ravin au sud de la route principale, au sud-est d'{area:415}. Des Cerfs à corne noire et des Ours d'Ashenvale parcourent les bois tout autour.",
		["Out of the ruins, take the road south through Tirisfal into {zone:1421} and on to the {area:228}."] = "En sortant des ruines, prenez la route vers le sud à travers Tirisfal jusqu'à {zone:1421} et continuez jusqu'au {area:228}.",
		["South down the road past Pyrewood: Dalaran Watchers and Wizards patrol the roads around {area:233}, and south-west of the town the Ravenclaw Drudgers and Guardians haunt the ruins of {quest:516} in the south-east of the forest. Careful: High Order Mages (30) walk the same roads among the Watchers and Wizards: leave them."] = "Descendez la route vers le sud en passant Bois-du-Bûcher : des Guetteurs et des Sorciers de Dalaran patrouillent sur les routes autour d'{area:233}, et au sud-ouest de la ville les Drudgers et les Gardiens Ravenclaw hantent les ruines de {quest:516}, dans le sud-est de la forêt. Attention : des Mages du Haut ordre (30) parcourent les mêmes routes parmi les Guetteurs et les Sorciers : laissez-les.",
		["Steer {npc:267214}'s {npc:271181} out of the ravine to the main road within four minutes; if the channel breaks, ask {npc:267214} again."] = "Guidez {npc:271181} de {npc:267214} hors du ravin jusqu'à la route principale en moins de quatre minutes ; si la canalisation se rompt, redemandez à {npc:267214}.",
		["The Ravenclaw undead haunt the ruins of {quest:516}, east of the road in the south-east of the forest; a {npc:1973} drops the {item:271343} that leads to the {object:645153}.\nAn elite spirit (20) often stands beside the {object:645153}: pull the Ravenclaws away from the stone before you fight them."] = "Les morts-vivants Ravenclaw hantent les ruines de {quest:516}, à l'est de la route, dans le sud-est de la forêt ; un {npc:1973} lâche le {item:271343} qui mène à la {object:645153}.\nUn esprit élite (20) se tient souvent à côté de la {object:645153} : attirez les Ravenclaw loin de la pierre avant de les combattre.",
		["The night elf {quest:6503} (23-24) stalk the woods south and south-east of the lumber camp; they stealth, so watch for them."] = "{quest:6503} (23-24), des elfes de la nuit, rôdent dans les bois au sud et au sud-est du camp de bûcherons ; elles sont camouflées, restez attentif.",
		["The quest hands you a {item:210713}: use it beside the {object:645153} to offer your blood, then kill the elite spirit that answers.\n{quest:95883} is elite: grouping up is advised."] = "La quête vous remet un {item:210713} : utilisez-le à côté de {object:645153} pour offrir votre sang, puis tuez l'esprit élite qui répond.\n{quest:95883} est élite : il est conseillé de se grouper.",
		["The road east to {area:285}"] = "La route de l'est vers {area:285}",
		["The road north to {area:431}"] = "La route du nord vers le {area:431}",
		["The {area:153} is a dungeon for a group of five, about levels 15 to 22, in the ruined city above the {zone:1458}: its portal is in the ruins you walked through.\nInside: every undead can drop {item:268580} for {npc:266484}, so clear as you go. {npc:250660} can drop an {item:280438}, which starts a quest for {npc:2055}, and a {npc:256102} found inside starts one for {npc:7825}: both are in the {zone:1458}, on this route's next stop there."] = "{area:153} est un donjon pour un groupe de cinq, vers les niveaux 15 à 22, dans la ville en ruine au-dessus de {zone:1458} : son portail se trouve dans les ruines que vous avez traversées.\nÀ l'intérieur : chaque mort-vivant peut lâcher des {item:268580} pour {npc:266484}, alors nettoyez au fur et à mesure. {npc:250660} peut lâcher une {item:280438}, qui lance une quête pour {npc:2055}, et un {npc:256102} trouvé à l'intérieur en lance une pour {npc:7825} : tous deux sont à {zone:1458}, lors de la prochaine étape de cet itinéraire là-bas.",
		["To {zone:1456}"] = "Vers les {zone:1456}",
		["Warsong lumber camp"] = "Camp de bûcherons chanteguerre",
		["Zeppelin to {zone:1458}"] = "Zeppelin pour {zone:1458}",
		["the {object:645153} offers {quest:95883} once the {item:271343} is in; below ground"] = "la {object:645153} propose {quest:95883} une fois le {item:271343} déposé ; sous terre",
		["{area:2897} flight master"] = "Maître de vol de {area:2897}",
		["{area:431} is just north up the road. Coming in from the south, the flight master and {npc:12696}'s hunt board at {area:428} come first, then the vendors. {npc:12867} at the lumber camp offers {quest:6503}: leave it for the next {zone:1440} visit, at 26."] = "{area:431} est juste au nord, sur la route. En arrivant du sud, le maître des vols et le tableau de chasse de {npc:12696} à {area:428} arrivent d'abord, puis les marchands. {npc:12867}, au camp des bûcherons, propose {quest:6503} : laissez-la pour la prochaine visite de {zone:1440}, au niveau 26.",
		["{item:15882}, from the {object:177844}"] = "{item:15882}, dans le {object:177844}",
		["{item:210713}, beside the {object:645153}: summons the elite spirit"] = "{item:210713}, à côté de {object:645153} : invoque l'esprit élite",
		["{item:271343}, from a {npc:1973}"] = "{item:271343}, sur un {npc:1973}",
		["{item:271350}, from the Tortured Souls among the ruins; below ground"] = "{item:271350}, sur les Âmes torturées parmi les ruines ; sous terre",
		["{npc:12696}'s hunt targets Ursangous and Shadumbra are for the next {zone:1440} visit, at 26; Sharptalon (31) only from level 30."] = "Les cibles de chasse de {npc:12696}, Ursangous et Shadumbra, sont pour la prochaine visite en {zone:1440}, au niveau 26 ; Serres-tranchantes (31) seulement à partir du niveau 30.",
		["{npc:12717} walks north up the strand to a naga brazier. Put the brazier out, then guard him through the naga waves until Vorsha is dead; the Wrathtail naga drop the heads {npc:12719} wants."] = "{npc:12717} remonte la grève vers le nord jusqu'à un brasero naga. Éteignez le brasero, puis protégez-le pendant les vagues de nagas jusqu'à la mort de Vorsha ; les nagas Irequeue lâchent les têtes que veut {npc:12719}.",
		["{npc:12717}: take it last, his escort starts at once"] = "{npc:12717} : prenez-la en dernier, son escorte commence aussitôt",
		["{npc:1937}: Lydon in {area:272}, next guide"] = "{npc:1937} : Lydon à {area:272}, guide suivant",
		["{npc:1952}, below ground"] = "{npc:1952}, sous terre",
		["{npc:2121}: {area:233}'s pendants, on the same roads"] = "{npc:2121} : les pendentifs de {area:233}, sur les mêmes routes",
		["{npc:2121}: {quest:516}, south-east of {area:233}"] = "{npc:2121} : {quest:516}, au sud-est d'{area:233}",
		["{npc:2214}: Darthalia in {area:272}"] = "{npc:2214} : Darthalia à {area:272}",
		["{npc:2391} in {area:272} teaches Poisons: keep it"] = "{npc:2391}, à {area:272}, enseigne les Poisons : gardez la quête",
		["{npc:246152} trains Paladins in {area:159}, a short walk north up the road from the zeppelin towers. Come back down the same road for Silverpine."] = "{npc:246152} entraîne les paladins à {area:159}, à courte distance au nord par la route depuis les tours des zeppelins. Redescendez la même route pour la forêt des Pins argentés.",
		["{npc:271181}, on the road"] = "{npc:271181}, sur la route",
		["{npc:2995}, the wind rider master, stands on the central rise: take his flight path if you don't have it. {npc:4046} stands on {area:1639} to the east; {npc:3419} in the {area:2197}, the caves under {area:1640} to the west."] = "{npc:2995}, le maître des coursiers du vent, se tient sur la butte centrale : prenez son trajet aérien si vous ne l'avez pas. {npc:4046} se tient sur {area:1639} à l'est ; l'{npc:3419} dans {area:2197}, les grottes sous {area:1640} à l'ouest.",
		["{npc:3034} in {zone:1412}; {zone:1454} has no druid trainer"] = "{npc:3034} en {zone:1412} ; {zone:1454} n'a pas de maître des druides",
		["{npc:3419}: her note is for {npc:2216} in {area:272}, next guide"] = "{npc:3419} : sa note est pour l'{npc:2216} à {area:272}, guide suivant",
		["{npc:5875} stands in the {object:172960}. Use {item:6626} on the summoning circle there and defeat the succubus to bind her."] = "{npc:5875} se tient dans {object:172960}. Utilisez le {item:6626} sur le cercle d'invocation qui s'y trouve et vainquez la succube pour la lier.",
		["{npc:6389} stands just west of the crypt entrance: hand him {item:16210} from the {zone:1458}."] = "{npc:6389} se tient juste à l'ouest de l'entrée de la crypte : remettez-lui {item:16210} venant de {zone:1458}.",
		["{quest:1063} first: fly to {area:1638} from the {area:2897} flight master. {npc:4046} and {npc:3419} send you to {npc:2216} in {area:272}, the next guide's base, and {area:1638}'s flight path takes you on to {zone:1454}."] = "{quest:1063} d'abord : volez jusqu'à {area:1638} depuis le maître de vol de {area:2897}. {npc:4046} et l'{npc:3419} vous envoient voir l'{npc:2216} à {area:272}, la base du guide suivant, et le trajet aérien de {area:1638} vous emmène ensuite à {zone:1454}.",
		["{quest:1063} first: fly to {area:378} from the {area:2897} flight master and walk on to {zone:1456}. {npc:4046} and {npc:3419} send you to {npc:2216} in {area:272}, the next guide's base, and {zone:1456}'s flight path takes you on to {zone:1454}."] = "{quest:1063} d'abord : volez jusqu'à {area:378} depuis le maître de vol de {area:2897} et continuez à pied jusqu'à {zone:1456}. {npc:4046} et l'{npc:3419} vous envoient voir l'{npc:2216} à {area:272}, la base du guide suivant, et le trajet aérien de {zone:1456} vous emmène ensuite à {zone:1454}.",
		["{quest:2478} is for level 23 or more: the tower's drones are 25 and Gallywix a 23 elite. Do it when you can, with a group, from the Class guide Poisons (Horde)."] = "{quest:2478} est pour le niveau 23 ou plus : les pantins de la tour sont de niveau 25 et Gallywix est un élite de niveau 23. Faites-la quand vous le pouvez, en groupe, depuis le guide de classe Poisons (Horde).",
		["{quest:92421}: the {item:268580}, inside"] = "{quest:92421} : les {item:268580}, à l'intérieur",
		["{zone:1421}: kill these as you meet them"] = "{zone:1421} : tuez-les au passage",
		["{zone:1456}'s central rise"] = "Le plateau central des {zone:1456}",
} end)()
t.guides["forever/horde/06-hillsbrad-foothills"] = (function() return {
		["After returning Mission: Possible But Not Probable to Shenthul, bring {quest:2479} to {npc:2391} in {area:272}. Stay beside him until the brewing objective completes, then hand in the follow-up to learn Poisons. Finish it even if the Zanzil poison has already been removed; removing the debuff alone does not teach the skill."] = "Après avoir rendu Mission : possible mais pas probable à Shenthul, apportez {quest:2479} à {npc:2391}, à {area:272}. Restez à côté de lui jusqu'à ce que l'objectif de préparation soit rempli, puis rendez la quête suivante pour apprendre les Poisons. Terminez-la même si le poison de Zanzil a déjà été retiré ; retirer l'affaiblissement ne suffit pas à apprendre la compétence.",
		["Back north up the road to the {area:228}: {npc:1938} stands just north of Allister."] = "Remontez la route vers le nord jusqu'au {area:228} : {npc:1938} se tient juste au nord d'Allister.",
		["Back to the Crossroads"] = "Retour à la Croisée",
		["Bears, creepers and lions"] = "Ours, rampemousses et lions",
		["Careful: When one lion is attacked, nearby lions come to its aid, and the Vicious Black Bears sharing those fields can also join the fight."] = "Attention : quand un lion est attaqué, les lions proches viennent l'aider, et les Ours noirs vicieux qui partagent ces champs peuvent aussi rejoindre le combat.",
		["Cast {spell:18960}. Join the two pendant halves at the {area:2362}, on the north-west shore of the lake, before you see {npc:11802} in {area:2361}. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Lancez {spell:18960}. Assemblez les deux moitiés de pendentif au {area:2362}, sur la rive nord-ouest du lac, avant d'aller voir {npc:11802} à {area:2361}. {npc:11802} se tient à l'étage de son bâtiment : montez par l'intérieur, la flèche ne distingue pas les étages.",
		["Drull and {npc:2238} are chained inside {area:275}'s courtyard buildings. Their locks need keys: {npc:2427} carries the {item:3467} and {npc:2428} the {item:3499}, both in the keep. Kill them, then open both locks.\nFrom {area:272} go south-east into the hills on the way to {area:275}. Rogues, Watchmen and Shadow Mages hold the camps along the way; the Shadow Mages carry Lydon's Vials of Innocent Blood."] = "Drull et {npc:2238} sont enchaînés dans les bâtiments de la cour de {area:275}. Leurs cadenas nécessitent des clés : {npc:2427} porte la {item:3467} et {npc:2428} la {item:3499}, tous deux dans le donjon. Tuez-les, puis ouvrez les deux cadenas.\nDepuis {area:272}, allez vers le sud-est dans les collines en direction de {area:275}. Des Voleurs, des Guetteurs et des Mages de l'ombre tiennent les camps en chemin ; les Mages de l'ombre portent les Fioles de sang d'innocent de Lydon.",
		["Drull's ball and chain"] = "Boulet et chaîne de Drull",
		["Fill the {item:7768} at the {object:107045} beside the inn"] = "Remplissez l'{item:7768} au {object:107045} à côté de l'auberge",
		["Fly on from {npc:2226}, the bat handler just east of the crypt, to the {area:1497}."] = "Continuez en vol depuis {npc:2226}, le maître des chauves-souris juste à l'est de la crypte, jusqu'à {area:1497}.",
		["Fly to the {area:1497}"] = "Prendre un vol pour {area:1497}",
		["For your {area:236} run: {npc:1952} stands below ground in the crypt, {npc:1938} just north of Allister."] = "Pour votre expédition dans {area:236} : {npc:1952} se tient sous terre dans la crypte, {npc:1938} juste au nord d'Allister.",
		["From {area:272} fly to the {area:228}: {npc:2121} stands by the crypt entrance."] = "Depuis {area:272}, prenez un vol pour le {area:228} : {npc:2121} se tient près de l'entrée de la crypte.",
		["Hadrec and {npc:1938}"] = "Hadrec et {npc:1938}",
		["Poison chain unfinished? Resume your current stage in the Class guide Poisons (Horde); completed quests do not need restarting. Arrange a group for Gallywix, finish the Hinott follow-up, then return to this leveling guide."] = "Suite des poisons inachevée ? Reprenez votre étape actuelle dans le guide de classe Poisons (Horde) ; les quêtes terminées n'ont pas besoin d'être recommencées. Formez un groupe pour Gallywix, terminez la suite d'Hinott, puis revenez à ce guide de progression.",
		["Take {quest:31} from {npc:11802}, who stands upstairs in his building. Then {npc:11798} in {area:2361} flies druids to {area:1638}: {npc:3033} is on {area:1639}."] = "Prenez {quest:31} auprès de {npc:11802}, qui se tient à l'étage de son bâtiment. Ensuite, {npc:11798} à {area:2361} emmène les druides aux {area:1638} : {npc:3033} est sur la {area:1639}.",
		["The farms east of {area:287} town. {npc:232} works the field by the northern farmhouse, {npc:2403} the one further south-east; Farmhands and Farmers are everywhere. {npc:2451} tends the field south of the farms. Careful: Kirin Tor Guards (55) stand north of the farms, on the road up toward Alterac: keep to the fields."] = "Les fermes à l'est du village de {area:287}. {npc:232} travaille le champ près de la ferme du nord, {npc:2403} celui plus au sud-est ; Ouvriers agricoles et Fermiers d'Hillsbrad sont partout. {npc:2451} s'occupe du champ au sud des fermes. Attention : des Gardes du Kirin Tor (55) se tiennent au nord des fermes, sur la route qui monte vers Alterac : restez dans les champs.",
		["The {item:280438} from the {area:153}: Faranell takes it here."] = "La {item:280438} de {area:153} : Faranell la prend ici.",
		["The {quest:95204} from your {area:153} run: {npc:7825} takes it."] = "Le {quest:95204} de votre expédition dans {area:153} : {npc:7825} le prend.",
		["Train and restock in the {zone:1458} before the zeppelin."] = "Entraînez-vous et réapprovisionnez-vous à {zone:1458} avant le zeppelin.",
		["Train before you fly on: the next guide flies from here."] = "Entraînez-vous avant de reprendre un vol : le guide suivant part d'ici en vol.",
		["Train with {npc:3033}. {npc:3419}, in the {area:2197} under {area:1640}, takes Lydon's toxin if you carry it. Before you fly on, {npc:3024} and {npc:4721}, a short walk east of the wind rider master, give two quests worked on the next guides' walks; then fly on to the Crossroads, where the next guide starts."] = "Entraînez-vous auprès de {npc:3033}. L'{npc:3419}, dans les {area:2197} sous la {area:1640}, prend la toxine de Lydon si vous l'avez. Avant de repartir, {npc:3024} et {npc:4721}, à quelques pas à l'est du maître des coursiers du vent, donnent deux quêtes qui se font en chemin dans les guides suivants ; puis prenez un vol pour la Croisée, où commence le guide suivant.",
		["West of Tarren Mill, Gray Bears, Forest Moss Creepers and Starving Mountain Lions roam the hills on the way down to the farms. The creepers drop {item:3477} rarely; you need only one."] = "À l'ouest de Moulin-de-Tarren, des Ours gris, des Rampemousses forestières et des Lions des montagnes affamés parcourent les collines en descendant vers les fermes. Les rampemousses lâchent rarement l'{item:3477} ; il vous en faut un seul.",
		["While you're here: learn Polearms from {npc:11870} ({object:36070}, 1 gold); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Pendant que vous y êtes : apprenez le maniement des armes d'hast auprès de {npc:11870} ({object:36070}, 1 pièce d'or) ; l'arme de mêlée d'un Chasseur vaut surtout par ses caractéristiques, et les armes à deux mains en portent le plus.",
		["While you're here: learn Polearms from {npc:11870} ({object:36070}, 1 gold); two-handers level a Warrior fastest."] = "Pendant que vous y êtes : apprenez le maniement des armes d'hast auprès de {npc:11870} ({object:36070}, 1 pièce d'or) ; les armes à deux mains font progresser un Guerrier le plus vite.",
		["While you're here: learn Swords from {npc:11870} ({object:36070}, 10 silver); a sword in the main hand levels a Rogue steadily."] = "Pendant que vous y êtes : apprenez le maniement des épées auprès de {npc:11870} ({object:36070}, 10 pièces d'argent) ; une épée en main droite fait progresser un Voleur régulièrement.",
		["While you're here: learn {spell:202} from {npc:11870} ({object:36070}, 10 silver); two-handers level a Paladin fastest."] = "Pendant que vous y êtes : apprenez {spell:202} auprès de {npc:11870} ({object:36070}, 10 pièces d'argent) ; les armes à deux mains font progresser un Paladin le plus vite.",
		["While you're here: learn {spell:202} from {npc:11870} ({object:36070}, 10 silver); two-handers level a Warrior fastest."] = "Pendant que vous y êtes : apprenez {spell:202} auprès de {npc:11870} ({object:36070}, 10 pièces d'argent) ; les armes à deux mains font progresser un Guerrier le plus vite.",
		["Your {area:153} limbs: {npc:266484} stands in the {object:36126}, just past the Apothecarium."] = "Vos membres de {area:153} : {npc:266484} se tient dans le {object:36126}, juste après l'Apothicarium.",
		["Zeppelin to {zone:1454}"] = "Zeppelin pour {zone:1454}",
		["{area:236} is a dungeon for a group of five, about levels 20 to 30, and a full run takes about an hour. Follow the road south from the {area:228}: the keep stands on the hill above {area:204}, its gate at the top of the path.\nInside: Rethilgore first; the Deathstalker freed from the cells after him opens the courtyard door, and {npc:4444} lies just inside the courtyard, to the right: hand {quest:1098} in to him there. Then {npc:3886}, {npc:3887}, {npc:4278}, {npc:4279}, {npc:4274} and {npc:3927}; {npc:4275} at the top drops his head for {npc:1938}."] = "{area:236} est un donjon pour un groupe de cinq, vers les niveaux 20 à 30, et une expédition complète prend environ une heure. Suivez la route vers le sud depuis le {area:228} : le donjon se dresse sur la colline au-dessus de {area:204}, sa porte en haut du chemin.\nÀ l'intérieur : Rethilgore d'abord ; le Traqueur de la mort libéré des cellules après lui ouvre la porte de la cour, et {npc:4444} gît juste à l'entrée de la cour, à droite : rendez-lui {quest:1098} sur place. Ensuite {npc:3886}, {npc:3887}, {npc:4278}, {npc:4279}, {npc:4274} et {npc:3927} ; {npc:4275}, au sommet, lâche sa tête pour {npc:1938}.",
		["{area:272} flight master"] = "Maître de vol de {area:272}",
		["{area:272} is your base for this guide: you come back here between each loop. Everyone stands around the town square."] = "{area:272} est votre base pour ce guide : vous y revenez entre chaque boucle. Tout le monde se tient autour de la place du village.",
		["{area:275}: kill these as you meet them"] = "{area:275} : tuez-les au passage",
		["{area:286}: kill these as you meet them"] = "{area:286} : tuez-les au passage",
		["{item:15885}: use a half at the {area:2362}"] = "{item:15885} : utilisez une moitié au {area:2362}",
		["{item:5620}, from the Syndicate Shadow Mages"] = "{item:5620}, sur les Mages de l'ombre du Syndicat",
		["{npc:11798} in {area:2361} flies druids there"] = "{npc:11798} à {area:2361} y emmène les druides",
		["{npc:1952}, below ground"] = "{npc:1952}, sous terre",
		["{npc:2055}, in the Apothecarium"] = "{npc:2055}, dans l'Apothicarium",
		["{npc:2121}: {area:233}'s pendants"] = "{npc:2121} : les pendentifs de {area:233}",
		["{npc:2216}, inside"] = "{npc:2216}, à l'intérieur",
		["{npc:2216}: Zamah's note"] = "{npc:2216} : la note de Zamah",
		["{npc:2216}: his toxin is for {npc:3419}, on the {zone:1413} & Stonetalon guide's {zone:1456} stop"] = "{npc:2216} : sa toxine est pour l'{npc:3419}, à l'étape {zone:1456} du guide {zone:1413} et Serres-Rocheuses",
		["{npc:2216}: the vials come from the Syndicate Shadow Mages on the way to Durnholde"] = "{npc:2216} : les fioles proviennent des Mages de l'ombre du Syndicat sur la route de Fort-de-Durn",
		["{npc:2229}, inside"] = "{npc:2229}, à l'intérieur",
		["{npc:2230}, next to Lydon; inside"] = "{npc:2230}, à côté de Lydon ; à l'intérieur",
		["{npc:2238}'s ball and chain"] = "Boulet et chaîne de {npc:2238}",
		["{npc:2261} walks around here: look inside the circle on the map"] = "{npc:2261} se promène par ici : cherchez dans le cercle sur la carte",
		["{npc:2274} is {npc:232}'s dog, at the northern farmhouse in {area:286}."] = "{npc:2274} est le chien de {npc:232}, à la ferme du nord dans {area:286}.",
		["{npc:2391}: Poisons"] = "{npc:2391} : Poisons",
		["{npc:3024}: {quest:97538}, the Mirkweed in {area:464} by Sun Rock"] = "{npc:3024} : {quest:97538}, les herbes à {area:464}, près du Roc-du-Soleil",
		["{npc:3419}: the {item:5638}, for {area:461} in the next guide"] = "{npc:3419} : le {item:5638}, pour {area:461} dans le guide suivant",
		["{npc:4606} stands in the {object:36070}."] = "{npc:4606} se tient dans le {object:36070}.",
		["{npc:4721}: {quest:1195}, the phial from {zone:1440}'s Laughing Sisters"] = "{npc:4721} : {quest:1195}, la fiole des Sœurs rieuses de {zone:1440}",
		["{quest:1014}: the {item:5442}"] = "{quest:1014} : la {item:5442}",
		["{zone:1454} flight master"] = "Maître de vol d'{zone:1454}",
} end)()
t.guides["forever/horde/07-ashenvale"] = (function() return {
		["A short walk north of the Galak camps, the cave of {area:1557} leads down to its deepest chamber, where the {object:20807} burns. Use the {item:5868} on it, then loot the {item:5869} at once: the flame only stays out briefly, and if it relights the phial is gone. Then east to {npc:2986}'s mesa.\nCareful: Two Galak Flame Guards (30) stand by the brazier and a centaur guard walks the cave: pull them away one at a time before you douse the flame."] = "À courte distance au nord des camps galak, la grotte de {area:1557} descend jusqu'à sa salle la plus profonde, où brûle {object:20807}. Utilisez {item:5868} dessus, puis ramassez aussitôt {item:5869} : la flamme ne reste éteinte que brièvement, et si elle se rallume la fiole est perdue. Ensuite, partez à l'est vers la mesa de {npc:2986}.\nAttention : deux Gardes de la flamme galak (30) se tiennent près du brasero et un garde centaure arpente la grotte : attirez-les un par un à l'écart avant d'éteindre la flamme.",
		["Back east to {area:484}."] = "Retournez à l'est jusqu'au {area:484}.",
		["Back south to the camp, then up into {zone:1456} for the flight to {area:378}."] = "Retournez au camp au sud, puis montez à {zone:1456} pour le vol vers {area:378}.",
		["Back south-west to {area:421}. {npc:12759}, a corrupted water elemental, drifts around the lake's island and under the water. She drops the {item:16408} only once you have {quest:25} from {npc:12737}; it starts a quest for Splintertree."] = "Revenez vers le sud-ouest jusqu'au {area:421}. {npc:12759}, une élémentaire d'eau corrompue, dérive autour de l'île du lac et sous l'eau. Elle ne lâche le {item:16408} qu'une fois que vous avez {quest:25} de {npc:12737} ; il lance une quête pour le Poste de Bois-brisé.",
		["Back to {npc:12867} at the lumber camp, on the road north to Splintertree."] = "Retour auprès de {npc:12867} au camp de bûcherons, sur la route du nord vers le Poste de Bois-brisé.",
		["Back west to Zoram'gar from Thistlefur before heading east for good."] = "Depuis Tombe-Chardon, retournez à Zoram'gar à l'ouest avant de partir pour de bon vers l'est.",
		["Befouled Water Elementals drift around the lake's shores; the gazebo stands on the island, overlooking the Alliance outpost."] = "Des Elémentaires d’eau souillés dérivent le long des rives du lac ; le belvédère se dresse sur l'île et domine l'avant-poste de l'Alliance.",
		["Below ground"] = "Sous terre",
		["Class trainer"] = "Maître de classe",
		["Crossroads flight master"] = "Maître de vol de la Croisée",
		["East along the road from Seereth's camp to the Crossroads' wind rider master, and fly to {area:2897}. If your hearthstone is ready, hearth to {area:378} and fly from there instead."] = "À l'est par la route depuis le camp de Seereth jusqu'au maître des coursiers du vent de la Croisée, puis prenez un vol pour l'{area:2897}. Si votre Pierre de foyer est prête, utilisez-la pour aller au {area:378} et prenez plutôt un vol depuis là-bas.",
		["East of Zoram'gar, the Thistlefur furbolgs fill the village and the hills around their hold.\nCareful: A Shaman at 15% health or lower runs off to find help, which can pull extra furbolgs."] = "À l'est de Zoram'gar, les furbolgs Crins-de-chardon remplissent le village et les collines autour de leur repaire.\nAttention : un Chaman à 15 % de vie ou moins fuit chercher de l'aide, ce qui peut attirer des furbolgs en plus.",
		["Felmusk satyrs"] = "Satyres Gangremusc",
		["Fly to {area:1638}"] = "Prendre un vol pour {area:1638}",
		["Fly to {area:1638} from Zoram'gar. If you don't know its flight path, fly to {area:378} and walk north through {zone:1412} instead."] = "Prenez le vol de Zoram'gar pour {area:1638}. Si vous ne connaissez pas ce trajet aérien, volez plutôt jusqu'à {area:378} et marchez vers le nord à travers {zone:1412}.",
		["Fly to {area:2897}"] = "Prendre un vol pour {area:2897}",
		["Fly to {area:378}"] = "Prendre un vol pour {area:378}",
		["Follow the main road east past {area:415} (Alliance: keep to the road). {npc:12678}, a big grizzly, roams the {area:418} south of the road, west of {area:421}. His paw starts the next hunt quest."] = "Suivez la route principale vers l'est après {area:415} (Alliance : restez sur la route). {npc:12678}, un grand grizzly, rôde dans {area:418}, au sud de la route, à l'ouest de {area:421}. Sa patte lance la quête de chasse suivante.",
		["For your {area:2797} run, in the same tunnels as the Sapphires: {npc:12736}'s ruins errand. Look for a group now if you have none yet."] = "Pour votre expédition dans {area:2797}, dans les mêmes tunnels que les Saphirs : la mission des ruines de {npc:12736}. Cherchez un groupe maintenant si vous n'en avez pas encore.",
		["From the {area:2360} head north-east to the Warsong lumber camp on the road: {npc:12867} stands there."] = "Depuis {area:2360}, allez au nord-est jusqu'au camp de bûcherons chanteguerre, sur la route : {npc:12867} s'y tient.",
		["Galak centaurs"] = "Centaures galak",
		["Gazebo"] = "Belvédère",
		["Gloomrise Toxin Samples, from the Gnawed Corpses"] = "Échantillons de toxine de la cime du Chagrin ({item:273001}), sur les Cadavres rongés ({npc:264096})",
		["Grimtotem camps below {area:2097}"] = "Camps du Totem sinistre sous {area:2097}",
		["Inside the hold, Troll Chests lie along the tunnels. {npc:12818} is held deep inside: free him and protect him all the way out, then he runs home to {area:428}.\nCareful: Two scripted ambushes occur, each made up of three Thistlefurs (a Shaman, a Pathfinder and an Avenger, Ursa or Den Watcher): the first when you come back to the tunnel's fork inside the cave, the second just beyond the gate where {npc:3987} roams."] = "Dans le repaire, des Coffres de troll se trouvent le long des tunnels. {npc:12818} est retenu tout au fond : libérez-le et protégez-le jusqu'à la sortie, puis il rentre chez lui à {area:428}.\nAttention : deux embuscades scénarisées ont lieu, chacune composée de trois Crins-de-chardon (un Chaman, un Éclaireur et un Vengeur, une Ursa ou un Protecteur) : la première quand vous revenez à l'embranchement du tunnel dans la grotte, la seconde juste après la porte où rôde {npc:3987}.",
		["Into {area:1638} by a lift: {npc:2995}, the wind rider master, stands on the central rise. Take his flight path if you don't know it yet."] = "Entrez aux {area:1638} par un ascenseur : {npc:2995}, le maître des coursiers du vent, se tient sur le plateau central. Prenez son trajet aérien si vous ne le connaissez pas encore.",
		["Keep east on the road. {npc:12858} waits south-west of the Warsong lumber camp. He and his grunts storm the {area:2360}: let them take aggro and stay with {npc:12858} until {npc:12860} is dead."] = "Continuez vers l'est sur la route. {npc:12858} attend au sud-ouest du Camp de bûcherons chanteguerre. Lui et ses grunts prennent d'assaut {area:2360} : laissez-les attirer l'aggro et restez avec {npc:12858} jusqu'à la mort de {npc:12860}.",
		["Kill the {npc:10720} that comes for {npc:10638}"] = "Tuez {npc:10720} qui s'en prend à {npc:10638}",
		["Laughing Sisters"] = "Les Sœurs rieuses",
		["Level 28"] = "Niveau 28",
		["North of Thunder Bluff"] = "Au nord des Pitons-du-Tonnerre",
		["North of the camp, spiders overrun the burial ground at {area:17044}. Use {npc:264074}'s {item:273015} on the Gnawed Corpses; the Spinners drop the {item:273181}. {npc:264082} (30, elite) sits at the north end: leave her unless you do {quest:96261} with a group; her {item:273658} starts {quest:96294}."] = "Au nord du camp, des araignées envahissent le cimetière de {area:17044}. Utilisez {item:273015} de {npc:264074} sur les Cadavres rongés ; les Spinners laissent {item:273181}. {npc:264082} (30, élite) se tient au nord : laissez-la tranquille sauf si vous faites {quest:96261} en groupe ; son objet {item:273658} lance {quest:96294}.",
		["North-west of Splintertree, the Felmusk satyrs camp in the woods. Every satyr can drop horns. Careful: Felmusk Rogues and Shadowstalkers move in stealth and join fights without warning."] = "Au nord-ouest de Bois-brisé, les Satyres Gangremusc campent dans les bois. Chaque satyre peut laisser des cornes. Attention : les Voleurs et les Traqueurs des ombres Gangremusc se déplacent camouflés et rejoignent les combats sans prévenir.",
		["On the way back north-east to Splintertree: {npc:12676} prowls the woods south-east of the Warsong lumber camp. Her claw starts the next hunt quest. Careful: {npc:12676} is a level 31 nightsaber and hits hard: pull her alone, away from the Outrunners."] = "Sur le chemin du retour vers le nord-est et le Poste de Bois-brisé : {npc:12676} rôde dans les bois au sud-est du camp de bûcherons Chanteguerre. Sa griffe lance la quête de chasse suivante. Attention : {npc:12676} est un sabre-de-nuit de niveau 31 qui frappe fort : attirez-la seule, loin des Estafettes d'Ashenvale.",
		["Only if the {npc:10617} dropped his plot for you: {npc:10638} stands at {area:2237}."] = "Seulement si {npc:10617} vous a laissé son plan : {npc:10638} se tient à {area:2237}.",
		["Ride the lift down, then follow the road east through the canyons to {area:484}, a Tauren village on top of the mesas. Its lift is on the north side."] = "Descendez par l'ascenseur, puis suivez la route vers l'est à travers les canyons jusqu'à {area:484}, un village tauren au sommet des mesas. Son ascenseur est du côté nord.",
		["Sapphires of Aku'Mai"] = "Saphirs d'Aku'Mai",
		["Short of 28? The Grimtotem around these camps (25-28) are the right level: kill a few more before the climb to {npc:10646}. Past it, this step skips itself. Or, with a group, run the {area:2797} dungeon instead."] = "Pas encore 28 ? Les Totem sinistre autour de ces camps (25-28) sont du bon niveau : tuez-en encore quelques-uns avant la montée vers {npc:10646}. Au-delà, cette étape se passe d'elle-même. Ou, en groupe, faites plutôt le donjon {area:2797}.",
		["South from Raynewood, the moonwell sits in a hollow west of the river, hard to see from the road; {area:421} is west of it. Use the {item:5867} at the moonwell to fill it."] = "Au sud de Raynewood, le puits de lune se trouve dans un creux à l'ouest de la rivière, difficile à voir depuis la route ; {area:421} est à l'ouest. Utilisez {item:5867} au puits de lune pour la remplir.",
		["Speak with {npc:3057}, in {area:1638}: {quest:93739}"] = "Parlez à {npc:3057}, à {area:1638} : {quest:93739}",
		["Take the lift down. The egg lies in a nest on the canyon floor in one of three spots: south-east of the mesas (52.3,55.2), east (56.4,50.4) or south-west (37.6,56.1)."] = "Descendez par l'ascenseur. L'œuf repose dans un nid au fond du canyon, à l'un de trois endroits : au sud-est des mesas (52.3,55.2), à l'est (56.4,50.4) ou au sud-ouest (37.6,56.1).",
		["Talk to {npc:3057}"] = "Parlez à {npc:3057}",
		["The Earthen Ring"] = "Le Cercle terrestre",
		["The Earthen Ring camp and its three quests stand up on {area:17045}, north of {zone:1456}. Fly to {zone:1456} if you know its flight path and take a lift down, else fly to {area:378} and walk north through {zone:1412}; the arrow then leads round to the plateau's north end and up onto it."] = "Le camp du Cercle terrestre et ses trois quêtes se trouvent en haut du {area:17045}, au nord des {zone:1456}. Volez jusqu'aux {zone:1456} si vous connaissez son trajet aérien et descendez par un ascenseur, sinon volez jusqu'au {area:378} et marchez vers le nord à travers {zone:1412} ; la flèche fait ensuite le tour jusqu'à l'extrémité nord du plateau et vous y fait monter.",
		["The Earthen Ring camp stands north of the bluffs: {npc:264074}, {npc:264072} and {npc:259118}. From {zone:1456}, take a lift down; coming on foot from {area:378}, keep north past the bluffs."] = "Le camp du Cercle terrestre se dresse au nord des pitons : {npc:264074}, {npc:264072} et {npc:259118}. Depuis les {zone:1456}, descendez par un ascenseur ; si vous venez à pied du {area:378}, continuez vers le nord après les pitons.",
		["The Foulweald furbolgs hold the woods east of {area:421}, south of the road. Place {item:16972} on the {object:178206} and guard it: the furbolgs come to tear it down. {npc:12918} comes last; his totem drops in the basket."] = "Les furbolgs Vile-sylve tiennent les bois à l'est de {area:421}, au sud de la route. Placez {item:16972} sur {object:178206} et gardez-le : les furbolgs viennent l'abattre. {npc:12918} arrive en dernier ; son totem tombe dans la corbeille.",
		["The Galak camps fill the canyon north of Freewind; Scouts, Wranglers and Windchasers share every camp. A lone {npc:10617} walks a long path between the camps: if you meet him, kill him, his note starts a quest for {area:2237}. Don't wait for him. Careful: storm elementals roam the canyon floor around the camps: Stormheart (30), the Ravaging Tempests (40) and {npc:216463} (38), all elite. Keep clear of them."] = "Les camps galak remplissent le canyon au nord du Poste de Librevent ; Eclaireurs, Querelleurs et Chasse-vent galak partagent chaque camp. Un {npc:10617} solitaire parcourt un long chemin entre les camps : si vous le croisez, tuez-le, sa note lance une quête pour {area:2237}. Ne l'attendez pas. Attention : des élémentaires de tempête rôdent au fond du canyon autour des camps : Stormheart (30), les Ravaging Tempests (40) et {npc:216463} (38), tous élites. Tenez-vous à l'écart.",
		["The Laughing Sisters, dryads, wander {area:426} around {npc:12677}'s woods; one of them drops {npc:4721}'s {item:5867}, which can take several kills."] = "Les Sœurs rieuses, des dryades, errent dans {area:426} autour des bois de {npc:12677} ; l'une d'elles laisse {item:5867} de {npc:4721}, ce qui peut demander plusieurs victimes.",
		["The Sapphires are blue crystals on the walls of the tunnels leading to the {area:2797} portal, underground and outside the instance: swim down from the pit, under the wall, into the cave. The satyrs and naga in the tunnels are elite: grouping up is advised. The crystals respawn quickly, so there is no need to go deep."] = "Les Saphirs d'Aku'Mai sont des cristaux bleus sur les parois des tunnels menant au portail de {area:2797}, sous terre et hors de l'instance : plongez depuis la fosse, passez sous le mur et entrez dans la grotte. Les satyres et nagas des tunnels sont élites : il est conseillé de grouper. Les cristaux réapparaissent vite, inutile d'aller loin.",
		["The Wanted poster beside {npc:10537}"] = "L'avis de recherche près de {npc:10537}",
		["The fountain stands in the middle of the {area:418}, where {npc:12678} roams: use the {item:7767} there."] = "La fontaine se trouve au milieu de {area:418}, où rôde {npc:12678} : utilisez-y {item:7767}.",
		["The night elf {quest:6503} (23-24) stalk the woods south and south-east of the lumber camp; they stealth, so watch for them."] = "{quest:6503} (23-24), des elfes de la nuit, rôdent dans les bois au sud et au sud-est du camp de bûcherons ; elles sont camouflées, restez attentif.",
		["The way to the Sapphires is through the sunken ruins at the north end of the strand: go down the stairs into the pit."] = "On rejoint les saphirs par les ruines englouties au nord de la plage : descendez l'escalier dans la fosse.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:10992} is a level 30 elite: most classes solo it at level 32, but you may need help. Skip it if you are alone."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. La {npc:10992} est une élite de niveau 30 : la plupart des classes la tuent seules au niveau 32, mais vous aurez peut-être besoin d'aide. Passez-la si vous êtes seul.",
		["Thistlefur Hold"] = "Antre des Crins-de-Chardon",
		["Underwater"] = "Sous l'eau",
		["Warsong lumber camp"] = "Camp de bûcherons chanteguerre",
		["West of Freewind, the Grimtotem camps below {area:2097}. The Secret Notes are in Document Chests at the south-east, south-west and north-west camps."] = "À l'ouest du Poste de Librevent, les camps du Totem sinistre sous {area:2097}. Les notes secrètes sont dans les Coffres à documents des camps sud-est, sud-ouest et nord-ouest.",
		["West of Mystral Lake, {npc:12678}, a big grizzly, roams the {area:418}: his paw now drops for you."] = "À l'ouest du lac Mystral, {npc:12678}, un grand grizzly, rôde dans {area:418} : sa patte tombe désormais pour vous.",
		["West of Whitereach the wyverns nest on the {area:482} cliffs; the eggs lie in the nests. {npc:10427} waits on the east side of the nesting grounds: free him and keep him alive on the walk back to {area:2237}.\nCareful: Wyverns at level 28-29 fly overhead and can be pulled without warning. A group of three wyverns can ambush you once you pass the first pillar at the bottom. Highperch Patriarchs (30-31) and the rare Heartrazor (32) nest here too: pull around them."] = "À l'ouest de Whitereach, les wyvernes nichent sur les falaises de {area:482} ; les œufs sont dans les nids. {npc:10427} attend du côté est des aires de nidification : libérez-le et gardez-le en vie sur le chemin du retour vers {area:2237}.\nAttention : des wyvernes de niveau 28-29 volent au-dessus de vous et peuvent être attirées sans prévenir. Un groupe de trois wyvernes peut vous tendre une embuscade une fois le premier pilier passé, en bas. Des Patriarches de Haut-perchoir (30-31) et le rare Tranchecœur (32) nichent aussi ici : contournez-les.",
		["While you're here: learn {spell:199} from {npc:11869} (10 silver); two-handers level a Warrior fastest."] = "Pendant que vous y êtes : apprenez {spell:199} auprès de {npc:11869} (10 pièces d'argent) ; les armes à deux mains font progresser un Guerrier le plus vite.",
		["for {npc:5901}, south of {area:392}: next guide"] = "pour {npc:5901}, au sud de {area:392} : guide suivant",
		["grind on {npc:10759}"] = "tuez en boucle : {npc:10759}",
		["the end of the planks"] = "Le bout des planches",
		["{area:17044}: kill these as you meet them"] = "{area:17044} : tuez-les au passage",
		["{area:2797} is a dungeon for a group of five, about levels 22 to 30, and a full run takes about an hour. Its portal is a little further along the tunnels you are in, past the Sapphires.\nInside: the {object:177964} lies under the water of the Moonshrine Ruins' pool, beneath the walkway (clear the crabs first): open it for the {item:16762}, and {quest:6922} comes; open the {item:16782} he drops for a quest for {npc:12736}. The Tide Priestesses sometimes drop a {item:16790}: open it for another quest for {npc:12736}. {npc:4787}, by a campfire in an underwater side room off Ghamoo-ra's room, offers Blackfathom Villainy ({npc:4832}' head, for {npc:9087} on {zone:1456}'s {area:1639})."] = "{area:2797} est un donjon pour un groupe de cinq, vers les niveaux 22 à 30, et une expédition complète prend environ une heure. Son portail se trouve un peu plus loin dans les tunnels où vous êtes, après les Saphirs.\nÀ l'intérieur : la {object:177964} repose sous l'eau du bassin des ruines du Sanctuaire de la Lune, sous la passerelle (éliminez d'abord les crabes) : ouvrez-la pour obtenir le {item:16762}, et {quest:6922} arrive ; ouvrez le {item:16782} qu'il lâche pour une quête de {npc:12736}. Les Prêtresses des marées lâchent parfois une {item:16790} : ouvrez-la pour une autre quête de {npc:12736}. {npc:4787}, près d'un feu de camp dans une salle annexe sous l'eau, à côté de la salle de Ghamoo-ra, propose Blackfathom Villainy (la tête de {npc:4832}, pour {npc:9087} sur la {area:1639} des {zone:1456}).",
		["{area:2797} ruins"] = "Ruines de {area:2797}",
		["{area:2897} flight master"] = "Maître de vol de {area:2897}",
		["{area:418} fountain"] = "Fontaine de {area:418}",
		["{area:484} flight master"] = "Maître de vol de {area:484}",
		["{area:484}'s lift"] = "Ascenseur du {area:484}",
		["{area:485} detour warning: the arrow may miss the path up {area:2097}. If you are on the canyon floor, follow the path and rope bridges up {area:2097}. {npc:10646} is held captive beside {npc:10896} (29): clear the guards and {npc:10896} first, then free her and protect her on the walk down; Grimtotem ambushers come at you on the way."] = "Attention au détour par le {area:485} : la flèche peut rater le chemin qui monte à {area:2097}. Si vous êtes au fond du canyon, suivez le chemin et les ponts de corde jusqu'à {area:2097}. {npc:10646} est retenue captive près de {npc:10896} (29) : éliminez d'abord les gardes et {npc:10896}, puis libérez-la et protégez-la pendant la descente ; des embusqués du Totem sinistre vous attaquent en route.",
		["{item:273181}, from Gloomrise Spinners"] = "{item:273181}, sur les Tisseuses de la cime du Chagrin ({npc:264081})",
		["{item:273658}, from {npc:264082}: it does not drop for everyone"] = "{item:273658}, sur {npc:264082} : il ne tombe pas pour tout le monde",
		["{item:5867}, at the {object:20806}"] = "{item:5867}, à {object:20806}",
		["{item:5867}, from a {npc:4054}"] = "{item:5867}, sur une {npc:4054}",
		["{item:5868}, at the {object:20807}"] = "{item:5868}, à {object:20807}",
		["{item:5869}, from the {object:20807}"] = "{item:5869}, sur {object:20807}",
		["{npc:10079}, at the top of the lift: {npc:10537} at {area:484}"] = "{npc:10079}, en haut de l'ascenseur : {npc:10537} au {area:484}",
		["{npc:10377}, by the wind rider master"] = "{npc:10377}, près du maître des coursiers du vent",
		["{npc:10617}'s {quest:4881}, if you meet him"] = "{quest:4881} de {npc:10617}, si vous le croisez",
		["{npc:10645}, inside"] = "{npc:10645}, à l'intérieur",
		["{npc:11116}, beside {npc:4877}"] = "{npc:11116}, à côté de {npc:4877}",
		["{npc:12576} and {npc:10079} wait at the top of the {area:485}: Maggran's letter is for {npc:12576}, and Moonhorn's message goes down to {area:484} with you."] = "{npc:12576} et {npc:10079} attendent en haut du {area:485} : la lettre de Maggran est pour {npc:12576}, et le message de Moonhorn descend avec vous jusqu'au {area:484}.",
		["{npc:12677}, a shadow panther, stalks the woods around {area:426}, west of the Felmusk camp. Her head starts the next hunt quest."] = "{npc:12677}, une panthère des ombres, rôde dans les bois autour de {area:426}, à l'ouest du camp Gangremusc. Sa tête lance la quête de chasse suivante.",
		["{npc:12696} keeps the hunt board at {area:428}, by the flight master: take {quest:6383} and hand it straight back. {npc:12678}, {npc:12676} and {npc:12677} drop their trophies only after it."] = "{npc:12696} tient le tableau des chasses à {area:428}, près du maître de vol : prenez {quest:6383} et rendez-la aussitôt. {npc:12678}, {npc:12676} et {npc:12677} ne laissent leurs trophées qu'après cela.",
		["{npc:12696}: {quest:247}, once {quest:2} is in"] = "{npc:12696} : {quest:247}, une fois {quest:2} rendue",
		["{npc:12718}: only if you carry the manual pages"] = "{npc:12718} : seulement si vous portez les pages du manuel",
		["{npc:12721}: the troll charms are in Thistlefur Hold, east of the outpost"] = "{npc:12721} : les charmes trolls sont dans l'Antre des Crins-de-Chardon, à l'est de l'avant-poste",
		["{npc:12736} offers a {area:2797} quest next; leave it unless you have a group."] = "{npc:12736} Sancrea propose ensuite une quête à {area:2797} ; laissez-la sauf si vous avez un groupe.",
		["{npc:12736} then offers the next part, {quest:6564}: it is for a second run, so leave it."] = "{npc:12736} propose ensuite la suite, {quest:6564} : elle est prévue pour une seconde expédition, alors laissez-la.",
		["{npc:12736}, {npc:12757} and {npc:12721} stand in the outpost."] = "{npc:12736}, {npc:12757} et {npc:12721} se tiennent dans l'avant-poste.",
		["{npc:12757}: a banner defence in the Foulweald, east of {area:421}: furbolg waves, then {npc:12918}"] = "{npc:12757} : défendre une bannière dans le territoire des Vile-sylve, à l'est de {area:421} : des vagues de furbolgs, puis {npc:12918}",
		["{npc:12818}, below ground"] = "{npc:12818}, sous terre",
		["{npc:12837}, inside the inn"] = "{npc:12837}, dans l'auberge",
		["{npc:259118} offers {quest:96261} only once {quest:96259} is handed in."] = "{npc:259118} ne propose {quest:96261} qu'une fois {quest:96259} rendue.",
		["{npc:259118}: {quest:96261} comes once this is handed in"] = "{npc:259118} : {quest:96261} vient une fois celle-ci rendue",
		["{npc:264082} sits at the north end of {area:17044}; her {item:273658} starts {quest:96294}. {npc:264082} is elite: grouping up is advised."] = "{npc:264082} se tient à l'extrémité nord de {area:17044} ; son {item:273658} lance {quest:96294}. {npc:264082} est un élite : il est conseillé de se grouper.",
		["{npc:2986} stands on a mesa top east of the Galak camps. Taking his {quest:1149} puts you on a high cliff far to the west: follow the stone path to the end of the wooden planks and step off there, and you land safely. Jump from anywhere else and you fall to your death."] = "{npc:2986} se tient au sommet d'une mesa à l'est des camps Galak. Prendre sa {quest:1149} vous dépose sur une haute falaise bien à l'ouest : suivez le chemin de pierre jusqu'au bout des planches de bois et sautez de là, et vous atterrissez sain et sauf. Sautez d'un autre endroit et vous tombez à mort.",
		["{npc:2986}, below ground"] = "{npc:2986}, sous terre",
		["{npc:2986}: {npc:4490}, in the harpy den west of the post"] = "{npc:2986} : {npc:4490}, dans le repaire des harpies à l'ouest du poste",
		["{npc:3024} stands beside {npc:4721}, east of {npc:2995}."] = "{npc:3024} se tient à côté de {npc:4721}, à l'est de {npc:2995}.",
		["{npc:3419} stands in the {area:2197}, the caves under {area:1640}, west of {npc:2995}."] = "L'{npc:3419} se tient dans les {area:2197}, les grottes sous {area:1640}, à l'ouest de {npc:2995}.",
		["{npc:4721} stands a short walk east of {npc:2995}."] = "{npc:4721} se tient à quelques pas à l'est de {npc:2995}.",
		["{npc:4721}: {npc:4722} at {area:484}, later in this guide"] = "{npc:4721} : {npc:4722} à {area:484}, plus loin dans ce guide",
		["{npc:4722} stands in {area:484}: {npc:4721}'s filled phial is for him."] = "{npc:4722} se tient à {area:484} : la fiole remplie de {npc:4721} est pour lui.",
		["{npc:4722}: the {object:20807} in {area:1557}, among the Galak camps"] = "{npc:4722} : {object:20807} dans {area:1557}, parmi les camps galak",
		["{npc:4877}, inside the inn"] = "{npc:4877}, dans l'auberge",
		["{npc:5899}'s hut stands on the ridge above the quilboar watering hole south of {area:378}, on the road to the {area:485}."] = "La hutte de {npc:5899} se dresse sur la crête au-dessus du point d'eau des huttins, au sud du {area:378}, sur la route du {area:485}.",
		["{object:176344}, north-west camp"] = "{object:176344}, camp nord-ouest",
		["{object:176344}, south-east camp"] = "{object:176344}, camp sud-est",
		["{object:176344}, south-west camp"] = "{object:176344}, camp sud-ouest",
		["{quest:1150} ({npc:4490}, 31) waits for the next Freewind visit, at about 30: keep it."] = "{quest:1150} ({npc:4490}, 31) attend la prochaine visite à Librevent, vers le niveau 30 : gardez-la.",
		["{quest:6921}: the {item:16762}, from the {object:177964}"] = "{quest:6921} : le {item:16762}, dans la {object:177964}",
		["{quest:98069}, on the ground around the den"] = "{quest:98069}, par terre autour du repaire",
		["{zone:1456} flight master"] = "Maître de vol des {zone:1456}",
		["{zone:1456}'s central rise"] = "Le plateau central des {zone:1456}",
} end)()
t.guides["forever/horde/30-40/01-hillsbrad-foothills"] = (function() return {
		["Back east to {area:272}."] = "Retournez vers l'est à {area:272}.",
		["Back to the fields: the Peasants work south of the farmhouses. Careful: A fleeing peasant that reaches the town hall can bring back adds; snares or roots keep them from escaping."] = "Retour aux champs : les Paysans travaillent au sud des fermes. Attention : un paysan qui s'enfuit et atteint l'hôtel de ville peut ramener des renforts ; les ralentissements ou les immobilisations les empêchent de s'échapper.",
		["Back to {area:272}."] = "Retour à {area:272}.",
		["City of Dalaran"] = "Cité de Dalaran",
		["Clear {area:290} from the gate in; the dwarves run for help at 30% health."] = "Nettoyez {area:290} en partant de la porte ; les nains fuient chercher de l'aide à 30 % de vie.",
		["Crossroads flight master"] = "Maître de vol de la Croisée",
		["Darthalia's last battle is at {area:290}, the dwarven keep south-east of {area:271}: every dwarf there is elite (28-32), {npc:2304} too. Great XP if you have a group for it."] = "La dernière bataille de Darthalia a lieu à {area:290}, le fort nain au sud-est d'{area:271} : tous les nains y sont élites (28-32), {npc:2304} aussi. Excellente XP si vous avez un groupe pour cela.",
		["Drull's ball and chain"] = "Boulet et chaîne de Drull",
		["Faranell's next {quest:513} needs a {item:3388} ({skill:171}) and the {area:287} coast: leave it."] = "La quête suivante de Faranell, {quest:513}, demande un {item:3388} ({skill:171}) et la côte de {area:287} : laissez-la.",
		["Finish the {item:3712}"] = "Terminez la {item:3712}",
		["Fly to the Crossroads"] = "Vol pour la Croisée",
		["Fly to the {area:228}. The {object:113791} stands on the hill just south-west of it: beat the Corrupt Manifestation of Water beside it, place its bracers in the brazier, speak to the {npc:5895} and keep the {item:7813} for {npc:5901}. Fly on to {area:272} from the {area:228}."] = "Prenez un vol pour {area:228}. Le {object:113791} se dresse sur la colline juste au sud-ouest : battez la Manifestation d'eau corrompue à côté, placez ses brassards dans le brasero, parlez à la {npc:5895} et gardez l'{item:7813} pour {npc:5901}. De {area:228}, continuez en vol jusqu'à {area:272}.",
		["Fly to {area:1497}"] = "Prendre un vol pour {area:1497}",
		["Fly to {area:1637}"] = "Prendre un vol pour {area:1637}",
		["Fly to {area:272}"] = "Prendre un vol pour {area:272}",
		["For characters of 29 to 31: the {quest:527}, {area:272}'s errands and the gnolls of the foothills, all at or under your level."] = "Pour les personnages de niveau 29 à 31 : {quest:527}, les tâches de {area:272} et les gnolls des contreforts, tous à votre niveau ou en dessous.",
		["For your City of Dalaran run, later in this guide: {npc:2278} stands in {area:272}, a short walk east of {npc:2410}."] = "Pour votre expédition dans Cité de Dalaran, plus loin dans ce guide : {npc:2278} se tient à {area:272}, à quelques pas à l'est de {npc:2410}.",
		["From the blossoms, back north along the river and then west to {area:287} town, well north of {area:271} (its guards are 55)."] = "Depuis les fleurs, remontez vers le nord le long de la rivière puis allez à l'ouest jusqu'au village d'{area:287}, bien au nord d'{area:271} (ses gardes sont niveau 55).",
		["Hillsbrad Peasants"] = "Paysans d'Hillsbrad",
		["Inside"] = "À l'intérieur",
		["Inside {area:288}"] = "Dans {area:288}",
		["Keep Infiltration in your log: its Syndicate (32-35) are over you now, and the 38-39 guide (Alterac and Arathi) works it on its first {area:272} loop."] = "Gardez Infiltration dans votre journal : son Syndicat (32-35) est au-dessus de votre niveau pour l'instant, et le guide 38-39 (Alterac et Arathi) la traite lors de sa première boucle à {area:272}.",
		["Keep these in your log: their camps are two to four levels over you now, and the 38-39 guide works them on its first {area:272} loop and in {area:321}."] = "Gardez-les dans votre journal : leurs camps ont deux à quatre niveaux de plus que vous pour l'instant, et le guide 38-39 les traite lors de sa première boucle à {area:272} et à {area:321}.",
		["Level 30"] = "Niveau 30",
		["North of Southshore"] = "Au nord d'Austrivage",
		["North-east back to {area:272}, passing well north of {area:271} (its guards are 55)."] = "Au nord-est, retour à {area:272}, en passant bien au nord d'{area:271} (ses gardes sont de niveau 55).",
		["Snapjaws"] = "Gueules d'acier",
		["South of the river's bend, the Mudsnout gnolls (26-28) camp in the hills above {area:290}; the blossoms grow among their tents. The Shamans heal and call their friends: pull them first."] = "Au sud du coude de la rivière, les gnolls Groin-de-boue (26-28) campent dans les collines au-dessus de {area:290} ; les fleurs poussent parmi leurs tentes. Les chamans soignent et appellent leurs alliés : attirez-les en premier.",
		["Thaivand's next errand, the flames, sends you among the Mountain and Giant Yetis (32-34) and to Helcular's grave inside {area:271}: leave it."] = "La course suivante de Thaivand, les flammes, vous envoie parmi les Yétis des montagnes et les Yétis géants (32-34) et jusqu'à la tombe d'Helcular dans {area:271} : laissez-la.",
		["The City of Dalaran is a dungeon for a group of five, about levels 28 to 33, under the violet dome. Without the {item:277507}, go in through the sewer pipe north-west of the crater: the arrow leads there.\nInside: {npc:247126} is {npc:2278}'s. {npc:268743}, in the sewer, gives Opportunistic Education and takes it back there."] = "Cité de Dalaran est un donjon pour un groupe de cinq, vers les niveaux 28 à 33, sous le dôme violet. Sans la {item:277507}, entrez par la canalisation d'égout au nord-ouest du cratère : la flèche y mène.\nÀ l'intérieur : {npc:247126} est pour {npc:2278}. {npc:268743}, dans les égouts, donne Opportunistic Education et la reprend là-bas.",
		["The river south of {area:272}: kill these as you meet them"] = "La rivière au sud de {area:272} : tuez-les au passage",
		["The smithy"] = "La forge",
		["The {quest:567} poster hangs by the inn; {npc:2216} stands inside it. {npc:2393}, the cook by the inn, wants turtle meat and sells the spices for it."] = "L'affiche de {quest:567} est près de l'auberge ; l'{npc:2216} se tient à l'intérieur. {npc:2393}, le cuisinier près de l'auberge, veut de la viande de tortue et vend les épices nécessaires.",
		["Town hall"] = "Hôtel de ville",
		["Train"] = "Entraînement",
		["Train while you are in the {zone:1458}: the trainers stand in the {object:36070}, the {object:36073} and the {object:36082} (Paladins: {npc:260093})."] = "Entraînez-vous pendant que vous êtes à {zone:1458} : les maîtres se trouvent dans {object:36070}, {object:36073} et {object:36082} (paladins : {npc:260093}).",
		["Train your new spells."] = "Apprenez vos nouveaux sorts.",
		["Voidglare, Bel'varil and {npc:2770}"] = "Voidglare, Bel'varil et {npc:2770}",
		["West across the foothills to {area:287} town: the smithy stands in the middle of it. {npc:2404} and his apprentices work at the forge; the {object:1736} is stacked beside it. {npc:2449} walks the west side of the town; {npc:2451} works the field south-east of the town."] = "Vers l'ouest, à travers les contreforts, jusqu'à la ville de {area:287} : la forge se trouve en son milieu. {npc:2404} et ses apprentis travaillent à la forge ; le {object:1736} est empilé à côté. {npc:2449} parcourt le côté ouest de la ville ; {npc:2451} travaille le champ au sud-est de la ville.",
		["West of Tarren Mill, the Cave and Ferocious Yetis (30-32) fill the {area:277} in the hills; about one in sixteen carries the rod. Stay in these caverns: the Mountain and Giant Yetis (32-34) of the cave further north carry it too, but they hit hard and come in pairs."] = "À l'ouest de Moulin-de-Tarren, les Yétis des grottes et les Yétis féroces (30-32) remplissent {area:277}, dans les collines ; environ un sur seize porte le bâtonnet. Restez dans ces cavernes : les Yétis des montagnes et les Yétis géants (32-34) de la grotte plus au nord le portent aussi, mais ils frappent fort et viennent par deux.",
		["West past the hills to the farms east of {area:287} town. {npc:232} works the field by the northern farmhouse, {npc:2403} the one further south-east; Farmhands and Farmers are everywhere.\nCareful: Kirin Tor Guards (55) patrol {area:287}'s fields and roads and attack the Horde: keep an eye out for them and stay out of their way."] = "À l'ouest après les collines, jusqu'aux fermes à l'est du village d'{area:287}. {npc:232} travaille le champ près de la ferme du nord, {npc:2403} celui plus au sud-est ; il y a des Ouvriers agricoles et des Fermiers partout.\nAttention : des Gardes du Kirin Tor (55) patrouillent dans les champs et sur les routes d'{area:287} et attaquent la Horde : guettez-les et ne vous mettez pas sur leur chemin.",
		["Zeppelin to {zone:1458}"] = "Zeppelin pour {zone:1458}",
		["for {npc:2055}, on the {zone:1458} stop at the end of this guide"] = "pour le {npc:2055}, lors de l'étape à {zone:1458} à la fin de ce guide",
		["for {npc:2425} in the {zone:1458}, at the end of this guide"] = "pour {npc:2425} à {zone:1458}, à la fin de ce guide",
		["for {npc:4483} in the {area:439}, next guide"] = "pour {npc:4483} aux {area:439} : guide suivant",
		["for {npc:5901}, next guide"] = "pour {npc:5901} : guide suivant",
		["{area:228} flight master"] = "Maître de vol du {area:228}",
		["{area:272} flight master"] = "Maître de vol de {area:272}",
		["{area:378} flight master"] = "Maître de vol du {area:378}",
		["{area:392} flight master"] = "Maître de vol de {area:392}",
		["{item:3712}, from the Snapjaws"] = "{item:3712}, sur les Happe-mâchoires",
		["{item:3713}, from {npc:2393}"] = "{item:3713}, chez {npc:2393}",
		["{item:6637}: drink it by the standing stone to see the elemental"] = "{item:6637} : buvez-le près de la pierre levée pour voir l'élémentaire",
		["{npc:2055} stands in the Apothecarium, in the {object:36126}."] = "{npc:2055} se tient dans l'Apothicarium, dans le {object:36126}.",
		["{npc:2215}: her next {quest:539}, and {npc:2419}'s sword, are elite group quests at {area:290}: take them only with a group"] = "{npc:2215} : sa {quest:539} suivante et l'épée de {npc:2419} sont des quêtes de groupe élites à {area:290} : ne les prenez qu'avec un groupe",
		["{npc:2216}, inside"] = "{npc:2216}, à l'intérieur",
		["{npc:2229} wants his two scouts freed from {area:275}."] = "{npc:2229} veut que ses deux éclaireurs soient libérés de {area:275}.",
		["{npc:2229}, inside"] = "{npc:2229}, à l'intérieur",
		["{npc:2229}, inside: Infiltration, worked on the 38-39 visit (its Syndicate are 32-35)"] = "{npc:2229}, à l'intérieur : Infiltration, faite lors du passage 38-39 (son Syndicat est 32-35)",
		["{npc:2238}'s ball and chain"] = "Boulet et chaîne de {npc:2238}",
		["{npc:2393}: {quest:7321}, the Snapjaws of the river south of town"] = "{npc:2393} : {quest:7321}, les Happe-mâchoires de la rivière au sud du village",
		["{npc:2410} and {npc:2437} are inside the inn, {npc:2770} just outside it. Their quests are offered from level 30; below it, the 38-39 guide's first {area:272} stop takes them."] = "{npc:2410} et le {npc:2437} sont dans l'auberge, {npc:2770} juste devant. Leurs quêtes sont proposées à partir du niveau 30 ; en dessous, la première étape du guide 38-39 à {area:272} les prend.",
		["{npc:2410}, inside: {quest:544}, for the 38-39 visit (the {area:279} crater's traitors are 33-35)"] = "{npc:2410}, à l'intérieur : {quest:544}, pour le passage 38-39 (les traîtres du cratère de {area:279} sont 33-35)",
		["{npc:2410}: {quest:93680}, with {quest:544} on the 38-39 visit"] = "{npc:2410} : {quest:93680}, avec {quest:544} lors du passage 38-39",
		["{npc:2419}'s sword drops from the same {area:290} dwarves (about one in twelve)."] = "L'épée de {npc:2419} tombe sur ces mêmes nains de {area:290} (environ une fois sur douze).",
		["{npc:2425} stands beside Sylvanas in the {object:36126}."] = "{npc:2425} se tient à côté de Sylvanas dans le {object:36126}.",
		["{npc:2425}: Darthalia's commendation"] = "{npc:2425} : la recommandation de Darthalia",
		["{npc:2429}, in the town: {item:3708}, from the yetis on the way to the town hall"] = "{npc:2429}, dans le village : {item:3708}, sur les yétis en route vers l'hôtel de ville",
		["{npc:2437}, inside: {quest:556}, with the crater on the 38-39 visit"] = "{npc:2437}, à l'intérieur : {quest:556}, avec le cratère lors du passage 38-39",
		["{npc:2449}, on the west side of the town"] = "{npc:2449}, du côté ouest de la ville",
		["{npc:260093} trains Paladins in the {zone:1458}."] = "{npc:260093} forme les Paladins à {zone:1458}.",
		["{npc:270038} stands in the Apothecarium. His {quest:97985} is for Stormheart, a level 30 elite who walks the canyon east of {area:484}, on the next guide's way to the {area:439}."] = "{npc:270038} se tient dans l'Apothicarium. Sa quête {quest:97985} vise Stormheart, un élite de niveau 30 qui arpente le canyon à l'est du {area:484}, sur le chemin du prochain guide vers les {area:439}.",
		["{npc:270038}: back to him on the next {zone:1458} stop, at about 38"] = "{npc:270038} : revenez le voir lors de la prochaine étape à {zone:1458}, vers le niveau 38",
		["{npc:2770}, outside the inn: the Boulderfist ogres (32-34) on the 38-39 Arathi visit"] = "{npc:2770}, devant l'auberge : les ogres Rochepoing (32-34) lors du passage 38-39 en Arathi",
		["{npc:3428}: for {npc:4485} in {zone:1454}"] = "{npc:3428} : pour {npc:4485} à {zone:1454}",
		["{npc:4485} stands in the {object:172958}, on the way out to the main gate."] = "{npc:4485} se tient dans la {object:172958}, sur le chemin de la grande porte.",
		["{npc:4949} waits in Grommash Hold, in the {object:172957}."] = "{npc:4949} attend dans le fort Grommash, dans la {object:172957}.",
		["{npc:4949}, Grommash Hold, if you carry it"] = "{npc:4949}, fort Grommash, si vous l'avez",
		["{npc:5901}: your {item:6637}, for the brazier"] = "{npc:5901} : votre {item:6637}, pour le brasero",
		["{object:1761}, inside"] = "{object:1761}, à l'intérieur",
		["{quest:539} with a group"] = "{quest:539} en groupe",
		["{quest:547} with a group"] = "{quest:547} en groupe",
		["{quest:567}, the poster by the inn"] = "{quest:567}, l'affiche près de l'auberge",
		["{quest:96986} from your City of Dalaran run: {npc:2278}, a short walk east of {npc:2410}."] = "{quest:96986} de votre expédition dans Cité de Dalaran : {npc:2278}, à quelques pas à l'est de {npc:2410}.",
		["{zone:1458} flight master"] = "Maître de vol de {zone:1458}",
		["{zone:1458} trainers"] = "Maîtres de {zone:1458}",
} end)()
t.guides["forever/horde/30-40/02-thousand-needles"] = (function() return {
		["Back across to {npc:2986}'s mesa north-east of the post, then take the lift down to the canyon floor. {npc:2986}'s next test, {npc:4499}, is an elite: leave it."] = "Retraversez jusqu'à la mesa de {npc:2986} au nord-est du poste, puis descendez par l'ascenseur au fond du canyon. La prochaine épreuve de {npc:2986}, {npc:4499}, est un élite : laissez-le.",
		["Back east to {area:484}."] = "Retournez à l'est jusqu'au {area:484}.",
		["Back to {area:1637}"] = "Retour à {area:1637}",
		["Clam beds"] = "Bancs de praires",
		["Crossroads flight master"] = "Maître de vol de la Croisée",
		["East to the raceway, on the way south to {area:976}."] = "Vers l'est jusqu'à la piste, en descendant vers le sud jusqu'à {area:976}.",
		["Fly from {zone:1454} to {area:1638} and train with {npc:3033} on {area:1639}; fly on to {area:484} from there."] = "Prenez un vol d'{zone:1454} pour {area:1638} et allez vous entraîner auprès de {npc:3033} sur {area:1639} ; de là, continuez en vol jusqu'à {area:484}.",
		["Fly from {zone:1454} to {area:392}. {npc:5901} camps on the coast a short walk south of the town; fly on to {area:484} from {area:392}."] = "Prenez un vol d'{zone:1454} pour {area:392}. {npc:5901} campe sur la côte, à quelques pas au sud de la ville ; de {area:392}, continuez en vol jusqu'à {area:484}.",
		["Fly to the Crossroads"] = "Vol pour la Croisée",
		["Fly to {area:460}"] = "Prenez un vol pour {area:460}",
		["Fly to {area:484}"] = "Prendre un vol pour {area:484}",
		["Giant Softshell Clams, on the sea floor"] = "Praires géantes, au fond de l'eau",
		["Head east to {area:599}. Beat a Burning Blade cultist down, then use the {item:6436} on it before it dies to fill one {item:6435}. The {npc:13019} stands on the fortress's top floor with the Sceptre. The cultists also drop a {item:20310} now and then (1-5%); if one drops, read it. Leave the red {object:176581} for now: its {npc:11876} is 37, and the second {zone:1443} visit comes back for it."] = "Allez vers l'est jusqu'à {area:599}. Affaiblissez un cultiste de la Lame ardente, puis utilisez la {item:6436} sur lui avant qu'il ne meure pour remplir une {item:6435}. Le {npc:13019} se tient au dernier étage de la forteresse avec le Sceptre. Les cultistes laissent aussi parfois tomber une {item:20310} (1-5 %) ; si vous en obtenez une, lisez-la. Laissez le {object:176581} rouge pour l'instant : son {npc:11876} est de niveau 37, et la seconde visite en {zone:1443} y reviendra.",
		["Head south out of Stonetalon into {zone:1443} and follow the road south to {npc:11596}'s camp."] = "Quittez les Serres-Rocheuses vers le sud pour entrer en {zone:1443} et suivez la route vers le sud jusqu'au camp de {npc:11596}.",
		["Keep killing silithid at the dig site for the heart, the talons and the carapaces."] = "Continuez à tuer des silithides sur le site de fouilles pour le cœur, les serres et les carapaces.",
		["Level 32"] = "Niveau 32",
		["North from the dig to {npc:4483}'s camp on the western edge of the flats."] = "Du site de fouilles, allez vers le nord jusqu'au camp de {npc:4483}, à la lisière ouest des Salines.",
		["North-east of the raceway onto the flats. The Saltstone Basilisks (30-31) sun themselves north-west of it, and the Sparkleshell Tortoises (30-31) wander among them on the western flats; the Salt Flats Scavengers and Vultures circle the eastern flats. Every vulture drops a bone, about one tortoise in three a shell.\nCareful: Scavengers and Vultures use Execute when your health is low. The Sparkleshell Snappers (34-35) crowd round a half-buried ship in the north-east and are over you here: the Tortoises of the western flats drop the shells just as often, so stay with them. Take the venom from the Reavers (31-32) of the north half and leave the Scorpid Terrors (33-34) further south."] = "Au nord-est de la piste, sur les Salines. Les Basilics du sel gemme (30-31) se chauffent au soleil au nord-ouest, et les Tortues nacrétoile (30-31) errent parmi eux à l'ouest des Salines ; les Charognards des Salines et les Vautours tournoient à l'est. Chaque vautour laisse un os, environ une tortue sur trois une carapace.\nAttention : Charognards et Vautours utilisent Exécution quand votre vie est basse. Les Mordeuses nacrétoile (34-35) se massent autour d'un navire à demi enterré au nord-est et sont trop fortes pour vous : les Tortues de l'ouest laissent les carapaces tout aussi souvent, restez donc avec elles. Prenez le venin sur les Ravageurs (31-32) de la moitié nord et laissez les Scorpides terrifiants (33-34) plus au sud.",
		["On the top floor"] = "Au dernier étage",
		["Scorpid Reavers"] = "Scorpides ravageurs",
		["South from the raceway over the {zone:1446} border to {area:976}, the walled goblin town: learn its flight path and fly back to {area:484} from there, which is quicker than the walk west across the flats, and the next guides fly straight to {area:976}."] = "Au sud depuis la piste, passez la frontière de {zone:1446} jusqu'à {area:976}, la ville gobeline fortifiée : apprenez son trajet aérien et revenez de là en vol au {area:484}, ce qui est plus rapide que de traverser les Salines à pied vers l'ouest, et les guides suivants volent directement vers {area:976}.",
		["South of the raceway, the Saltstone Crystalhides (32-33) and Gazers (34-35) roam the far end of the flats.\nCareful: the level 35 Gazers can still be two over you: pull them one at a time from the camp's edge, never two together."] = "Au sud de la piste, les Peaux de cristal du sel gemme (32-33) et les Contemplateurs (34-35) parcourent l'extrémité des Salines.\nAttention : les Contemplateurs de niveau 35 peuvent encore avoir deux niveaux de plus que vous : attirez-les un par un depuis le bord du camp, jamais deux à la fois.",
		["South-west back to the raceway."] = "Retour au sud-ouest vers la piste.",
		["Swim out to {area:2406} off the far northern tip: {object:177786} stands on the shore beside the {object:177673}. Open it with both keys; leave the statue alone."] = "Nagez jusqu'à {area:2406}, au large de la pointe nord : le {object:177786} se trouve sur le rivage à côté de la {object:177673}. Ouvrez-le avec les deux clés ; ne touchez pas à la statue.",
		["Take the lift down and follow the canyon east. {npc:4483} camps on the north-western edge of the salt flats."] = "Descendez par l'ascenseur et suivez le canyon vers l'est. {npc:4483} campe à la lisière nord-ouest des Salines.",
		["The flats' south and the silithid dig are 32-35, {zone:1443}'s quests 32-38. Still below 32 after the raceway's hand-ins? Back north on the flats, the Scorpid Reavers (31-32) roam among the basilisks and tortoises: kill them until level 32; leave the Sparkleshell Snappers (34-35) and the Scorpid Terrors (33-34) alone. Or, with a group, run the {area:1717} dungeon instead."] = "Le sud des Salines et le site silithide sont 32-35, les quêtes de {zone:1443} 32-38. Toujours sous le niveau 32 après les rendus de la piste ? Retournez au nord des Salines : les Scorpides ravageurs (31-32) errent parmi les basilics et les tortues : tuez-les jusqu'au niveau 32 ; laissez les Mordeuses nacrétoile (34-35) et les Scorpides terrifiants (33-34). Ou, en groupe, faites plutôt le donjon de {area:1717}.",
		["The goblins and gnomes of the {area:2240} are neutral and give quests to both factions."] = "Les gobelins et les gnomes de {area:2240} sont neutres et donnent des quêtes aux deux factions.",
		["The southern flats"] = "Le sud des Salines",
		["The zeppelin lands at the tower outside {zone:1454}'s main gate. {npc:5639} walks the Drag: if he isn't at the arrow, look along its streets to the south-west. {npc:5640} stands in the {object:172961} on the west side of the city."] = "Le zeppelin se pose à la tour devant la porte principale d'{zone:1454}. {npc:5639} parcourt la Herse : s'il n'est pas à la flèche, cherchez-le dans ses rues au sud-ouest. {npc:5640} se tient dans {object:172961}, à l'ouest de la ville.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:270094} is a level 30 elite: most classes solo it at level 32, but you may need help. Skip it if you are alone: the route has you grind the XP back.\n{npc:270094} walks the canyon road east of {area:484}'s lift, on the way to the salt flats: kill him for his heart."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {npc:270094} est un élite de niveau 30 : la plupart des classes le battent seules au niveau 32, mais vous aurez peut-être besoin d'aide. Passez-le si vous êtes seul : l'itinéraire vous fait regagner l'expérience en tuant des monstres.\n{npc:270094} arpente la route du canyon à l'est de l'ascenseur du {area:484}, sur le chemin des Salines : tuez-le pour son cœur.",
		["Train while you are in the city."] = "Entraînez-vous pendant que vous êtes en ville.",
		["Underwater"] = "Sous l'eau",
		["Use {npc:11596}'s {item:13892} on an Aged, Dying or {npc:4702} in the graveyard and walk the tamed kodo back to {npc:11596}. At his camp, talk to the kodo: that counts it and lets you tame the next. Five kodos, one at a time. Careful: leave the kodo skulls on the ground alone: opening one raises a {npc:11521} (37-38) that hits hard."] = "Utilisez le {item:13892} de {npc:11596} sur un kodo âgé, un kodo mourant ou un {npc:4702} du cimetière et ramenez le kodo apprivoisé à {npc:11596}. À son camp, parlez au kodo : il est alors compté et vous pouvez apprivoiser le suivant. Cinq kodos, un à la fois. Attention : ne touchez pas aux crânes de kodo au sol : en ouvrir un fait apparaître une {npc:11521} (37-38) qui frappe fort.",
		["West of them the silithid swarm the dig site. Searchers and Hive Drones walk among the mounds; the Invaders (34-35) stay inside the hive cave. The first silithid you kill drops a {item:5877}: open it.\nCareful: Hive Drones call for help when they fall to 20% health, and the {npc:4132} (37, rare) walks the dig: take the Searchers and Drones (32-34) outside first, then pull the Invaders (34-35) one at a time from the cave mouth."] = "À l'ouest, les silithides grouillent sur le site de fouilles. Des Chercheurs et des Drones de la ruche se promènent parmi les monticules ; les Envahisseurs (34-35) restent dans la grotte de la ruche. Le premier silithide que vous tuez laisse tomber une {item:5877} : ouvrez-la.\nAttention : les Drones de la ruche appellent à l'aide quand ils tombent à 20 % de vie, et le {npc:4132} (37, rare) parcourt le site : tuez d'abord les Chercheurs et les Drones (32-34) à l'extérieur, puis attirez les Envahisseurs (34-35) un par un depuis l'entrée de la grotte.",
		["West to the shore. Giant Softshell Clams lie in the shallows and the Enraged Reef Crawlers walk the beach: each clam you open on the sea floor, and some crawlers, give a {item:15874}. Open each one in your bags for its meat.\nThe Drysnap Crawlers and Pincers on the same beach carry {item:15878}, about one in seven."] = "Vers l'ouest jusqu'au rivage. Les Praires géantes reposent dans les hauts-fonds et les Clampants des récifs enragés parcourent la plage : chaque praire que vous ouvrez au fond de l'eau, ainsi que certains clampants, donne une {item:15874}. Ouvrez-la dans vos sacs pour récupérer sa chair.\nLes Clampants claque-sec et les Pinceurs de la même plage portent la {item:15878}, environ un sur sept.",
		["You missed this on the route's earlier visit here: it comes first now. It is quick and opens the quests after it.\n{npc:2986} waits on the mesa just north-east of {area:484}, across the rope bridges.\nFor the {quest:1149}, walk off the end of the planks beside him: you land safely."] = "Vous avez manqué ceci lors du passage précédent de l'itinéraire ici : cela passe d'abord maintenant. C'est rapide et cela ouvre les quêtes qui suivent.\n{npc:2986} attend sur la mesa juste au nord-est du {area:484}, de l'autre côté des ponts de corde.\nPour {quest:1149}, avancez jusqu'au bout des planches à côté de lui et sautez : vous atterrissez sans dommage.",
		["Zeppelin to {zone:1454}"] = "Zeppelin pour {zone:1454}",
		["for {npc:4483} in the {area:439}, later in this guide"] = "pour {npc:4483} dans les {area:439}, plus loin dans ce guide",
		["for {npc:5641} in {zone:1443}, later in this guide"] = "pour {npc:5641} en {zone:1443}, plus loin dans ce guide",
		["grind on {npc:4140}"] = "tuez en boucle : {npc:4140}",
		["on an Aged, Dying or {npc:4702} in the graveyard; don't kill it"] = "sur un kodo âgé, un kodo mourant ou un {npc:4702} du cimetière ; ne le tuez pas",
		["the tamed kodo, at {npc:11596}'s camp: talk to it, five times"] = "le kodo apprivoisé, au camp de {npc:11596} : parlez-lui, cinq fois",
		["{area:392} flight master"] = "Maître de vol de {area:392}",
		["{area:439}: kill these as you meet them"] = "{area:439} : tuez-les en chemin",
		["{area:483}: kill these as you meet them"] = "{area:483} : tuez-les au passage",
		["{area:484} flight master"] = "Maître de vol de {area:484}",
		["{item:15874}: open it in your bags"] = "{item:15874} : ouvrez-la dans vos sacs",
		["{item:15878}, from the Drysnap crabs"] = "{item:15878}, sur les crabes Sèchepince",
		["{item:15881}, from the Slitherblade naga"] = "{item:15881}, sur les nagas Lame-sinueuse",
		["{item:279186}, from {npc:270094}"] = "{item:279186}, sur {npc:270094}",
		["{item:5795}, from the Sparkleshell Tortoises of the western flats"] = "{item:5795}, sur les Tortues nacrétoile de l'ouest des Salines",
		["{item:5843}, from {npc:4490}"] = "{item:5843}, sur {npc:4490}",
		["{npc:10537} stands in the middle of the post, on the way to the flight master."] = "{npc:10537} se tient au milieu du poste, sur le chemin du maître de vol.",
		["{npc:10537}: for {npc:11259} in {zone:1443}, next"] = "{npc:10537} : pour {npc:11259} en {zone:1443}, ensuite",
		["{npc:11259}, up on the rise"] = "{npc:11259}, en haut de la butte",
		["{npc:11863}'s next errand, the {item:15803}, needs {npc:12369} (38) out on {area:2406}: leave it, he is over your level."] = "La course suivante d'{npc:11863}, le {item:15803}, nécessite le {npc:12369} (38) sur {area:2406} : laissez-la, il est au-dessus de votre niveau.",
		["{npc:11877}: for {quest:5762} in Stranglethorn, next guide"] = "{npc:11877} : pour {quest:5762} à Strangleronce, guide suivant",
		["{npc:2986} waits on the mesa just north-east of {area:484}, across the rope bridges."] = "{npc:2986} attend sur la mesa juste au nord-est du {area:484}, de l'autre côté des ponts de corde.",
		["{npc:2986}: {npc:4490}, in the harpy den west of the post"] = "{npc:2986} : {npc:4490}, dans le repaire des harpies à l'ouest du poste",
		["{npc:3428} stands beside the Crossroads flight master."] = "{npc:3428} se tient à côté du maître de vol de la Croisée.",
		["{npc:3428}'s {quest:1145} needed level 29 on the last guide's Crossroads stop: take it now, on a short flight to the Crossroads and back."] = "La quête {quest:1145} de {npc:3428} demandait le niveau 29 lors de l'étape à la Croisée du guide précédent : prenez-la maintenant, avec un court vol aller-retour jusqu'à la Croisée.",
		["{npc:3428}: for {npc:4485} in {zone:1454}"] = "{npc:3428} : pour {npc:4485} à {zone:1454}",
		["{npc:4452}'s crate for {quest:5762} in Stranglethorn, later on the route"] = "La caisse de {npc:4452} pour {quest:5762} à Strangleronce, plus loin sur la route",
		["{npc:4452}: his parts order goes to {quest:1111} in {area:392}, later on the route"] = "{npc:4452} : sa commande de pièces va à {quest:1111} à {area:392}, plus loin sur la route",
		["{npc:4454}: his letter goes to Martek in the {zone:1418}, at 39"] = "{npc:4454} : sa lettre va à Martek dans {zone:1418}, au niveau 39",
		["{npc:4485} stands in the {object:172958}."] = "{npc:4485} se tient dans la {object:172958}.",
		["{npc:4630}: for Gazlowe in {area:392}, later on the route"] = "{npc:4630} : pour Gazlowe à {area:392}, plus loin sur la route",
		["{npc:4877}, inside the inn"] = "{npc:4877}, dans l'auberge",
		["{npc:4877}: her stolen supplies lie in the same harpy den"] = "{npc:4877} : ses fournitures volées se trouvent dans le même repaire de harpies",
		["{npc:4877}: the Screeching harpies of {area:487}"] = "{npc:4877} : les harpies Hurleuses de {area:487}",
		["{npc:5395} stands in the post, {npc:11259} up on its rise; {npc:5641} and {npc:4498} wait on the rise west of it, above the {area:596}."] = "{npc:5395} se tient dans le poste, {npc:11259} en haut de sa butte ; {npc:5641} et {npc:4498} attendent sur la butte à l'ouest, au-dessus du {area:596}.",
		["{npc:5639}: offered from level 30"] = "{npc:5639} : proposée à partir du niveau 30",
		["{npc:5641} and {npc:4498}"] = "{npc:5641} et {npc:4498}",
		["{npc:5641}: for {npc:5640} in {zone:1454}, next guide"] = "{npc:5641} : pour {npc:5640} à {zone:1454}, guide suivant",
		["{npc:5892} stands in the {object:172957}."] = "{npc:5892} se tient dans {object:172957}.",
		["{npc:5892}: for {npc:5905} by {area:484}, later in this guide"] = "{npc:5892} : pour {npc:5905} près de {area:484}, plus loin dans ce guide",
		["{npc:5901}: {npc:3527} and your {item:5177}"] = "{npc:5901} : {npc:3527} et votre {item:5177}",
		["{npc:5905} also starts Elemental Aid ({area:1717}), the 33-40 chain to The Tempest's Weapons: forever/class/shaman/call-of-air-horde."] = "{npc:5905} lance aussi Elemental Aid ({area:1717}), la suite 33-40 menant à The Tempest's Weapons : forever/class/shaman/call-of-air-horde.",
		["{npc:5905} hides in a small cave in the canyon wall north-east of the post, on the way east."] = "{npc:5905} se cache dans une petite grotte de la paroi du canyon au nord-est du poste, sur le chemin de l'est.",
		["{npc:5905}: your {item:5178}"] = "{npc:5905} : votre {item:5178}",
		["{npc:6726}, at the village's south-west end"] = "{npc:6726}, à l'extrémité sud-ouest du village",
		["{object:177787} lies on the ground just south-west of {npc:11863}'s tower, on the way down to the shore: read it. Its two keys drop only while you have the quest."] = "{object:177787} gît sur le sol juste au sud-ouest de la tour de {npc:11863}, sur le chemin qui descend vers le rivage : lisez-le. Ses deux clés ne tombent que si vous avez la quête.",
		["{object:19868}, all over the northern flats: pick it on the western flats, away from the Snappers"] = "{object:19868}, partout au nord des Salines : ramassez-les à l'ouest, loin des Mordeuses",
		["{quest:1104}, from the Scorpid Reavers of the north half"] = "{quest:1104}, sur les Scorpides ravageurs de la moitié nord",
		["{quest:98069}, on the ground around the den"] = "{quest:98069}, par terre autour du repaire",
		["{zone:1454} flight master"] = "Maître de vol d'{zone:1454}",
		["{zone:1454} trainers"] = "Maîtres d'{zone:1454}",
		["{zone:1456} flight master"] = "Maître de vol des {zone:1456}",
} end)()
t.guides["forever/horde/30-40/03-stranglethorn-vale"] = (function() return {
		["Back north to the camp."] = "Retournez au camp, au nord.",
		["Back to {area:1637}"] = "Retour à {area:1637}",
		["Back to {object:3202}."] = "Retour à {object:3202}.",
		["Boat to {area:35}"] = "Bateau pour {area:35}",
		["Dizzywig's parts go back to Kravel in the {area:439}, off the route: leave them."] = "Les pièces de Dizzywig retournent à Kravel dans {area:439}, hors de l'itinéraire : laissez-les.",
		["East of the Mosh'Ogg hills, Shadowmaw Panthers (37-38) stalk the jungle towards the lake; the Stranglethorn Tigresses roam the same ground and now and then drop a pristine fang. Snapjaw Crocolisks line the river just west of the jungle; keep their skins for {npc:2495}. Careful: Shadowmaw Panthers (level 37-38) and Elder Shadowmaw Panthers (level 42-43) use Sneak while out of combat, so they remain hidden until you get near them; the 38s can be two over you: pull them one at a time and leave the Elders alone."] = "À l'est des collines Mosh'Ogg, les Panthères Ombregueule (37-38) rôdent dans la jungle en direction du lac ; les Tigresses de Strangleronce parcourent le même terrain et lâchent de temps en temps un croc intact. Les Crocilisques Gueule d'acier bordent la rivière juste à l'ouest de la jungle ; gardez leurs peaux pour {npc:2495}. Attention : les Panthères Ombregueule (niveau 37-38) et les Anciennes panthères Ombregueule (niveau 42-43) se camouflent hors combat, elles restent donc cachées jusqu'à ce que vous vous approchiez ; celles de niveau 38 peuvent avoir deux niveaux de plus que vous : attirez-les une par une et laissez les Anciennes tranquilles.",
		["Elder Stranglethorn Tigers"] = "Anciens tigres de Strangleronce",
		["Escort {npc:268992} out of the ruins and keep him alive: Lozgil takes the news once he is safe."] = "Escortez {npc:268992} hors des ruines et gardez-le en vie : Lozgil prend les nouvelles une fois qu'il est en sécurité.",
		["Fly from {area:2408} to {area:1638} and train with {npc:3033} on {area:1639}; fly on to {zone:1454} from there."] = "Prenez un vol de {area:2408} pour {area:1638} et allez vous entraîner auprès de {npc:3033} sur {area:1639} ; de là, continuez en vol jusqu'à {zone:1454}.",
		["Fly to {area:1637}"] = "Prendre un vol pour {area:1637}",
		["Fly to {area:35}"] = "Prendre un vol pour {area:35}",
		["Fly to {area:392}"] = "Prendre un vol pour {area:392}",
		["Fly to {object:3202}"] = "Prendre un vol pour {object:3202}",
		["Follow the road north out of {object:3202}; Nesingwary's hunting camp sits on the hill north-east of the river. {npc:773} wants it investigated: walk among its tents. From here on, keep every page of The {item:2755} you loot: {npc:716} takes them on your next Stranglethorn visit."] = "Suivez la route vers le nord depuis {object:3202} ; le camp de chasse de Nesingwary se trouve sur la colline au nord-est de la rivière. {npc:773} veut qu'on enquête dessus : marchez parmi ses tentes. Dès maintenant, gardez chaque page ramassée du livre {item:2755} : {npc:716} les prendra lors de votre prochain passage à Strangleronce.",
		["Lashtail Raptors"] = "Raptors Fouette-queue",
		["Leave {area:35} through the tunnel and follow the road north to {object:3202}, the orc camp on the west side of the vale. Stay on the road: the jungle beside it is above your level."] = "Quittez {area:35} par le tunnel et suivez la route vers le nord jusqu'à {object:3202}, le camp orc à l'ouest de la vallée. Restez sur la route : la jungle alentour est au-dessus de votre niveau.",
		["Level 35"] = "Niveau 35",
		["Level 36"] = "Niveau 36",
		["Mosh'Ogg camp"] = "Camp Mosh'Ogg",
		["Nesingwary's camp"] = "Camp de Nesingwary",
		["North-west of Grom'gol the {area:104} lies under the water off the coast. The {item:4094} rests on the sea floor by the sunken ruins; watch your breath and the murlocs."] = "Au nord-ouest de Grom'gol, {area:104} s'étend sous l'eau au large de la côte. L'{item:4094} repose au fond de la mer près des ruines englouties ; surveillez votre souffle et les murlocs.",
		["On the walk west from Nesingwary's camp, a pile of {object:661516} lies by the path: it starts {quest:97328}, whose Stolen Shipments lie in the {area:102} on the coast ahead."] = "En allant vers l'ouest depuis le camp de Nesingwary, un tas de {object:661516} se trouve près du sentier : il lance {quest:97328}, dont les Cargaisons volées se trouvent dans les {area:102} sur la côte, plus loin.",
		["On your way back south to {object:3202}, the Lashtail Raptors (35-36) hunt the jungle between the camp and {object:3202}: they count for Hemet and for {npc:2464}. Careful: the 36s can be two over you: pull them one at a time. Carnivorous Weeds (36-38) are rooted in the jungle south of the raptors: walk around them."] = "En redescendant vers le sud jusqu'à {object:3202}, les Raptors flagellants (35-36) chassent dans la jungle entre le camp et {object:3202} : ils comptent pour Hemet et pour {npc:2464}. Attention : ceux de niveau 36 peuvent avoir deux niveaux de plus que vous : attirez-les un par un. Des Herbes carnivores (36-38) sont enracinées dans la jungle au sud des raptors : contournez-les.",
		["River Crocolisks lie along the river below the camp. Young Stranglethorn Tigers prowl west of the camp, Young Panthers east of it. Head west past the camp. Stranglethorn Raptors (33-34) hunt the clearings, and the Bloodscalp trolls hold the ruins on the coast: every Bloodscalp can drop a tusk. A {item:4614} is a very rare drop from them: if one drops, read it. Careful: The troll camps have many patrolling mobs, so other trolls often join a fight."] = "Des Crocilisques des rivières se trouvent le long de la rivière sous le camp. Les Jeunes tigres de Strangleronce rôdent à l'ouest du camp, les Jeunes panthères à l'est. Allez vers l'ouest après le camp. Les Raptors de Strangleronce (33-34) chassent dans les clairières, et les trolls Bloodscalp tiennent les ruines sur la côte : chaque Bloodscalp peut lâcher une défense. Le {item:4614} est un butin très rare sur eux : si vous en obtenez un, lisez-le. Attention : les camps trolls ont de nombreuses patrouilles, d'autres trolls rejoignent donc souvent le combat.",
		["Snapjaw Crocolisks"] = "Crocilisques Gueule d'acier",
		["Stolen Shipments, in the ruins"] = "Cargaisons volées, dans les ruines",
		["The Bloodscalp Headhunters (36-37) in the village on the coast carry the shrunken heads. Careful: the 37s can be two over you: pull them one at a time from the village's edge, never into the middle with the Witch Doctors.\nThe Bloodscalp trolls hold the ruins up the coast north of the reef and the village beyond; every one can drop a {item:3915}. Keep looting pages of The {item:2755}."] = "Les Chasseurs de tête Bloodscalp (36-37) du village sur la côte portent les têtes réduites. Attention : ceux de niveau 37 peuvent avoir deux niveaux de plus que vous : attirez-les un par un depuis la lisière du village, jamais au centre avec les Sorciers-docteurs.\nLes trolls Bloodscalp tiennent les ruines plus haut sur la côte, au nord du récif, et le village au-delà ; chacun peut lâcher un {item:3915}. Continuez à ramasser des pages du livre {item:2755}.",
		["The Elder Stranglethorn Tigers (34-35) roam the hills south-west of the camp. Careful: Troll camps are close to the tiger area, and trolls can join a fight if you pull carelessly."] = "Les Anciens tigres de Strangleronce (34-35) parcourent les collines au sud-ouest du camp. Attention : des camps trolls sont proches du territoire des tigres, et des trolls peuvent rejoindre le combat si vous attirez sans prudence.",
		["The Mosh'Ogg ogres camp in the hills just east of {object:3202}, on your way back. Kill 10 Brutes and 5 Witch Doctors (36-37); pull them one at a time. Careful: the 37s can be two over you: take them from the camp's western edge, never two together."] = "Les ogres Mosh'Ogg campent dans les collines juste à l'est de {object:3202}, sur votre chemin du retour. Tuez 10 Brutes et 5 Sorciers-docteurs (36-37) ; attirez-les un par un. Attention : ceux de niveau 37 peuvent avoir deux niveaux de plus que vous : prenez-les depuis la lisière ouest du camp, jamais deux à la fois.",
		["The Shadowmaw Panthers come much later, by {object:3202}"] = "Les Panthères Ombregueule viendront bien plus tard, près de {object:3202}",
		["Train while you are in the city."] = "Entraînez-vous pendant que vous êtes en ville.",
		["Tumbled Crystals, from the geologists of the eastern camps"] = "Cristaux réduits, sur les géologues des camps de l'est",
		["Underwater"] = "Sous l'eau",
		["grind on {npc:1085}"] = "tuez en boucle : {npc:1085}",
		["grind on {npc:1152}"] = "tuez en boucle : {npc:1152}",
		["{area:100}: kill these as you meet them"] = "{area:100} : tuez-les au passage",
		["{area:102}: kill these as you meet them"] = "{area:102} : tuez-les au passage",
		["{area:2408} flight master"] = "Maître de vol de {area:2408}",
		["{area:301}: kill these as you meet them"] = "{area:301} : tuez-les au passage",
		["{area:35} first: the goblins' boat sails there from {area:392}, and every {area:35} quest is for the north of the vale, which you then walk up into."] = "{area:35} d'abord : le bateau des gobelins s'y rend depuis {area:392}, et toutes les quêtes de {area:35} concernent le nord de la vallée, que vous remonterez ensuite à pied.",
		["{area:35} flight master"] = "Maître de vol de {area:35}",
		["{item:277957}, from the Bloodscalp Scouts, Hunters and Mystics"] = "{item:277957}, sur les Éclaireurs, Chasseurs et Mystiques Bloodscalp",
		["{npc:2464} stands in the middle of {object:3202}, {npc:2497} near the zeppelin tower, {npc:2465} beside the flight master."] = "{npc:2464} se tient au centre de {object:3202}, {npc:2497} près de la tour du zeppelin, {npc:2465} à côté du maître de vol.",
		["{npc:2465}: the Shadowmaw claws and the tigress fang come at the end of this guide"] = "{npc:2465} : les griffes d'Ombregueule et le croc de la tigresse viennent à la fin de ce guide",
		["{npc:2495}'s shop is in the building east of the inn; {npc:2498} is on the inn's bottom floor, {npc:2496}, {npc:737} and {npc:773} upstairs beside the flight master. {npc:4631} stands on the pier."] = "La boutique de {npc:2495} est dans le bâtiment à l'est de l'auberge ; {npc:2498} est au rez-de-chaussée de l'auberge, {npc:2496}, {npc:737} et {npc:773} à l'étage, à côté du maître de vol. {npc:4631} se tient sur le quai.",
		["{npc:2495}, inside"] = "{npc:2495}, à l'intérieur",
		["{npc:2496}, upstairs"] = "{npc:2496}, à l'étage",
		["{npc:2497}: for Arathi, later on the route"] = "{npc:2497} : pour les Hautes-terres Arathies, plus loin sur l'itinéraire",
		["{npc:2498}, inside"] = "{npc:2498}, à l'intérieur",
		["{npc:2498}, inside, on the bottom floor"] = "{npc:2498}, à l'intérieur, au rez-de-chaussée",
		["{npc:268992} is held at the east edge of the {area:102}; the Stolen Shipments lie among the ruins around him. The Bloodscalp Scouts, Hunters and Mystics (34-35) there carry his {item:277957}. Then lead him out of the ruins: {npc:4631} in {area:35} takes the news and the shipments.\nCareful: Bloodscalp Berserkers and Headhunters (36-37) and Witch Doctors (37, casters) hold the ruins north and west of {npc:268992}, close to the northern shipments (around 24.9,9.6): pick the shipments in the southern ruins by {npc:268992} first, and pull one at a time if you go north."] = "{npc:268992} est retenu à l'extrémité est des {area:102} ; les Cargaisons volées se trouvent dans les ruines autour de lui. Les Éclaireurs, Chasseurs et Mystiques Bloodscalp (34-35) portent sa {item:277957}. Ensuite, escortez-le hors des ruines : {npc:4631} à {area:35} prend les nouvelles et les cargaisons.\nAttention : les Berserkers et Chasseurs de têtes Bloodscalp (36-37) et les Sorciers-docteurs (37, lanceurs de sorts) tiennent les ruines au nord et à l'ouest de {npc:268992}, près des cargaisons du nord (vers 24.9,9.6) : ramassez d'abord les cargaisons des ruines du sud près de {npc:268992}, et attirez-les un par un si vous allez au nord.",
		["{npc:3391} waits upstairs in the house by the flight master; {quest:1111} stands on the docks, beside the boat."] = "{npc:3391} attend à l'étage de la maison près du maître de vol ; {quest:1111} se tient sur les quais, à côté du bateau.",
		["{npc:3391}, upstairs"] = "{npc:3391}, à l'étage",
		["{npc:3391}: for {npc:4631} in {area:35}, where the boat goes"] = "{npc:3391} : pour {npc:4631} à {area:35}, là où va le bateau",
		["{npc:4631} stands on the pier where the boat docks. {npc:2495}'s shop is in the building east of the inn; {npc:2498} is on the inn's bottom floor, {npc:2496}, {npc:737} and {npc:773} upstairs, {npc:2858} the flight master on the upper deck."] = "{npc:4631} se tient sur la jetée où accoste le bateau. La boutique de {npc:2495} est dans le bâtiment à l'est de l'auberge ; {npc:2498} est au rez-de-chaussée de l'auberge, {npc:2496}, {npc:737} et {npc:773} à l'étage, {npc:2858}, le maître de vol, sur le ponton supérieur.",
		["{npc:4631}, on the pier"] = "{npc:4631}, sur la jetée",
		["{npc:4631}, on the pier: the Stolen Shipments"] = "{npc:4631}, sur le quai : les Cargaisons volées",
		["{npc:4631}: {npc:268992} is safe"] = "{npc:4631} : {npc:268992} est sain et sauf",
		["{npc:5640} stands in the {object:172961} on the west side of the city."] = "{npc:5640} se tient dans {object:172961}, à l'ouest de la ville.",
		["{npc:737}, upstairs"] = "{npc:737}, à l'étage",
		["{npc:773}, upstairs"] = "{npc:773}, à l'étage",
		["{object:3202} flight master"] = "Maître de vol de Grom'gol",
		["{quest:1111}, on the docks"] = "{quest:1111}, sur les quais",
		["{quest:629}'s and Zul'Kunda's quests are next, with Bloodscalp Headhunters of 36-37. Still below 35 after {area:35}'s hand-ins? The Elder Stranglethorn Tigers (34-35) roam the hills north of {object:3202}, below Nesingwary's camp: kill them until level 35. The Lashtail Raptors (35-36) beside them are a level higher."] = "Les quêtes {quest:629} et de Zul'Kunda viennent ensuite, avec des Chasseurs de tête Bloodscalp de niveau 36-37. Toujours sous le niveau 35 après avoir rendu les quêtes de {area:35} ? Les Anciens tigres de Strangleronce (34-35) parcourent les collines au nord de {object:3202}, sous le camp de Nesingwary : tuez-les jusqu'au niveau 35. Les Raptors flagellants (35-36) à côté ont un niveau de plus.",
		["{zone:1434}: kill these as you meet them"] = "{zone:1434} : tuez-les au passage",
		["{zone:1454} flight master"] = "Maître de vol d'{zone:1454}",
		["{zone:1454} trainers"] = "Maîtres d'{zone:1454}",
		["{zone:1456} flight master"] = "Maître de vol des {zone:1456}",
} end)()
t.guides["forever/horde/30-40/04-dustwallow-marsh"] = (function() return {
		["Back north along the coast to {area:392}'s flight master."] = "Remontez la côte vers le nord jusqu'au Maître de vol de {area:392}.",
		["Back to {area:1637}"] = "Retour à {area:1637}",
		["Crossroads flight master"] = "Maître de vol de la Croisée",
		["Drywallow Crocolisks"] = "Crocilisques Sèchefange",
		["East along the road to {area:597}; {npc:5412} stands beside {npc:5395}."] = "Suivez la route vers l'est jusqu'à {area:597} ; {npc:5412} se tient à côté de {npc:5395}.",
		["Every Darkfang spider drops them: Lurkers, Spiders, Venomspitters and the Giant Darkfang Spiders"] = "Chaque araignée Darkfang les laisse tomber : rôdeurs, araignées, Venomspitters et les araignées Darkfang géantes",
		["Fly from {area:2408} to {area:1638} and train with {npc:3033} on {area:1639}; fly on to {zone:1454} from there."] = "Prenez un vol de {area:2408} pour {area:1638} et allez vous entraîner auprès de {npc:3033} sur {area:1639} ; de là, continuez en vol jusqu'à {zone:1454}.",
		["Fly to the Crossroads"] = "Vol pour la Croisée",
		["Fly to {area:1637}"] = "Prendre un vol pour {area:1637}",
		["Fly to {area:2408}"] = "Prendre un vol pour {area:2408}",
		["Fly to {area:2408} from the flight master you are next to: {area:392}'s, or Brackenwall's if you had no errand in {area:392}."] = "Prenez un vol pour {area:2408} depuis le Maître de vol le plus proche : celui de {area:392}, ou celui de Mur-de-Fougères si vous n'aviez rien à faire à {area:392}.",
		["Fly to {area:378}"] = "Volez jusqu'au {area:378}",
		["Fly to {area:392}"] = "Prendre un vol pour {area:392}",
		["Head back west to Brackenwall with the head: {npc:4503} stands at the south edge of the village where the road comes in, {npc:4791} and {npc:4926} in the village."] = "Retournez vers l'ouest à Mur-de-Fougères avec la tête : {npc:4503} se tient à la lisière sud du village, là où arrive la route, {npc:4791} et {npc:4926} dans le village.",
		["Head east from {area:378} along the road into the marsh. The burned-out {area:403} stands beside it just past the border; the shield, the badge and the hoofprints are in and beside the ruin."] = "Allez vers l'est depuis le {area:378} par la route qui entre dans le marais. Les ruines incendiées de {area:403} se dressent au bord, juste après la frontière ; le bouclier, l'insigne et les empreintes de sabots sont dans la ruine et à côté.",
		["Head east to {area:602}. With the {quest:5381} from {npc:11624} in your bags, open a demon portal's ring: a {npc:11937} (38-39) comes out; kill it to close that portal. Six portals. Careful: Infernals, Doomguards and Burning Blade Summoners walk close by many portals and may join in; kill nearby mobs first or drag the guardian away, for example toward the coven's central lake."] = "Allez vers l'est jusqu'à {area:602}. Avec le {quest:5381} de {npc:11624} dans vos sacs, ouvrez l'anneau d'un portail démoniaque : un {npc:11937} (38-39) en sort ; tuez-le pour fermer ce portail. Six portails. Attention : des Infernaux, des Gardes funestes et des Invocateurs de la Lame ardente circulent près de nombreux portails et peuvent se joindre au combat ; tuez d'abord les monstres proches ou éloignez le gardien, par exemple vers le lac central du cercle.",
		["Head north to {area:502}. Stinky stands at the foot of the hill; escort him while he gathers Bogbean Leaves just south of it."] = "Allez vers le nord jusqu'à {area:502}. Stinky se tient au pied de la colline ; escortez-le pendant qu'il ramasse des feuilles de fève des marais juste au sud.",
		["Head south along the coast from {area:392} to {area:720}. {npc:6236} stands by the arena: step on the grate to start the fight; the challengers come one at a time, then {npc:6238} (33)."] = "Descendez la côte vers le sud depuis {area:392} jusqu'à {area:720}. {npc:6236} se tient près de l'arène : marchez sur la grille pour lancer le combat ; les adversaires arrivent un par un, puis {npc:6238} (33).",
		["Head west back across the marsh. The Darkfang Lurkers (36-37) and Venomspitters (37-38) on the ridges north of Brackenwall drop the venom sacs. Theramore Infiltrators (35-36) sneak through the same woods: they are stealthed, so look closely.\nThe Darkmist spiders swarm the cavern mouth north-west of Brackenwall; every kind drops eyes. Work its outer edge, where the Spiders and Recluses (35-37) stand: the Lurkers and Silkspinners (37-39) deeper in are two or three over you.\nCareful: Darkfang Lurkers (level 36-37) use Sneak to stealth while out of combat and cast Poison once fighting.\nCareful: Stealthed spiders in the same area will attack you on sight.\nCareful: Darkmist Lurkers move about stealthed and use poison once in combat. The spiders stand close together, so adds are common; pulling single targets from the outer edge cuts down on them."] = "Retraversez le marais vers l'ouest. Les Rôdeuses Sombrecroc (36-37) et les Crache-venin (37-38), sur les crêtes au nord de Mur-de-Fougères, lâchent les poches de venin. Les Infiltrateurs de Theramore (35-36) se faufilent dans les mêmes bois : ils sont camouflés, regardez bien.\nLes araignées de Sombrebrume grouillent à l'entrée de la caverne au nord-ouest de Mur-de-Fougères ; toutes lâchent des yeux. Restez sur le bord extérieur, où se trouvent les Araignées et les Recluses (35-37) : les Rôdeuses et les Tisseuses (37-39) plus au fond ont deux ou trois niveaux de plus que vous.\nAttention : les Rôdeuses Sombrecroc (niveau 36-37) se camouflent hors combat et lancent Poison une fois en combat.\nAttention : des araignées camouflées dans la même zone vous attaquent à vue.\nAttention : les Rôdeuses de Sombrebrume se déplacent camouflées et utilisent du poison en combat. Les araignées sont serrées les unes contre les autres, les monstres en plus sont donc fréquents ; attirer des cibles isolées depuis le bord extérieur les limite.",
		["Hearth to Shadowprey: your hearthstone is still bound there."] = "Pierre de foyer vers Mort-Bois : elle y est toujours liée.",
		["Jarl lives in the {area:497} south-east of {area:502}."] = "Jarl vit au {area:497}, au sud-est de la {area:502}.",
		["Level 36"] = "Niveau 36",
		["Mirefin murlocs"] = "Murlocs Aileron boueux",
		["North up the road to {area:599}. Clear the middle of the largest building, then use the {item:14523} on the red {object:176581} there. A {npc:11876} (37) comes out: kill it for the {item:13542}. The Burning Blade around it are well under you now."] = "Remontez la route vers le nord jusqu'à {area:599}. Nettoyez le centre du plus grand bâtiment, puis utilisez la {item:14523} sur le {object:176581} rouge qui s'y trouve. Un {npc:11876} (37) en sort : tuez-le pour obtenir la {item:13542}. Les membres de la Lame ardente autour sont désormais bien en dessous de votre niveau.",
		["North-west to the goblin camp on the west side of the {area:596}, back past {area:602}: keep west of the Magram's village."] = "Au nord-ouest jusqu'au camp gobelin, du côté ouest du {area:596}, en repassant par {area:602} : restez à l'ouest du village Magram.",
		["On east to the {area:497}."] = "Continuez vers l'est jusqu'au {area:497}.",
		["On the way east, {npc:4983} waits in the {area:2302} east of the village. Follow him to Reethe and keep him alive through the fight that breaks out: {npc:5045} and Theramore Skirmishers (36) join it."] = "En allant vers l'est, {npc:4983} attend dans {area:2302}, à l'est du village. Suivez-le jusqu'à Reethe et gardez-le en vie pendant le combat qui éclate : le {npc:5045} et des Tirailleurs de Theramore (36) s'y joignent.",
		["Shadowprey"] = "Proie-de-l'Ombre",
		["South-east from the manor to {area:513}: the {object:20925} lies on the sea floor off the docks on the isle's east side. Swim in and out and keep off the piers and the town: Theramore's guards are level 53-57, and a death here is a long run back from the spirit healer. Young Murk Threshers (40-41) circle in the water around the docks: grab the footlocker and swim straight out."] = "Au sud-est du manoir jusqu'à {area:513} : {object:20925} gît au fond de la mer au large des quais, sur la côte est de l'île. Entrez et sortez à la nage et tenez-vous à l'écart des jetées et de la ville : les gardes de Theramore sont de niveau 53-57, et une mort ici vous coûte une longue course depuis le gardien des âmes. Des Jeunes batteurs des boues (40-41) tournent dans l'eau autour des quais : prenez la cantine et repartez droit vers le large.",
		["South-east of the coven, the bone fields of the {area:2657}, where Undead Ravagers roam, at {zone:1443}'s southern edge: keep south of the Magram's village on the way. Use the {item:15848} at the arrow to draw the Magrami Spectres (38-39): they come in numbers, so fight them with your back to the valley's edge. They drop the ghost-o-plasm.\nCareful: Magram Necrokhans and Corpsefeeders (45, elite) walk the bone fields just west of the arrow, well above you: use the crate at the arrow, on the valley's eastern side, and pull the spectres away from them."] = "Au sud-est du cercle, les champs d'ossements de la {area:2657}, où rôdent des Ravageurs morts-vivants, à la limite sud de {zone:1443} : en chemin, restez au sud du village Magram. Utilisez la {item:15848} à la flèche pour attirer les Spectres magrami (38-39) : ils arrivent nombreux, alors combattez-les dos au bord de la vallée. Ils laissent tomber l'ectoplasme.\nAttention : des Nécrokhans magram et des Mange-cadavres (45, élites) parcourent les champs d'ossements juste à l'ouest de la flèche, bien au-dessus de vous : utilisez la caisse à la flèche, du côté est de la vallée, et attirez les spectres loin d'eux.",
		["Stinky Ignatz"] = "Ignatz \"Puant\"",
		["Swamp Eye Jarl"] = "Jarl \"Oeil-des-marais\"",
		["Take the road north at the fork to the ogre village of Brackenwall."] = "À l'embranchement, prenez la route du nord jusqu'au village ogre de Mur-de-Fougères.",
		["The Mirefin murlocs crowd the coast east and north-east of {area:502}; every kind drops heads."] = "Les murlocs Aileron boueux peuplent la côte à l'est et au nord-est de la {area:502} ; tous laissent tomber des têtes.",
		["The middle of {zone:1454}"] = "Le centre d'{zone:1454}",
		["The next guide takes the {zone:1458} zeppelin from the tower outside the main gate."] = "Le prochain guide prend le zeppelin pour {zone:1458} depuis la tour devant la porte principale.",
		["The {area:2657}"] = "{area:2657}",
		["Train while you are in the city; everyone else trains in the {zone:1458}, next."] = "Entraînez-vous pendant que vous êtes en ville ; toutes les autres classes s'entraînent à {zone:1458}, ensuite.",
		["Underwater"] = "Sous l'eau",
		["West of the post, the Maraudine centaurs hold the {area:607}; every Maraudine can drop a {item:254432} and an ear for {npc:5395}'s {quest:1366}. Stay with the Scouts and Wranglers (36-38) at the valley's eastern edge; the Maulers and Windchasers (38-39) a little further in are up to two over you at 37: pull them one at a time.\nCareful: {npc:5402} and the Rock Worms (41-42, elite) hold the valley's north-western end with the Khan Guards and Marauders (39-40), and the Magram's village in the south-east has Necromancers (42-43): keep east of the arrow."] = "À l'ouest du poste, les centaures Maraudine tiennent la {area:607} ; chaque Maraudine peut laisser tomber un {item:254432} et une oreille pour {quest:1366} de {npc:5395}. Restez sur les Éclaireurs et les Dresseurs (36-38) au bord est de la vallée ; les Écorcheurs et les Chasse-vent (38-39) un peu plus loin ont jusqu'à deux niveaux de plus que vous au niveau 37 : attirez-les un par un.\nAttention : {npc:5402} et les Vers des rochers (41-42, élites) tiennent l'extrémité nord-ouest de la vallée avec les Gardes du khan et les Maraudeurs (39-40), et le village Magram au sud-est abrite des Nécromanciens (42-43) : restez à l'est de la flèche.",
		["Zeppelin to {zone:1454}"] = "Zeppelin pour {zone:1454}",
		["for {npc:4485} in {zone:1454}, at the end of this guide"] = "pour {npc:4485} à {zone:1454}, à la fin de ce guide",
		["grind on {npc:4341}"] = "tuez en boucle : {npc:4341}",
		["only if you carry a {item:3853} ({skill:164} or the Auction House)"] = "seulement si vous avez une {item:3853} ({skill:164} ou Hôtel des ventes)",
		["{area:2408} flight master"] = "Maître de vol de {area:2408}",
		["{area:392} flight master"] = "Maître de vol de {area:392}",
		["{area:496} flight master"] = "Maître de vol de {area:496}",
		["{area:496}: kill these as you meet them"] = "{area:496} : tuez-les au passage",
		["{item:14523}, on the {object:176581}"] = "{item:14523}, sur le {object:176581}",
		["{item:3713}, for \"Swamp Eye\" Jarl"] = "{item:3713}, pour « Œil-des-marais » Jarl",
		["{npc:11624} and {npc:12340} stand in the village."] = "{npc:11624} et {npc:12340} se tiennent dans le village.",
		["{npc:11624}: the {quest:5381}, at {area:599} later on this visit"] = "{npc:11624} : {quest:5381}, à {area:599} plus tard lors de ce passage",
		["{npc:12277} is held in the Maraudine camp at the valley's western end; free her and escort her out east of the valley.\nCareful: The scripted groups are linked and only appear during the escort, so you cannot clear them in advance or pull them one at a time. Clearing the normal centaurs on the path before you start does help."] = "{npc:12277} est retenue dans le camp Maraudine, à l'extrémité ouest de la vallée ; libérez-la et escortez-la hors de la vallée, vers l'est.\nAttention : les groupes scénarisés sont liés et n'apparaissent que pendant l'escorte, vous ne pouvez donc pas les éliminer à l'avance ni les attirer un par un. Éliminer avant de commencer les centaures normaux sur le chemin aide quand même.",
		["{npc:12340}: the Slitherblade of Sar'theris Strand, on the way back from {area:599}"] = "{npc:12340} : les Ondulame du rivage de Sar'theris, au retour de {area:599}",
		["{npc:3354}, {object:172958}: for {area:720}, later in this guide (offered from level 30)"] = "{npc:3354}, {object:172958} : pour {area:720}, plus loin dans ce guide (proposée à partir du niveau 30)",
		["{npc:3412}'s workshop is in the {object:172958} beside {npc:4485}: hand in {quest:2841} if you ran {area:133}."] = "L'atelier de {npc:3412} se trouve dans la {object:172958}, à côté de {npc:4485} : rendez {quest:2841} si vous avez fait {area:133}.",
		["{npc:3428} stands beside the Crossroads flight master."] = "{npc:3428} se tient à côté du maître de vol de la Croisée.",
		["{npc:3446} stands below Gazlowe's house by the flight master, towards the docks."] = "{npc:3446} se tient sous la maison de Gazlowe, près du maître de vol, en direction des quais.",
		["{npc:4485} stands in the {object:172958}."] = "{npc:4485} se tient dans la {object:172958}.",
		["{npc:4503}, at the south edge of the village where the road comes in"] = "{npc:4503}, à l'entrée sud du village, là où arrive la route",
		["{npc:5395}: his {quest:1366}, from the same Maraudine as Gurda's totems"] = "{npc:5395} : sa {quest:1366}, sur les mêmes Maraudine que les totems de Gurda",
		["{npc:6019} waits at the goblin camp on the west side of the {area:596}."] = "{npc:6019} attend au camp gobelin, du côté ouest du {area:596}.",
		["{npc:6019}: the ghost-o-plasm, after {area:602} at the end of this visit"] = "{npc:6019} : l'ectoplasme, après {area:602} à la fin de cette visite",
		["{object:20985}, beside the manor"] = "{object:20985}, à côté du manoir",
		["{object:20985}, now that {npc:4791} has read the report"] = "{object:20985}, maintenant que {npc:4791} a lu le rapport",
		["{quest:1218}, if you did not buy them in {zone:1454}"] = "{quest:1218}, si vous ne les avez pas achetées à {zone:1454}",
		["{zone:1443}'s last quests are 36-39. Still below 36 after Brackenwall's hand-ins? The Drywallow Crocolisks (35-36) along the river east of the village are the closest at your level: kill them until level 36."] = "Les dernières quêtes de {zone:1443} sont de niveau 36-39. Toujours sous le niveau 36 après avoir rendu les quêtes de Mur-de-Fougères ? Les Crocilisques Sèchefange (35-36) le long de la rivière à l'est du village sont les plus proches à votre niveau : tuez-les jusqu'au niveau 36.",
		["{zone:1454} flight master"] = "Maître de vol d'{zone:1454}",
		["{zone:1454} trainers"] = "Maîtres d'{zone:1454}",
		["{zone:1456} flight master"] = "Maître de vol des {zone:1456}",
} end)()
t.guides["forever/horde/30-40/05-arathi-highlands"] = (function() return {
		["Back east along the foothills to {area:272}: everything from the first loop is handed in inside the inn."] = "Revenez vers l'est le long des contreforts jusqu'à {area:272} : tout ce qui vient de la première boucle se rend dans l'auberge.",
		["Back north to {area:321}: the doctor stands at the south gate."] = "Retournez au nord à {area:321} : le docteur se tient à la porte sud.",
		["Back north-east to {area:321}."] = "Retournez au nord-est à {area:321}.",
		["Back to {area:272}"] = "Retour à {area:272}",
		["Back to {area:321}"] = "Retour à {area:321}",
		["Below ground"] = "Sous terre",
		["Boulderfist camp"] = "Camp Rochepoing",
		["Boulderfist quests for a group"] = "Quêtes Rochepoing en groupe",
		["Each {object:180105} is a ring of standing stones; the key sits on the stone at its heart. The eastern circle is on the hills north-west of {area:321}.\nCareful: Each center stone is guarded by around three elementals near level 39 that attack together if you click the stone without clearing them: Burning Exiles at West, Thundering Exiles at Outer, Cresting Exiles at East."] = "Chaque {object:180105} est un anneau de pierres levées ; la clé repose sur la pierre en son centre. Le cercle de l'est se trouve sur les collines au nord-ouest de {area:321}.\nAttention : chaque pierre centrale est gardée par environ trois élémentaires proches du niveau 39, qui attaquent ensemble si vous cliquez sur la pierre sans les avoir éliminés : des Exilés ardents à l'ouest, des Exilés foudroyants au cercle extérieur, des Exilés grimpeurs à l'est.",
		["Escort the professor up the hill to the cave above the cove and guard him while he works. Two level 40 water elementals ambush him there, and they are immune to frost. Hold them at the cave mouth, away from him: if the fight happens inside the cave, he joins in instead of working and more elementals keep coming."] = "Escortez le professeur en haut de la colline jusqu'à la grotte au-dessus de la crique et protégez-le pendant qu'il travaille. Deux élémentaires d'eau de niveau 40 lui tendent une embuscade là-haut, et ils sont insensibles au givre. Retenez-les à l'entrée de la grotte, loin de lui : si le combat a lieu dans la grotte, il s'y joint au lieu de travailler et d'autres élémentaires continuent d'arriver.",
		["Find where {quest:503} is held, on the top floor"] = "Trouvez où {quest:503} est retenu, au dernier étage",
		["Fleshstalker raptors"] = "Raptors charognards",
		["Fly to {area:272}"] = "Prendre un vol pour {area:272}",
		["Follow the road east. The violet shards glow just off the road a short way west of {area:321}."] = "Suivez la route vers l'est. Les éclats violets brillent juste à côté de la route, un peu à l'ouest de {area:321}.",
		["Follow the road north out of {area:272} into the Alterac foothills: {quest:535} waits by the Syndicate camp. He offers his errand only while you carry {npc:2229}'s Infiltration: hand him the stout at once, and his reward is the Syndicate Missive Krusk wants. A missive from the Syndicate here does the same: with one in your bags the guide passes {quest:535}."] = "Suivez la route vers le nord depuis {area:272} dans les contreforts d'Alterac : {quest:535} attend près du camp du Syndicat. Il ne propose sa course que si vous avez l'Infiltration de {npc:2229} : donnez-lui tout de suite la bière, et sa récompense est la Missive du Syndicat que veut Krusk. Une missive du Syndicat trouvée ici fait aussi l'affaire : si vous en avez une dans vos sacs, le guide passe {quest:535}.",
		["From the south, walk up into the camp below the violet dome of {area:279}. {npc:2411}, {npc:2412} and {npc:2413} (33-34) stand together in the camp, {npc:2414} (35) a little west of them; each carries one Bloodstone piece. The Shield Guards and Theurgists (31-33) around them drop the Worn Stone Tokens: the ones on the camp's west side are furthest from the Guard's road.\nCareful: Kirin Tor Guards (55) attack the Horde on sight, and one of them patrols the road that comes down into the camp from the north-east and walks right up to the traitors: he has killed many players here. Watch for him, let him walk back up the road, then pull the traitors. Many of the camp's guards stand in linked pairs and others patrol alone. Arcane Sentries (55, elite) and Kirin Tor Enforcers (55) stand around the violet dome itself: keep to the camp below the rim."] = "Par le sud, montez dans le camp sous le dôme violet de {area:279}. {npc:2411}, {npc:2412} et {npc:2413} (33-34) se tiennent ensemble dans le camp, {npc:2414} (35) un peu à l'ouest ; chacun porte un fragment de Pierre de sang. Les Gardes-boucliers et Théurgistes (31-33) autour d'eux laissent tomber les Runes gravées usées : ceux du côté ouest du camp sont les plus éloignés de la route du Garde.\nAttention : les Gardes du Kirin Tor (55) attaquent la Horde à vue, et l'un d'eux patrouille sur la route qui descend dans le camp depuis le nord-est et va jusqu'aux traîtres : il a tué beaucoup de joueurs ici. Surveillez-le, laissez-le remonter la route, puis attirez les traîtres. De nombreux gardes du camp sont liés par deux et attaquent ensemble ; d'autres patrouillent seuls. Des Sentinelles arcaniques (55, élites) et des Massacreurs du Kirin Tor (55) se tiennent autour du dôme violet lui-même : restez dans le camp sous le rebord.",
		["From {area:280} follow the road south-west to {area:1357} and on west to the ruins north of the {area:279} crater, along the lake shore. The Dalaran Summoners lead Elemental Slaves; the bracers drop from the slaves. Careful: Arcane Sentries (55, elite) and Kirin Tor Guards (55) guard the dome itself and attack the Horde: work the ruins' outer edge and don't go up to the dome."] = "Depuis {area:280}, suivez la route vers le sud-ouest jusqu'à {area:1357}, puis continuez vers l'ouest jusqu'aux ruines au nord du cratère de {area:279}, le long de la rive du lac. Les Invocateurs de Dalaran mènent des Elémentaires asservis ; les brassards tombent sur les élémentaires. Attention : des Sentinelles arcaniques (55, élites) et des Gardes du Kirin Tor (55) gardent le dôme lui-même et attaquent la Horde : restez au bord extérieur des ruines et ne montez pas jusqu'au dôme.",
		["Go'shek Farm"] = "Ferme de Go'shek",
		["Head east out of {area:272} through {area:1057} and follow the road east. The Boulderfist Ogres and Enforcers (32-34) camp south of the road, south of {area:313}; the Enforcers stay in the cave there."] = "Sortez de {area:272} vers l'est par le {area:1057} et suivez la route vers l'est. Les Ogres Rochepoing et les Exécuteurs (32-34) campent au sud de la route, au sud du {area:313} ; les Exécuteurs restent dans la grotte.",
		["Head north up the road past {quest:535}'s camp to {area:280}, the Syndicate-held village (35-37). {npc:2431} carries the {item:3704}; {quest:503} sits in a cage in the house on the north side.\nCareful: Stealthed Syndicate spies roam {area:280}, and the buildings hold many Syndicate mobs, mages among them."] = "Remontez la route vers le nord au-delà du camp de {quest:535} jusqu'à {area:280}, le village tenu par le Syndicat (35-37). {npc:2431} porte la {item:3704} ; {quest:503} est enfermé dans une cage, dans la maison du côté nord.\nAttention : des espions camouflés du Syndicat rôdent dans {area:280}, et les bâtiments abritent de nombreux membres du Syndicat, dont des mages.",
		["Head south to the goblins' cove on the southern coast. {npc:2766} keeps watch on the cliff above it."] = "Allez vers le sud jusqu'à la crique des gobelins sur la côte sud. {npc:2766} monte la garde sur la falaise au-dessus.",
		["Head west; the outer circle stands in the middle of the highlands."] = "Allez vers l'ouest ; le cercle extérieur se dresse au milieu des Hautes-terres.",
		["Hearth back to {area:272} (your hearthstone is bound there), or walk back south-east along the road out of Alterac."] = "Utilisez votre Pierre de foyer pour retourner à {area:272} (elle y est liée), ou revenez à pied vers le sud-est par la route qui sort d'Alterac.",
		["Hearth back to {area:272}: your hearthstone is bound there."] = "Utilisez votre Pierre de foyer pour retourner à {area:272} : elle y est liée.",
		["Highland Fleshstalkers (36-37) hunt the southern highlands, a pack north of {area:316} and another on the plain to its west. Pull them one at a time."] = "Des Charognards des hautes-terres ({npc:2561}) (36-37) chassent dans le sud des hautes-terres, une meute au nord de {area:316} et une autre dans la plaine à son ouest. Attirez-les un par un.",
		["Highland raptors and Plains Creepers"] = "Raptors des Hautes-terres et Rampants des plaines",
		["Inside"] = "À l'intérieur",
		["North-east of Hammerfall the Drywhisker kobolds mine the gorge; the Kobolds at the mouth and the Diggers and Surveyors deeper in all drop the Motes of Myzrael.\nCareful: Every kobold type runs off for help when low on health (Kobolds at 30%, Surveyors and Diggers at 15%), which can pull more of them."] = "Au nord-est de Trépas-d'Orgrim, les kobolds Drywhisker exploitent la gorge ; les Kobolds à l'entrée, et les Fouilleurs et les Géomètres plus loin, lâchent tous des Particules de Myzrael.\nAttention : chaque type de kobold fuit chercher de l'aide quand sa vie est basse (les Kobolds à 30 %, les Géomètres et les Fouilleurs à 15 %), ce qui peut en attirer d'autres.",
		["On the way back north, Highland Striders roam the hills all around {area:321} and drop the eyes, and south of it the Plains Creepers (32-33) spin their webs in the grass; they carry the spidersilk."] = "En revenant vers le nord, des Trotteurs des Hautes-terres parcourent les collines tout autour de {area:321} et laissent tomber les yeux ; au sud, les Rampants des plaines (32-33) tissent leurs toiles dans l'herbe : ils portent la soie d'araignée.",
		["Only if you ran Stromgarde with a group: back to {area:321} for its hand-ins, then on to the {area:880}."] = "Seulement si vous avez fait Stromgarde en groupe : retournez à {area:321} pour rendre ses quêtes, puis continuez jusqu'au {area:880}.",
		["Only if {quest:535}'s missive didn't come your way: the Syndicate Footpads and Thieves (32-34) around the camps west of the road carry missives too; about one in three drops one."] = "Seulement si vous n'avez pas obtenu la missive de {quest:535} : les Détrousseurs et Voleurs du Syndicat (32-34) autour des camps à l'ouest de la route portent aussi des missives ; environ un sur trois en laisse tomber une.",
		["South of Hammerfall, the Witherbark trolls hold the village in the hills. Axe Throwers guard the outer huts; the Witch Doctors and Headhunters hold the heart of the village. Careful: All three troll types flee for help at 15% health, which can pull more trolls from the nearby camps."] = "Au sud de Trépas-d'Orgrim, les trolls Fanécorce tiennent le village dans les collines. Des Lanceurs de haches gardent les huttes extérieures ; les Sorciers-docteurs et les Chasseurs de têtes tiennent le cœur du village. Attention : les trois types de trolls fuient chercher de l'aide à 15 % de vie, ce qui peut attirer d'autres trolls des camps voisins.",
		["South of the {area:279} crater's camp"] = "Au sud du camp du cratère de {area:279}",
		["Stromgarde"] = "Stromgarde",
		["Stromgarde quests for a group"] = "Quêtes de Stromgarde en groupe",
		["Syndicate missives"] = "Missives du Syndicat",
		["The Boulderfist Brutes camp outside the ogres' hall, far south-west of {area:321}; the Magus stand among them. Pull them one at a time."] = "Les Brutes Rochepoing campent devant la salle des ogres, loin au sud-ouest de {area:321} ; les Magus se tiennent parmi elles. Attirez-les un par un.",
		["The inner circle lies south of the western circle, east of Stromgarde."] = "Le cercle intérieur se trouve au sud du cercle ouest, à l'est de Stromgarde.",
		["The magus offers a dungeon errand next: leave it."] = "Le magus propose ensuite une mission de donjon : laissez-la.",
		["The next guide crosses the {area:880} into the {zone:1437} and heads for the {zone:1418}."] = "Le prochain guide traverse le {area:880} vers {zone:1437} et se dirige vers {zone:1418}.",
		["The orc stronghold at the eastern end of the road. {npc:2851}, the wind rider master, stands by the gate.\n{npc:15126} offers the {quest:8263} only once you are Friendly with the Defilers ({zone:1461}): skip it if he doesn't offer it."] = "La forteresse orque au bout est de la route. {npc:2851}, la maîtresse des coursiers du vent, se tient près de la porte.\n{npc:15126} ne propose le {quest:8263} qu'une fois que vous êtes Amical auprès des Profanateurs ({zone:1461}) : passez-le s'il ne le propose pas.",
		["The road east through {area:1057}"] = "La route vers l'est par le {area:1057}",
		["The stone's next task needs Fozruk, a level 42 elite who roams west of {area:321}: leave it."] = "La tâche suivante de la pierre demande Fozruk, un élite de niveau 42 qui rôde à l'ouest de {area:321} : laissez-la.",
		["The western circle is near {area:1057}, north-west of the outer one."] = "Le cercle ouest se trouve près du {area:1057}, au nord-ouest du cercle extérieur.",
		["The {area:279} crater"] = "Le cratère de {area:279}",
		["The {object:138492}"] = "{object:138492}",
		["The {object:2690}"] = "{object:2690}",
		["The {object:2691}"] = "{object:2691}",
		["The {object:2701} lie at the far end of the gorge."] = "{object:2701} se trouvent tout au fond de la gorge.",
		["The {object:2702}"] = "{object:2702}",
		["Train while you are in the {zone:1458}: the trainers stand in the {object:36070}, the {object:36073} and the {object:36082} (Paladins: {npc:260093})."] = "Entraînez-vous pendant que vous êtes à {zone:1458} : les maîtres se trouvent dans {object:36070}, {object:36073} et {object:36082} (paladins : {npc:260093}).",
		["Underwater"] = "Sous l'eau",
		["West along the foot of the hills, south of the road: a {npc:246848} (55) walks that road from the north-east down into the traitors' camp."] = "Vers l'ouest au pied des collines, au sud de la route : un {npc:246848} (55) parcourt cette route depuis le nord-est jusqu'au camp des traîtres.",
		["West of the inner circle, Stromgarde's ruins: the Syndicate hold the east half (the Sigil drops from their Conjurors, Prowlers and Magi), the Boulderfist the west half by the {area:325} ({npc:2773} waits in one of the roofless houses beside it)."] = "À l'ouest du cercle intérieur, les ruines de Stromgarde : le Syndicat tient la moitié est (le Sceau tombe sur ses Conjurateurs, Rôdeurs et Mages), les Rochepoing la moitié ouest, près de la {area:325} ({npc:2773} attend dans l'une des maisons sans toit à côté).",
		["Worn Stone Tokens, from the Shield Guards and Theurgists on the camp's west side"] = "Runes gravées usées, sur les Gardes-boucliers et Théurgistes du côté ouest du camp",
		["Zeppelin to {zone:1458}"] = "Zeppelin pour {zone:1458}",
		["for {npc:2487} in {area:35}, around level 41"] = "pour {npc:2487} à {area:35}, vers le niveau 41",
		["{area:17707}: kill these as you meet them"] = "{area:17707} : tuez-les au passage",
		["{area:328}: kill these as you meet them"] = "{area:328} : tuez-les au passage",
		["{item:278225}, from Plains Creepers"] = "{item:278225}, sur les Rampants des plaines",
		["{item:279469}: an object to loot, by the traitors"] = "{item:279469} : un objet à ramasser, près des traîtres",
		["{item:3703}, for {npc:2333}"] = "{item:3703}, pour {npc:2333}",
		["{npc:12920}, at the south gate"] = "{npc:12920}, à la porte sud",
		["{npc:12920}, at the south gate. If he won't take the silk, another player may be running Triage: wait a few minutes and talk to him again."] = "{npc:12920}, à la porte sud. S'il refuse la soie, un autre joueur fait peut-être Triage : attendez quelques minutes et parlez-lui à nouveau.",
		["{npc:12920}, at the south gate. If {npc:12920} offers nothing, another player may be running his {skill:129} quest Triage: he can be busy for a few minutes. Wait, then talk to him again."] = "{npc:12920}, à la porte sud. Si {npc:12920} ne propose rien, un autre joueur fait peut-être sa quête de {skill:129}, Triage : il peut être occupé quelques minutes. Attendez, puis parlez-lui à nouveau.",
		["{npc:2229} will offer {npc:2423} (41, in his manor far up {area:1339}) for this: leave it, he is over your level."] = "{npc:2229} proposera ensuite {npc:2423} (41, dans son manoir loin au nord du {area:1339}) : laissez tomber, il est au-dessus de votre niveau.",
		["{npc:2229}, inside"] = "{npc:2229}, à l'intérieur",
		["{npc:2229}, {npc:2410} and {npc:2437} are inside the inn; {npc:2770} stands outside it."] = "{npc:2229}, {npc:2410} et {npc:2437} sont dans l'auberge ; {npc:2770} se tient devant.",
		["{npc:2410}, inside"] = "{npc:2410}, à l'intérieur",
		["{npc:2410}: {quest:93680}, the {item:279469} is by the traitors"] = "{npc:2410} : {quest:93680}, la {item:279469} est près des traîtres",
		["{npc:2437}, inside"] = "{npc:2437}, à l'intérieur",
		["{npc:270038} stands in the Apothecarium."] = "{npc:270038} se tient dans l'Apothicarium.",
		["{npc:270038}: Stormheart's heart from {zone:1441}"] = "{npc:270038} : le cœur de Stormheart, de {zone:1441}",
		["{npc:2703}'s {quest:639} drops from the elite Syndicate (35-38) in Stromgarde's ruins, the west of the highlands. Great XP if you have a group for it: the route passes Stromgarde on its way to the inner circle."] = "La {quest:639} de {npc:2703} tombe sur les membres élites du Syndicat (35-38) dans les ruines de Stromgarde, à l'ouest des Hautes-terres. Excellente XP si vous avez un groupe pour cela : la route passe par Stromgarde en allant au cercle intérieur.",
		["{npc:2733}'s lab shack stands at Go'shek Farm, north-east of the raptors' plain on the way back to {area:321}; the case of {item:278462} is inside."] = "La cabane-laboratoire de {npc:2733} se trouve à la ferme de Go'shek, au nord-est de la plaine des raptors, sur le chemin du retour vers {area:321} ; la caisse de {item:278462} est à l'intérieur.",
		["{npc:2770}: for {npc:2771} in {area:321}, later in this guide"] = "{npc:2770} : pour {npc:2771} à {area:321}, plus loin dans ce guide",
		["{npc:2771}'s next {quest:678} and {npc:2772}'s {quest:680} are the elite ogres (38-40) in Stromgarde's ogre quarter, on the same group trip as the Sigil."] = "La {quest:678} suivante de {npc:2771} et la {quest:680} de {npc:2772} concernent les ogres élites (38-40) du quartier ogre de Stromgarde, lors de la même sortie de groupe que le Sceau.",
		["{npc:2772}, beside him"] = "{npc:2772}, à côté de lui",
		["{npc:2792}, by the gate"] = "{npc:2792}, près de la porte",
		["{quest:503}, on the top floor"] = "{quest:503}, au dernier étage",
		["{zone:1458} flight master"] = "Maître de vol de {zone:1458}",
		["{zone:1458} trainers"] = "Maîtres de {zone:1458}",
} end)()
t.guides["forever/horde/30-40/06-badlands"] = (function() return {
		["Below ground"] = "Sous terre",
		["Head back south down the road, past the {area:1877}."] = "Redescendez la route vers le sud, en passant {area:1877}.",
		["Head for the {object:2673}, the great bridge at Arathi's southern edge, cross it and follow the road south through the {zone:1437} to the {object:1668} tunnel into {zone:1432}. {area:144}, the dwarf town on the road in the middle of {zone:1432}, has guards who attack the Horde: leave the road before it and pass the town on the hills to its west. The road leaves {zone:1432} to the south into the {zone:1418}; follow it to the goblin camp in the {area:1877}."] = "Dirigez-vous vers le {object:2673}, le grand pont à la limite sud de l'Arathi, traversez-le et suivez la route vers le sud à travers {zone:1437} jusqu'au tunnel de {object:1668} qui mène au {zone:1432}. {area:144}, la ville naine sur la route au milieu du {zone:1432}, a des gardes qui attaquent la Horde : quittez la route avant et contournez la ville par les collines à l'ouest. La route quitte le {zone:1432} par le sud vers {zone:1418} ; suivez-la jusqu'au camp gobelin de la {area:1877}.",
		["Head west along the road towards {area:340}; {npc:2921}'s camp sits in the {area:1878} halfway there."] = "Allez vers l'ouest par la route en direction de {area:340} ; le camp de {npc:2921} se trouve dans {area:1878}, à mi-chemin.",
		["Head west back to {area:340}. {npc:5394} stands on {area:340}'s upper level, high above the flight master: take the ramps up, the arrow cannot tell the levels apart."] = "Retournez vers l'ouest à {area:340}. {npc:5394} se tient au niveau supérieur de {area:340}, bien au-dessus du maître de vol : montez par les rampes, la flèche ne distingue pas les niveaux.",
		["Into the {zone:1418}"] = "Vers {zone:1418}",
		["Keep north on the road to {area:1517}'s entrance, in the north of the {zone:1418}: the chest lies just inside the cave mouth. {npc:2932} and the Obsidian Golems (38) stand beside it and Shadowforge Diggers (35-36) work the tunnel, all elite: keep your group together."] = "Continuez vers le nord par la route jusqu'à l'entrée d'{area:1517}, dans le nord des {zone:1418} : le coffre se trouve juste à l'entrée de la grotte. {npc:2932} et les Golems d'obsidienne (38) se tiennent à côté, et des Terrassiers Ombreforge (35-36) creusent le tunnel, tous élites : restez groupés.",
		["Lesser Rock Elementals"] = "Elémentaires de roche inférieurs ({npc:2735})",
		["North-west across the basin to {npc:2921}'s camp. Short of Jarkal's shards? The Lesser Rock Elementals (37) on the flats west of the camp drop them about one kill in five."] = "Traversez le bassin vers le nord-ouest jusqu'au camp de {npc:2921}. Il vous manque des éclats pour Jarkal ? Les Elémentaires de roche inférieurs (37) dans la plaine à l'ouest du camp en lâchent environ une fois sur cinq.",
		["Rock Elementals"] = "Elémentaires de roche",
		["South-east across the basin, the bigger Rock Elementals (39) stand on the slopes west of {area:345}; each one drops a slab. Every rock elemental can drop {npc:6868}'s Rock Elemental Shards. Careful: Malevolent Mirages (42, elite) drift across these slopes too."] = "Au sud-est, de l'autre côté du bassin, les grands Elémentaires de roche (39) se tiennent sur les pentes à l'ouest de {area:345} ; chacun lâche une dalle. Chaque élémentaire de roche peut laisser tomber les Éclats d'élémentaire de roche de {npc:6868}. Attention : des Mirages malveillants (42, élites) errent aussi sur ces pentes.",
		["Stonevault troggs"] = "Troggs Stonevault",
		["The Stonevault troggs dig around the cave mouths south of the {area:1877}, on the way north from {area:345}; the Bonesnappers and Shamans drop the flakes. The Buzzards for {npc:2817}'s wings circle the hills between the {area:1877} and {area:345}."] = "Les troggs Stonevault creusent autour des entrées de grottes au sud de la {area:1877}, sur le chemin du nord depuis {area:345} ; les Brise-os et les Chamans lâchent les éclats. Les busards, pour les ailes de {npc:2817}, tournoient au-dessus des collines entre la {area:1877} et {area:345}.",
		["The road north to {area:1517} runs through the {area:1877}: {npc:2817} and {npc:4618} take the wings and the flakes on the way."] = "La route du nord vers {area:1517} traverse la {area:1877} : {npc:2817} et {npc:4618} prennent les ailes et les éclats au passage.",
		["The small elementals drift across the flats between {area:340} and {npc:2921}'s camp, on the road back east. Every rock elemental in the zone can drop {npc:6868}'s Rock Elemental Shards."] = "Les petits élémentaires errent dans la plaine entre {area:340} et le camp de {npc:2921}, sur la route du retour vers l'est. Chaque élémentaire de roche de la zone peut laisser tomber les Éclats d'élémentaire de roche de {npc:6868}.",
		["Theldurin sits among the dwarven ruins at {area:345}, just east of the elementals. His tablet lies just inside {area:1517}'s cave mouth, beside level 38 elites: a quest for a group."] = "Theldurin est assis parmi les ruines naines de {area:345}, juste à l'est des élémentaires. Sa tablette se trouve juste à l'entrée de la grotte d'{area:1517}, à côté d'élites de niveau 38 : une quête de groupe.",
		["for Fizzle at the {area:2240}, on the way from {area:484} to {zone:1446} around level 43"] = "pour Fizzle à {area:2240}, sur le chemin de {area:484} à {zone:1446}, vers le niveau 43",
		["for Helgrum in {area:75}, around level 42"] = "pour Helgrum l'Agile à {area:75}, vers le niveau 42",
		["{area:340} is the Horde fortress built into the cliffs at the zone's western edge. {quest:1418} stands on {area:340}'s upper level, high above the flight master: take the ramps up, the arrow cannot tell the levels apart."] = "{area:340} est la forteresse de la Horde bâtie dans les falaises à la limite ouest de la zone. {quest:1418} se tient au niveau supérieur de {area:340}, bien au-dessus du maître de vol : montez par les rampes, la flèche ne distingue pas les niveaux.",
		["{npc:2921}'s next study wants bracers from the Greater Rock Elementals (42-44) in the south-western gulches, well above you: leave it."] = "L'étude suivante de {npc:2921} demande des brassards des Elémentaires de roche supérieurs (42-44), dans les ravins du sud-ouest, bien au-dessus de vous : laissez-la.",
		["{npc:6868}, inside"] = "{npc:6868}, à l'intérieur",
		["{quest:1106}: Fizzle's letter from the {area:439}"] = "{quest:1106} : la lettre de Fizzle, de {area:439}",
		["{zone:1418}: kill these as you meet them"] = "{zone:1418} : tuez-les au passage",
} end)()
t.guides["forever/horde/40-50/01-stranglethorn-vale"] = (function() return {
		["\"Sea Wolf\" MacKinley, on the top floor"] = "« Loup de mer » MacKinley, au dernier étage",
		["Draenethyst crystals"] = "Cristaux de draenéthyste",
		["Felsteed: Zevrost in {zone:1454}, then {npc:6251} in {area:392}, on the {zone:1444} guide's {zone:1454} stop."] = "Palefroi corrompu : Zevrost à {zone:1454}, puis {npc:6251} à {area:392}, lors de l'étape à {zone:1454} du guide de {zone:1444}.",
		["Fly back to {object:3202}: Zul'Mamwe's Skullsplitters are just east of it."] = "Prenez un vol pour revenir à {object:3202} : les Fendeurs de crânes de Zul'Mamwe sont juste à l'est.",
		["Fly to the {area:1497}"] = "Prendre un vol pour {area:1497}",
		["Fly to {area:35}"] = "Prendre un vol pour {area:35}",
		["Fly to {object:3202}"] = "Vol pour {object:3202}",
		["Follow the road east from {zone:1431} through {zone:1430} into the swamp. {npc:1776} waits at the {area:657}, the draenei camp just off the road where it comes in from {zone:1430}."] = "Suivez la route vers l'est depuis {zone:1431} à travers {zone:1430} jusqu'au marais. {npc:1776} attend à {area:657}, le camp draeneï juste à côté de la route, là où elle arrive depuis {zone:1430}.",
		["Further north, the goblins of the Venture Co. dig at the mine east of the road; miners, foremen, surveyors and tinkerers all drop the crystals.\nCareful: Stealthed Shadowmaw Panthers and Stranglethorn Tigresses roam the area around the camp."] = "Plus au nord, les gobelins de la KapitalRisk creusent dans la mine à l'est de la route ; mineurs, contremaîtres, géomètres et bricoleurs lâchent tous les cristaux.\nAttention : des Panthères Ombregueule camouflées et des Tigresses de Strangleronce parcourent les environs du camp.",
		["Gringer, the flight master, waits on {area:35}'s upper deck. The quest givers stand on the boardwalks around the harbour and in the inn."] = "Gringer, le maître de vol, attend sur le pont supérieur de {area:35}. Les donneurs de quête se tiennent sur les passerelles autour du port et dans l'auberge.",
		["Head east to {area:75}, in the reeds south of the road."] = "Allez vers l'est jusqu'à {area:75}, dans les roseaux au sud de la route.",
		["Head north up the road to the hunters' camp."] = "Remontez la route vers le nord jusqu'au camp des chasseurs.",
		["Head north up the road; the hunters camp on the hill above the river."] = "Remontez la route vers le nord ; les chasseurs campent sur la colline au-dessus de la rivière.",
		["Head north-east to the {area:76}. The crystals stand along the way up to {npc:5391}'s cage."] = "Allez vers le nord-est jusqu'à {area:76}. Les cristaux se dressent le long du chemin qui monte vers la cage de {npc:5391}.",
		["Head south to {area:35}. Shaky Phillipe waits on the docks."] = "Allez vers le sud jusqu'à {area:35}. Shaky Phillipe attend sur les quais.",
		["Head west to {object:3202}."] = "Allez vers l'ouest jusqu'à Grom'gol.",
		["His strongbox waits at his old camp north of {area:75}, on the way back west."] = "Son coffre attend à son ancien camp au nord de {area:75}, sur le chemin du retour vers l'ouest.",
		["Inside"] = "À l'intérieur",
		["Into the {zone:1435}"] = "Vers {zone:1435}",
		["Jungle Stalkers"] = "Traqueurs de la jungle",
		["Jungle stalkers"] = "Traqueurs de la jungle",
		["Keep {quest:571}, {quest:621} and {npc:737}'s tusks: the Skullsplitter chief, Zanzil's camps, the naga coast and {area:35} come on your Stranglethorn stop at about 45, after the {zone:2548}."] = "Gardez {quest:571}, {quest:621} et les défenses de {npc:737} : le chef des Fendeurs de crânes, les camps de Zanzil, la côte des nagas et {area:35} viennent lors de votre étape à Strangleronce vers le niveau 45, après {zone:2548}.",
		["Lashtail Raptors"] = "Raptors Fouette-queue",
		["Leave town by the tunnel; the note lies in the pirates' cove just north of {area:35}."] = "Quittez la ville par le tunnel ; la note se trouve dans la crique des pirates juste au nord de {area:35}.",
		["MacKinley: keep it, the ghost pirates (43-44) wait for your Stranglethorn stop at about 45"] = "MacKinley : gardez-la, les pirates fantômes (43-44) attendent votre étape à Strangleronce vers le niveau 45",
		["Mistvale gorillas"] = "Gorilles de Valbrume",
		["Nesingwary's camp"] = "Camp de Nesingwary",
		["Noboru wanders the clearing south-west of the {area:76}; his cudgel starts a quest."] = "Noboru erre dans la clairière au sud-ouest de {area:76} ; son gourdin lance une quête.",
		["Riding at 40"] = "La monte au niveau 40",
		["Riding needs level 40 and costs 100 gold; learning it gives you a Galestrider, and the {zone:2548} after Stranglethorn are a long walk without one. Take the zeppelin from {object:3202}'s tower to {zone:1454} and fly to {zone:1456}: the skyboat to {zone:2521} leaves the cliffs south of {area:17045}, north of {zone:1456}, about every five minutes, and {npc:265756} teaches Skyborne at the {area:17684} in {area:16638}. Then back to {zone:1454} for the {object:3202} zeppelin. Short of gold? Skip this step: the {zone:1444} guide passes {zone:1454} again at about 45."] = "La monte exige le niveau 40 et coûte 100 po ; l'apprendre vous donne un Galestrider, et {zone:2548} après Strangleronce sont une longue marche sans lui. Prenez le zeppelin depuis la tour de {object:3202} jusqu'à {zone:1454} et volez jusqu'aux {zone:1456} : le bateau volant pour {zone:2521} part des falaises au sud de {area:17045}, au nord des {zone:1456}, environ toutes les cinq minutes, et {npc:265756} enseigne aux Skyborne aux {area:17684} à {area:16638}. Puis retournez à {zone:1454} pour le zeppelin de {object:3202}. À court d'or ? Passez cette étape : le guide {zone:1444} repasse par {zone:1454} vers le niveau 45.",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount, and the {zone:2548} after Stranglethorn are a long walk without one. Take the zeppelin from {object:3202}'s tower to {zone:1454} and go south down the {zone:1411} road to {area:367}: {npc:7953} teaches Trolls there, with Zjolnir's raptors (20 gold each). Then back to the zeppelin for {object:3202}. Short of gold? Skip this step: the {zone:1444} guide passes {zone:1454} again at about 45."] = "La monte exige le niveau 40 et coûte 100 po ; l'apprendre vous donne une monture, et {zone:2548} après Strangleronce sont une longue marche sans elle. Prenez le zeppelin depuis la tour de {object:3202} jusqu'à {zone:1454} et descendez vers le sud par la route de {zone:1411} jusqu'au {area:367} : {npc:7953} y enseigne aux Trolls, avec les raptors de Zjolnir (20 po chacun). Puis retournez au zeppelin pour {object:3202}. À court d'or ? Passez cette étape : le guide {zone:1444} repasse par {zone:1454} vers le niveau 45.",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount, and the {zone:2548} after Stranglethorn are a long walk without one. Take the zeppelin from {object:3202}'s tower to {zone:1454}, fly to {zone:1456} and ride down to {area:222}: {npc:3690} teaches Tauren there, with {npc:3685}'s kodos (20 gold each). Then fly back to {zone:1454} for the {object:3202} zeppelin. Short of gold? Skip this step: the {zone:1444} guide passes {zone:1456} again at about 45."] = "La monte exige le niveau 40 et coûte 100 po ; l'apprendre vous donne une monture, et {zone:2548} après Strangleronce sont une longue marche sans elle. Prenez le zeppelin depuis la tour de {object:3202} jusqu'à {zone:1454}, volez jusqu'aux {zone:1456} et descendez jusqu'au {area:222} : {npc:3690} y enseigne aux Taurens, avec les kodos de {npc:3685} (20 po chacun). Puis revolez jusqu'à {zone:1454} pour le zeppelin de {object:3202}. À court d'or ? Passez cette étape : le guide {zone:1444} repasse par les {zone:1456} vers le niveau 45.",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount, and the {zone:2548} after Stranglethorn are a long walk without one. Take the zeppelin from {object:3202}'s tower to {zone:1454}: {npc:4752} teaches Orcs in the {object:172958}, by {npc:3362}'s kennel (wolves 20 gold each). Then the zeppelin back to {object:3202}. Short of gold? Skip this step: the {zone:1444} guide passes {zone:1454} again at about 45."] = "La monte exige le niveau 40 et coûte 100 po ; l'apprendre vous donne une monture, et {zone:2548} après Strangleronce sont une longue marche sans elle. Prenez le zeppelin depuis la tour de {object:3202} jusqu'à {zone:1454} : {npc:4752} enseigne aux Orcs dans la {object:172958}, près du chenil de {npc:3362} (loups à 20 po chacun). Puis reprenez le zeppelin vers {object:3202}. À court d'or ? Passez cette étape : le guide {zone:1444} repasse par {zone:1454} vers le niveau 45.",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount. Each race learns it from its own race's trainer: yours is {npc:4773} in {area:159}, a short ride north of the zeppelin towers, with {npc:4731}'s skeletal horses (20 gold each) beside her. Ride back to the towers for the {object:3202} zeppelin."] = "La monte demande le niveau 40 et coûte 100 pièces d'or ; l'apprendre vous donne une monture. Chaque race l'apprend auprès du maître de sa propre race : le vôtre est {npc:4773} à {area:159}, à courte distance au nord des tours des zeppelins, avec les chevaux squelettes de {npc:4731} (20 pièces d'or chacun) à côté d'elle. Revenez aux tours pour le zeppelin de {object:3202}.",
		["Sawtooth crocolisks"] = "Crocilisques Dents-de-scie",
		["Sawtooth snappers"] = "Mordeurs Dents-de-scie",
		["Skeletal horses: {npc:4731}, beside {npc:4773} in {area:159}."] = "Chevaux squelettes : {npc:4731}, à côté de {npc:4773} à {area:159}.",
		["The Bloodsail ships"] = "Les navires de la Voile sanglante",
		["The Jungle Stalkers (40-41) hunt the coast south of {object:3202}. They are well above you: pull one at a time and rest between fights.\nCareful: {npc:730}, a level 43 elite raptor, roams among the stalkers: leave him for {quest:195}'s group step."] = "Les Traqueurs de la jungle (40-41) chassent sur la côte au sud de {object:3202}. Ils sont bien au-dessus de vous : attirez-les un par un et reposez-vous entre les combats.\nAttention : {npc:730}, un raptor élite de niveau 43, rôde parmi les traqueurs : laissez-le pour l'étape de groupe de {quest:195}.",
		["The crocolisks wallow in the pools around {npc:5391}'s camp and south towards {area:75}; about one in four drops a flank."] = "Les crocilisques se vautrent dans les mares autour du camp de {npc:5391} et vers le sud jusqu'à {area:75} ; environ un sur quatre laisse tomber un flanc.",
		["The naga explorers on the coast south of here (43-44) are for Bloads and Mok'thardin: keep both quests for your Stranglethorn stop at about 45."] = "Les explorateurs nagas sur la côte au sud d'ici (43-44) sont pour Bloads et Mok'thardin : gardez les deux quêtes pour votre étape à Strangleronce vers le niveau 45.",
		["The scroll, {quest:624}, lies on the decks of the three ships off the {area:43}, crewed by pirates of 42-45 who come in pairs, with captains of 45-48: take it with a group. Its chain runs on through the {zone:1435}, {zone:1445} and the {zone:1425}."] = "Le parchemin, {quest:624}, se trouve sur les ponts des trois navires au large de {area:43}, dont l'équipage compte des pirates de niveau 42-45 qui vont par deux, et des capitaines de niveau 45-48 : faites-le en groupe. Sa suite se poursuit dans {zone:1435}, {zone:1445} et les {zone:1425}.",
		["The stalker raptors hunt the jungle south of {object:3202}, out towards the west coast.\nCareful: the Jungle Stalkers (40-41) are thick here: pull one at a time and rest between fights."] = "Les raptors traqueurs chassent dans la jungle au sud de {object:3202}, vers la côte ouest.\nAttention : les Traqueurs de la jungle (40-41) sont nombreux ici : attirez-les un par un et reposez-vous entre les combats.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:728} is a level 40 elite: most classes solo it at level 42, but you may need help. Skip it if you are alone."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {npc:728} est un élite de niveau 40 : la plupart des classes le tuent seules au niveau 42, mais vous aurez peut-être besoin d'aide. Passez-le si vous êtes seul.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:730} is a level 43 elite: most classes solo it at level 45, but you may need help. Skip it if you are alone."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {npc:730} est un élite de niveau 43 : la plupart des classes le tuent seules au niveau 45, mais vous aurez peut-être besoin d'aide. Passez-le si vous êtes seul.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:731} is a level 43 elite: most classes solo it at level 45, but you may need help. Skip it if you are alone.\nCareful: Tigers and stealthed shadowmaw panthers roam close to him. Clear them before you pull him. When he is pulled, {npc:731} calls for help from creatures within 20 yd."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. Le {npc:731} est un élite de niveau 43 : la plupart des classes le tuent seules au niveau 45, mais vous aurez peut-être besoin d'aide. Passez-le si vous êtes seul.\nAttention : des tigres et des panthères Ombregueule camouflées rôdent près de lui. Éliminez-les avant de l'attirer. Une fois attiré, le {npc:731} appelle à l'aide les créatures à moins de 20 m.",
		["Venture Co. mine"] = "Mine de la KapitalRisk",
		["Warlocks don't buy riding: your mount is the Felsteed, from your class quest. Zevrost in {zone:1454}'s {object:172960} starts it and {npc:6251} in {area:392} teaches it, both on the {zone:1444} guide's {zone:1454} stop at about 45."] = "Les démonistes n'achètent pas la monte : leur monture est le Palefroi corrompu, obtenu par leur quête de classe. Zevrost, à {object:172960} à {zone:1454}, la lance et {npc:6251} à {area:392} vous l'apprend, tous deux lors de l'étape à {zone:1454} du guide de {zone:1444}, vers le niveau 45.",
		["West of the expedition, the Bloodscalp chiefs {npc:1061} and {npc:1062} stand together in the ruins of Zul'Kunda. Clear their guards first, then pull them.\nOn the coast between Zul'Kunda and {object:3202} an {npc:2635} (level 38 elite) shares the spawns of the ordinary crocolisks: kill it if it is up and take its skin for {npc:2495}."] = "À l'ouest de l'expédition, les chefs Bloodscalp {npc:1061} et {npc:1062} se tiennent ensemble dans les ruines de Zul'Kunda. Éliminez d'abord leurs gardes, puis attirez-les.\nSur la côte entre Zul'Kunda et {object:3202}, un {npc:2635} (élite de niveau 38) partage les points d'apparition des crocilisques ordinaires : tuez-le s'il est là et prenez sa peau pour {npc:2495}.",
		["You missed this on the route's earlier visit here: it comes first now. It is quick and opens the quests after it."] = "Vous avez manqué ceci lors du passage précédent de l'itinéraire ici : cela passe d'abord maintenant. C'est rapide et cela ouvre les quêtes qui suivent.",
		["Your level 40 training is in the {area:1497}: fly there from {area:340}, train, and take the zeppelin from the towers outside the city to {object:3202}."] = "Votre entraînement de niveau 40 se fait à {area:1497} : prenez un vol depuis {area:340}, entraînez-vous, puis prenez le zeppelin aux tours à l'extérieur de la ville pour {object:3202}.",
		["Your mount at 40"] = "Votre monture au niveau 40",
		["Zeppelin to {object:3202}"] = "Zeppelin pour {object:3202}",
		["Zul'Kunda"] = "Ruines de Zul'Kunda",
		["Zul'Mamwe"] = "Ruines de Zul'Mamwe",
		["for a later stop in the {zone:1435}"] = "pour une étape ultérieure dans {zone:1435}",
		["from the {object:52}, in the ruins"] = "sur la {object:52}, dans les ruines",
		["the {area:16550}'s entrance, underwater"] = "l'entrée de {area:16550}, sous l'eau",
		["the {object:2076}, beside {npc:2497}"] = "le {object:2076}, à côté de {npc:2497}",
		["{area:340} flight master"] = "Maître de vol de {area:340}",
		["{area:35} flight master"] = "Maître de vol de {area:35}",
		["{npc:1442}, upstairs"] = "{npc:1442}, à l'étage",
		["{npc:1443}, on the top floor"] = "{npc:1443}, au dernier étage",
		["{npc:2464}: for {npc:256418} in {area:16743}, the {zone:2548}' Horde fort, in the next guide"] = "{npc:2464} : pour {npc:256418} à {area:16743}, le fort de la Horde de {zone:2548}, dans le guide suivant",
		["{npc:2487}: keep it for the {area:43} at about 45"] = "{npc:2487} : gardez-la pour {area:43} vers le niveau 45",
		["{npc:2488}, on the top floor: keep it for the {area:43} at about 45"] = "{npc:2488}, au dernier étage : gardez-la pour {area:43} vers le niveau 45",
		["{npc:2491}, in the inn: his bottles wash up on the {zone:1425} coast, around level 48"] = "{npc:2491}, dans l'auberge : ses bouteilles s'échouent sur la côte des {zone:1425}, vers le niveau 48",
		["{npc:2493}: keep it for the {area:43} at about 45"] = "{npc:2493} : gardez-la pour {area:43} vers le niveau 45",
		["{npc:2495}, inside: the {item:4105}"] = "{npc:2495}, à l'intérieur : la {item:4105}",
		["{npc:2495}: the Snapjaw skins gathered earlier; inside"] = "{npc:2495} : les peaux de Gueule d'acier ramassées plus tôt ; à l'intérieur",
		["{npc:2495}: the {npc:2635} suns on the coast between Zul'Kunda and {object:3202}, later on this loop"] = "{npc:2495} : le {npc:2635} se dore au soleil sur la côte entre Zul'Kunda et {object:3202}, plus tard dans cette boucle",
		["{npc:2496}, on the balcony beside MacKinley"] = "{npc:2496}, sur le balcon à côté de MacKinley",
		["{npc:2519}: the cavern entrance under the {area:104}, west of the camp"] = "{npc:2519} : l'entrée de la caverne sous {area:104}, à l'ouest du camp",
		["{npc:2519}: the legend lies in Zul'Kunda, where this guide goes for {npc:1061}"] = "{npc:2519} : la légende se trouve à Zul'Kunda, où ce guide va pour {npc:1061}",
		["{npc:265756}, riding trainer, at the {area:17684} in {area:16638}"] = "{npc:265756}, Maître de monte, aux {area:17684} à {area:16638}",
		["{npc:3690}, riding trainer"] = "{npc:3690}, maître de monte",
		["{npc:4631}, on the docks: Gazlowe's letter, if you carry it"] = "{npc:4631}, sur les quais : la lettre de Gazlowe, si vous l'avez",
		["{npc:4631}: {quest:97332}, after Zimmix's rescue; the package goes to {npc:259961} at {area:16727}, in the {zone:2548} guide"] = "{npc:4631} : {quest:97332}, après le sauvetage de Zimmix ; le paquet va à {npc:259961} à {area:16727}, dans le guide {zone:2548}",
		["{npc:4752}, riding trainer"] = "{npc:4752}, maître de monte",
		["{npc:4773}, riding trainer"] = "{npc:4773}, maître de monte",
		["{npc:5391} is held in the {area:76} in the swamp's north-east. Free him and follow him out, fighting off the swamp creatures that chase him."] = "{npc:5391} est retenu à {area:76}, dans le nord-est du marais. Libérez-le et suivez-le dehors en repoussant les créatures du marais qui le poursuivent.",
		["{npc:5591}, inside"] = "{npc:5591}, à l'intérieur",
		["{npc:716} collects the pages of {quest:338}: the trolls of the vale drop them now and then. Take his quest; each chapter he takes once you have all its pages."] = "{npc:716} rassemble les pages de {quest:338} : les trolls de la vallée en lâchent de temps en temps. Prenez sa quête ; il prend chaque chapitre une fois que vous en avez toutes les pages.",
		["{npc:716}: every page of chapter I is in your bags"] = "{npc:716} : toutes les pages du chapitre I sont dans vos sacs",
		["{npc:716}: every page of chapter II is in your bags"] = "{npc:716} : toutes les pages du chapitre II sont dans vos sacs",
		["{npc:716}: every page of chapter III is in your bags"] = "{npc:716} : toutes les pages du chapitre III sont dans vos sacs",
		["{npc:716}: every page of chapter IV is in your bags"] = "{npc:716} : toutes les pages du chapitre IV sont dans vos sacs",
		["{npc:716}: the four chapters"] = "{npc:716} : les quatre chapitres",
		["{npc:729}, the tiger {npc:717} sent you after on your last visit, prowls the hilltop just south-west of the camp."] = "{npc:729}, le tigre que {npc:717} vous a demandé de traquer lors de votre dernière visite, rôde sur la colline juste au sud-ouest du camp.",
		["{npc:737}, upstairs"] = "{npc:737}, à l'étage",
		["{npc:737}, upstairs, has his next errand now: the Skullsplitter tusks come from the trolls of Zul'Mamwe, later on this loop."] = "{npc:737}, à l'étage, a maintenant sa mission suivante : les défenses Skullsplitter viennent des trolls de Zul'Mamwe, plus loin dans cette boucle.",
		["{npc:737}, upstairs: the tusks come from the Skullsplitters, later on this loop"] = "{npc:737}, à l'étage : les défenses viennent des Skullsplitter, plus loin dans cette boucle",
		["{npc:7953}, riding trainer"] = "{npc:7953}, maître de monte",
		["{object:3202} flight master"] = "Maître de vol de Grom'gol",
		["{quest:95770}: west of {object:3202}, swim out over the {area:104} and dive to the cavern entrance in the reef; the quest completes as you find it. Leave the cavern for now: the jungle stalkers are south along the coast."] = "{quest:95770} : à l'ouest de {object:3202}, nagez au-dessus de {area:104} et plongez jusqu'à l'entrée de la caverne dans le récif ; la quête s'accomplit dès que vous la trouvez. Laissez la caverne pour l'instant : les traqueurs de la jungle sont au sud, le long de la côte.",
		["{zone:1458} trainers"] = "Maîtres de {zone:1458}",
} end)()
t.guides["forever/horde/40-50/01b-riverglades"] = (function() return {
		["About 70 quests in Forever's new zone, from the fort of {area:16743}."] = "Environ 70 quêtes dans la nouvelle zone de Forever, depuis le fort de {area:16743}.",
		["Across the {area:3} to {area:340}, the Horde fortress built into the cliffs at the zone's western edge: its flight master stands at the foot of the fortress."] = "Traversez les {area:3} jusqu'à {area:340}, la forteresse de la Horde bâtie dans les falaises à l'ouest de la zone : son Maître de vol se tient au pied de la forteresse.",
		["Back north along the shore: hand in the murlocs and the hide on the docks on your way to the crawlers."] = "Revenez vers le nord le long du rivage : rendez les murlocs et la peau sur les quais en allant vers les rampants.",
		["Back through the port"] = "Retour par le port",
		["Back to the port, from the north pier west through the docks."] = "Retournez au port, depuis la jetée nord vers l'ouest à travers les quais.",
		["Back to the port."] = "Retournez au port.",
		["Back to {area:16743}, where your Hearthstone is set: {npc:263190} on the fort's west side first, then {npc:256418}, {npc:256655} by the cook fire, {npc:256657} and {npc:258031} on your way east through the fort."] = "Retournez à {area:16743}, où votre Pierre de foyer est liée : d'abord {npc:263190} du côté ouest du fort, puis {npc:256418}, {npc:256655} près du feu de cuisine, {npc:256657} et {npc:258031} en traversant le fort vers l'est.",
		["Back to {npc:255829} on his hill. {npc:257062} runs the {quest:94668} just below it."] = "Retournez voir {npc:255829} sur sa colline. {npc:257062} gère {quest:94668} juste en contrebas.",
		["Boat to {area:16727}"] = "Bateau pour {area:16727}",
		["Bonegnaw"] = "Bonegnaw",
		["Down to the port."] = "Descendez au port.",
		["Each bout is a fight in the ring below {npc:255829}'s hill against an elite: Buzzbeak (41), Kronk and Bonegnaw (42), {npc:258626} (43), Snufflesnout (44) and {npc:257059} (45). Come in rested, with full health and mana; if a bout goes wrong, {npc:257062} offers it again."] = "Chaque combat a lieu dans l'arène sous la colline de {npc:255829}, contre un élite : Buzzbeak (41), Kronk et Bonegnaw (42), {npc:258626} (43), Snufflesnout (44) et {npc:257059} (45). Arrivez reposé, vie et mana au maximum ; si un combat tourne mal, {npc:257062} vous le propose à nouveau.",
		["East along the cliffs to the far end of the pirates' camp: {npc:260390} waits by the water, {npc:260391} beside him."] = "Vers l'est le long des falaises jusqu'au bout du camp des pirates : {npc:260390} attend au bord de l'eau, {npc:260391} à côté de lui.",
		["East back to {area:16743}."] = "Retournez à l'est jusqu'à {area:16743}.",
		["East back to {area:16743}: {npc:260931}'s word goes to {npc:256710}, and {npc:256710}'s to {npc:255829}, the ogres' chieftain."] = "Retournez à l'est jusqu'à {area:16743} : le message de {npc:260931} va à {npc:256710}, et celui de {npc:256710} à {npc:255829}, le chef des ogres.",
		["East of Rog'mar, on the hill above the road to {area:16727}: {npc:263367} has his workshop there. The gas vents are in the marsh south-west of it, on your first hunt for {npc:258031}."] = "À l'est de Rog'mar, sur la colline au-dessus de la route de {area:16727} : {npc:263367} y a son atelier. Les évents de gaz sont dans le marais au sud-ouest, lors de votre première chasse pour {npc:258031}.",
		["East to {area:16735}, the Alliance farm by the river: the farmhands work the fields and the feed satchels lie by the barns. {area:16744}, the Alliance outpost on the road, has guards: pass south of it.\nCareful: {npc:263380}, an elite (level 42), hunts along the river by the farm: keep an eye on the riverbank."] = "À l'est jusqu'à {area:16735}, la ferme de l'Alliance près de la rivière : les ouvriers agricoles travaillent aux champs et les sacoches de fourrage se trouvent près des granges. {area:16744}, l'avant-poste de l'Alliance sur la route, est gardé : passez au sud.\nAttention : {npc:263380}, un élite (niveau 42), chasse le long de la rivière près de la ferme : surveillez la berge.",
		["Finish the {item:268632}"] = "Terminez les {item:268632}",
		["Fly to {area:340}"] = "Volez jusqu'à {area:340}",
		["Fly to {area:484}"] = "Prendre un vol pour {area:484}",
		["Frazzlespark's crate from the port goes to {npc:256418}, in the middle of the fort."] = "La caisse de Frazzlespark venant du port va à {npc:256418}, au milieu du fort.",
		["Into the {area:16591}"] = "Vers {area:16591}",
		["Kronk"] = "Kronk",
		["Learn {area:976}'s flight path: it saves the ride next time."] = "Apprenez le trajet aérien de {area:976} : cela vous épargnera le trajet la prochaine fois.",
		["Most beasts in the {zone:2548} drop {item:268632} for {npc:260231}: the shore crawlers on this coast and the boars on the ridge west of the pirates.\nCareful: {npc:257001} (elite, 42) wanders the shore and {npc:263380} (elite, 42) the river: take your beasts away from them."] = "La plupart des bêtes de {zone:2548} lâchent des {item:268632} pour {npc:260231} : les rampants du rivage sur cette côte et les sangliers sur la crête à l'ouest des pirates.\nAttention : {npc:257001} (élite, 42) erre sur le rivage et {npc:263380} (élite, 42) dans la rivière : éloignez vos bêtes d'eux.",
		["New in Forever: if a step is wrong, tell us on Polestar's Discord or GitHub and name the step.\n{npc:255897} keeps a stall at the west end of the docks. The port's other jobs are for later in this guide: this crate goes to the Horde's fort."] = "Nouveauté de Forever : si une étape est erronée, signalez-le sur le Discord ou le GitHub de Polestar en nommant l'étape.\n{npc:255897} tient un étal au bout ouest des quais. Les autres tâches du port viendront plus tard dans ce guide : cette caisse va au fort de la Horde.",
		["New in Forever: this guide follows what players did in the {area:16591}. If a step is wrong, tell us on Polestar's Discord or GitHub and name the step.\nFrom {area:340}, ride south-east across the {area:3} to the zone's southern edge: the pass of {area:16685} leads down into the {area:16591}. {area:16743}, the Horde's fort, stands in the middle of the zone, east along the valley."] = "Nouveauté de Forever : ce guide suit ce que les joueurs ont fait dans {area:16591}. Si une étape est erronée, signalez-le sur le Discord ou le GitHub de Polestar en nommant l'étape.\nDepuis {area:340}, allez au sud-est à travers les {area:3} jusqu'au bord sud de la zone : le col de {area:16685} descend dans {area:16591}. {area:16743}, le fort de la Horde, se dresse au milieu de la zone, à l'est le long de la vallée.",
		["New in Forever: this guide follows what players did in the {zone:2548}. If a step is wrong, tell us on Polestar's Discord or GitHub and name the step.\nThe {zone:2548} lie across the sea from {zone:1446}: a goblin boat sails from {area:977}, north-east of {area:976}, to {area:16727}. Fly to {area:484} in {zone:1441} and head south-east through the {area:439} to {area:976}. (If you already know {area:340} in the {area:3}, the way in through {area:16685} works too.)"] = "Nouveauté de Forever : ce guide suit ce que les joueurs ont fait dans les {zone:2548}. Si une étape est erronée, signalez-le sur le Discord ou le GitHub de Polestar en nommant l'étape.\nLes {zone:2548} se trouvent de l'autre côté de la mer depuis {zone:1446} : un bateau gobelin part de {area:977}, au nord-est de {area:976}, pour {area:16727}. Prenez un vol pour {area:484} dans {zone:1441} et allez au sud-est à travers {area:439} jusqu'à {area:976}. (Si vous connaissez déjà {area:340} dans les {area:3}, l'accès par {area:16685} fonctionne aussi.)",
		["North along the beach from the docks: the crawlers drop the meat for {npc:259962}, and their entrails count for {npc:260231}. {npc:260235}, a big crab, scuttles along the rocks east of the docks. {npc:259758}, a rare elite of level 49, roams this coast from the docks up to the pirates' camp: if you see him, keep well away."] = "Remontez la plage vers le nord depuis les quais : les rampants lâchent la viande pour {npc:259962}, et leurs entrailles comptent pour {npc:260231}. {npc:260235}, un gros crabe, se déplace sur les rochers à l'est des quais. {npc:259758}, un rare élite de niveau 49, parcourt cette côte des quais jusqu'au camp des pirates : si vous le voyez, restez bien à l'écart.",
		["North along the coast from the port: the Eastsea raiders and bombardiers have dug in on the slopes west of the buccaneers' camp, among their powder kegs. Watch for {npc:259758} on these cliffs.\nCareful: the Eastsea Raiders are level 44-45, a level or two over you here: pull them one at a time from the edge of the slopes and keep clear of the camp behind them."] = "Longez la côte vers le nord depuis le port : les écumeurs et bombardiers des mers de l'Est se sont retranchés sur les pentes à l'ouest du camp des boucaniers, parmi leurs barils de poudre. Méfiez-vous de {npc:259758} sur ces falaises.\nAttention : les Ecumeurs des mers de l'Est sont de niveau 44-45, un ou deux niveaux au-dessus de vous ici : attirez-les un par un depuis le bord des pentes et tenez-vous à l'écart du camp derrière eux.",
		["North of the camps the cult works ogre miners in a mine: talk five of them into rising up against their masters.\nCareful: Twilight Enforcers (elites, level 45) walk past the mine's mouth on their way through the camps. Wait for one to pass before you go in."] = "Au nord des camps, le culte fait travailler des mineurs ogres dans une mine : convainquez-en cinq de se soulever contre leurs maîtres.\nAttention : des Massacreurs du Crépuscule (élites, niveau 45) passent devant l'entrée de la mine en traversant les camps. Attendez qu'un d'eux soit passé avant d'entrer.",
		["North of the fort the Rog'mar Trainees drill: use {npc:256655}'s {item:265066} on them.\nCareful: {npc:263380}, an elite (level 42), can come up from the river south of the fort: let him pass."] = "Au nord du fort, les Recrues de Rog'mar s'entraînent : utilisez le {item:265066} de {npc:256655} sur elles.\nAttention : {npc:263380}, un élite (niveau 42), peut remonter de la rivière au sud du fort : laissez-le passer.",
		["North-east along the coast to the pirates' camp on the cliffs. The buccaneers and musketeers carry the smuggled goods. {npc:259758} walks the camp too: keep an eye out for him."] = "Au nord-est le long de la côte jusqu'au camp des pirates sur les falaises. Les boucaniers et les mousquetaires portent les marchandises de contrebande. {npc:259758} parcourt aussi le camp : surveillez-le.",
		["North-east from {area:16743} up into the hills: {npc:256728} watches the Paletusk boars from his camp."] = "Au nord-est de {area:16743}, montez dans les collines : {npc:256728} surveille les sangliers brochepâles depuis son camp.",
		["North-east to the workshop. {npc:263367}'s stress test is a fight with his G45-B4G beside the workshop: hand the quest in once it's beaten."] = "Au nord-est jusqu'à l'atelier. Le test de résistance de {npc:263367} est un combat contre son G45-B4G à côté de l'atelier : rendez la quête une fois qu'il est vaincu.",
		["North-west to {area:16726}, the ogres' town. {npc:255829}, its chieftain, sits on the hill. The ogres are friendly while you leave them alone."] = "Au nord-ouest jusqu'à {area:16726}, la ville des ogres. {npc:255829}, leur chef, est assis sur la colline. Les ogres restent amicaux tant que vous les laissez tranquilles.",
		["Rotflesh Mushrooms"] = "Champignons cadavériques",
		["Snufflesnout (44)"] = "Renifle-groin (44)",
		["South down the hills, round the west side of the Alliance scouts' camp: tap the Young Paletusks with {npc:256728}'s staff to send them home; the Mature Paletusks around the hills drop the boar meat."] = "Descendez les collines vers le sud en contournant par l'ouest le camp des éclaireurs de l'Alliance : touchez les Jeunes brochepâles avec le bâton de {npc:256728} pour les renvoyer chez eux ; les Brochepâles adultes autour des collines donnent la viande de sanglier.",
		["South-east back towards the port: the shore crawlers on the beach north of the docks are the quickest entrails. {npc:259758} wanders down to this beach too."] = "Retournez vers le port au sud-est : les rampants du rivage sur la plage au nord des quais sont le moyen le plus rapide d'obtenir les entrailles. {npc:259758} descend aussi jusqu'à cette plage.",
		["South-east down out of the hills to {area:16727}, the goblins' harbour on the coast. {npc:255897} keeps a stall at the west end of the docks, {npc:259962} cooks by the inn, and {npc:259961} works the north pier."] = "Descendez des collines vers le sud-est jusqu'à {area:16727}, le port gobelin sur la côte. {npc:255897} tient un étal à l'extrémité ouest des quais, {npc:259962} cuisine près de l'auberge, et {npc:259961} travaille sur la jetée nord.",
		["South-east of Rog'mar the plains run down to {area:16729}. The Low Plains Buzzards circle everywhere; a picked carcass lies in the grass (its skull starts {quest:96103}), and the marsh vents are just past it."] = "Au sud-est de Rog'mar, les plaines descendent jusqu'à {area:16729}. Les Busards des basses plaines tournoient partout ; une carcasse dépecée gît dans l'herbe (son crâne lance {quest:96103}), et les évents du marais sont juste après.",
		["South-east out of the hills: {npc:262399}, a prospector who deals with both sides, has camped by the Cinderscale dragonkin's hollow."] = "Au sud-est en sortant des collines : {npc:262399}, une prospectrice qui traite avec les deux camps, s'est installée près du creux des dragonkin Écaille-de-cendre.",
		["South-west across the river to the Alliance lumber camp. The lumberjacks carry the axes. Loot Wood Bundles from the Peasant Woodpiles around the camp and use them to fletch Makeshift Stickin' Spears. {npc:263380}, an elite (level 42), prowls the river by the camp: if he comes your way, back off and let him pass."] = "Au sud-ouest, de l'autre côté de la rivière, jusqu'au camp de bûcherons de l'Alliance. Les bûcherons portent les haches. Ramassez des Tas de bois sur les Piles de bois de paysan autour du camp et utilisez-les pour fabriquer des Lances transperçantes de fortune. {npc:263380}, un élite (niveau 42), rôde le long de la rivière près du camp : s'il vient vers vous, reculez et laissez-le passer.",
		["South-west along the shore from the port: the saltwater murlocs camp on the beaches. On the way, a painted hide is stretched beside the path: it starts {quest:95260} for {npc:260231} at the docks."] = "Au sud-ouest le long du rivage depuis le port : les murlocs d'eau salée campent sur les plages. En chemin, une peau peinte est tendue à côté du sentier : elle lance {quest:95260} pour {npc:260231} sur les quais.",
		["South-west of Rog'mar the river runs between the farms: impale the Freshwater Crocolisks with {npc:263190}'s spears. The Alliance trains its scouts and priests at a camp on the far bank. {npc:257079}, the Alliance elite, rides the road just east of the camp: pull the scouts and priests away from it.\nCareful: {npc:263380}, an elite (level 42), hunts along this river: if he comes your way, back off and let him pass."] = "Au sud-ouest de Rog'mar, la rivière coule entre les fermes : empalez les Crocilisques d'eau douce avec les lances de {npc:263190}. L'Alliance entraîne ses éclaireurs et ses prêtres dans un camp sur l'autre rive. {npc:257079}, l'élite de l'Alliance, patrouille sur la route juste à l'est du camp : attirez les éclaireurs et les prêtres loin d'elle.\nAttention : {npc:263380}, un élite (niveau 42), chasse le long de cette rivière : s'il vient vers vous, reculez et laissez-le passer.",
		["The Cinderscale hollow"] = "Le creux Écaille-de-cendre",
		["The Eastsea pirates"] = "Les pirates de la mer de l'Est",
		["The Glade Vipers hide in the long grass south-east of town; the Roving Tallstriders graze beside them. {npc:257079}, an Alliance elite (level 45), rides the road from {area:16729} to {area:16725} along the grass's south-west edge: keep clear of him."] = "Les Vipères des clairières se cachent dans les hautes herbes au sud-est de la ville ; les Haut-trotteurs en maraude broutent à côté. {npc:257079}, un élite de l'Alliance (niveau 45), parcourt la route de {area:16729} à {area:16725} le long de la lisière sud-ouest des herbes : tenez-vous à l'écart.",
		["The Twilight Maulers and Firecallers camp on the ridge east of {npc:256728}. {npc:260973}, who carries the {item:269257}, stands among them. Just south of the ogres, {npc:260211} (an Alliance elite, level 42) and his Farholde Ambushers hold the scouts' camp: keep north of it unless you came with a group for him."] = "Les Marteleurs du Crépuscule et les Invocateurs de feu campent sur la crête à l'est de {npc:256728}. {npc:260973}, qui porte {item:269257}, se tient parmi eux. Juste au sud des ogres, {npc:260211} (élite de l'Alliance, niveau 42) et ses Embusqués de Farholde tiennent le camp des éclaireurs : restez au nord à moins d'être venu en groupe pour lui.",
		["The Twilight camps"] = "Les camps du Crépuscule",
		["The Twilight ogres' camp"] = "Le camp des ogres du Crépuscule",
		["The Wildplains lions roam the plains just south of {area:16743}.\nCareful: {npc:263315}, an elite lion (level 41), prowls the same plains around 59.6,53.2: keep an eye out for him and pull the lions away from where he walks."] = "Les lions des Plaines sauvages errent dans les plaines juste au sud de {area:16743}.\nAttention : {npc:263315}, un lion élite (niveau 41), rôde dans ces mêmes plaines vers 59.6,53.2 : surveillez-le et attirez les lions loin de son chemin.",
		["The crawlers and {npc:260235}"] = "Les rampants et {npc:260235}",
		["The cultists fill the streets and fields; the Shadowmancers on the town's northern side carry the missives. The finger bones drop from all of them.\nCareful: {npc:256899}, an elite ogre (level 41), walks the western streets of {area:16723}, around 44-47,47-52. Pull the cultists out towards you and let him pass."] = "Les cultistes remplissent les rues et les champs ; les Ombremanciens du côté nord du village portent les missives. Les phalanges tombent sur tous.\nAttention : {npc:256899}, un ogre élite (niveau 41), arpente les rues ouest de {area:16723}, vers 44-47,47-52. Attirez les cultistes vers vous et laissez-le passer.",
		["The lions"] = "Les lions",
		["The murlocs, south-west"] = "Les murlocs, au sud-ouest",
		["The ogre mine"] = "La mine des ogres",
		["The paletusks"] = "Les brochepâles",
		["The pirates' second wave"] = "La deuxième vague des pirates",
		["The pirates' ships"] = "Les navires des pirates",
		["The plains and the marsh"] = "Les plaines et le marais",
		["The ritual grounds"] = "Les terrains rituels",
		["The ritualists and their empowered brutes gather at the ritual circles in the middle of {area:16723}: wreck five of the circles.\nCareful: {npc:256899}, the elite ogre (level 41), walks through here from the western streets: watch for him before each pull."] = "Les ritualistes et leurs brutes renforcées se rassemblent autour des cercles rituels au milieu de {area:16723} : détruisez cinq de ces cercles.\nAttention : {npc:256899}, l'ogre élite (niveau 41), passe par ici depuis les rues ouest : surveillez-le avant chaque attaque.",
		["The river and the Farholde camp"] = "La rivière et le camp de Farholde",
		["The training grounds"] = "Le terrain d'entraînement",
		["The vipers and the tallstriders"] = "Les vipères et les haut-trotteurs",
		["The whelps nest all over the hollow; the warriors guard its back, by the {item:271611}. The warriors are level 41-42: pull them one at a time. Scaldaron, a rare elite drake, can be up here too: leave him be unless you have a group."] = "Les dragonnets nichent dans tout le creux ; les guerriers en gardent le fond, près de la {item:271611}. Les guerriers sont de niveau 41-42 : attirez-les un par un. Scaldaron, un drake élite rare, peut aussi se trouver ici : laissez-le tranquille sauf si vous êtes en groupe.",
		["The {area:16737}"] = "{area:16737}",
		["The {npc:260244} prowls the shallows south-west of the port, below the murlocs' beaches. {npc:257001}, an elite, walks the shore close by: give him room."] = "Le {npc:260244} rôde dans les hauts-fonds au sud-ouest du port, sous les plages des murlocs. {npc:257001}, un élite, arpente le rivage tout près : gardez vos distances.",
		["The {object:628948} poster by the inn"] = "L'affiche {object:628948} près de l'auberge",
		["The {object:628948} poster by the inn: {npc:260235}"] = "L'affiche {object:628948} près de l'auberge : {npc:260235}",
		["The {quest:94670}: Buzzbeak"] = "{quest:94670} : Buzzbeak",
		["The {quest:94670}: Kronk and Bonegnaw"] = "{quest:94670} : Kronk et Bonegnaw",
		["The {quest:94962}: {npc:258626}"] = "{quest:94962} : {npc:258626}",
		["West back to {area:16743}'s east side."] = "Retournez vers l'ouest, jusqu'au côté est de {area:16743}.",
		["West from the northern ship, up the ridge: the Rotflesh Mushrooms grow among the rocks, close to the Twilight ogres' camp. The Mature Paletusks on the ridge give entrails too."] = "À l'ouest du navire nord, montez sur la crête : les Champignons cadavériques poussent parmi les rochers, près du camp des ogres du Crépuscule. Les Brochepâles adultes de la crête donnent aussi des entrailles.",
		["West from {area:16743} through {area:16723} and on up the valley towards {area:16685}: {npc:258570}, {npc:256418}'s wayward warrior, keeps a camp in the hills below the Twilight cult's fortress."] = "Allez vers l'ouest depuis {area:16743}, traversez {area:16723} et remontez la vallée vers {area:16685} : {npc:258570}, le guerrier égaré de {npc:256418}, a un camp dans les collines sous la forteresse du culte du Crépuscule.",
		["West into the {area:16737}: the Redridge gnolls camp along the slopes and carry the stolen ore. Work south-west through their camps.\nCareful: {npc:255906}, an elite gnoll (level 40), roams the south-western camps: pull the gnolls away from him."] = "À l'ouest dans les {area:16737} : les gnolls des Carmines campent le long des pentes et portent le minerai volé. Progressez vers le sud-ouest à travers leurs camps.\nAttention : {npc:255906}, un gnoll élite (niveau 40), erre dans les camps du sud-ouest : attirez les gnolls loin de lui.",
		["West to {area:16723} again: {npc:260931}, a Twilight miner who wants out, waits at the town's eastern edge. Talk him round, then hand {npc:256710}'s quest in; one of the missing ogres stands a few steps west."] = "Retournez à l'ouest jusqu'à {area:16723} : {npc:260931}, un mineur du Crépuscule qui veut s'en sortir, attend à la lisière est du village. Convainquez-le, puis rendez la quête de {npc:256710} ; l'un des ogres disparus se tient à quelques pas à l'ouest.",
		["West to {area:16743}, the Horde's fort in the middle of the zone. {npc:258031} stands on its east side, {npc:256657} and {npc:256418} in the middle with {npc:255993}, the wind rider master; {npc:256675} and {npc:263190} on the west side."] = "À l'ouest jusqu'à {area:16743}, le fort de la Horde au milieu de la zone. {npc:258031} se tient du côté est, {npc:256657} et {npc:256418} au centre avec {npc:255993}, le maître des coursiers du vent ; {npc:256675} et {npc:263190} du côté ouest.",
		["West up the road from the port: {npc:263367} has his workshop on the hill. The gas vents are in the marsh south-west of it, on your first hunt for {npc:258031}."] = "Remontez la route vers l'ouest depuis le port : {npc:263367} a son atelier sur la colline. Les évents de gaz sont dans le marais au sud-ouest, lors de votre première chasse pour {npc:258031}.",
		["beat Buzzbeak"] = "battez Buzzbeak",
		["destroy 5 Twilight Ritual Circles"] = "détruire 5 Cercles rituels du Crépuscule",
		["free five captive Rog'mar Scouts"] = "libérer cinq Éclaireurs Rog'mar captifs",
		["help {npc:258048} reach {area:16726}"] = "aidez {npc:258048} à rejoindre {area:16726}",
		["lead {npc:259158} out of {area:16723} to his treasure, west of the town"] = "menez {npc:259158} hors de {area:16723} jusqu'à son trésor, à l'ouest de la ville",
		["recruit five Ogre Miners"] = "recruter cinq Mineurs ogres",
		["talk {npc:260931} round"] = "convainquez {npc:260931}",
		["the middle ship"] = "le navire du milieu",
		["the northern ship"] = "le navire nord",
		["the stress test: beat G45-B4G beside the workshop"] = "le test de résistance : battez G45-B4G à côté de l'atelier",
		["the {object:645164} poster"] = "l'affiche {object:645164}",
		["{area:75} flight master"] = "Maître de vol de {area:75}",
		["{area:977} is on the coast north-east of {area:976}: wait on the pier for the goblin boat to {area:16727}."] = "{area:977} se trouve sur la côte au nord-est de {area:976} : attendez sur le quai le bateau gobelin pour {area:16727}.",
		["{item:268505}, the southern ship"] = "{item:268505}, le navire sud",
		["{item:268521}, on the Young Paletusks"] = "{item:268521}, sur les Jeunes brochepâles",
		["{item:268632} as you go"] = "{item:268632} en chemin",
		["{item:269257}, from {npc:260973}"] = "{item:269257}, sur {npc:260973}",
		["{item:271629}, from the Peasant Woodpiles"] = "{item:271629}, sur les Piles de bois de paysan",
		["{item:271629}: fletch it into Makeshift Stickin' Spears"] = "{item:271629} : transformez-le en Lances transperçantes de fortune",
		["{item:769}, from the Mature Paletusks"] = "{item:769}, sur les Brochepâles adultes",
		["{npc:255829}, on the hill"] = "{npc:255829}, sur la colline",
		["{npc:255897}: {quest:95296}, for {npc:260405} at {area:977} in the {zone:1444} & {zone:1446} guide"] = "{npc:255897} : {quest:95296}, pour {npc:260405} à {area:977}, dans le guide {zone:1444} & {zone:1446}",
		["{npc:255906} is an elite gnoll (level 40) who roams the south-western camps of the {area:16737}: grouping up is advised."] = "{npc:255906} est un gnoll élite (niveau 40) qui erre dans les camps sud-ouest de {area:16737} : il est conseillé de grouper.",
		["{npc:255993}, in the middle of the fort"] = "{npc:255993}, au milieu du fort",
		["{npc:256418}: Aggro'gosh's report from {object:3202}, if you carry it"] = "{npc:256418} : le rapport d'Aggro'gosh depuis Grom'gol, si vous l'avez",
		["{npc:256655}, by the cook fire"] = "{npc:256655}, près du feu de cuisine",
		["{npc:256710} stands beside {npc:256418} in the middle of {area:16743}: now that the Farholde camp has had its lesson, he has work in {area:16723}."] = "{npc:256710} se tient à côté de {npc:256418} au milieu de {area:16743} : maintenant que le camp de Farholde a reçu sa leçon, il a du travail à {area:16723}.",
		["{npc:256728}'s camp"] = "Camp de {npc:256728}",
		["{npc:256881} is an elite (level 46) in the fortress at the head of the valley, with the Enforcers around him: grouping up is advised."] = "{npc:256881} est un élite (niveau 46) dans la forteresse au fond de la vallée, entouré des Massacreurs : un groupe est conseillé.",
		["{npc:257001} is an elite (level 42) on the south shore: grouping up is advised."] = "{npc:257001} est un élite (niveau 42) sur la rive sud : il est conseillé de former un groupe.",
		["{npc:258031}'s elites"] = "Les élites de {npc:258031}",
		["{npc:259158} wants out of {area:16723}: lead him west to his treasure at the edge of town and keep the cultists off him."] = "{npc:259158} veut quitter {area:16723} : escortez-le vers l'ouest jusqu'à son trésor à la lisière du village et protégez-le des cultistes.",
		["{npc:259961} on the north pier takes Lozgil's {item:277974}."] = "{npc:259961}, sur la jetée nord, prend le {item:277974} de Lozgil.",
		["{npc:260211} is an elite (level 42) at the Alliance scouts' camp in the hills south-east of {npc:256728}, where you go next: grouping up is advised. The poster hangs in the middle of the fort; {npc:258031} takes the eye, later in this guide."] = "{npc:260211} est un élite (niveau 42) au camp des éclaireurs de l'Alliance, dans les collines au sud-est de {npc:256728}, votre prochaine destination : un groupe est conseillé. L'affiche est accrochée au milieu du fort ; {npc:258031} récupère l'œil, plus loin dans ce guide.",
		["{npc:260993}, a {area:16726} ogre, hides in the cave west of {npc:258570}'s camp."] = "{npc:260993}, un ogre de {area:16726}, se cache dans la grotte à l'ouest du camp de {npc:258570}.",
		["{npc:261208}, a few steps west"] = "{npc:261208}, à quelques pas à l'ouest",
		["{npc:263190}: {quest:95033}, for {npc:8115} at {area:1099} in the {zone:1444} guide"] = "{npc:263190} : {quest:95033}, pour {npc:8115} au {area:1099} dans le guide de {zone:1444}",
		["{npc:263315}, an elite lion (level 41), prowls the plains south of {area:16743}, where the lions are: grouping up is advised."] = "{npc:263315}, un lion élite (niveau 41), rôde dans les plaines au sud de {area:16743}, là où se trouvent les lions : il est conseillé de former un groupe.",
		["{npc:263367}'s workshop"] = "L'atelier de {npc:263367}",
		["{npc:263380} is an elite (level 42) who hunts along the river south-west of {area:16743}, by the Farholde camp you go to next: grouping up is advised. The poster hangs in the middle of the fort."] = "{npc:263380} est un élite (niveau 42) qui chasse le long de la rivière au sud-ouest de {area:16743}, près du camp de Farholde où vous allez ensuite : il est conseillé de former un groupe. L'affiche est au milieu du fort.",
		["{quest:93976}: for {npc:255897} in {area:16727}, keep it"] = "{quest:93976} : pour {npc:255897} à {area:16727}, gardez-la",
		["{quest:94669}: the Ring's bouts, one-on-one fights with elites (41-45); a deposit first"] = "{quest:94669} : les combats de l'Arène, en duel contre des élites (41-45) ; un dépôt d'abord",
		["{quest:94670}: Buzzbeak"] = "{quest:94670} : Buzzbeak",
		["{quest:94727}: for {npc:260931} in {area:16723}"] = "{quest:94727} : pour {npc:260931} à {area:16723}",
		["{quest:94744}: for {npc:258570}, west of {area:16723}"] = "{quest:94744} : pour {npc:258570}, à l'ouest de {area:16723}",
		["{quest:95062}: for {npc:256418} in {area:16743}"] = "{quest:95062} : pour {npc:256418} à {area:16743}",
		["{quest:95261}: the beasts' entrails come as you go; the mushrooms grow on the ridge west of the pirates"] = "{quest:95261} : les entrailles des bêtes viennent en chemin ; les champignons poussent sur la crête à l'ouest des pirates",
		["{quest:95267}: a big beast in the shallows south-west of the port, near {npc:257001}, the elite"] = "{quest:95267} : une grosse bête dans les hauts-fonds au sud-ouest du port, près de {npc:257001}, l'élite",
		["{quest:95293}: for {npc:260390} at the pirates' camp"] = "{quest:95293} : pour {npc:260390} au camp des pirates",
		["{quest:95418}: for {npc:256710} in {area:16743}"] = "{quest:95418} : pour {npc:256710} à {area:16743}",
		["{quest:95420}: for {npc:255829} in {area:16726}"] = "{quest:95420} : pour {npc:255829} à {area:16726}",
		["{quest:95428}: for {npc:256418} in {area:16743}, later in this guide"] = "{quest:95428} : pour {npc:256418} à {area:16743}, plus loin dans ce guide",
} end)()
t.guides["forever/horde/40-50/02-feralas"] = (function() return {
		["\"Sea Wolf\" MacKinley, on the top floor"] = "« Loup de mer » MacKinley, au dernier étage",
		["Back east past {area:75}: the Atal'ai artifacts lie in the water and on the banks of the {quest:1424}."] = "Retournez à l'est après {area:75} : les Artefacts atal'ai se trouvent dans l'eau et sur les rives du Bassin des larmes (quête {quest:1424}).",
		["Back west to {object:3202}."] = "Retournez à l'ouest jusqu'à {object:3202}.",
		["Below ground"] = "Sous terre",
		["Coming from the {zone:2548}: {area:340}'s flight master stands at the foot of the fortress."] = "En venant des {zone:2548} : le maître de vol de {area:340} se tient au pied de la forteresse.",
		["Flown in to {area:976}: the raceway is a short ride north over the {zone:1446} border.\nThe road from {area:484} to {zone:1446} runs past the {area:2240} on the {area:439}: {npc:4454} is in the gnomes' camp beside the track, {npc:4630} and {npc:4709} by the goblins' camp. {npc:4630} first, then {npc:4709}, who runs off to keep Rizzle busy; then take Rizzle's plans from the gnomes' camp and bring them back to {npc:4630}."] = "Arrivé en vol à {area:976} : la piste n'est qu'à une courte chevauchée au nord, de l'autre côté de la frontière de {zone:1446}.\nLa route de {area:484} à {zone:1446} passe devant {area:2240}, sur les {area:439} : {npc:4454} est dans le camp des gnomes à côté de la piste, {npc:4630} et {npc:4709} près du camp des gobelins. D'abord {npc:4630}, puis {npc:4709}, qui part occuper Rizzle ; prenez ensuite les plans de Rizzle dans le camp des gnomes et rapportez-les à {npc:4630}.",
		["Flown in: {area:976}'s quests first, by the flight master, then the {area:2240} is a short ride north over the {zone:1446} border."] = "Arrivée en vol : d'abord les quêtes de {area:976}, près du maître de vol, puis la {area:2240} est à courte distance au nord, de l'autre côté de la frontière de {zone:1446}.",
		["Fly from {zone:1454} to {area:392}; {npc:6251} stands on the hill above the docks."] = "Prenez un vol d'{zone:1454} pour {area:392} ; {npc:6251} se tient sur la colline au-dessus des quais.",
		["Fly to {area:1638}"] = "Prendre un vol pour {area:1638}",
		["Fly to {area:484}"] = "Prendre un vol pour {area:484}",
		["Fly to {area:75}"] = "Prendre un vol pour {area:75}",
		["Fly to {area:976}"] = "Prendre un vol pour {area:976}",
		["Fly to {object:3202}"] = "Prendre un vol pour {object:3202}",
		["For your {area:978} run, in the next guide: {quest:2864} wants scarab shells, and {npc:7804}, a short walk from the flight master, {quest:3042} from the Sandfury trolls."] = "Pour votre expédition dans {area:978}, dans le prochain guide : {quest:2864} veut des carapaces de scarabée, et {npc:7804}, à quelques pas du maître de vol, de la {quest:3042} des trolls Furie-des-sables.",
		["Grimtotem camp"] = "Camp du Totem sinistre",
		["Ironjaw Basilisks"] = "Basilics gueule de fer",
		["Kodos: {npc:3685}, beside {npc:3690} in {area:222}."] = "Kodos : {npc:3685}, à côté de {npc:3690} à {area:222}.",
		["Murlocs of the Misty Reed"] = "Les murlocs de Misty Reed",
		["North-west of the ruins, the yetis den in {area:1105}; every yeti there can drop a thick hide."] = "Au nord-ouest des ruines, les yétis ont leur tanière dans le {area:1105} ; chaque yéti peut y laisser tomber une peau épaisse.",
		["Only with the distress beacon: any beast, gnoll or ogre in {zone:1444} can drop it, about one kill in a hundred; use it to start the quest. The robot sits in a small cave on the north side of {area:1105}, just north-west of the ruins. Escort it to the dock on the {area:1108}; yetis and gorillas ambush you on the way. Its reward waits in {area:35} for a later visit.\nCareful: Three ambushes spawn during the escort, and the robot warns you before each one. The first is 3 yetis, just after the robot leaves the cave and climbs toward the road. The second is 3 gorillas, on the path that runs along the cliff. The third is about 4 gnolls, one of them a caster, where the route turns off toward the dock."] = "Seulement avec la balise de détresse : n'importe quelle bête, gnoll ou ogre de {zone:1444} peut la lâcher, environ une victime sur cent ; utilisez-la pour lancer la quête. Le robot se trouve dans une petite grotte du côté nord de {area:1105}, juste au nord-ouest des ruines. Escortez-le jusqu'au quai de la {area:1108} ; des yétis et des gorilles vous tendent des embuscades en chemin. Sa récompense vous attend à {area:35} pour une visite ultérieure.\nAttention : trois embuscades surviennent pendant l'escorte, et le robot vous prévient avant chacune. La première, 3 yétis, juste après que le robot a quitté la grotte et monte vers la route. La deuxième, 3 gorilles, sur le chemin qui longe la falaise. La troisième, environ 4 gnolls dont un lanceur de sorts, là où la route bifurque vers le quai.",
		["Pirate ghosts and Zanzil's camps"] = "Fantômes pirates et camps de Zanzil",
		["Raptors: Zjolnir, beside {npc:7953} in {area:367}."] = "Raptors : Zjolnir, à côté de {npc:7953} à {area:367}.",
		["Ride east to the Skullsplitter ruins east of the Venture Co. mine. The headhunters, berserkers and hunters roam the ruins.\n{npc:1059} (45) carries the Broken Armor for {quest:586}: he walks the south-western ruins with two guards and sometimes stands in a small cave there. Pull the guards first.\nCareful: {npc:1060}, an elite troll (level 44), stands in the southern ruins around 47.7,44.3: pull the headhunters and berserkers away from him."] = "Allez à l'est jusqu'aux ruines Brise-crâne, à l'est de la mine de la KapitalRisk. Les chasseurs de têtes, berserkers et chasseurs parcourent les ruines.\n{npc:1059} (45) porte l'Armure brisée pour {quest:586} : il arpente les ruines du sud-ouest avec deux gardes et se tient parfois dans une petite grotte. Attaquez d'abord les gardes.\nAttention : {npc:1060}, un troll élite (niveau 44), se tient dans les ruines du sud vers 47.7,44.3 : attirez les chasseurs de têtes et berserkers loin de lui.",
		["Ride north-east back to the port: {npc:7881}, the {npc:15165} and the Security Chief take what {area:1336} gave you. {area:976} is west of it."] = "Retournez au nord-est jusqu'au port : {npc:7881}, la {npc:15165} et le chef de la sécurité prennent ce que {area:1336} vous a donné. {area:976} se trouve à l'ouest.",
		["Ride north-east to the goblin harbour on the coast."] = "Allez au nord-est jusqu'au port gobelin sur la côte.",
		["Ride south along the road towards {area:35}; the basilisks bask on the rocks east of it in the middle of the jungle. Their shards drop often."] = "Allez au sud par la route vers {area:35} ; les basilics se prélassent sur les rochers à l'est, au milieu de la jungle. Leurs éclats tombent souvent.",
		["Ride west along the road; the scroll lies at the water's edge in the swamp's far west."] = "Suivez la route vers l'ouest ; le parchemin se trouve au bord de l'eau, à l'extrême ouest du marais.",
		["Ride west from the hive to the ogre ruins below {area:1105}. Shamans, warlocks and maulers fill them; the Mage-Lords at the southern end carry the orb.\nCareful: the Mage-Lords (45-46) and the Shamans cast from range and the ruins are packed: pull one at a time from the edge."] = "Allez vers l'ouest depuis la ruche jusqu'aux ruines ogres sous {area:1105}. Chamans, démonistes et marteleurs les peuplent ; les Seigneurs-mages, au bout sud, portent l'orbe.\nAttention : les Seigneurs-mages (45-46) et les Chamans attaquent à distance et les ruines sont bondées : attirez-les un par un depuis le bord.",
		["Riding and Galestriders: {npc:265756}, at the {area:17684} in {area:16638} on Zephras Isle."] = "Monte et Trotteurs des trombes : {npc:265756}, aux {area:17684} à {area:16638}, sur l'île de Zéphras.",
		["Riding at 40"] = "Monte au niveau 40",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount. Each race learns it from its own race's trainer: yours is {npc:3690} in {area:222}, with {npc:3685}'s kodos (20 gold each) beside him. Ride back up to {zone:1456}'s flight master afterwards."] = "La monte demande le niveau 40 et coûte 100 pièces d'or ; l'apprendre vous donne une monture. Chaque race l'apprend auprès de son propre maître : le vôtre est {npc:3690}, à {area:222}, avec les kodos de {npc:3685} (20 pièces d'or chacun) à côté de lui. Remontez ensuite jusqu'au maître de vol des {zone:1456}.",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount. Each race learns it from its own race's trainer: yours is {npc:7953} in {area:367}, a short ride south of {zone:1454} down the {zone:1411} road, with Zjolnir's raptors (20 gold each) beside him. Ride back to {zone:1454}'s flight master afterwards."] = "La monte demande le niveau 40 et coûte 100 pièces d'or ; l'apprendre vous donne une monture. Chaque race l'apprend auprès du maître de sa propre race : le vôtre est {npc:7953} à {area:367}, à une courte chevauchée au sud d'{zone:1454} par la route de {zone:1411}, avec les raptors de Zjolnir (20 pièces d'or chacun) à côté de lui. Revenez ensuite au maître de vol d'{zone:1454}.",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount. {npc:4752} teaches Orcs in the {object:172958}, by {npc:3362}'s kennel. Skyborne learn it from {npc:265756} at the {area:17684} in {area:16638} on Zephras Isle, with a Galestrider: the skyboat to the isle leaves the cliffs south of {area:17045}, north of {zone:1456}, about every five minutes. Your race's other mounts are 20 gold each: Collectibles, Mounts · Level 40 has a guide for each."] = "La monte demande le niveau 40 et coûte 100 pièces d'or ; l'apprendre vous donne une monture. {npc:4752} l'enseigne aux Orcs dans la {object:172958}, près du chenil de {npc:3362}. Les Éolides l'apprennent auprès de {npc:265756} aux {area:17684} à {area:16638}, sur l'île de Zéphras, avec un Trotteur des trombes : l'aéronef pour l'île part des falaises au sud de {area:17045}, au nord des {zone:1456}, toutes les cinq minutes environ. Les autres montures de votre race coûtent 20 pièces d'or chacune : Objets de collection, Montures · Niveau 40 a un guide pour chacune.",
		["Rogue Vale screechers"] = "Hurleurs des vallées insoumis",
		["Sawtooth crocolisks"] = "Crocilisques Dents-de-scie",
		["Skeletal horses: {npc:4731}, beside {npc:4773} in {area:159}."] = "Chevaux squelettes : {npc:4731}, à côté de {npc:4773} à {area:159}.",
		["The Grimtotem tauren camp beside the sprite darters' grove; raiders, naturalists and shamans all carry horns.\nCareful: {npc:222286} (level 43, elite) stands in the camp: pull the raiders and shamans away from her."] = "Les taurens du Totem sinistre campent à côté du bosquet des Fées fléchetteuses ; Ecumeurs, Naturalistes et Chamans portent tous des Cornes de Totem sinistre.\nAttention : {npc:222286} (niveau 43, élite) se tient dans le camp : attirez les Ecumeurs et les Chamans loin d'elle.",
		["The Marsh Murlocs live on the strand south of the post; the Inkspewers are along the shore east of it and the Flesheaters further west, around the huts on the western shore."] = "Les Murlocs des marais vivent sur la grève au sud du poste ; les Crache-encre sont le long du rivage à l'est et les Mange-chair plus à l'ouest, autour des huttes de la rive ouest.",
		["The Woodpaw gnolls camp in the hills just north-west of Mojache; any of them can drop a mane.\nCareful: Every Woodpaw gnoll except the Alpha runs off for help at 15% health, which can pull more gnolls into the fight."] = "Les gnolls Patte-de-bois campent dans les collines juste au nord-ouest de Mojache ; n'importe lequel peut lâcher une crinière.\nAttention : tous les gnolls Patte-de-bois sauf l'Alpha fuient chercher de l'aide à 15 % de vie, ce qui peut attirer d'autres gnolls dans le combat.",
		["The Zukk'ash hive burrows into the hills south-east of the camp; {quest:7731} waits in its deepest chamber.\nCareful: {quest:7731} is level 47: clear the hive around him and pull him alone at full health."] = "La ruche des Zukk'ash s'enfonce dans les collines au sud-est du camp ; {quest:7731} attend dans sa chambre la plus profonde.\nAttention : {quest:7731} est de niveau 47 : nettoyez la ruche autour de lui et attirez-le seul, avec toute votre vie.",
		["The battle map lies in the Woodpaw camp south of Mojache."] = "Le Plan de bataille des Griffebois se trouve dans le camp Griffebois au sud de Mojache.",
		["The crocolisks wallow in the pools around Galen's old camp, just north of {area:75}, on the way back east; about one in four drops a flank."] = "Les crocilisques se vautrent dans les mares autour de l'ancien camp de Galen, juste au nord de {area:75}, sur le chemin du retour vers l'est ; environ un sur quatre laisse tomber un flanc.",
		["The middle of {zone:1454}"] = "Le centre d'{zone:1454}",
		["The same murloc shore again: Inkspewers east of the post, Flesheaters around the western huts, and the Oracles among both."] = "Encore le même rivage des murlocs : les Cracheurs d'encre à l'est du poste, les Mangeurs de chair autour des huttes de l'ouest, et les Oracles parmi les deux.",
		["The shadow mages, rogues and assassins camp south-east of {area:976}.\nSouth-east of Gadgetzan the Wastewander bandits camp in the dunes; {npc:7847} stands in the eastern camp.\nCareful: Wastewander Rogues keep Sneak up while out of combat, so hidden rogues can join a fight you start at a camp.\nCareful: Two stealthed Wastewander Rogues travel with him wherever he goes. At his spawn camp, two shadowmages and their minions are close enough to join a fight with him. Out by the towers you can fight him without them."] = "Les mages des ombres, les voleurs et les assassins campent au sud-est de {area:976}.\nAu sud-est de Gadgetzan, les bandits Bat-le-désert campent dans les dunes ; {npc:7847} se tient dans le camp est.\nAttention : les Voleurs Bat-le-désert restent camouflés hors combat, des voleurs cachés peuvent donc rejoindre un combat que vous lancez dans un camp.\nAttention : deux Voleurs Bat-le-désert camouflés l'accompagnent partout. À son camp d'apparition, deux mages des ombres et leurs serviteurs sont assez proches pour se joindre au combat. Près des tours, vous pouvez l'affronter sans eux.",
		["The snappers line the strand south of the post.\nThe Monstrous Crawlers walk the beaches of the east coast, few and far between: kill every one you see, the ones on the ride down from the pool too.\nCareful: a {npc:272377} (level 60) walks the south-east strand: give it a wide berth."] = "Les mordeurs bordent la grève au sud du poste.\nLes Clampants monstrueux parcourent les plages de la côte est, rares et dispersés : tuez tous ceux que vous voyez ainsi que ceux sur le trajet depuis le bassin.\nAttention : un {npc:272377} (niveau 60) arpente la grève sud-est : gardez vos distances.",
		["The sprite darters flit over the grove just west of Mojache; nearly every one drops a wing. The Woodpaw alphas lead the camps south-west of it: kill them within the hour.\nCareful: Most Alphas sit in small tent camps with 2-4 other gnolls that join the fight, and other gnolls patrol between the camps."] = "Les fées fléchetteuses voltigent au-dessus du bosquet juste à l'ouest de Mojache ; presque toutes lâchent une aile. Les alphas Patte-de-bois dirigent les camps au sud-ouest : tuez-les dans l'heure.\nAttention : la plupart des Alphas se tiennent dans de petits camps de tentes avec 2 à 4 autres gnolls qui se joignent au combat, et d'autres gnolls patrouillent entre les camps.",
		["The {area:43}"] = "{area:43}",
		["To {area:75}"] = "Vers {area:75}",
		["To {area:976}"] = "Vers {area:976}",
		["Underwater"] = "Sous l'eau",
		["Upstairs"] = "À l'étage",
		["West into Mistvale: {npc:1449} sits among the gorillas. Any gorilla can drop a fang: hand him ten and stay by him, he calls three waves of gorillas, then {npc:1514}.\nCareful: three waves of gorillas come one after another with little rest between, then {npc:1514}. Start at full health and mana, and stay near Unbagwa. Some classes find it hard alone: a friend makes it easy."] = "À l'ouest dans Val-Brumeux : {npc:1449} est assis parmi les gorilles. Tout gorille peut lâcher un croc : donnez-lui-en dix et restez près de lui, il appelle trois vagues de gorilles, puis {npc:1514}.\nAttention : les trois vagues arrivent l'une après l'autre avec peu de répit, puis {npc:1514}. Commencez avec toute votre vie et votre mana, et restez près d'Unbagwa. Certaines classes ont du mal seules : un ami rend la chose facile.",
		["Wolves: {npc:3362}, beside {npc:4752}."] = "Loups : {npc:3362}, à côté de {npc:4752}.",
		["Woodpaw battle map"] = "Plan de bataille des Griffebois",
		["Woodpaw north camp"] = "Camp Griffebois du nord",
		["Your trainer is in {zone:1456}: {npc:3033} (Druids) on {area:1639}, {npc:246344} (Paladins)."] = "Votre maître est aux {zone:1456} : {npc:3033} (druides) sur {area:1639}, {npc:246344} (paladins).",
		["Zeppelin to {zone:1454}"] = "Zeppelin pour {zone:1454}",
		["Zul'Mamwe"] = "Ruines de Zul'Mamwe",
		["for {area:35}, around level 51 (40-50/06)"] = "pour {area:35}, vers le niveau 51 (40-50/06)",
		["for {zone:1454}, after {zone:2652}"] = "pour {zone:1454}, après {zone:2652}",
		["the Rage Scar yetis, on the next visit to {zone:1444}"] = "les yétis de la Balafre de rage, lors de la prochaine visite de {zone:1444}",
		["the {item:8523} from these errands: keep it, Tanaris Field Sampling hands it back in {area:976}"] = "la {item:8523} de ces missions : gardez-la, la quête Les échantillons du désert de Tanaris vous la redonne à {area:976}",
		["the {object:2076}"] = "le {object:2076}",
		["the {object:2076} again: Yenniku's fate"] = "le {object:2076} à nouveau : le sort de Yenniku",
		["the {object:2076}: {quest:586}"] = "le {object:2076} : {quest:586}",
		["{area:1105} yetis"] = "Yétis du {area:1105}",
		["{area:1336}: kill these as you meet them"] = "{area:1336} : tuez-les au passage",
		["{area:1577}: kill these as you meet them"] = "{area:1577} : tuez-les au passage",
		["{area:1937}: kill these as you meet them"] = "{area:1937} : tuez-les au passage",
		["{area:2403}: kill these as you meet them"] = "{area:2403} : tuez-les au passage",
		["{area:2522}: kill these as you meet them"] = "{area:2522} : tuez-les au passage",
		["{area:340} flight master"] = "Maître de vol de {area:340}",
		["{area:35} flight master"] = "Maître de vol de {area:35}",
		["{area:392} flight master"] = "Maître de vol de {area:392}",
		["{area:392} for the Felsteed"] = "{area:392} pour le Palefroi corrompu",
		["{area:75} flight master"] = "Maître de vol de {area:75}",
		["{area:976} flight master"] = "Maître de vol de {area:976}",
		["{area:976} is the walled goblin town just past the {zone:1446} border."] = "{area:976} est la ville gobeline fortifiée juste après la frontière de {zone:1446}.",
		["{area:985}: kill these as you meet them"] = "{area:985} : tuez-les au passage",
		["{npc:1443}, on the top floor"] = "{npc:1443}, au dernier étage",
		["{npc:2491}, in the inn: his bottles wash up on the {zone:1425} coast, around level 48"] = "{npc:2491}, dans l'auberge : ses bouteilles s'échouent sur la côte des {zone:1425}, vers le niveau 48",
		["{npc:2498}, inside"] = "{npc:2498}, à l'intérieur",
		["{npc:2519}: the basilisks bask beside the road south, on the ride to {area:35}"] = "{npc:2519} : les basilics se prélassent au bord de la route au sud, sur le chemin de {area:35}",
		["{npc:260405}, on the pier: Friz's errand from the {zone:2548}, if you carry it"] = "{npc:260405}, sur la jetée : la course de Friz depuis les {zone:2548}, si vous l'avez",
		["{npc:2934}, on the way back to Zinge"] = "{npc:2934}, sur le chemin du retour vers Zinge",
		["{npc:3690}, riding trainer"] = "{npc:3690}, maître de monte",
		["{npc:4454}: {quest:1137}, from Martek in the {zone:1418}"] = "{npc:4454} : {quest:1137}, de la part de Martek dans {zone:1418}",
		["{npc:4706}, beside {npc:4630}"] = "{npc:4706}, à côté de {npc:4630}",
		["{npc:4752}, riding trainer"] = "{npc:4752}, maître de monte",
		["{npc:5234} walks around {area:2522}: look inside the circle on the map"] = "{npc:5234} se promène autour de {area:2522} : cherchez dans le cercle sur la carte",
		["{npc:5591}, inside"] = "{npc:5591}, à l'intérieur",
		["{npc:669} walks around here: look inside the circle on the map"] = "{npc:669} se promène par ici : cherchez dans le cercle sur la carte",
		["{npc:737}, upstairs"] = "{npc:737}, à l'étage",
		["{npc:773}, upstairs: for {quest:2864} in {area:976}, later in this guide"] = "{npc:773}, à l'étage : pour {quest:2864} à {area:976}, plus loin dans ce Guide",
		["{npc:7777} walks around {area:1099}: look inside the circle on the map"] = "{npc:7777} se promène autour de {area:1099} : cherchez dans le cercle sur la carte",
		["{npc:7854}, inside"] = "{npc:7854}, à l'intérieur",
		["{npc:7875}: for {npc:7010} in {zone:1454}"] = "{npc:7875} : pour {npc:7010} à {zone:1454}",
		["{npc:7881}, inside"] = "{npc:7881}, à l'intérieur",
		["{npc:7882}, inside"] = "{npc:7882}, à l'intérieur",
		["{npc:7953}, riding trainer"] = "{npc:7953}, maître de monte",
		["{npc:8115}: {npc:263190}'s errand from the {zone:2548}, if you carry it"] = "{npc:8115} : la course de {npc:263190} depuis les {zone:2548}, si vous l'avez",
		["{object:3202} flight master"] = "Maître de vol de Grom'gol",
		["{quest:2863}: one hour from now"] = "{quest:2863} : dans une heure",
		["{zone:1444}: kill these as you meet them"] = "{zone:1444} : tuez-les au passage",
		["{zone:1454} flight master"] = "Maître de vol d'{zone:1454}",
		["{zone:1456} flight master"] = "Maître de vol des {zone:1456}",
		["{zone:2652} is next, a ride north from {area:1099} into {zone:1443}: keep your {zone:1454} hand-ins (Neeru, Zilzibin, {npc:4485}, {npc:7311}) for the flight there after it."] = "{zone:2652} est la suite, à une chevauchée au nord de {area:1099} en {zone:1443} : gardez vos quêtes à rendre à {zone:1454} (Neeru, Zilzibin, {npc:4485}, {npc:7311}) pour le vol qui suivra.",
} end)()
t.guides["forever/horde/40-50/03-feralas"] = (function() return {
		["Below ground"] = "Sous terre",
		["East through the {area:511}: the Firemane scouts and ash tails roam its northern edge with the Searing hatchlings and whelps; the scalebanes guard the dragon caves further south-east. Mok'Morokk's snuff, grog and strongbox lie in the dragonkin camps."] = "Vers l'est à travers la {area:511} : les éclaireurs et les queues-de-cendre Crins-de-feu parcourent sa lisière nord avec les jeunes dragons et les dragonnets brûlants ; les Fléaux-d'écailles gardent les grottes des dragons plus au sud-est. Le tabac à priser, le grog et le coffre-fort de Mok'Morokk se trouvent dans les camps des draconiens.",
		["Fly to {area:1099}"] = "Prendre un vol pour {area:1099}",
		["Fly to {area:496}"] = "Prendre un vol pour {area:496}",
		["From the flight master: the {object:172960}, then the Drag, then the {object:172958}."] = "Depuis le maître de vol : {object:172960}, puis la Herse, puis la {object:172958}.",
		["Inside {area:498}"] = "Dans {area:498}",
		["Level 45.37"] = "Niveau 45.37",
		["Onyxia's eggs"] = "Oeufs d'Onyxia",
		["Ride back north to Brackenwall."] = "Retournez au nord jusqu'à Mur-de-Fougères.",
		["Ride south-west to the {object:2555}."] = "Allez au sud-ouest jusqu'au {object:2555}.",
		["Stays on the main route"] = "Reste sur l'itinéraire principal",
		["Takes you to level 47"] = "Vous amène au niveau 47",
		["The Eggs of Onyxia lie in the dragon caves in the {area:511}'s south-east, guarded by the scalebanes; smash five."] = "Les Oeufs d'Onyxia reposent dans les grottes des dragons au sud-est de {area:511}, gardés par les Plaiedécailles Crins-de-feu ; écrasez-en cinq.",
		["The {object:2555}"] = "Le {object:2555}",
		["Then on to {zone:1446}"] = "Puis direction {zone:1446}",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {quest:1173} needs a group of 3. Skip it if you are alone: the route has you grind the XP back.\n{npc:4500} is elite: grouping up is advised. Beat him down until he gives up, then report to {npc:4501}."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {quest:1173} demande un groupe de 3. Passez-la si vous êtes seul : la route vous fait regagner cette expérience en tuant des monstres.\nLe {npc:4500} est élite : il est conseillé de se grouper. Frappez-le jusqu'à ce qu'il abandonne, puis faites votre rapport à {npc:4501}.",
		["grind on {npc:4329}"] = "tuez en boucle : {npc:4329}",
		["the {object:2555}"] = "le {object:2555}",
		["{area:1099} flight master"] = "Maître de vol de {area:1099}",
		["{area:510}: kill these as you meet them"] = "{area:510} : tuez-les au passage",
		["{npc:4329} walks around {area:510}: look inside the circle on the map"] = "{npc:4329} se promène autour de {area:510} : cherchez dans le cercle sur la carte",
		["{npc:4500}'s challenge, back in Brackenwall, needs a group of three. Alone, grind the Firemane scouts here on the {area:511}'s northern edge to level 45.37 before you ride back north, so you don't come back down for it. Or, with a group, run the {area:978} dungeon instead."] = "Le défi de {npc:4500}, de retour à Mur-de-Fougères, demande un groupe de trois. Seul, tuez en boucle les Eclaireurs Crins-de-feu ici, sur la lisière nord de {area:511}, jusqu'au niveau 45.37 avant de repartir vers le nord, pour ne pas avoir à redescendre. Ou, en groupe, faites plutôt le donjon {area:978}.",
		["{npc:4500}, {npc:4502} and {npc:4501} (below ground) are in the village; their quests are for the {area:511} on this trip."] = "{npc:4500}, {npc:4502} et {npc:4501} (sous terre) sont dans le village ; leurs quêtes concernent la {area:511} lors de ce passage.",
		["{npc:4501}, below ground"] = "{npc:4501}, sous terre",
		["{npc:6986}, the Drag"] = "{npc:6986}, la Herse",
		["{npc:7010}, the Drag"] = "{npc:7010}, la Herse",
		["{zone:1454} flight master"] = "Maître de vol d'{zone:1454}",
} end)()
t.guides["forever/horde/40-50/04-tanaris"] = (function() return {
		["Back east to Fizzledowser on the west side of {area:976}; {npc:7771} is south from there."] = "Retournez vers l'est voir Fizzledowser, du côté ouest de {area:976} ; {npc:7771} est au sud de là.",
		["Below ground"] = "Sous terre",
		["Below ground: the plans, on the {area:1443}'s upper ledge"] = "Sous terre : les plans, sur la corniche supérieure de {area:1443}",
		["Boat to {area:16727}"] = "Bateau pour {area:16727}",
		["Careful: Shadow Mages (level 42-43) call a Voidwalker while out of combat and attack with Immolate and {spell:686}. Thieves can Disarm you, Rogues move around in Sneak, and Assassins use Execute once you are at 20% health or less."] = "Attention : les Mages des ombres (niveau 42-43) invoquent un Marcheur du Vide hors combat et attaquent avec Immolation et {spell:686}. Les Malandrins peuvent vous désarmer, les Voleurs se déplacent camouflés, et les Assassins utilisent Exécution une fois que vous êtes à 20 % de vie ou moins.",
		["Dark Iron Lookouts"] = "Guetteurs Sombrefer",
		["Fly to {area:976}"] = "Prendre un vol pour {area:976}",
		["For your {area:978} run, after {area:979}: {npc:7407}, by the water tower, wants his {quest:2768} back; {quest:2864} his scarab shells and Trenton Lighthammer Troll Temper, if you have not taken those yet."] = "Pour votre expédition dans {area:978}, après {area:979} : {npc:7407}, près du château d'eau, veut récupérer sa {quest:2768} ; {quest:2864} veut ses carapaces de scarabée et Trenton Lighthammer de la Trempe de troll, si vous ne les avez pas encore prises.",
		["Further south, Junior Surveyor Scrimshank's gear lies at the mouth of a Centipaar hive.\nCareful: One bug guards the gear. Many bugs patrol the tunnels, some of them level 50, so fights often pull extra adds."] = "Plus au sud, l'équipement du géomètre débutant Scrimshank se trouve à l'entrée d'une ruche Centipaar.\nAttention : un insecte garde l'équipement. De nombreux insectes patrouillent dans les tunnels, certains de niveau 50, les combats attirent donc souvent des monstres en plus.",
		["Heavy War Golems patrol the Cauldron below {npc:8479} and drop the oil; the Magma and Blazing Elementals drifting among them drop the hearts. The Dark Iron Taskmasters and Slavers drive the slaves on the paths; a Slaver may drop the {item:11818}: keep it.\nThe Searing Lava Spiders roam the plateaus and lava pools in the south-west of the gorge.\n{area:1443} opens in the north of the Cauldron. Incendosaurs swim in its lava pools: pull them to the edge. The secret plans lie on the pit's upper ledge.\nCareful: Dark Iron Slavers (level 45-46) call for help from allies within 15 yd when pulled, cast Net from up to 15 yd, and use Rend in melee. The biggest Incendosaurs and Lava Spiders are 49: pull them one at a time."] = "Les Golems de guerre lourds patrouillent dans le Chaudron sous {npc:8479} et lâchent l'huile ; les Élémentaires de magma et les Élémentaires flamboyants qui errent parmi eux lâchent les cœurs. Les Sous-chefs et les Esclavagistes Sombrefer mènent les esclaves sur les chemins ; un Esclavagiste peut lâcher la {item:11818} : gardez-la.\nLes Grandes araignées de lave parcourent les plateaux et les mares de lave au sud-ouest de la gorge.\n{area:1443} s'ouvre au nord du Chaudron. Des Incendosaures nagent dans ses mares de lave : attirez-les vers le bord. Les plans secrets se trouvent sur la corniche supérieure de la fosse.\nAttention : les Esclavagistes Sombrefer (niveau 45-46) appellent à l'aide les alliés à moins de 15 m quand ils sont attirés, lancent Filet jusqu'à 15 m et utilisent Pourfendre au corps à corps. Les plus gros Incendosaures et Araignées de lave sont niveau 49 : attirez-les un par un.",
		["His next request needs the {item:10552} from elite cultists: leave it."] = "Sa demande suivante exige le {item:10552} sur des cultistes élites : laissez-la.",
		["Into {zone:1427}"] = "Vers la {zone:1427}",
		["Keep the Model 4711-FTZ Power Source Bilgewhizzle gave you: it starts {quest:654}, a two-hour timer, so use it on the way back north from Scrimshank's hive."] = "Gardez la Source d'énergie modèle 4711-FTZ que Bilgewhizzle vous a donnée : elle lance {quest:654}, avec un délai de deux heures, alors utilisez-la en revenant vers le nord depuis la ruche de Scrimshank.",
		["OOX-17/TN"] = "OOX-17/TN",
		["Only with the distress beacon: OOX-17/TN sits south-east of Scrimshank's hive. Escort it north to {area:977}; its reward waits with Oglethorpe in {area:35}.\nCareful: The escort has two ambushes. Three level 47 scorpids attack near the start. Near the end, by the beach, three Wastewander humans attack: one mage and two assassins, around level 44."] = "Seulement avec la balise de détresse : OOX-17/TN se trouve au sud-est de la ruche de Scrimshank. Escortez-le vers le nord jusqu'à {area:977} ; sa récompense vous attend auprès d'Oglethorpe, à {area:35}.\nAttention : l'escorte comporte deux embuscades. Trois scorpides de niveau 47 attaquent près du départ. Vers la fin, près de la plage, trois humains Bat-le-désert attaquent : un mage et deux assassins, autour du niveau 44.",
		["Only with the {item:11818}: back east to the {object:173265} at the dig site."] = "Seulement avec la {item:11818} : retournez à l'est jusqu'aux {object:173265} du site de fouilles.",
		["Ride back north to {area:1446}, just past {npc:8479}."] = "Remontez vers le nord jusqu'à {area:1446}, juste après {npc:8479}.",
		["Ride north-west across the gorge; {area:1446} is the scaffolded camp in the north-west."] = "Traversez la gorge vers le nord-ouest ; {area:1446} est le camp entouré d'échafaudages au nord-ouest.",
		["Ride south from {area:1446} into the Cauldron: the Dark Iron Taskmasters and Slavers drive the slaves on the paths, and the Heavy War Golems patrol the floor below {npc:8479}. Careful: the biggest golems are 49: pull them one at a time."] = "Partez vers le sud depuis {area:1446} jusque dans le Chaudron : les Sous-chefs et les Esclavagistes Sombrefer mènent les esclaves sur les chemins, et les Golems de guerre lourds patrouillent au fond, sous {npc:8479}. Attention : les plus gros golems sont niveau 49 : attirez-les un par un.",
		["Scrimshank's gear"] = "Équipement d'analyse de Scrimshank",
		["The Dark Iron Lookouts stand on the ridges around the sentry towers south of the Cauldron; about one in ten carries the {item:18960}."] = "Les Guetteurs Sombrefer se tiennent sur les crêtes autour des tours de guet au sud du Chaudron ; environ un sur dix porte la {item:18960}.",
		["The Dark Iron Steamsmiths work the furnaces in the middle of the Cauldron; half of them carry a {item:10551}, one in ten the {item:18959}. Slaves, Slavers and Taskmasters carry daggers too."] = "Les Forge-vapeur Sombrefer travaillent aux fourneaux au milieu du Chaudron ; la moitié d'entre eux portent une {item:10551}, un sur dix la {item:18959}. Les Esclaves, les Esclavagistes et les Sous-chefs portent aussi des dagues.",
		["The Steamsmiths' furnaces"] = "Les fourneaux des Forge-vapeur",
		["The flight lands beside {npc:7876}. Take the town's quests before riding west to {area:979}."] = "Le vol se pose à côté de {npc:7876}. Prenez les quêtes de la ville avant de partir vers l'ouest jusqu'à {area:979}.",
		["The {area:247}"] = "{area:247}",
		["The {object:179827} board"] = "Le panneau {object:179827}",
		["The {quest:2768}: {npc:7407}, by the water tower."] = "La {quest:2768} : {npc:7407}, près du château d'eau.",
		["The {quest:3042}: {npc:7804}, a short walk from the flight master."] = "La {quest:3042} : {npc:7804}, à quelques pas du maître de vol.",
		["Use the {item:8524}"] = "Utilisez la {item:8524}",
		["West along the road south; {npc:7771} camps by the ruins at the {area:1938}. Put on his {item:9978}: it shows the buried ornaments, here and around the {area:983}."] = "À l'ouest, le long de la route du sud ; {npc:7771} campe près des ruines : {area:1938}. Équipez son {item:9978} : il montre les ornements enterrés, ici et autour de {area:983}.",
		["West of Gadgetzan, use the {item:8584} beside the water hole in the troll camp."] = "À l'ouest de Gadgetzan, utilisez le {item:8584} près du point d'eau du camp troll.",
		["West, the Centipaar insects swarm around their hives; any of them drops the parts.\nCareful: Centipaar Swarmers cast {npc:4196} both in and out of combat, which brings small adds that interrupt you. The Sandreavers are 49-50: take the Workers and Tunnelers."] = "À l'ouest, les insectes Centipaar grouillent autour de leurs ruches ; n'importe lequel lâche les pièces.\nAttention : les Traînards Centipaar lancent {npc:4196} en combat comme hors combat, ce qui fait venir de petits monstres qui vous interrompent. Les Ravageurs des sables sont de niveau 49-50 : prenez les Ouvriers et les Tunneliers.",
		["You missed this on the route's earlier visit here: it comes first now. It is quick and opens the quests after it."] = "Vous avez manqué ceci lors du passage précédent de l'itinéraire ici : cela passe d'abord maintenant. C'est rapide et cela ouvre les quêtes qui suivent.",
		["Your {area:978} scarab shells: {npc:7876}, beside the wind rider master."] = "Vos carapaces de scarabée de {area:978} : {npc:7876}, à côté du maître des coursiers du vent.",
		["for {npc:5204} in the {zone:1458}, around level 52"] = "pour {npc:5204} à {zone:1458}, vers le niveau 52",
		["for {npc:7010} in {zone:1454}, around level 50"] = "pour {npc:7010} à {zone:1454}, vers le niveau 50",
		["the {item:8526} grows in the {zone:1425}, around level 48"] = "la {item:8526} pousse dans {zone:1425}, vers le niveau 48",
		["the {object:173265}"] = "les {object:173265}",
		["{area:1099} flight master"] = "Maître de vol de {area:1099}",
		["{area:246}'s slavers and golems"] = "Esclavagistes et golems de {area:246}",
		["{area:496} flight master"] = "Maître de vol de {area:496}",
		["{area:978} is a dungeon for a group of five; its quests here are level 45 to 47. Its gate lies about 400 yards north of the troll camp's water hole.\nInside: the Scarabs drop the shells, every Sandfury troll can drop {quest:3042}, and {npc:7604} carries the {quest:2768}."] = "{area:978} est un donjon pour un groupe de cinq ; ses quêtes d'ici sont de niveau 45 à 47. Son entrée se trouve à environ 400 mètres au nord du point d'eau du camp troll.\nÀ l'intérieur : les Scarabées lâchent les carapaces, n'importe quel troll Furie-des-sables peut lâcher la {quest:3042}, et {npc:7604} porte la {quest:2768}.",
		["{item:11818}, a rare drop"] = "{item:11818}, butin rare",
		["{item:8623}, a rare drop"] = "{item:8623}, butin rare",
		["{npc:5594}, inside"] = "{npc:5594}, à l'intérieur",
		["{npc:5955} waits in the valley. Walk him all the way to his wife {npc:6015} in {area:977}, north-east across the desert: stay close, slow down for him and fight off what attacks him. Do not mount or hearth out of his reach. {npc:8579} stands in the port too."] = "{npc:5955} attend dans la vallée. Accompagnez-le jusqu'à sa femme {npc:6015} à {area:977}, au nord-est à travers le désert : restez près de lui, ralentissez pour lui et repoussez ce qui l'attaque. Ne montez pas en selle et n'utilisez pas votre pierre de foyer hors de sa portée. {npc:8579} se tient aussi dans le port.",
		["{npc:5955}'s escort"] = "Escorte de {npc:5955}",
		["{npc:7876}, beside the wind rider master"] = "{npc:7876}, à côté du maître des coursiers du vent",
		["{npc:8479} stands alone south of {area:1446}, at the edge of the Cauldron. Listen to his story."] = "{npc:8479} se tient seul au sud de {area:1446}, au bord du Chaudron. Écoutez son histoire.",
		["{quest:2768}: {npc:7604}, inside"] = "{quest:2768} : {npc:7604}, à l'intérieur",
		["{quest:2865}: the Scarabs, inside"] = "{quest:2865} : les Scarabées, à l'intérieur",
		["{quest:3042}: the Sandfury trolls, inside"] = "{quest:3042} : les trolls Furie-des-sables, à l'intérieur",
		["{quest:3161} ornaments"] = "Ornements de {quest:3161}",
		["{quest:3362}: kill these as you meet them"] = "{quest:3362} : tuez-les au passage",
		["{zone:1427}: kill these as you meet them"] = "{zone:1427} : tuez-les au passage",
} end)()
t.guides["forever/horde/40-50/05-the-hinterlands"] = (function() return {
		["Back west to {area:350}; rangers and marksmen stay near the lodge, scouts and outrunners on the slopes south of it."] = "Retournez à l'ouest jusqu'à {area:350} ; les Forestiers et Tireurs d'élite du Haut-val restent près du gîte, les Eclaireurs et Estafettes du Haut-val sur les pentes au sud.",
		["Careful: Stealthed wolves and griffons roam the {area:1883} area."] = "Attention : des loups et des griffons camouflés rôdent dans les environs de {area:1883}.",
		["East of the village, the violet flower grows in the hills."] = "À l'est du village, le Tragan violet pousse dans les collines.",
		["Fly to {area:272}"] = "Prendre un vol pour {area:272}",
		["Fly to {area:75}"] = "Prendre un vol pour {area:75}",
		["Follow the roads east across the {zone:1425} to the troll village on the eastern coast."] = "Suivez les routes vers l'est à travers les {zone:1425} jusqu'au village troll de la côte est.",
		["Highvale"] = "Haut-val",
		["His next request, going on to the {area:355}, is for a group."] = "Sa demande suivante, qui mène à {area:355}, est pour un groupe.",
		["Huntsman Malkhor's skull lies on a pile below the Vilebranch ruins, his bones on a pile at the foot of {area:354}. The Vessels of Tainted Blood sit on the lower terraces, and {npc:14757} is held at the top. The trolls inside are elite: stay with your group and keep to the paths."] = "Le Crâne du veneur Malkhor se trouve sur un tas sous les ruines Vilebranch, les Os du veneur Malkhor sur un tas au pied de {area:354}. Les Calices de sang corrompu sont posés sur les terrasses inférieures, et {npc:14757} est retenu au sommet. Les trolls à l'intérieur sont des élites : restez avec votre groupe et sur les chemins.",
		["If you skipped {quest:7816} or the {area:354} group quests, grind here to level 49.02 to stay on the route's plan."] = "Si vous avez passé {quest:7816} ou les quêtes de groupe de {area:354}, tuez des monstres ici jusqu'au niveau 49.02 pour rester dans le plan de la route.",
		["Level 49.02"] = "Niveau 49.02",
		["No flight path to {area:75} yet: the arrow takes the quickest way there (by the {object:3202} flight and the road through {zone:1431} and {zone:1430}). Learn {area:75}'s flight path when you arrive."] = "Pas encore de trajet aérien vers {area:75} : la flèche prend le chemin le plus rapide (par le vol de {object:3202} et la route à travers {zone:1431} et le {zone:1430}). Apprenez le trajet aérien de {area:75} en arrivant.",
		["North along the coast, {npc:14731}'s picnic basket is on the small island; a {npc:14748} guards it."] = "Au nord le long de la côte, le panier de pique-nique de {npc:14731} est sur la petite île ; un {npc:14748} le garde.",
		["OOX-09/HL"] = "OOX-09/HL",
		["On the top floor"] = "Au dernier étage",
		["Only with the distress beacon: the robot sits at the head of the river west of {area:351}. Escort it east to the shore beyond the {area:307}; its reward waits with Oglethorpe in {area:35}.\nCareful: Two ambushes spawn during the escort: first three wildkin owlbeasts, then three trolls. Before each, the robot halts and announces it senses danger. Oozes, stealthed wolves and a large turtle along the path can join fights, and they respawn even if cleared beforehand."] = "Seulement avec la balise de détresse : le robot se trouve à la source de la rivière, à l'ouest de {area:351}. Escortez-le vers l'est jusqu'au rivage au-delà de {area:307} ; sa récompense vous attend auprès d'Oglethorpe, à {area:35}.\nAttention : deux embuscades surviennent pendant l'escorte : d'abord trois chouettards, puis trois trolls. Avant chacune, le robot s'arrête et annonce qu'il sent un danger. Des limons, des loups camouflés et une grande tortue le long du chemin peuvent se joindre aux combats, et ils réapparaissent même si vous les avez éliminés avant.",
		["Ride all the way west to the Wildhammer town of {area:348} and place the message by the well in its centre. The town is full of Alliance guards: get in, place it and get out."] = "Allez tout à l'ouest jusqu'à {area:348}, la ville des Wildhammer, et déposez le message près du puits en son centre. La ville est pleine de gardes de l'Alliance : entrez, déposez-le et repartez.",
		["Ride back north through the canyon to {area:75}."] = "Remontez vers le nord par le canyon jusqu'à {area:75}.",
		["Ride back north to the bloodmages."] = "Retournez au nord jusqu'aux mages de sang.",
		["Ride north-east from {area:272} into the {zone:1425} and east along the road; {npc:7801} camps on the hill south of the elves' {area:350}."] = "Depuis {area:272}, allez au nord-est jusqu'aux {zone:1425}, puis à l'est le long de la route ; {npc:7801} campe sur la colline au sud de {area:350}, le gîte des elfes.",
		["Ride west out of {area:75} and south through the canyon into the {zone:1419}; the two bloodmages stand by the road just inside."] = "Sortez de {area:75} par l'ouest et descendez le canyon vers le sud jusqu'à {zone:1419} ; les deux mages de sang se tiennent au bord de la route, juste à l'entrée.",
		["South of the lodge the Witherbark trolls hold their villages. Every one of them carries a skull: with twenty, use {item:15002} to make the Laden Pike, then plant it inside the village."] = "Au sud du gîte, les trolls Witherbark tiennent leurs villages. Chacun porte un crâne : avec vingt crânes, utilisez {item:15002} pour obtenir la Pique de Nimboya préparée, puis plantez-la dans le village.",
		["South-west again, the exile hides by the ruins of {area:353}."] = "De nouveau au sud-ouest, l'exilé se cache près des ruines de {area:353}.",
		["South-west of the lake, the Vilebranch soothsayers hold the {area:355}, the troll temple south of the central hills. Qiaga and {npc:8636} (elite, 50) stand at its top: take the soothsayers on the lower steps.\nSouth-west, the Silvermane Howlers roam the hills east of the Witherbark villages."] = "Au sud-ouest du lac, les devins Vilebranch tiennent l'{area:355}, le temple troll au sud des collines centrales. Qiaga et {npc:8636} (élite, 50) se tiennent au sommet : affrontez les devins sur les marches inférieures.\nAu sud-ouest, les Hurleurs Crins-d'argent parcourent les collines à l'est des villages Witherbark.",
		["The Highvale elves camp around {area:350}. Burn the report, the notes and the records in their camps. {npc:7780} is held inside the lodge: lead him out and fight off the ambush on the way.\nCareful: Groups of about three elves ambush the escort, usually twice."] = "Les elfes de Highvale campent autour de {area:350}. Brûlez le rapport, les notes et les registres dans leurs camps. {npc:7780} est retenu dans le pavillon : faites-le sortir et repoussez l'embuscade en chemin.\nAttention : des groupes d'environ trois elfes attaquent l'escorte, généralement deux fois.",
		["The big turtles crawl along the beaches north of the village, and {npc:2491}'s bottles of port lie on the same beaches, from the village up to the {area:307}: pick them up as you go. A snapjaw can drop OOX-09/HL's distress beacon, rarely: keep it.\nCareful: the biggest Saltwater Snapjaws are 50: pull them one at a time."] = "Les grosses tortues rampent sur les plages au nord du village, et les bouteilles de Porto Pupellyverbos de {npc:2491} jonchent ces mêmes plages, du village jusqu'à {area:307} : ramassez-les en chemin. Une Gueule d'acier des mers peut laisser tomber la Balise de détresse OOX-09/HL, rarement : gardez-la.\nAttention : les plus grosses Gueules d'acier des mers sont niveau 50 : attirez-les une par une.",
		["The bloodmages"] = "Les mages de sang",
		["The crates of {item:8684} lie around the abandoned Horde camp at {area:351}, among the oozes."] = "Les caisses de {item:8684} se trouvent autour du camp abandonné de la Horde à {area:351}, parmi les limons.",
		["The five quests share the same parts: gather them all in one sweep. West of the road the {npc:5982} vultures, Starving Snickerfangs, Scorpok Stingers and Deatheye basilisks share the hills.\nEast of the road the Ashmane boars and Grunters root on the slopes beside the Redstone basilisks. Stay away from the level 52 Helboars further south.\nCareful: Scorpok Stingers (50-51) use {spell:5416}; {npc:8301} adds Knockdown. Pull the Stingers one at a time."] = "Les cinq quêtes demandent les mêmes morceaux : ramassez-les tous en un seul passage. À l'ouest de la route, les vautours {npc:5982}, les Raillecrocs affamées, les Aiguillonneurs scorpok et les basilics Deatheye se partagent les collines.\nÀ l'est de la route, les sangliers Ashmane et les Grogneurs fouillent les pentes à côté des basilics Redstone. Restez à l'écart des Sangliers infernaux de niveau 52 plus au sud.\nAttention : les Aiguillonneurs scorpok (50-51) utilisent {spell:5416} ; {npc:8301} y ajoute Renversement. Attirez les Aiguillonneurs un par un.",
		["The ghostly orc stands by the road where the swamp meets the canyon into the {zone:1419}. Listen to his story."] = "L'orc fantomatique se tient près de la route, là où le marais rejoint le canyon qui mène aux {zone:1419}. Écoutez son histoire.",
		["The secret lies on the {area:307}, above the beach."] = "Le Secret de Rin'ji se trouve sur {area:307}, au-dessus de la plage.",
		["Their follow-ups ask for the same parts again for a buff item and pay no experience: leave them."] = "Leurs quêtes suivantes redemandent les mêmes morceaux pour un objet d'amélioration et ne rapportent pas d'expérience : laissez-les.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:7977} is a level 48 elite: most classes solo it at level 50, but you may need help. Skip it if you are alone: the route has you grind the XP back.\n{npc:7977} walks the shore below the {area:307}, from the arrow south to about 75,66 and north to about 82,52: if she isn't at the arrow, follow the shore."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {npc:7977} est une élite de niveau 48 : la plupart des classes la tuent seules au niveau 50, mais vous aurez peut-être besoin d'aide. Passez-la si vous êtes seul : la route vous fait regagner cette expérience en tuant des monstres.\n{npc:7977} arpente le rivage au pied de {area:307}, de la flèche vers le sud jusqu'à environ 75,66 et vers le nord jusqu'à environ 82,52 : si elle n'est pas à la flèche, suivez le rivage.",
		["To {area:75}"] = "Vers {area:75}",
		["Underwater"] = "Sous l'eau",
		["West of the island, the Vilebranch scalpers hold the temples of {area:1884} and {area:1917}. Slagtree's tools lie at one of the temples.\nThe Silvermane Stalkers, Savage Owlbeasts and Razorbeak Skylords share the hills between the temples and {area:351}. Use the {item:9618} on the owlbeasts you kill. The Skylords also drop Long Elegant Feathers: keep ten for {npc:14738}'s second message.\nCareful: Silvermane Stalkers are level 47-48 and stay stealthed while out of combat. Up close they use {spell:7367}. When a {npc:2925} falls to 50% health or lower, it calls for help from anything within 25 yd."] = "À l'ouest de l'île, les scalpeurs Vilebranch tiennent les temples de {area:1884} et de {area:1917}. Les outils de Slagtree se trouvent près de l'un des temples.\nLes Traqueurs Crins-d'argent, les Chouettards sauvages et les Seigneurs du ciel Bec-rasoir se partagent les collines entre les temples et {area:351}. Utilisez le {item:9618} sur les chouettards que vous tuez. Les Seigneurs du ciel lâchent aussi des Longues plumes élégantes : gardez-en dix pour le second message de {npc:14738}.\nAttention : les Traqueurs Crins-d'argent sont de niveau 47-48 et restent camouflés hors combat. De près, ils utilisent {spell:7367}. Quand un {npc:2925} tombe à 50 % de vie ou moins, il appelle à l'aide tout ce qui se trouve à moins de 25 m.",
		["for {npc:6986} in {zone:1454}, around level 50"] = "pour {npc:6986} à {zone:1454}, vers le niveau 50",
		["for {npc:7623} in {area:75}, after the {zone:1419}"] = "pour {npc:7623} à {area:75}, après les {zone:1419}",
		["for {npc:7825} in the {zone:1458}, around level 50"] = "pour {npc:7825} à {zone:1458}, vers le niveau 50",
		["grind on {npc:2505}"] = "tuez en boucle : {npc:2505}",
		["{area:1440}: kill these as you meet them"] = "{area:1440} : tuez-les au passage",
		["{area:1446} flight master"] = "Maître de vol de {area:1446}",
		["{area:1917}: kill these as you meet them"] = "{area:1917} : tuez-les au passage",
		["{area:307}: kill these as you meet them"] = "{area:307} : tuez-les au passage",
		["{area:3317} flight master"] = "Maître de vol de {area:3317}",
		["{area:348} well"] = "Puits de {area:348}",
		["{area:355}: kill these as you meet them"] = "{area:355} : tuez-les au passage",
		["{item:8704}, a rare drop"] = "{item:8704}, butin rare",
		["{npc:14731}'s lunch"] = "Le repas de {npc:14731}",
		["{npc:14731}, inside"] = "{npc:14731}, à l'intérieur",
		["{npc:14736} stands up on top of the inn, above {npc:14731}: go up, the arrow cannot tell the levels apart."] = "{npc:14736} se tient sur le toit de l'auberge, au-dessus de {npc:14731} : montez, la flèche ne distingue pas les niveaux.",
		["{npc:14757}, at the top of {area:354}"] = "{npc:14757}, au sommet de {area:354}",
		["{npc:7643}'s The {npc:950} is a level 55 quest: leave it."] = "La quête {npc:950} de {npc:7643} est une quête de niveau 55 : laissez-la.",
		["{npc:7801}'s camp"] = "Camp de {npc:7801}",
		["{object:2068}, on the beaches"] = "{object:2068}, sur les plages",
		["{quest:7849}, {quest:7845} and {quest:7850} are group quests: they send you into {area:354}, whose trolls are elite (46-50). Take them with a group of three or more; skip them if you are alone, the route has you grind the experience back.\n{npc:14736} stands up on top of the inn, above {npc:14731}: go up, the arrow cannot tell the levels apart."] = "{quest:7849}, {quest:7845} et {quest:7850} sont des quêtes de groupe : elles vous envoient à {area:354}, dont les trolls sont élites (46-50). Prenez-les avec un groupe de trois ou plus ; passez-les si vous êtes seul, la route vous fait regagner cette expérience en tuant des monstres.\n{npc:14736} se tient sur le toit de l'auberge, au-dessus de {npc:14731} : montez, la flèche ne distingue pas les niveaux.",
} end)()
t.guides["forever/horde/40-50/06-azshara"] = (function() return {
		["\"Sea Wolf\" MacKinley, on the top floor: Stoley's shipment from {zone:1446}"] = "« Loup de mer » MacKinley, au dernier étage : la cargaison de Stoley venue de {zone:1446}",
		["Back to {area:1099}"] = "Retour à {area:1099}",
		["Back to {npc:11548} at the shrine; stay west of the {area:3137} guards."] = "Retournez voir {npc:11548} au sanctuaire ; restez à l'ouest des gardes de {area:3137}.",
		["Back to {object:3202}"] = "Retour à {object:3202}",
		["Below ground"] = "Sous terre",
		["Fly to {area:1099}"] = "Prendre un vol pour {area:1099}",
		["Fly to {area:1637}"] = "Prendre un vol pour {area:1637}",
		["Fly to {area:1638}"] = "Prendre un vol pour {area:1638}",
		["Fly to {area:35}"] = "Prendre un vol pour {area:35}",
		["Fly to {area:976}"] = "Prendre un vol pour {area:976}",
		["Fly to {object:3202}"] = "Prendre un vol pour {object:3202}",
		["Fly to {zone:1456}; it is on the way to {area:1099}. No flight path there yet? Fly to {area:378} and ride west through {zone:1412}. Hamuul and Magatha are on the {area:1639}; Druids and Paladins train here ({npc:3033}, {npc:246344})."] = "Volez jusqu'aux {zone:1456} ; c'est sur le chemin du {area:1099}. Pas encore de trajet aérien ? Volez jusqu'au {area:378} et allez vers l'ouest à travers {zone:1412}. Hamuul et Magatha sont sur la {area:1639} ; les Druides et les Paladins s'entraînent ici ({npc:3033}, {npc:246344}).",
		["Follow the road north to {area:1237}, the Horde camp."] = "Suivez la route vers le nord jusqu'à {area:1237}, le camp de la Horde.",
		["Frayfeather Hippogryphs"] = "Hippogryphes Aigreplume",
		["Hippogryph nests"] = "Nids d'hippogryphes",
		["Keep {quest:3444}: {npc:7771}'s chest is opened on a later visit."] = "Gardez {quest:3444} : le coffre de {npc:7771} s'ouvre lors d'une visite ultérieure.",
		["Northspring harpies"] = "Harpies Northspring",
		["On the way through {zone:1454} to the flight master, step into the Drag: {npc:7010} takes the insect report from {zone:1446}."] = "En traversant {zone:1454} vers le maître de vol, passez par la Herse : {npc:7010} prend le rapport sur les insectes de {zone:1446}.",
		["Pestlezugg's samples come from {zone:1449}."] = "Les échantillons de Pestlezugg viennent de {zone:1449}.",
		["Rage Scar yetis"] = "Yétis Griffe féroce",
		["Ride east along the road out of Splintertree. {npc:11548} waits at the {area:1235} just off the road, a few steps west of the Alliance's {area:3137}: come in from the west and keep clear of the Azshara Sentinels and Jarrodenus (elite)."] = "Chevauchez vers l'est sur la route en quittant Bois-brisé. {npc:11548} attend au {area:1235}, juste à côté de la route, à quelques pas à l'ouest de la {area:3137} de l'Alliance : arrivez par l'ouest et évitez les Sentinelles d'Azshara ({npc:11276}) et Jarrodenus (élite).",
		["Ride into {zone:1447}"] = "Entrer en {zone:1447}",
		["Ride south along the road to the {area:1938}; {npc:7771} camps beside it. From here the road west leads down into {zone:1449}, where the next guide starts."] = "Suivez la route vers le sud jusqu'à {area:1938} ; {npc:7771} campe à côté. De là, la route vers l'ouest descend dans {zone:1449}, où commence le guide suivant.",
		["South of Booty Bay, three Bloodsail ships lie off the {area:43}: {npc:2550}, {npc:2548} and {npc:2546} each stand on a deck with their crews. Swim out and work from ship to ship."] = "Au sud de Baie-du-Butin, trois navires de la Voile sanglante mouillent au large du {area:43} : {npc:2550}, {npc:2548} et {npc:2546} se tiennent chacun sur un pont avec leur équipage. Nagez jusqu'à eux et passez d'un navire à l'autre.",
		["Sprite Darters"] = "Fées fléchetteuses",
		["The Bloodsail ships"] = "Les navires de la Voile sanglante",
		["The Droffers' shop is a few steps further into the Drag."] = "La boutique des Droffers est à quelques pas plus loin dans la Herse.",
		["The Highborne ghosts haunt the ruins just north of the shrine; the Haldarr satyrs camp a little further north."] = "Les fantômes bien-nés hantent les ruines juste au nord du sanctuaire ; les satyres Haldarr campent un peu plus au nord.",
		["The Northspring harpies nest on the ridges in the far north-west, past the giants' hills. The Windcallers heal, so kill them first and pull one at a time."] = "Les harpies Sourcenord nichent sur les crêtes à l'extrême nord-ouest, au-delà des collines des géants. Les Mandevents soignent : tuez-les en premier et attirez-les un par un.",
		["The flight from {area:75} lands on {area:35}'s upper deck. {npc:7406} has his workshop on the upper ring of the bay."] = "Le vol depuis {area:75} se pose sur le pont supérieur de {area:35}. {npc:7406} a son atelier sur le cercle supérieur de la baie.",
		["The flight lands at {area:117}; {npc:2497} stands by the {object:2076}."] = "Le vol se pose au {area:117} ; {npc:2497} se tient près du {object:2076}.",
		["The hippogryph nests are on the hills to the south, around the {area:2522}; each holds an egg for the {object:142071}."] = "Les nids d'hippogryphes se trouvent sur les collines au sud, autour des {area:2522} ; chacun contient un œuf pour l'{object:142071}.",
		["The {object:142071}"] = "Le {object:142071}",
		["The {object:142071}, in the middle of town"] = "L'{object:142071}, au centre de la ville",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:818} (level 47 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back.\nCareful: Two elite caster guards, around level 45, stand with {npc:818} and join the fight together with him."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {npc:818} (élite de niveau 47) demande un groupe de 2. Passez-le si vous êtes seul : la route vous fait regagner cette expérience en tuant des monstres.\nAttention : deux gardes élites lanceurs de sorts, autour du niveau 45, se tiennent avec {npc:818} et se joignent au combat avec lui.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {quest:8552} needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {quest:8552} demande un groupe de 2. Passez-la si vous êtes seul : la route vous fait regagner cette expérience en tuant des monstres.",
		["Wandering Forest Walkers"] = "Marcheurs des bois errants",
		["Zeppelin to {zone:1454}"] = "Zeppelin pour {zone:1454}",
		["{area:1099} flight master"] = "Maître de vol de {area:1099}",
		["{area:1236}: kill these as you meet them"] = "{area:1236} : tuez-les au passage",
		["{area:1237} flight master"] = "Maître de vol de {area:1237}",
		["{area:35} flight master"] = "Maître de vol de {area:35}",
		["{area:75} flight master"] = "Maître de vol de {area:75}",
		["{item:18904}, on the Wave and Deep Striders in the water"] = "{item:18904}, sur les Marcheurs des vagues et des profondeurs dans l'eau",
		["{item:18958}, from the Sea Sprays"] = "{item:18958}, sur les Embruns",
		["{npc:2487}, on the balcony of the same building"] = "{npc:2487}, sur le balcon du même bâtiment",
		["{npc:2491}, in the inn"] = "{npc:2491}, dans l'auberge",
		["{npc:5594}, inside"] = "{npc:5594}, à l'intérieur",
		["{npc:5769}, on the {area:1639}"] = "{npc:5769}, sur la {area:1639}",
		["{npc:6117} walks around {area:1235}: look inside the circle on the map"] = "{npc:6117} se promène autour de {area:1235} : cherchez dans le cercle sur la carte",
		["{npc:6746}, at the inn: for Hamuul"] = "{npc:6746}, à l'auberge : pour Hamuul",
		["{npc:6986}, the Drag"] = "{npc:6986}, la Herse",
		["{npc:7010}, the Drag"] = "{npc:7010}, la Herse",
		["{npc:7406}, inside"] = "{npc:7406}, à l'intérieur",
		["{npc:7776}: the bears are in {zone:1448}"] = "{npc:7776} : les ours sont à {zone:1448}",
		["{npc:7854}, inside"] = "{npc:7854}, à l'intérieur",
		["{npc:7876}, beside the wind rider master"] = "{npc:7876}, à côté du maître des coursiers du vent",
		["{npc:8659}, the {object:172960}"] = "{npc:8659}, {object:172960}",
		["{quest:3761} is gathered in the next guide."] = "{quest:3761} se récolte dans le guide suivant.",
		["{quest:7738}, a rare drop"] = "{quest:7738}, butin rare",
		["{zone:1454} flight master"] = "Maître de vol d'{zone:1454}",
		["{zone:1456} flight master"] = "Maître de vol des {zone:1456}",
} end)()
t.guides["forever/horde/50-60/01-un-goro-crater"] = (function() return {
		["Back a few steps west to Felstone Farm, the first farm along the road; {npc:10778} waits in the house."] = "Revenez quelques pas à l'ouest jusqu'à la ferme Felstone, la première ferme le long de la route ; {npc:10778} attend dans la maison.",
		["Back north-east to {area:251}."] = "Retournez au nord-est à la {area:251}.",
		["Back to {area:976}"] = "Retour à {area:976}",
		["Below ground"] = "Sous terre",
		["Boat to {area:16727}"] = "Bateau pour {area:16727}",
		["Bridge into {area:254}"] = "Pont vers le {area:254}",
		["Careful: Gorishi Workers may call for help within 25 yd when below 45% health; silithids cast {spell:8137} and Tunnelers and the Hive Guard use {spell:14120}."] = "Attention : les Ouvriers Gorishi peuvent appeler à l'aide à moins de 25 m sous 45 % de vie ; les silithides lancent {spell:8137}, et les Tunneliers et le Garde de la ruche utilisent {spell:14120}.",
		["Careful: Gorishi Workers that drop below 45% health have a 50% chance to call for help from allies within 25 yd. The Hive Guards (54) and the Queen stand inside the hive: work the Workers and Wasps outside it."] = "Attention : les Ouvriers Gorishi qui passent sous 45 % de vie ont 50 % de chances d'appeler à l'aide leurs alliés à moins de 25 m. Les Gardes de la ruche (54) et la Reine se tiennent dans la ruche : occupez-vous des Ouvriers et des Guêpes à l'extérieur.",
		["Careful: There are many ravasaurs roaming the area, so you can easily pull several at the same time."] = "Attention : de nombreux ravasaures parcourent la zone, il est donc facile d'en attirer plusieurs à la fois.",
		["Cross the south of the crater to the pylon on the western cliffs."] = "Traversez le sud du cratère jusqu'au pylône sur les falaises de l'ouest.",
		["Eastern Pylon"] = "Pylône est",
		["Fly to {area:1497}"] = "Prendre un vol pour {area:1497}",
		["Fly to {area:1637} and train before the boat to {area:16727}: the {zone:1458} stop later in this guide has no Hunter or Shaman trainer."] = "Volez jusqu'à {area:1637} et entraînez-vous avant le bateau pour {area:16727} : l'arrêt à {zone:1458}, plus tard dans ce guide, n'a ni maître des chasseurs ni maître des chamans.",
		["Follow the cliffs south to {quest:3821}, the Firegut ogres' hill. {npc:9136}'s remains lie at its foot."] = "Longez les falaises vers le sud jusqu'au {quest:3821}, la colline des ogres Brûlentrailles. Les restes de {npc:9136} gisent à son pied.",
		["From here on pick up every {npc:271301} (blue, green, red, yellow) and every {quest:3761} pile you pass: 20 for Hamuul, and 5 more for Pestlezugg if you carry {quest:4496}."] = "Dès maintenant, ramassez chaque {npc:271301} (bleu, vert, rouge, jaune) et chaque tas de {quest:3761} sur votre route : 20 pour Hamuul, et 5 de plus pour Pestlezugg si vous avez {quest:4496}.",
		["From the {area:152}, follow the road east into the {zone:1422}. The Scarlet Crusade's tents stand just past Felstone Farm, between {area:199} and {area:200}. Torch the command tent with the {object:176092} and plant the Scourge banner. Careful: the Scarlets around the tents reach 54 and the Invokers cast: come in from the side nearest the command tent and leave the others be."] = "Depuis la {area:152}, suivez la route vers l'est jusqu'aux {zone:1422}. Les tentes de la Croisade écarlate se dressent juste après la ferme Felstone, entre {area:199} et {area:200}. Incendiez la tente de commandement avec les {object:176092} et plantez la bannière du Fléau. Attention : les Écarlates autour des tentes vont jusqu'au niveau 54 et les Invocateurs lancent des sorts : arrivez par le côté le plus proche de la tente de commandement et laissez les autres tranquilles.",
		["From the {area:1938} ride west to the long ramp that winds down into {zone:1449}, then follow the crater's north wall to {area:541}, a camp in the cliff caves. Everyone here is neutral."] = "Depuis le {area:1938}, chevauchez vers l'ouest jusqu'à la longue rampe qui descend dans le {zone:1449}, puis longez la paroi nord du cratère jusqu'au {area:541}, un camp dans les grottes de la falaise. Tout le monde ici est neutre.",
		["Gorillas"] = "Gorilles",
		["Into the {zone:1427}"] = "Vers la {zone:1427}",
		["Into {zone:1449}"] = "Vers le {zone:1449}",
		["Keep the parcel: {npc:10781} is in the {zone:1458}. The next guide starts with {npc:10739} by the {area:202}, south-east of here."] = "Gardez le colis : le {npc:10781} est à {zone:1458}. Le guide suivant commence avec {npc:10739} près de {area:202}, au sud-est d'ici.",
		["Keep {npc:10267}'s letter: {quest:4808} is in {area:2255}, {zone:1452}."] = "Gardez la Lettre de {npc:10267} : {quest:4808} est à {area:2255}, {zone:1452}.",
		["Keep {npc:9118}'s {quest:4147} and {npc:8737}'s letter for later guides."] = "Gardez la quête {quest:4147} de {npc:9118} et la lettre de {npc:8737} pour des guides ultérieurs.",
		["Lar'korwi Mates"] = "Compagnes de Lar'korwi ({npc:9683})",
		["Lashers and Threshers"] = "Flagellants et Batteurs",
		["Leave the {zone:1458} and ride east along the road through {zone:1420} to the {area:152}, the Forsaken fort on the border."] = "Quittez {zone:1458} et suivez la route vers l'est à travers les {zone:1420} jusqu'à la {area:152}, le fort réprouvé de la frontière.",
		["Leave {zone:2548} on foot to the north-west, north of {area:16685}, into the {zone:1418}."] = "Quittez {zone:2548} à pied vers le nord-ouest, au nord de {area:16685}, pour entrer dans les {zone:1418}.",
		["Listen to {npc:8479}'s story once more."] = "Écoutez encore une fois l'histoire de {npc:8479}.",
		["North of Torwa, a dead Threshadon lies by the water. The {item:280417} lies on the ground a short ride west of {npc:9619}'s camp."] = "Au nord de Torwa, un Threshadon mort gît près de l'eau. Le {item:280417} se trouve au sol à courte distance à l'ouest du camp de {npc:9619}.",
		["Northern Pylon"] = "Pylône nord",
		["Only from level 53: her next errand is {quest:3822} (54), who walks the caves of {quest:3821} among ogres of 50-53."] = "Seulement à partir du niveau 53 : sa mission suivante est {quest:3822} (54), qui arpente les grottes du {quest:3821} parmi des ogres de niveau 50-53.",
		["Out of the refuge"] = "Hors du refuge",
		["Power Crystals and soil"] = "Cristaux de puissance et terre",
		["Ride down the east side of the crater to the pylon on the eastern cliffs."] = "Descendez le côté est du cratère jusqu'au pylône sur les falaises de l'est.",
		["Ride north along the east side. Bloodpetal Lashers and Threshers fill the jungle."] = "Allez vers le nord le long du côté est. Les Flagellants et les Batteurs Pétale-de-sang remplissent la jungle.",
		["Ride south-west to {area:537}, the volcano in the middle of the crater. Bloodpetal Flayers grow around its foot.\nSouth of the hot springs, Dinosaur Bones lie on the ground among the Stegodons and drop from the Diemetradons nearby, which also carry the scales {npc:9998} wants. Careful: the Stegodons are elites (52-53): pick the bones up around them, don't pull them; the Elder Diemetradons are 53-55, take the smaller ones. Ravasaurs hunt in packs in the south-west: their claws are for {npc:8659}, and now and then one carries a Mangled Journal (a rare drop: take its quest only if you get one). Avoid Gruff, a level 57 Stegodon.\nRide south-west along the western cliffs. Bloodpetal Trappers grow in the jungle there. Careful: the biggest Trappers are 53: pull them one at a time."] = "Allez vers le sud-ouest jusqu'à {area:537}, le volcan au milieu du cratère. Les Écorcheurs Pétale-de-sang poussent à son pied.\nAu sud des sources chaudes, des Os de dinosaure jonchent le sol parmi les stégodons et tombent des dimeurtrodons tout proches, qui portent aussi les écailles que veut {npc:9998}. Attention : les stégodons sont élites (52-53) : ramassez les os autour d'eux sans les attirer ; les Anciens dimeurtrodons sont de niveau 53-55, prenez les plus petits. Les ravasaures chassent en meute au sud-ouest : leurs griffes sont pour {npc:8659}, et de temps en temps l'un d'eux porte un Journal abîmé (butin rare : ne prenez sa quête que si vous en obtenez un). Évitez Gruff, un stégodon de niveau 57.\nAllez vers le sud-ouest le long des falaises de l'ouest. Les Trappeurs Pétale-de-sang poussent dans la jungle. Attention : les plus gros Trappeurs sont de niveau 53 : attirez-les un par un.",
		["Scarlet forward camp"] = "Camp avancé écarlate",
		["Sentry Braziers"] = "Braseros de sentinelle",
		["Stegodons and ravasaurs"] = "Stégodons et ravasaures",
		["Take a {object:176092} from the crate next to Derrington for {quest:5096}, done on the way back. Equip the {quest:5405}: Scourgestones only drop while you wear it."] = "Prenez une {object:176092} dans la caisse à côté de Derrington pour {quest:5096}, à faire au retour. Équipez la {quest:5405} : les Pierres du Fléau ne tombent que si vous la portez.",
		["The Anvilrage dwarves of your {area:1584} run: {npc:9077}, in {area:340}."] = "Les nains Enclume-ardente de votre expédition dans {area:1584} : {npc:9077}, à {area:340}.",
		["The Lar'korwi Mates prowl the jungle north-west of {npc:9619}."] = "Les Compagnes de Lar'korwi ({npc:9683}) rôdent dans la jungle au nord-ouest de {npc:9619}.",
		["The crystal clusters stand all over the crater, many around {area:537}. Take a few extra of each colour for the pylons."] = "Les amas de cristaux se dressent partout dans le cratère, beaucoup autour de {area:537}. Prenez-en quelques-uns de plus de chaque couleur pour les pylônes.",
		["The expedition's crate sits at an abandoned camp in the eastern jungle."] = "La caisse de l'expédition se trouve dans un camp abandonné de la jungle de l'est.",
		["The expedition's lost equipment lies in the south-west jungle."] = "L'équipement perdu de l'expédition se trouve dans la jungle du sud-ouest.",
		["The gorillas live on the north-east plateau: {npc:9619} wants two pelts of each kind, and the Thunderers (52-53) are the biggest. Stay out of the deepest cave: {npc:9622} lives there."] = "Les gorilles vivent sur le plateau du nord-est : {npc:9619} veut deux peaux de chaque sorte, et les Tonnerres (52-53) sont les plus gros. N'entrez pas dans la grotte la plus profonde : {npc:9622} y vit.",
		["The hearth lands in {area:976}: {npc:11758} takes the {area:983} and Tran'rek Thistleshrub Valley, both done on the way into the crater."] = "La pierre de foyer vous ramène à {area:976} : {npc:11758} prend l'{area:983} et Tran'rek la vallée des Chardonniers, toutes deux faites en route vers le cratère.",
		["The mountain lets you out beside {area:252}, full of 55-57 orcs. Follow the road east along the northern cliffs to the Horde camp at {area:251}."] = "La montagne débouche près du {area:252}, plein d'orcs de niveau 55-57. Suivez la route vers l'est le long des falaises du nord jusqu'au camp de la Horde à la {area:251}.",
		["The pylon stands on the slope east of the refuge."] = "Le pylône se dresse sur la pente à l'est du refuge.",
		["The raft lies on the shore of the south-eastern lake; the small pack sits in the water beside it."] = "Le radeau est sur la rive du lac du sud-est ; le petit paquetage est dans l'eau à côté.",
		["The tar pits lie just south of the refuge. Tar Beasts, Lurkers and Creepers drop the {item:11834}. Careful: the Lurkers reach 54 and the Tar Lords stand among them: take the Tar Beasts (50-51) and Creepers (51-52)."] = "Les fosses de goudron se trouvent juste au sud du refuge. Les Bêtes du goudron, les Rôdeurs et les Rampants lâchent le {item:11834}. Attention : les Rôdeurs vont jusqu'au niveau 54 et les Seigneurs du goudron se tiennent parmi eux : prenez les Bêtes du goudron (50-51) et les Rampants (51-52).",
		["The {npc:9167} fly over the western cliffs around the pylon. Careful: the biggest are 54: pull them one at a time."] = "Les {npc:9167} survolent les falaises de l'ouest autour du pylône. Attention : les plus gros sont de niveau 54 : attirez-les un par un.",
		["To {area:976}"] = "Vers {area:976}",
		["Underwater"] = "Sous l'eau",
		["Upstairs"] = "À l'étage",
		["Use the Mangled Journal to start it"] = "Utilisez Un journal abîmé pour la commencer",
		["Use the scale to start {quest:87494}, for {npc:9619}"] = "Utilisez l'écaille pour commencer {quest:87494}, pour {npc:9619}",
		["Western Pylon"] = "Pylône ouest",
		["the wooden sign beside {npc:9997}, by the flight master: the {npc:9167} (51-54) come on the pylon loop"] = "le panneau de bois à côté de {npc:9997}, près du maître de vol : les {npc:9167} (51-54) viennent sur la boucle des pylônes",
		["{area:1584} is a dungeon for a group of five from about level 48, the biggest in the mountain: its Anvilrage dwarves are this quest's, and you need not go further in than they are. Its portal is deep inside the mountain, down the chain walkways from the bridge.\nInside: the Anvilrage Guardsmen, Wardens and Footmen. Then back out of the portal and on through the mountain's southern exit to the {zone:1428}."] = "{area:1584} est un donjon pour un groupe de cinq à partir du niveau 48 environ, le plus grand de la montagne : ses nains Enclume-ardente sont ceux de cette quête, et vous n'avez pas besoin d'aller plus loin qu'eux. Son portail se trouve au cœur de la montagne, en descendant les passerelles de chaînes depuis le pont.\nÀ l'intérieur : les Gardes, les Gardiens et les Fantassins Enclume-ardente. Ressortez ensuite par le portail et continuez par la sortie sud de la montagne jusqu'aux {zone:1428}.",
		["{area:250}: kill these as you meet them"] = "{area:250} : tuez-les au passage",
		["{area:340} flight master"] = "Maître de vol de {area:340}",
		["{area:340} is built into the cliffs on the {zone:1418}' west edge."] = "{area:340} est construit dans les falaises du bord ouest de {zone:1418}.",
		["{area:538}: kill these as you meet them"] = "{area:538} : tuez-les au passage",
		["{item:10575}, from the hoard"] = "{item:10575}, dans le trésor",
		["{item:11116}, a rare drop"] = "{item:11116}, butin rare",
		["{item:280459}, a rare drop from the ravasaurs and Diemetradons"] = "{item:280459}, butin rare des ravasaures et des dimeurtrodons",
		["{npc:10879}, the {object:36078}, beside the bat master"] = "{npc:10879}, {object:36078}, près du maître des chauves-souris",
		["{npc:5204}, near Cuely in the Apothecarium"] = "{npc:5204}, près de Cuely dans l'Apothicarium",
		["{npc:5594}, inside"] = "{npc:5594}, à l'intérieur",
		["{npc:7825} stands in the {object:36082}."] = "{npc:7825} se tient dans le {object:36082}.",
		["{npc:8390}, the Apothecarium: the vials fill in {zone:1447} later"] = "{npc:8390}, l'Apothicarium : les fioles se remplissent plus tard en {zone:1447}",
		["{npc:9117}, at the back of the cave; below ground"] = "{npc:9117}, au fond de la grotte ; sous terre",
		["{npc:9117}, below ground"] = "{npc:9117}, sous terre",
		["{npc:9166} (50-52) fly over the east of the crater, from the slopes below the refuge southward; their webbed scales are for {npc:9998}, and {npc:9997}'s sign wants ten of them. Leave the {npc:9167} over the west for the pylon loop."] = "Les {npc:9166} (50-52) survolent l'est du cratère, des pentes sous le refuge jusqu'au sud ; leurs écailles palmées sont pour {npc:9998}, et le panneau de {npc:9997} en veut dix. Laissez les {npc:9167} de l'ouest pour la boucle des pylônes.",
		["{npc:9167}: kill these as you meet them"] = "{npc:9167} : tuez-les au passage",
		["{npc:9618}, just outside"] = "{npc:9618}, juste dehors",
		["{npc:9619} camps in the south-east corner of the crater."] = "{npc:9619} campe dans le coin sud-est du cratère.",
		["{npc:9619}'s camp is in the south-east corner, a short ride from the {area:1942}."] = "Le camp de {npc:9619} est dans le coin sud-est, à courte distance des {area:1942}.",
		["{npc:9619}: {quest:4289}, the gorillas of the north-east plateau on the pylon loop"] = "{npc:9619} : {quest:4289}, les gorilles du plateau nord-est sur la boucle des pylônes",
		["{npc:9619}: {quest:87492}, a short ride west of his camp"] = "{npc:9619} : {quest:87492}, à courte distance à l'ouest de son camp",
		["{npc:9619}: {quest:87494}, if the scale dropped"] = "{npc:9619} : {quest:87494}, si l'écaille est tombée",
		["{npc:9623} then wants a {item:10561}, an {skill:202} item. Skip it unless you have one."] = "{npc:9623} veut ensuite une {item:10561}, un objet d'{skill:202}. Passez cette quête sauf si vous en avez une.",
		["{npc:9623}, the robot on the plateau; below ground"] = "{npc:9623}, le robot sur le plateau ; sous terre",
		["{npc:9706}, by the dock: for {quest:4324} at {area:251}, later in this guide"] = "{npc:9706}, près du quai : pour {quest:4324} à {area:251}, plus loin dans ce guide",
		["{npc:9997}, beside the flight master"] = "{npc:9997}, à côté du maître de vol",
		["{npc:9998}, at the entrance"] = "{npc:9998}, à l'entrée",
		["{npc:9998}, at the refuge entrance"] = "{npc:9998}, à l'entrée du refuge",
		["{object:175894}, beside the house; inside"] = "{object:175894}, à côté de la maison ; à l'intérieur",
		["{quest:3453} lies on the ground at {npc:8479}'s feet; {quest:3462} stands beside him."] = "{quest:3453} se trouve par terre aux pieds de {npc:8479} ; {quest:3462} se tient à côté de lui.",
		["{quest:3822} walks the caves and mine tunnels of {quest:3821}; if he isn't home, clear the ogres around the entrances until he comes back."] = "{quest:3822} arpente les grottes et galeries de mine du {quest:3821} ; s'il est absent, tuez les ogres autour des entrées jusqu'à son retour.",
		["{quest:4081}: the Anvilrage dwarves, inside"] = "{quest:4081} : les nains Enclume-ardente, à l'intérieur",
		["{zone:1449}: kill these as you meet them"] = "{zone:1449} : tuez-les au passage",
		["{zone:1454} flight master"] = "Maître de vol d'{zone:1454}",
} end)()
t.guides["forever/horde/50-60/02-felwood"] = (function() return {
		["Back north to {area:1763}. Fill Greta's canteen at the corrupted moonwell in the middle of the southern camp."] = "Retournez au nord jusqu'à {area:1763}. Remplissez la gourde de Greta au puits de lune corrompu au milieu du camp sud.",
		["Back north to {npc:8420} with the rune, then south-west along the road."] = "Retournez au nord auprès de {npc:8420} avec la rune, puis suivez la route vers le sud-ouest.",
		["Back north-west to {npc:8420}."] = "Retournez au nord-ouest auprès de {npc:8420}.",
		["Below ground"] = "Sous terre",
		["Class trainer"] = "Maître de classe",
		["Derrington's watchtowers and Vandis' cauldron are done on a later visit: keep them."] = "Les tours de guet de Derrington et le chaudron de Vandis se font lors d'une visite ultérieure : gardez-les.",
		["Diseased Wolves"] = "Loups malades",
		["Druid trainer"] = "Maître des druides",
		["Each of the camp's three officers (53) carries a seal: {npc:247006} in the middle of the camp, {npc:247013} at its eastern end, and {npc:246991}, who walks its western half: take him on the east side of his walk, where the arrow points.\nCareful: the {npc:250023}, a level 55-57 elite, stands at the camp's western edge, close to the far end of Hawkhelm's walk: wait for Hawkhelm to come back east."] = "Chacun des trois officiers du camp (53) porte un sceau : {npc:247006} au centre du camp, {npc:247013} à son extrémité est, et {npc:246991}, qui patrouille sa moitié ouest : affrontez-le du côté est de sa ronde, là où pointe la Flèche.\nAttention : le {npc:250023}, un élite de niveau 55-57, se tient à la lisière ouest du camp, près du bout de la ronde de Hawkhelm : attendez que Hawkhelm revienne vers l'est.",
		["East of Bloodvenom Post, the cratered vale where the Entropic Beasts and Horrors roam. Kill two of each, then walk to each of the three fel-water craters."] = "À l'est du Poste de la Vénéneuse, le val criblé de cratères où errent les Bêtes d'entropie et les Horreurs. Tuez-en deux de chaque, puis allez à chacun des trois cratères d'eau gangrenée.",
		["Fly to {area:1237}"] = "Prendre un vol pour {area:1237}",
		["Fly to {area:431}"] = "Prendre un vol pour {area:431}",
		["From the {area:152}, follow the road east into the {zone:1422}. The Scarlet Crusade's tents stand just past Felstone Farm, between {area:199} and {area:200}. Torch the command tent with the {object:176092} and plant the Scourge banner. Careful: the Scarlets around the tents reach 54 and the Invokers cast: come in from the side nearest the command tent and leave the others be."] = "Depuis la {area:152}, suivez la route vers l'est jusqu'aux {zone:1422}. Les tentes de la Croisade écarlate se dressent juste après la ferme Felstone, entre {area:199} et {area:200}. Incendiez la tente de commandement avec les {object:176092} et plantez la bannière du Fléau. Attention : les Écarlates autour des tentes vont jusqu'au niveau 54 et les Invocateurs lancent des sorts : arrivez par le côté le plus proche de la tente de commandement et laissez les autres tranquilles.",
		["He camps by the {area:202}, south-east of {area:200}."] = "Il campe près du {area:202}, au sud-est de {area:200}.",
		["Inside"] = "À l'intérieur",
		["Keep {quest:8465} for {zone:1452}."] = "Gardez {quest:8465} pour {zone:1452}.",
		["Makrinni Burrowers"] = "Fouisseurs makrinni",
		["Northern crater"] = "Cratère nord",
		["On north-east across the middle of {zone:1447}: {npc:235903} camps by the road."] = "Continuez au nord-est à travers le centre d'{zone:1447} : {npc:235903} campe près de la route.",
		["Paladin trainer"] = "Maître des paladins",
		["Ride back west to {area:1237}."] = "Retournez à l'ouest jusqu'à {area:1237}.",
		["Ride east to the ruins on the coast. The four tablets lie among the ruins, guarded by Spitelash naga (52-55): pull them one at a time."] = "Chevauchez vers l'est jusqu'aux ruines sur la côte. Les quatre tablettes se trouvent parmi les ruines, gardées par des nagas Fouette-bile (52-55) : attirez-les un par un.",
		["Ride north-east to the goblin's camp on the cliffs above the {area:1227}, just north of the blood elves."] = "Chevauchez au nord-est jusqu'au camp du gobelin sur les falaises au-dessus de {area:1227}, juste au nord des elfes de sang.",
		["Ride south to the northern edge of the {area:1221}. The Spitelash Sirens and Myrmidons (50-52) there carry {npc:8420}'s rune; it doesn't drop often, so work your way along the edge until it does."] = "Allez au sud jusqu'à la lisière nord des {area:1221}. Les Sirènes et les Myrmidons Fouette-bile (50-52) qui s'y trouvent portent la rune de {npc:8420} ; elle tombe rarement, alors longez la lisière jusqu'à l'obtenir.",
		["Ride south-west past Felstone Farm and follow the road west back to the {area:152}."] = "Chevauchez vers le sud-ouest en passant la ferme des Felstone et suivez la route vers l'ouest jusqu'à {area:152}.",
		["Rimtori's camp is at the east end of the base camp. Read the {object:151286} there: on Forever the Sin'dorei Tome beside it then asks for the seals of the camp's three officers."] = "Le camp de Rimtori se trouve à l'extrémité est du camp de base. Lisez-y le {object:151286} : sur Forever, le Tome sin'dorei à côté demande ensuite les sceaux des trois officiers du camp.",
		["Scarlet forward camp"] = "Camp avancé écarlate",
		["South-west along the road: {npc:235903} takes the satyrs."] = "Suivez la route vers le sud-ouest : {npc:235903} prend les satyres.",
		["Southern crater"] = "Cratère sud",
		["Southern {area:1763}"] = "Sud de {area:1763}",
		["The Deadwood furbolg village lies just south of the Sanctuary. Every Deadwood kill also raises your {area:1769} reputation; keep the headdress feathers."] = "Le village des furbolgs Mort-bois se trouve juste au sud du Sanctuaire. Chaque Mort-bois tué augmente aussi votre réputation auprès du {area:1769} ; gardez les plumes de coiffe.",
		["The Horde camp just north of {area:1763}."] = "Le camp de la Horde juste au nord de {area:1763}.",
		["The Legashi satyrs"] = "Les satyres legashi",
		["The Makrinni Burrowers (50-51) dig in the sands just east of the ruins, on the way north-east; they and the buried caches there give up the Highborne Treasure Fragments."] = "Les Fouisseurs makrinni (50-51) creusent le sable juste à l'est des ruines, sur le chemin du nord-est ; eux et les caches enfouies là donnent les Fragments de trésor de Bien-né.",
		["The apprentice at the top of the tower sends you back down."] = "L'apprenti en haut de la tour vous renvoie en bas.",
		["The blood elves camp on the cliffs in the north-east, by the {area:1227}. {npc:8420}'s four pieces of equipment lie in the crates around the camp; the Blood Elf Arcanists carry {npc:247473}'s wand.\nCareful: a {npc:250023}, a level 55-57 elite, stands at the west edge of the camp: work the blood elves from its east side."] = "Les elfes de sang campent sur les falaises au nord-est, près de {area:1227}. Les quatre pièces d'équipement de {npc:8420} se trouvent dans les caisses autour du camp ; les Arcanistes elfes de sang portent la baguette de {npc:247473}.\nAttention : un {npc:250023}, un élite de niveau 55-57, se tient à la lisière ouest du camp : occupez-vous des elfes de sang par le côté est.",
		["The diary lies in the farmhouse, the cabinet stands inside and the outhouse is behind it. A {npc:10816} carries the outhouse key; {npc:10836} comes out when you open the outhouse and carries the cabinet key."] = "Le journal se trouve dans la ferme, le meuble est à l'intérieur et les latrines sont derrière. Un {npc:10816} porte la clé des latrines ; {npc:10836} sort quand vous ouvrez les latrines et porte la clé du meuble.",
		["The druids' camp is just past the border."] = "Le camp des druides se trouve juste après la frontière.",
		["The middle of {zone:1454}"] = "Le centre d'{zone:1454}",
		["The road ends at {npc:15395}, outside the {area:1769} tunnel in the far north-east."] = "La route se termine à {npc:15395}, devant le tunnel du {area:1769}, à l'extrême nord-est.",
		["The wolves roam the fields between Andorhal, {area:200} and the {area:202}. Finish them on the ride back east. Careful: the biggest are 54: pull them one at a time."] = "Les loups parcourent les champs entre Andorhal, {area:200} et le {area:202}. Finissez-les sur le chemin du retour vers l'est. Attention : les plus gros sont de niveau 54 : attirez-les un par un.",
		["The {area:1763} moonwell"] = "Le puits de lune de {area:1763}",
		["The {object:661778} stands just south of the vale, by the road north: its bauble starts a quest for {npc:9996} at {area:1997}."] = "La Statue de Malorne se dresse juste au sud du vallon, près de la route vers le nord : sa babiole lance une quête pour {npc:9996} au {area:1997}.",
		["Upstairs"] = "À l'étage",
		["Western crater"] = "Cratère ouest",
		["You missed this on the route's earlier visit here: it comes first now. It is quick and opens the quests after it.\nTake a {object:176092} from the crate next to Derrington for {quest:5096}."] = "Vous avez manqué ceci lors du passage précédent de l'itinéraire ici : cela passe d'abord maintenant. C'est rapide et cela ouvre les quêtes qui suivent.\nPrenez une {object:176092} dans la caisse à côté de Derrington pour {quest:5096}.",
		["Zeppelin to {zone:1454}"] = "Zeppelin pour {zone:1454}",
		["{area:1221}: kill these as you meet them"] = "{area:1221} : tuez-les au passage",
		["{area:1237} flight master"] = "Maître de vol de {area:1237}",
		["{area:200} farmhouse"] = "Ferme de {area:200}",
		["{item:246680}, from the Blood Elf Arcanists"] = "{item:246680}, sur les Arcanistes elfes de sang",
		["{item:246721}, from {npc:246991}"] = "{item:246721}, sur {npc:246991}",
		["{item:246722}, from {npc:247013}"] = "{item:246722}, sur {npc:247013}",
		["{item:246725}, from {npc:247006}"] = "{item:246725}, sur {npc:247006}",
		["{item:277958}, from the Angerclaw bears"] = "{item:277958}, sur les ours de la griffe colérique",
		["{item:277959}, from the Felpaw wolves"] = "{item:277959}, sur les loups Gangrepatte",
		["{npc:10306}: the owlbeasts are in {zone:1452}"] = "{npc:10306} : les chouettards sont à {zone:1452}",
		["{npc:10920}, beside {npc:10921}: {quest:86577}, the organs of {zone:1448}'s bears and wolves"] = "{npc:10920}, à côté de {npc:10921} : {quest:86577}, les organes des ours et des loups de {zone:1448}",
		["{npc:11554}, at the south edge of the camp"] = "{npc:11554}, à la lisière sud du camp",
		["{npc:11558} walks around here: look inside the circle on the map"] = "{npc:11558} se promène par ici : cherchez dans le cercle sur la carte",
		["{npc:235903}: {quest:86746}, the satyrs north of the blood elves' camp"] = "{npc:235903} : {quest:86746}, les satyres au nord du camp des elfes de sang",
		["{npc:246152} in {zone:1420}; {zone:1454} has no paladin trainer"] = "{npc:246152} ({zone:1420}) ; {zone:1454} n'a pas de maître des paladins",
		["{npc:247473}: {quest:91569}, a wand from the blood elves' arcanists"] = "{npc:247473} : {quest:91569}, une baguette sur les arcanistes elfes de sang",
		["{npc:3034} in {zone:1412}; {zone:1454} has no druid trainer"] = "{npc:3034} ({zone:1412}) ; {zone:1454} n'a pas de maître des druides",
		["{npc:3326}, the {object:172960}"] = "{npc:3326}, {object:172960}",
		["{npc:8576}: {quest:91531}, for {npc:4485} in {zone:1454}"] = "{npc:8576} : {quest:91531}, pour {npc:4485} à {zone:1454}",
		["{npc:8578}'s camp"] = "Le camp de {npc:8578}",
		["{npc:8587}: the tome goes to {npc:3326} in {zone:1454}"] = "{npc:8587} : le tome va à {npc:3326} à {zone:1454}",
		["{npc:8659} takes the ravasaur claws from Un'Goro; he stands in the {object:172960}, a short walk from the middle of the city."] = "{npc:8659} prend les griffes de ravasaure d'Un'Goro ; il se tient dans {object:172960}, à courte distance du centre de la ville.",
		["{npc:8659}, the {object:172960}"] = "{npc:8659}, {object:172960}",
		["{npc:9529}, on the west side of the camp"] = "{npc:9529}, à l'ouest du camp",
		["{quest:91538}: for {npc:8587} in {area:1237}"] = "{quest:91538} : pour {npc:8587} à {area:1237}",
		["{zone:1454} flight master"] = "Maître de vol d'{zone:1454}",
} end)()
t.guides["forever/horde/50-60/03-winterspring"] = (function() return {
		["Back south to {npc:7775}. Keep the elixir and don't drink it yet: it kills you, and that is how you meet Gaeriyan by {area:976} later."] = "Retournez au sud voir {npc:7775}. Gardez l'élixir et ne le buvez pas encore : il vous tue, et c'est ainsi que vous rencontrerez Gaeriyan près de {area:976} plus tard.",
		["Chillwind chimaeras"] = "Chimères Frisevent",
		["Fly to {area:1099}"] = "Volez jusqu'au {area:1099}",
		["Fly to {area:1638}"] = "Volez jusqu'à {area:1638}",
		["Fly to {area:431}"] = "Prendre un vol pour {area:431}",
		["Gregor's quests lead to other zones: keep them."] = "Les quêtes de Gregor mènent à d'autres zones : gardez-les.",
		["Ice Thistle yetis"] = "Yétis Chardon de glace",
		["Into {zone:1452}"] = "Vers {zone:1452}",
		["Linken's letter"] = "La lettre de Linken",
		["Raging Owlbeasts"] = "Chouettards enragés ({npc:7451})",
		["Ride south from the tunnel: {npc:9298} camps among the steaming pools of {area:2246}, in the west of the valley."] = "Chevauchez vers le sud depuis le tunnel : {npc:9298} campe parmi les bassins fumants des {area:2246}, à l'ouest de la vallée.",
		["The Jadefire moonwell"] = "Le puits de lune des Jadefeu",
		["The Matriarchs and Patriarchs that carry Umi's horns are 56-58: leave them for that later stop."] = "Les Matriarches et Patriarches qui portent les cornes d'Umi sont de niveau 56-58 : laissez-les pour cet arrêt ultérieur.",
		["The {item:11242} grows inside a ruined building north of {npc:7775}'s camp, east of the harpies' {area:1114}: climb in through the broken part of its wall."] = "La {item:11242} pousse dans un bâtiment en ruine au nord du camp de {npc:7775}, à l'est de {area:1114} des harpies : entrez par la partie effondrée de son mur.",
		["{area:2246}: kill these as you meet them"] = "{area:2246} : tuez-les au passage",
		["{area:2255} flight master"] = "Maître de vol de {area:2255}",
		["{area:2255} is the goblin town on the east side of the valley, past the owlbeast hills."] = "{area:2255} est la ville gobeline à l'est de la vallée, après les collines des chouettes-ours.",
		["{area:2408} flight master"] = "Maître de vol de {area:2408}",
		["{item:11243}, {npc:7775}'s reward"] = "{item:11243}, récompense de {npc:7775}",
		["{item:12565}, at the Jadefire moonwell"] = "{item:12565}, au puits de lune des Jadefeu",
		["{item:12771}: about one Winterfall furbolg in ten carries one; keep killing them until it drops"] = "{item:12771} : environ un furbolg Tombe-hiver sur dix en porte une ; continuez à les tuer jusqu'à ce qu'elle tombe",
		["{npc:10431}, inside"] = "{npc:10431}, à l'intérieur",
		["{npc:10881} and {npc:14728} stand on {area:1641}. Each of Rumstag's donations takes sixty Wool, Silk or Mageweave from your bags: hand in what you carry, skip the rest."] = "{npc:10881} et {npc:14728} se tiennent sur {area:1641}. Chaque don de Rumstag prend soixante étoffes de laine, de soie ou de tisse-mage dans vos sacs : rendez ce que vous avez, passez le reste.",
		["{npc:11556} stands right at the {zone:1452} exit of {area:1769}'s tunnel, where you come out."] = "{npc:11556} se tient à la sortie vers {zone:1452} du tunnel du {area:1769}, juste à la sortie.",
		["{npc:3033} on {area:1639}; {npc:246344}"] = "{npc:3033} sur la {area:1639} ; {npc:246344}",
		["{npc:9087} buys {item:11040} grown from your {quest:3761}. {quest:3782} wants ten, and the {item:11020} gives one try every ten minutes: take it only if you already have the grain."] = "{npc:9087} achète le {item:11040} cultivé à partir de votre {quest:3761}. {quest:3782} en demande dix, et la {item:11020} permet un essai toutes les dix minutes : ne la prenez que si vous avez déjà le grain.",
		["{npc:9529}, on the west side of the Sanctuary"] = "{npc:9529}, à l'ouest du Sanctuaire",
		["{npc:9996}'s kitten"] = "Le chaton de {npc:9996}",
		["{npc:9996}: the {quest:86612}"] = "{npc:9996} : {quest:86612}",
		["{quest:1123} waits in {zone:1450}: keep it for later."] = "{quest:1123} attend à {zone:1450} : gardez-la pour plus tard.",
		["{quest:5084} is turned in at the {object:176091} in {zone:1448}, on a later trip."] = "{quest:5084} se rend au {object:176091} en {zone:1448}, lors d'un voyage ultérieur.",
		["{quest:8471}, a rare drop from the Winterfall furbolgs"] = "{quest:8471}, un butin rare des furbolgs Tombe-hiver",
} end)()
t.guides["forever/horde/50-60/04-azshara"] = (function() return {
		["Both {item:14047} donations are handed in later in the route: save sixty {item:14047} for each if you want them."] = "Les deux dons d'{item:14047} se rendent plus loin dans le parcours : gardez soixante {item:14047} pour chacun si vous les voulez.",
		["Cleansed Water goes to the {area:2479} in {zone:1448}: keep it for later."] = "L'eau purifiée retourne à {area:2479}, à {zone:1448} : gardez-la pour plus tard.",
		["Fly to {area:1637}"] = "Prendre un vol pour {area:1637}",
		["Fly to {area:392}"] = "Prendre un vol pour {area:392}",
		["Fly to {zone:1454} and train."] = "Volez jusqu'à {zone:1454} et entraînez-vous.",
		["In the {object:172958}."] = "Dans {object:172958}.",
		["In the {object:172961}. Each donation takes sixty Wool, Silk or Mageweave from your bags: hand in what you carry, skip the rest."] = "Dans {object:172961}. Chaque don prend soixante étoffes de laine, de soie ou de tisse-mage dans vos sacs : rendez celles que vous avez sur vous, ignorez les autres.",
		["Inside"] = "À l'intérieur",
		["Into {zone:1411}"] = "Vers {zone:1411}",
		["Lady Sylvanas holds the {object:36126}."] = "Dame Sylvanas se tient dans {object:36126}.",
		["Liv's workshop is at the north end of {area:392}'s docks; {object:149036} stands inside it."] = "L'atelier de Liv Rizzlefix se trouve au bout nord des quais de {area:392} ; le {object:149036} est à l'intérieur.",
		["Only with {quest:79095} from {area:159}'s alchemy shop in your bags (the Library Books guide)"] = "Seulement avec {quest:79095} de la boutique d'alchimie de {area:159} dans vos sacs (le guide des Livres de la bibliothèque)",
		["Paladin trainer"] = "Maître des paladins",
		["Ride east out of the {zone:1458} along the road; the {area:152} guards the way into the {zone:1422}."] = "Sortez de {zone:1458} vers l'est par la route ; {area:152} garde l'accès aux {zone:1422}.",
		["Upstairs"] = "À l'étage",
		["Zeppelin to {zone:1458}"] = "Zeppelin pour {zone:1458}",
		["{area:392} flight master"] = "Maître de vol de {area:392}",
		["{npc:10778}'s farm is the first one east of the {area:152}. Jabbering Ghouls on the farm carry the other half of her charm; {npc:11075} guards the cauldron in the field.\nCareful: One or two undead usually fight alongside him, and more cauldron lords can attack after you use the cauldron."] = "La ferme de {npc:10778} est la première à l'est de {area:152}. Les Goules jacassantes de la ferme portent l'autre moitié de son porte-bonheur ; {npc:11075} garde le chaudron dans le champ.\nAttention : un ou deux morts-vivants combattent généralement à ses côtés, et d'autres seigneurs du chaudron peuvent attaquer après que vous avez utilisé le chaudron.",
		["{npc:11615}: the termites are in {area:2627}, on the next guide"] = "{npc:11615} : les termites sont à {area:2627}, dans le guide suivant",
		["{npc:15188}, {object:172957}: keep it for {zone:1451}"] = "{npc:15188}, {object:172957} : gardez-la pour {zone:1451}",
		["{npc:246344} in {zone:1456}; {zone:1454} has no paladin trainer"] = "{npc:246344} ({zone:1456}) ; {zone:1454} n'a pas de maître des paladins",
		["{npc:5901} camps on the shore just north of {area:392}."] = "{npc:5901} Waterseer campe sur le rivage, juste au nord de {area:392}.",
		["{npc:6522} stands in the {object:36073}."] = "{npc:6522} se trouve dans le {object:36073}.",
		["{npc:7010} works in the Drag."] = "{npc:7010} travaille dans la Herse.",
		["{npc:8390} and {npc:8393} work in the Apothecarium."] = "{npc:8390} et {npc:8393} travaillent dans l'Apothicarium.",
		["{npc:8393}, beside him"] = "{npc:8393}, à côté de lui",
		["{npc:8403}, nearby"] = "{npc:8403}, tout près",
		["{npc:8659}, the {object:172960}"] = "{npc:8659}, {object:172960}",
		["{quest:5050} goes back to {npc:10778} in the {zone:1422}: keep it."] = "{quest:5050} se rend à {npc:10778}, dans {zone:1422} : gardez-la.",
} end)()
t.guides["forever/horde/50-60/05-eastern-plaguelands"] = (function() return {
		["A {item:13140} dropped: the Jaedenar Enforcers, Darkweavers, Warlocks and Legionnaires of Shadow Hold carry one now and then. Use it to start the quest, then free {npc:11018} from her cage in the cave's south end on your way out."] = "Une {item:13140} est tombée : les Massacreurs, Tisseurs de ténèbres, Démonistes et Légionnaires de Jaedenar du Bastion des ombres en portent une de temps en temps. Utilisez-la pour commencer la quête, puis libérez {npc:11018} de sa cage au fond sud de la grotte en repartant.",
		["Andorhal watchtowers and silos"] = "Tours de guet et silos d'Andorhal",
		["Back south to the Sanctuary, a short ride."] = "Retournez au sud au Sanctuaire d'émeraude, un court trajet.",
		["Back to {area:2268}"] = "Retour à {area:2268}",
		["Below ground"] = "Sous terre",
		["Both quests lead to {zone:1451}: keep them."] = "Les deux quêtes mènent à {zone:1451} : gardez-les.",
		["Careful: {npc:10411} goes invisible when out of combat and calls Rockwing Gargoyles once a fight starts. Only 3 exist and they respawn every 15 min."] = "Attention : {npc:10411} devient invisible hors combat et appelle des Gargouilles aile-de-roc dès qu'un combat commence. Il n'en existe que 3 et elles réapparaissent toutes les 15 min.",
		["Class trainer"] = "Maître de classe",
		["Diseased Grizzlies"] = "Grizzlys malades",
		["Fly to {area:1638}"] = "Prendre un vol pour {area:1638}",
		["Fly to {area:2268}"] = "Prendre un vol pour {area:2268}",
		["Fly to {area:272}"] = "Prendre un vol pour {area:272}",
		["Fly to {area:431}"] = "Prendre un vol pour {area:431}",
		["Follow the road east from the {zone:1422}, over the river and across the whole {zone:1423}, to the {object:92525}'s chapel in the far east."] = "Suivez la route vers l'est depuis {zone:1422}, franchissez la rivière et traversez tout {zone:1423} jusqu'à la chapelle de {object:92525}, à l'extrême est.",
		["Free Darrowshire Spirits: talk to them"] = "Libérez les Esprits de Darrowshire : parlez-leur",
		["From the tunnel's {zone:1452} exit, ride south to {area:2246}."] = "Depuis la sortie du tunnel vers {zone:1452}, chevauchez vers le sud jusqu'aux {area:2246}.",
		["Inside"] = "À l'intérieur",
		["Into {zone:1423}"] = "Vers {zone:1423}",
		["Keep {quest:5152}: {npc:10927} lives at {area:197} in the {zone:1422}."] = "Gardez {quest:5152} : {npc:10927} habite à {area:197}, dans {zone:1422}.",
		["Moontouched Owlbeasts"] = "Chouettards lunaires",
		["Plaguehound Runts and Plaguebats roam the hills north of the {area:2260}, Carrion Grubs crawl among them; work north toward {area:2627}."] = "Les Chiens pestiférés chétifs et les Chauves-souris pestiférées parcourent les collines au nord de {area:2260}, et des Larves putrides rampent parmi eux ; progressez vers le nord en direction de {area:2627}.",
		["Plaguehounds and their runts roam the shores of the lake south-west of the chapel; Plaguebats and Carrion Grubs share the ground. Careful: the biggest Plaguehounds are 56, pull them one at a time.\nThe shattered sword lies on the ground north-west of the lake."] = "Les Chiens pestiférés et leurs petits parcourent les rives du lac au sud-ouest de la chapelle ; des Chauves-souris pestiférées et des Larves putrides partagent le terrain. Attention : les plus gros Chiens pestiférés sont de niveau 56, attirez-les un par un.\nL'épée brisée gît au sol au nord-ouest du lac.",
		["Pristine Yeti Horns"] = "Cornes de yéti en parfait état",
		["Radley and Durgen"] = "Radley et Durgen",
		["Ride back south to {area:272} and fly to {area:2268}."] = "Redescendez vers le sud jusqu'à {area:272} et prenez un vol pour {area:2268}.",
		["Ride east along the road into the {zone:1423}. {npc:1855} lives in a small house by the {area:2619}, just north of the road at the border; his three hunts are on this guide's ground."] = "Suivez la route vers l'est jusqu'aux {zone:1423}. {npc:1855} vit dans une petite maison près de {area:2619}, juste au nord de la route à la frontière ; ses trois chasses se déroulent sur le terrain de ce guide.",
		["Ride east to {area:2255} and north out of it; the Moontouched Owlbeasts roam the hills of {area:2241}'s southern slopes. Careful: they are 57-58: pull them one at a time.\nCareful: Hailspite, level 60 elites, gather in the snowfields south-east of {area:2255}, where a few Moontouched Owlbeasts roam too: stay on the slopes north of town."] = "Allez à l'est jusqu'à {area:2255} et sortez-en par le nord ; les Chouettards lunaires rôdent dans les collines des pentes sud de {area:2241}. Attention : ils sont de niveau 57-58 : attirez-les un par un.\nAttention : les Hailspite, des élites de niveau 60, se rassemblent dans les champs de neige au sud-est de {area:2255}, où rôdent aussi quelques Chouettards lunaires : restez sur les pentes au nord de la ville.",
		["Ride north up the road from {area:272}. {npc:10927}'s house stands by the road at {area:197}, and {npc:10936}'s monument is in the graveyard behind it."] = "Remontez la route vers le nord depuis {area:272}. La maison de {npc:10927} se trouve au bord de la route à {area:197}, et le monument de {npc:10936} est dans le cimetière derrière.",
		["Ride north-west into Andorhal. {npc:10667} waits in the ruined inn on the west side of town; the skeletons inside are 54-57, so keep to the edges."] = "Allez au nord-ouest jusqu'à Andorhal. {npc:10667} attend dans l'auberge en ruine, à l'ouest de la ville ; les squelettes à l'intérieur sont de niveau 54-57, restez donc sur les bords.",
		["Ride south to {area:2264}, on the road. {item:15447} spoils within ten minutes: kill the town's Scourge quickly and grind the seven pieces with the {item:15454} at once.\nCareful: Unseen Servants call for help within 25 yd once they drop to 40% health. Out of combat they also turn invisible with {spell:10228}. If a call for help happens inside the town, a large number of mobs can join the fight. Fighting near the outskirts lowers this risk.\nWith {quest:5211} in your log (from {npc:11063} at the start of this guide), the Scourge around the town leave Darrowshire Spirits: talk to each one to free it. Free them before you start on the {item:15447}."] = "Allez au sud par la route jusqu'à {area:2264}. {item:15447} se gâte en dix minutes : tuez vite le Fléau de la ville et broyez aussitôt les sept morceaux avec {item:15454}.\nAttention : les Serviteurs invisibles appellent à l'aide à moins de 25 m dès qu'ils tombent à 40 % de vie. Hors combat, ils deviennent aussi invisibles avec {spell:10228}. Si un appel à l'aide a lieu dans la ville, un grand nombre de monstres peut rejoindre le combat. Combattre en périphérie réduit ce risque.\nSi vous avez {quest:5211} dans votre journal (donnée par {npc:11063} au début de ce guide), le Fléau autour de la ville laisse des Esprits de Darrowshire : parlez à chacun pour le libérer. Libérez-les avant de commencer à récolter {item:15447}.",
		["Scarlet Crusade"] = "Croisade écarlate",
		["The Annals lie among the Musty Tomes in Andorhal's town hall; open them until you find the right one.\nCareful: a {npc:10996}, a level 58-59 elite, can stand in Andorhal, as at many other spots of the {zone:1422}: give it room."] = "Les Annales se trouvent parmi les Tomes moisis de l'hôtel de ville d'Andorhal ; ouvrez-les jusqu'à trouver le bon.\nAttention : un {npc:10996}, élite de niveau 58-59, peut se trouver à Andorhal, comme en bien d'autres endroits des {zone:1422} : gardez vos distances.",
		["The book lies in the ruined inn of {area:2627}; the undead in the town are 54-56, so pull them one at a time.\nThe Large Termite Mounds stand all over the hills east of {area:2627}. Use the {item:15042} on each mound you pass.\nCareful: Ziggurat Protectors (58, elite) stand by the ziggurats east and north-east of the town: take the mounds nearer the town and stay clear of them."] = "Le livre se trouve dans l'auberge en ruine de {area:2627} ; les morts-vivants de la ville sont de niveau 54-56, attirez-les donc un par un.\nLes Grandes termitières parsèment les collines à l'est de {area:2627}. Utilisez le {item:15042} sur chaque termitière que vous croisez.\nAttention : des Protecteurs de la ziggourat (58, élites) se tiennent près des ziggourats à l'est et au nord-est de la ville : prenez les termitières proches de la ville et restez à l'écart.",
		["The doll's head and its two sides lie in the houses around {npc:10926}; join them from your bags."] = "La tête de la poupée et ses deux côtés se trouvent dans les maisons autour de {npc:10926} ; assemblez-les depuis vos sacs.",
		["The skull sits in the {area:2622}, among Blighted Horrors and Plague Monstrosities."] = "Le crâne se trouve dans {area:2622}, parmi les Horreurs corrompues et les Monstruosités de la peste.",
		["The {area:2479}"] = "{area:2479}",
		["To {area:197}"] = "Vers {area:197}",
		["Umi's horns, carried from your last {area:2255} stop: the yeti hills start just south-east of {area:2255}. Only Matriarchs and Patriarchs drop horns, and the Patriarchs reach 58: pull them one at a time."] = "Les cornes d'Umi, rapportées depuis votre dernier passage à {area:2255} : les collines des yétis commencent juste au sud-est de {area:2255}. Seuls les Matriarches et Patriarches lâchent des cornes, et les Patriarches montent jusqu'au niveau 58 : attirez-les un par un.",
		["Underwater"] = "Sous l'eau",
		["Upstairs"] = "À l'étage",
		["West to the {area:152} one last time."] = "Vers l'ouest jusqu'à {area:152}, une dernière fois.",
		["West to the {area:152}."] = "Vers l'ouest jusqu'à {area:152}.",
		["You missed this on the route's earlier visit here: it comes first now. It is quick and opens the quests after it."] = "Vous avez manqué ceci lors du passage précédent de l'itinéraire ici : cela passe d'abord maintenant. C'est rapide et cela ouvre les quêtes qui suivent.",
		["Zaeldarr lurks just west of {area:2262}."] = "Zaeldarr rôde juste à l'ouest de {area:2262}.",
		["a message for {npc:11063} at {area:2268}"] = "un message pour {npc:11063} à {area:2268}",
		["{area:2268} flight master"] = "Maître de vol de {area:2268}",
		["{area:2277}: kill these as you meet them"] = "{area:2277} : tuez-les au passage",
		["{area:2627}: kill these as you meet them"] = "{area:2627} : tuez-les au fil de vos rencontres",
		["{area:272} flight master"] = "Maître de vol de {area:272}",
		["{npc:10667}, upstairs"] = "{npc:10667}, à l'étage",
		["{npc:10926}'s ghost stands in the ruins of {area:2262}, in the south-west."] = "Le fantôme de {npc:10926} se tient dans les ruines de {area:2262}, au sud-ouest.",
		["{npc:10927}, upstairs"] = "{npc:10927}, à l'étage",
		["{npc:11016}, below ground"] = "{npc:11016}, sous terre",
		["{npc:11140} the ghost stands by a hut in {area:2627}, in the north-west corner; {npc:12384} sits inside the hut."] = "Le fantôme {npc:11140} se tient près d'une cabane à {area:2627}, dans le coin nord-ouest ; {npc:12384} est assis dans la cabane.",
		["{npc:11558} walks around here: look inside the circle on the map"] = "{npc:11558} se promène par ici : cherchez dans le cercle sur la carte",
		["{npc:11613} stands east of the lumber camp; {npc:11611} guards the road north-east of {npc:11610}, toward {area:190}.\nCareful: Guards stand at the tower's base and one more circles it on patrol. Clear them before you engage Durgen so they don't join the fight."] = "{npc:11613} se tient à l'est du camp de bûcherons ; {npc:11611} garde la route au nord-est de {npc:11610}, en direction de {area:190}.\nAttention : des gardes se tiennent au pied de la tour et un autre en fait le tour en patrouille. Éliminez-les avant d'engager Durgen pour qu'ils ne rejoignent pas le combat.",
		["{npc:12384}, inside"] = "{npc:12384}, à l'intérieur",
		["{npc:3033} (Druids) trains on {area:1639}, {npc:246344} (Paladins) in the city too."] = "{npc:3033} (Druides) entraîne sur {area:1639}, {npc:246344} (Paladins) aussi dans la ville.",
		["{npc:3033} on {area:1639}; {npc:246344}"] = "{npc:3033} sur {area:1639} ; {npc:246344}",
		["{quest:5086} are in {zone:1448}, on a later trip: keep it."] = "Les cibles de {quest:5086} sont à {zone:1448}, lors d'un passage ultérieur : gardez-la.",
		["{quest:5211}'s spirits come with the {area:2264} stop later in this guide: keep it."] = "Les esprits de {quest:5211} viennent avec l'étape de {area:2264}, plus loin dans ce guide : gardez-la.",
		["{quest:5510}: the {area:2627} undead drop them while you wear the {item:12846}"] = "{quest:5510} : les morts-vivants de {area:2627} les lâchent tant que vous portez le {item:12846}",
		["{zone:1423}: kill these as you meet them"] = "{zone:1423} : tuez-les au passage",
		["{zone:1454} flight master"] = "Maître de vol d'{zone:1454}",
		["{zone:1456} flight master"] = "Maître de vol : {zone:1456}",
} end)()
t.guides["forever/horde/50-60/06-silithus"] = (function() return {
		["Back to Southwind and climb the tower. Stirring the hive at the top brings out Hive'Ashi Ambushers; one carries the {item:17346}."] = "Retournez à Sudevent et montez dans la tour. Remuer la ruche au sommet fait sortir des Embusquées de la Ruche'Ashi ({npc:13301}) ; l'une porte {item:17346}.",
		["Back to {area:3425}"] = "Retour au {area:3425}",
		["Below ground"] = "Sous terre",
		["Class trainer"] = "Maître de classe",
		["Collect twenty Encrypted Twilight Texts from the cultists here, ten for {npc:15306} and ten for Ortell. Take them from the Twilight Avengers and Geolords; leave the Flamereavers and Stonecallers (59-60)."] = "Récupérez vingt Textes du crépuscule cryptés sur les cultistes d'ici, dix pour {npc:15306} et dix pour Ortell. Prenez-les sur les Vengeurs du crépuscule et les Géoseigneurs ; laissez les Saccageurs des flammes et les Implorateurs de pierre (59-60).",
		["Dredge Crushers and Pincers"] = "Écraseurs térébrants et Pinceurs",
		["Dredge Strikers, Stonelash Scorpids and Sand Skitterers share the sands just north of the hold."] = "Frappeurs térébrants, Scorpides Cinglepierre et Glisseuses du sable se partagent les sables juste au nord du fort.",
		["Drink the {item:11243} at the graveyard just east of {area:976}: it kills you, and only as a ghost can you see {npc:9299}, in a rocky crevice in the hills due north of it. Talk to him there, then run back to your body and resurrect: the Conspicuous Gravestone he sends you to stands in that graveyard."] = "Buvez l'{item:11243} au cimetière juste à l'est de {area:976} : il vous tue, et ce n'est que sous forme de fantôme que vous pouvez voir {npc:9299}, dans une crevasse rocheuse des collines plein nord. Parlez-lui là-bas, puis retournez à votre corps et ressuscitez : la Pierre tombale remarquable où il vous envoie se trouve dans ce cimetière.",
		["Escort {npc:9999}"] = "Escortez {npc:9999}",
		["Flayers and Rock Stalkers"] = "Écorcheurs et Traqueuses des rochers",
		["Fly to {area:1637}"] = "Prendre un vol pour {area:1637}",
		["Fly to {area:541}"] = "Prendre un vol pour {area:541}",
		["Head north along the western dunes; Dredge Crushers and Stonelash Pincers range from here back toward the hold."] = "Remontez vers le nord le long des dunes de l'ouest ; les Ecraseurs térébrants et les Pinceurs Cinglepierre rôdent d'ici jusqu'au fort.",
		["Inside"] = "À l'intérieur",
		["Inside: {quest:4493}, if you took it in {zone:1454} on the {zone:1447} guide"] = "À l'intérieur : {quest:4493}, si vous l'avez prise à {zone:1454} pendant le guide d'{zone:1447}",
		["Lead {npc:9999} north to {area:541}. When he faints, use {item:11804} on him to wake him."] = "Menez {npc:9999} vers le nord jusqu'au {area:541}. Quand il s'évanouit, utilisez {item:11804} sur lui pour le réveiller.",
		["Mar'alith's next errand, Into the Maw of Madness, leads into {area:2744} among elites. Skip it."] = "La mission suivante de Mar'alith, L'antre de la folie, mène dans la {area:2744}, parmi des élites. Passez-la.",
		["Only if you took {quest:4496} in {area:976} on the way here: the Gorishi of the {area:540}, south of {area:537}, drop the Scent Gland, and most of the crater's beasts and plants drop {item:11018}."] = "Seulement si vous avez pris {quest:4496} à {area:976} en venant : les Gorishi de {area:540}, au sud de {area:537}, lâchent la Glande à phéromones, et la plupart des bêtes et plantes du cratère lâchent de l'{item:11018}.",
		["Paladin trainer"] = "Maître des paladins",
		["Ride east to {area:537}, climb it and use {npc:10541} at the lava vent near the top, then ride back west to {npc:10302}."] = "Chevauchez vers l'est jusqu'à {area:537}, grimpez-y et utilisez {npc:10541} sur la cheminée de lave près du sommet, puis revenez vers l'ouest jusqu'à {npc:10302}.",
		["Ride north-east to {area:3077}; you leave {zone:1451} through the pass beside it."] = "Allez vers le nord-est jusqu'au cimetière ({area:3077}) ; vous quittez {zone:1451} par le col tout proche.",
		["Ride north-east to {area:3447}."] = "Allez vers le nord-est jusqu'à {area:3447}.",
		["Ride south-east to {area:3447} under the Un'Goro cliffs."] = "Allez vers le sud-est jusqu'à {area:3447}, au pied des falaises d'Un'Goro.",
		["Ride south-west to the ruins of {area:2738}. The {object:179565} for {npc:11801} sits inside one of the ruined houses."] = "Allez vers le sud-ouest jusqu'aux ruines du {area:2738}. Le {object:179565} pour {npc:11801} se trouve dans l'une des maisons en ruine.",
		["Ride west to the Horde camp north of {area:2744}."] = "Allez vers l'ouest jusqu'au camp de la Horde au nord de la {area:2744}.",
		["Scare {npc:7583} with {item:12928}"] = "Effrayez {npc:7583} avec {item:12928}",
		["Silithyst geysers erupt across the southern desert. Walk into the Silithyst one leaves behind and carry it to the Horde's Silithyst Extractor at Kirika's camp; fighting or mounting drops it."] = "Des Geysers de silithyste jaillissent dans le désert du sud. Marchez dans le silithyste qu'ils laissent et portez-le à l'extracteur de silithyste de la Horde, au camp de Kirika ; combattre ou monter en selle vous le fait lâcher.",
		["Stonelash Flayers and Rock Stalkers roam the dunes south-west of Kirika's camp."] = "Les Ecorcheurs Cinglepierre et les Traqueuses des rochers parcourent les dunes au sud-ouest du camp de Kirika.",
		["The pass from Un'Goro comes out at {area:3077}, the graveyard in north-east {zone:1451}. {npc:13220} stands among the graves."] = "Le col venant d'Un'Goro débouche sur {area:3077}, le cimetière du nord-est de {zone:1451}. {npc:13220} se tient parmi les tombes.",
		["The spare texts from the cultists"] = "Les textes en trop des cultistes",
		["Twilight Vanguard"] = "Avant-garde du Crépuscule",
		["Use the {item:11833} where the arrow points, inside the Gorishi hive of the {area:540}, to call the {npc:10041} (level 56)."] = "Utilisez le {item:11833} là où pointe la flèche, dans la ruche Gorishi de la {area:540}, pour appeler la {npc:10041} (niveau 56).",
		["Use {item:12928} on {npc:7583}, the goblin girl in {area:976}. {npc:10977} and {npc:10978} are scared later in the route."] = "Utilisez {item:12928} sur {npc:7583}, la petite gobeline de {area:976}. {npc:10977} et {npc:10978} seront effrayés plus loin dans le parcours.",
		["ten for each quest: {npc:15306} takes his ten before Ortell"] = "dix pour chaque quête : {npc:15306} prend ses dix avant Ortell",
		["{area:976} flight master"] = "Maître de vol de {area:976}",
		["{item:20377} from {npc:11739}, 130 yd south-west"] = "{item:20377} sur les {npc:11739}, à 130 m au sud-ouest",
		["{npc:10302} sends you to {npc:9298} in {zone:1452}: keep it."] = "{npc:10302} vous envoie voir {npc:9298} au {zone:1452} : gardez-la.",
		["{npc:11741} walks around {area:2738}: look inside the circle on the map"] = "{npc:11741} se promène autour de {area:2738} : cherchez dans le cercle sur la carte",
		["{npc:11803} walks the Vanguard camp in the far south-west. Keep every {item:20404} the cultists drop: {npc:15306} and Ortell want ten each later."] = "{npc:11803} arpente le camp de l'Avant-garde, à l'extrême sud-ouest. Gardez chaque {item:20404} que lâchent les cultistes : {npc:15306} et Ortell en veulent dix chacun plus tard.",
		["{npc:11804} stands in the outpost west of {area:3425}. Keep any Encrypted Twilight Texts that drop here too."] = "{npc:11804} se tient dans l'avant-poste à l'ouest du {area:3425}. Gardez aussi les Textes du crépuscule cryptés qui tombent ici.",
		["{npc:15171} and {npc:15170} camp at Bronzebeard's Encampment, just north of the satchel's mountains. Question them: go through each one's whole conversation; there is no need to fight them."] = "{npc:15171} et {npc:15170} campent au campement de Barbe-de-bronze, juste au nord des montagnes de la sacoche. Interrogez-les : suivez toute la conversation de chacun ; inutile de les combattre.",
		["{npc:15189} and {npc:15190} stand upstairs in their building: go up inside, the arrow cannot tell the floors apart."] = "{npc:15189} et {npc:15190} se tiennent à l'étage de leur bâtiment : montez par l'intérieur, la flèche ne distingue pas les étages.",
		["{npc:15189} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{npc:15189} se tient à l'étage de son bâtiment : montez par l'intérieur, la flèche ne distingue pas les étages.",
		["{npc:15190} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{npc:15190} se tient à l'étage de son bâtiment : montez par l'intérieur, la flèche ne distingue pas les étages.",
		["{npc:15200} holds the camp in the west."] = "{npc:15200} tient le camp de l'ouest.",
		["{npc:15306}, on the west side of the Hold"] = "{npc:15306}, du côté ouest du fort",
		["{npc:246344} in {zone:1456}; {zone:1454} has no paladin trainer"] = "{npc:246344} ({zone:1456}) ; {zone:1454} n'a pas de maître des paladins",
		["{npc:7771} camps by the {area:1336} road, south of {area:976}."] = "{npc:7771} Rivetseeker campe près de la route de {area:1336}, au sud de {area:976}.",
		["{npc:9117}, below ground"] = "{npc:9117}, sous terre",
		["{npc:9684}'s lair is just south of the pylon. Use {npc:9619}'s bait there; {npc:9684} is level 56 and hits hard, so start at full health."] = "Le repaire de {npc:9684} est juste au sud du pylône. Utilisez-y l'appât de {npc:9619} ; {npc:9684} est de niveau 56 et frappe fort, commencez donc avec toute votre vie.",
		["{npc:9999} sits on the ridge, lost and exhausted."] = "{npc:9999} est assis sur la crête, perdu et épuisé.",
		["{quest:3914} goes back to {npc:8737} in Un'Goro: keep it."] = "{quest:3914} se rend à {npc:8737}, dans le Cratère d'Un'Goro : gardez-la.",
		["{zone:1451}: kill these as you meet them"] = "{zone:1451} : tuez-les au passage",
} end)()
t.guides["forever/horde/50-60/07-felwood"] = (function() return {
		["Back into the Timbermaw tunnel and take the {zone:1452} exit; {npc:9298} camps by the hot springs just outside."] = "Retournez dans le tunnel des Grumegueules et prenez la sortie de {zone:1452} ; {npc:9298} campe près des sources chaudes juste dehors.",
		["Below ground"] = "Sous terre",
		["Class trainer"] = "Maître de classe",
		["Fly to {area:431}"] = "Prendre un vol pour {area:431}",
		["Fly to {area:431} and ride north-west along the road out of {zone:1440} into {zone:1448}. The {area:2479} is the druids' camp just past the border."] = "Volez jusqu'au {area:431} et suivez la route vers le nord-ouest pour quitter {zone:1440} et entrer dans {zone:1448}. Le camp des druides juste après la frontière est {area:2479}.",
		["Frostfire Winterfall camp"] = "Camp Tombe-hiver des sources chaudes",
		["Ice Thistle yetis"] = "Yétis Chardon de glace",
		["In the {object:172961}."] = "Dans {object:172961}.",
		["North of Donova, at the tunnel's {zone:1452} exit."] = "Au nord de Donova, à la sortie du tunnel côté {zone:1452}.",
		["Ride back west along the road to {area:2246}."] = "Revenez vers l'ouest par la route jusqu'à {area:2246}.",
		["Ride north along the road, past {area:1763}, to {area:1997}."] = "Suivez la route vers le nord, après {area:1763}, jusqu'au {area:1997}.",
		["Ride north to {area:2255}."] = "Allez vers le nord jusqu'à {area:2255}.",
		["Scare {npc:10978} with {npc:10980}"] = "Effrayez {npc:10978} avec {npc:10980}",
		["The runners walk the road from {area:1769} toward {area:2244} in small groups; wait by the road near {npc:9298} and kill them as they pass. Each one carries a crate.\nCareful: Turning in spawns three or four level 56-57 Winterfall ambushers that attack you; you can escape them while mounted, in stealth or with {spell:5384}, and they then gather by the lake so you can take the next quest."] = "Les Messagers Tombe-hiver suivent la route du {area:1769} vers {area:2244} en petits groupes ; attendez au bord de la route près de {npc:9298} et tuez-les à leur passage. Chacun porte une caisse.\nAttention : rendre la quête fait apparaître trois ou quatre embusqués Tombe-hiver de niveau 56-57 qui vous attaquent ; vous pouvez leur échapper sur votre monture, camouflé ou avec {spell:5384}, et ils se rassemblent ensuite près du lac pour que vous puissiez prendre la quête suivante.",
		["The {area:2479}"] = "{area:2479}",
		["Through the Timbermaw tunnel to {zone:1450}. {npc:11939} reads in a house in {area:2361}."] = "Traversez le tunnel des Grumegueules jusqu'à {zone:1450}. {npc:11939} lit dans une maison de {area:2361}.",
		["With 30 {quest:6031} in your bags: follow the road north to {area:1769}; {npc:11557} trades just inside the entrance."] = "Avec 30 {quest:6031} dans vos sacs : suivez la route vers le nord jusqu'au {area:1769} ; {npc:11557} commerce juste après l'entrée.",
		["grind on {npc:7446}"] = "tuez en boucle : {npc:7446}",
		["sixty {item:14047}"] = "soixante {item:14047}",
		["{npc:11556} takes the beads only once {quest:8464} is handed in: any Winterfall furbolg can carry them, and the camps just south of {npc:11556} are the closest."] = "{npc:11556} n'accepte les perles qu'une fois {quest:8464} rendue : n'importe quel furbolg Tombe-hiver peut les porter, et les camps juste au sud de {npc:11556} sont les plus proches.",
		["{npc:11558} walks around here: look inside the circle on the map"] = "{npc:11558} se promène par ici : cherchez dans le cercle sur la carte",
		["{npc:11801}'s Shards of the Felvine needs {area:2577}. Skip it."] = "Le Fragment de la Gangrevigne de {npc:11801} demande {area:2577}. Passez-la.",
		["{npc:11939} walks around {area:2361}: look inside the circle on the map"] = "{npc:11939} se promène autour de {area:2361} : cherchez dans le cercle sur la carte",
		["{npc:9116}, inside"] = "{npc:9116}, à l'intérieur",
		["{quest:8464}'s village is north-east of {area:2255}, on this guide's way back from {area:2256}."] = "Le village de {quest:8464} est au nord-est de {area:2255}, sur le chemin du retour de {area:2256} dans ce guide.",
		["{zone:1454} flight master"] = "Maître de vol d'{zone:1454}",
} end)()
t.guides["forever/horde/orc/01-durotar"] = (function() return {
		["Armored Scorpids crawl over the plains west of {area:362}. Tame one, then return to {npc:3171}."] = "Les Scorpides blindés rampent dans les plaines à l'ouest de {area:362}. Apprivoisez-en un, puis retournez voir {npc:3171}.",
		["Back east to Sen'jin on the way to the {area:368}."] = "Retournez à l'est à Sen'jin en route vers {area:368}.",
		["Back north-west to {area:362}: {npc:3139} first, then {npc:3147} in the watchtower, then {npc:3142} and {npc:266940} on the way out east to the shore."] = "Retournez au nord-ouest à {area:362} : d'abord {npc:3139}, puis {npc:3147} dans la tour de guet, puis {npc:3142} et {npc:266940} en sortant vers l'est, vers le rivage.",
		["Back over the bridge and south along the {zone:1411} bank of the river to where a narrow trail climbs the mountain: {npc:5900} keeps the shrine at the top. Mind the edges on the way up, and come back down the same trail."] = "Repassez le pont et descendez vers le sud le long de la rive du fleuve côté {zone:1411}, jusqu'à l'endroit où un sentier étroit grimpe la montagne : {npc:5900} garde le sanctuaire au sommet. Attention aux bords en montant, et redescendez par le même sentier.",
		["Back to the Den"] = "Retour à l'Antre",
		["Back to the Den: {npc:3143} takes {quest:804}'s claw and {npc:5887}, just outside, has {quest:1516} now that you are level 4."] = "Retournez à l'Antre : {npc:3143} prend la griffe de {quest:804}, et {npc:5887}, juste dehors, propose {quest:1516} maintenant que vous êtes niveau 4.",
		["Back to {area:362}: {npc:3139}, then {npc:3142}."] = "Retour à {area:362} : {npc:3139}, puis {npc:3142}.",
		["Back to {zone:1411}"] = "Retour en {zone:1411}",
		["Below ground"] = "Sous terre",
		["Burning Blade cultists hold the caves of {quest:827}; any of them drops a {item:4871}. {npc:3204}, a level 14 warlock, stands deep inside and drops the {item:4903}.\nCareful: voidwalkers fight beside the Burning Blade cultists in {quest:827} and {npc:3204} (14) waits at the back with his own: pull one cultist at a time near the entrance for the collars. The {item:4903} is optional: leave {npc:3204} unless you are 13 or have a friend."] = "Les sectateurs de la Lame ardente tiennent les grottes de {quest:827} ; chacun d'eux peut laisser tomber un {item:4871}. {npc:3204}, un démoniste de niveau 14, se tient au fond et laisse tomber l'{item:4903}.\nAttention : des marcheurs du Vide combattent aux côtés des sectateurs de la Lame ardente dans {quest:827} et {npc:3204} (14) attend au fond avec le sien : attirez un sectateur à la fois près de l'entrée pour les colliers. L'objet {item:4903} est facultatif : laissez {npc:3204} tranquille sauf si vous êtes niveau 13 ou accompagné.",
		["Careful: Ukorsbane (8) is elite and walks among the Ridgeshade spiders in the camp south of {area:362}: pull the spiders away from him."] = "Attention : Ukorsbane (8) est élite et se promène parmi les araignées Ridgeshade dans le camp au sud de {area:362} : attirez les araignées loin de lui.",
		["Class trainer"] = "Maître de classe",
		["Deathskip to Northern Durotar"] = "Mort volontaire jusqu'au nord de Durotar",
		["Deathskip to {area:367}"] = "Mort volontaire jusqu'à {area:367}",
		["Die to the mobs at 52.0,21.4 ({npc:3118}): a death there sends you to this graveyard. Release your spirit and take the {npc:6491}'s resurrection."] = "Laissez-vous tuer par les monstres en 52.0,21.4 ({npc:3118}) : mourir là vous envoie à ce cimetière. Libérez votre esprit et acceptez la résurrection du {npc:6491}.",
		["Die to the mobs at 66.9,87.2 ({npc:3206}): a death there sends you to this graveyard. Release your spirit and take the {npc:6491}'s resurrection."] = "Laissez-vous tuer par les monstres en 66.9,87.2 ({npc:3206}) : mourir là vous envoie à ce cimetière. Libérez votre esprit et acceptez la résurrection du {npc:6491}.",
		["Druid trainer"] = "Maître des druides",
		["Felstalkers roam the slope below the cave, on the valley's north side."] = "Les Traqueurs corrompus parcourent la pente sous la grotte, du côté nord de la vallée.",
		["Fizzle holds the Burning Blade camp on {area:369}, just north of Misha's hut. Hunters: tame a {npc:3099} with the {item:15908} on the way.\nCareful: Burning Blade cultists surround Fizzle, some linked so they aggro in pairs, and they respawn quickly.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "Fizzle tient le camp de la Lame ardente sur {area:369}, juste au nord de la hutte de Misha. Chasseurs : apprivoisez un {npc:3099} avec {item:15908} en chemin.\nAttention : des sectateurs de la Lame ardente entourent Fizzle, certains liés pour attaquer par paires, et ils réapparaissent vite.\nAttention : Halikor, un élite de niveau 12, rôde sur {area:369} parmi les lézards : repérez-le avant d'attirer quoi que ce soit.",
		["Free {npc:275811} and see her safely out of the crag"] = "Libérez {npc:275811} et escortez-la hors de la Combe",
		["Head north-east to the road toward {zone:1454}. {npc:3293} camps beside it; the stolen sacks lie along the road south of him."] = "Allez vers le nord-est jusqu'à la route d'{zone:1454}. {npc:3293} campe à côté ; les sacs volés sont éparpillés le long de la route au sud de lui.",
		["Head south through the isles. The Loa idols lie all over the southern isles; Voodoo and Hexed Trolls hold them and drop the Hexed Pendants. {quest:826} and Minshina's cage are on the southernmost isle.\nCareful: the trolls stand close together and the Voodoo Trolls cast from range: pull one at a time. {quest:826} himself is level 10."] = "Dirigez-vous vers le sud à travers les îles. Les idoles des loas sont éparpillées sur les îles du sud ; les Trolls vaudous et les Trolls maléficiés les gardent et laissent tomber les Pendentifs maléficiés. {quest:826} et la cage de Minshina se trouvent sur l'île la plus au sud.\nAttention : les trolls sont proches les uns des autres et les Trolls vaudous lancent des sorts à distance : attirez-les un par un. {quest:826} lui-même est niveau 10.",
		["Inside"] = "À l'intérieur",
		["Inside the cave, go straight on at the first split, then right and follow the stream on your left to the waterfall: the pick glows by the water, behind a column of rock."] = "Dans la grotte, allez tout droit à la première bifurcation, puis à droite, et suivez le ruisseau sur votre gauche jusqu'à la cascade : la pioche brille près de l'eau, derrière une colonne de roche.",
		["Inside the cave, keep to the right wall all the way round, over the stream: {npc:3183} waits at the end."] = "Dans la grotte, longez la paroi de droite tout du long, en passant le ruisseau : {npc:3183} attend au fond.",
		["Level 10"] = "Niveau 10",
		["Level 11"] = "Niveau 11",
		["Level 7"] = "Niveau 7",
		["Level 9"] = "Niveau 9",
		["Misha's hut stands south of the lizards. The crocolisks along the {area:814} to the west carry {item:4891}."] = "La hutte de Misha se trouve au sud des lézards. Les crocilisques le long de {area:814}, à l'ouest, portent l'{item:4891}.",
		["North-east to the beach below {area:370}, north of {npc:275657}: Spitelash Scouts and Attendants hold it. Hunters: tame a {npc:3107} on the beach."] = "Au nord-est jusqu'à la plage sous {area:370}, au nord de {npc:275657} : les Eclaireurs et les Domestiques fouette-bile la tiennent. Chasseurs : apprivoisez un {npc:3107} sur la plage.",
		["Paladin trainer"] = "Maître des paladins",
		["Quilboars and scouts hold the huts west of town, where the prickly pears grow; dustrunners and battleguards hold the camps farther west."] = "Les Hurans et les Éclaireurs Tranchecrin tiennent les huttes à l'ouest de la ville, là où poussent les figues de Barbarie ; les Lève-poussière et les Gardes de guerre tiennent les camps plus à l'ouest.",
		["Savages and Storm Witches nest in {area:370}, east of {npc:3293}. A Storm Witch drops the {item:277661}. Shamans: the Burning Blade Cultists by {area:371}, at the ravine's south end, drop the {item:6652}."] = "Sauvages et Sorcières des tempêtes Terrevent nichent dans {area:370}, à l'est de {npc:3293}. Une Sorcière des tempêtes lâche {item:277661}. Chamans : les Sectateurs de la Lame ardente près de {area:371}, au bout sud du ravin, lâchent {item:6652}.",
		["Spitelash naga"] = "Nagas Fouette-bile",
		["Tame it with the {item:15908}"] = "Apprivoisez-le avec le {item:15908}",
		["The Scorpid Workers roam the slope south of {npc:3287}; pick the Cactus Apples by the cactuses on the way.\nThe {quest:792} swarm the slope below the {area:365}, the cave on the valley's north side."] = "Les Scorpides ouvriers parcourent la pente au sud de {npc:3287} ; cueillez les Pommes de cactus près des cactus en chemin.\n{quest:792} grouillent sur la pente sous l'{area:365}, la grotte du côté nord de la vallée.",
		["The cattails and speargrass grow along the water in the {object:172958}, east of the Drag."] = "Les massettes et les herbes-lances poussent au bord de l'eau dans {object:172958}, à l'est de la Herse.",
		["The gnomish toolboxes lie in the wreckage along the shore east and south-east of {area:362}. Follow the shore south to Sen'jin.\nMakrura and surf crawlers line the beaches north-east of Sen'jin."] = "Les boîtes à outils gnomes se trouvent dans les épaves le long du rivage, à l'est et au sud-est de {area:362}. Suivez le rivage vers le sud jusqu'à Sen'jin.\nMakruras et clampants de l'écume bordent les plages au nord-est de Sen'jin.",
		["The keep stands on the coast south-east of {area:362}. The raiders' axe, bow and shield lie on its outskirts. Sailors and marines drop the {item:4870}."] = "Le donjon se dresse sur la côte au sud-est de {area:362}. La hache, l'arc et le bouclier des pillards traînent aux abords. Les Marins et Soldats de marine de Kul Tiras laissent tomber les {item:4870}.",
		["The weapons lie around the Den and the training grounds; the Mottled Boars roam the whole valley floor."] = "Les armes traînent autour de l'Antre et du terrain d'entraînement ; les Sangliers tachetés parcourent tout le fond de la vallée.",
		["The {object:58595} stands in {area:817}, among the cultists you just fought."] = "La {object:58595} se trouve dans {area:817}, parmi les sectateurs que vous venez de combattre.",
		["Through Sen'jin on the way west to {area:366}: {npc:3304} takes the eyes and mucus now."] = "Passez par Sen'jin en allant vers l'ouest à {area:366} : {npc:3304} prend maintenant les yeux et le mucus.",
		["Thunder Lizards and Lightning Hides graze on {area:369}, beside the road north to {zone:1454}; any of them can drop a {item:6486}. {npc:5810} takes it when the next guide passes {area:379}.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "Les Lézards-tonnerre et les Foudroyants paissent sur {area:369}, à côté de la route du nord vers {zone:1454} ; chacun d'eux peut laisser tomber une {item:6486}. {npc:5810} la prend quand le guide suivant passe par {area:379}.\nAttention : Halikor, un élite de niveau 12, rôde sur {area:369} parmi les lézards : repérez-le avant d'attirer quoi que ce soit.",
		["Thunder Lizards and Lightning Hides graze on {area:369}, just west and south-west of {npc:3293}.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "Lézards-tonnerre et Foudroyants paissent sur {area:369}, juste à l'ouest et au sud-ouest de {npc:3293}.\nAttention : Halikor, un élite de niveau 12, rôde sur {area:369} parmi les lézards : repérez-le avant d'attirer quoi que ce soit.",
		["Thunder lizards on the way north"] = "Lézards-tonnerre sur la route du nord",
		["To {zone:1454}"] = "Vers {zone:1454}",
		["Top up here to level 11 before {npc:3203} (12) and his imp: the Thunder Lizards (9-10) graze on the ridge just west of Misha's hut."] = "Montez ici jusqu'au niveau 11 avant {npc:3203} (12) et son diablotin : les Lézards-tonnerre (9-10) paissent sur la crête juste à l'ouest de la hutte de Misha.",
		["Top up here to level 7 before {npc:3192} (8) and the marines at the top of the keep."] = "Montez ici jusqu'au niveau 7 avant {npc:3192} (8) et les soldats de marine au sommet du donjon.",
		["Top up here to level 9 before the southern isles: the Voodoo and Hexed Trolls there are 8-9 and {quest:826} is 10."] = "Montez ici jusqu'au niveau 9 avant les îles du sud : les Trolls vaudous et Trolls maléficiés y sont niveau 8-9 et {quest:826} est niveau 10.",
		["Training weapons and boars"] = "Armes d'entraînement et sangliers",
		["Underwater"] = "Sous l'eau",
		["Upstairs"] = "À l'étage",
		["Wade across to the northern Echo Isle. The Matriarch prowls among the raptors there.\nDurotar Tigers roam the isle as well as the shore south of Sen'jin, and the Taillasher eggs sit in nests on the isles and along the beach."] = "Traversez à gué jusqu'à l'île de l'Écho la plus au nord. La Matriarche rôde parmi les raptors.\nDes Tigres de Durotar parcourent l'île ainsi que le rivage au sud de Sen'jin, et les œufs de Fouette-queue reposent dans des nids sur les îles et le long de la plage.",
		["Wake {quest:5441} with the {item:16114}"] = "Réveillez {quest:5441} avec la {item:16114}",
		["West from {area:362} over the {area:814} bridge: {npc:3337} and {npc:5810} stand together at {area:379} above it. From there the road north through {zone:1411} leads to {zone:1454}."] = "Vers l'ouest depuis {area:362}, par le pont de la {area:814} : {npc:3337} et {npc:5810} se tiennent ensemble à {area:379}, au-dessus. De là, la route vers le nord à travers {zone:1411} mène à {zone:1454}.",
		["West over the {area:814} bridge, past {area:379} and on along the ridge: {npc:5907} stands alone above the Razormane camp."] = "Allez vers l'ouest par le pont de {area:814}, passez {area:379} et continuez le long de la crête : {npc:5907} se tient seul au-dessus du camp Tranchecrin.",
		["West over the {area:814} bridge: {npc:3337} stands at {area:379} above it, on your way to {npc:5907}."] = "À l'ouest par le pont de la {area:814} : {npc:3337} se tient au {area:379}, au-dessus, sur votre chemin vers {npc:5907}.",
		["While you're here: learn Staves from {npc:2704} ({object:172958}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Tant que vous y êtes : apprenez les Bâtons auprès de {npc:2704} ({object:172958}, 10 pièces d'argent) ; l'arme de mêlée d'un chasseur compte surtout pour ses caractéristiques, et les armes à deux mains en apportent le plus.",
		["While you're here: learn Staves from {npc:2704} ({object:172958}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "Tant que vous y êtes : apprenez les Bâtons auprès de {npc:2704} ({object:172958}, 10 pièces d'argent) ; un bâton apporte plus de caractéristiques de sorts qu'une arme à une main pendant la montée de niveau.",
		["grind on {npc:3111}"] = "tuez en boucle : {npc:3111}",
		["grind on {npc:3121}"] = "tuez en boucle : {npc:3121}",
		["grind on {npc:3128}"] = "tuez en boucle : {npc:3128}",
		["grind on {npc:3130}"] = "tuez des {npc:3130}",
		["the {object:654925} on the ground beside her"] = "le {object:654925} par terre à côté d'elle",
		["{area:363}: kill these as you meet them"] = "{area:363} : tuez-les au passage",
		["{area:366} lies west of Sen'jin. The three attack plans sit on the ground among the centaur tents. {npc:275811} is held at the crag as well."] = "{area:366} se trouve à l'ouest de Sen'jin. Les trois plans d'attaque sont posés au sol parmi les tentes des centaures. {npc:275811} est aussi retenue à la Combe.",
		["{area:368}: kill these as you meet them"] = "{area:368} : tuez-les au passage",
		["{area:369}: kill these as you meet them"] = "{area:369} : tuez-les au passage",
		["{area:373}: kill these as you meet them"] = "{area:373} : tuez-les au passage",
		["{area:817}'s mouth"] = "Entrée de {area:817}",
		["{npc:10176}, where you start"] = "{npc:10176}, à votre point de départ",
		["{npc:11025} takes it once your {skill:202} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:11025} prend la quête une fois votre compétence {skill:202} à 20 : récoltez ou fabriquez d'ici là, le guide continue en attendant.",
		["{npc:11378}, at the lumber pile east of the Den"] = "{npc:11378}, près du tas de bois à l'est de l'Antre",
		["{npc:246344} in {zone:1456}; {area:362} has no paladin trainer"] = "{npc:246344} ({zone:1456}) ; {area:362} n'a pas de maître des paladins",
		["{npc:246344} in {zone:1456}; {area:363} has no paladin trainer"] = "{npc:246344} ({zone:1456}) ; {area:363} n'a pas de maître des paladins",
		["{npc:265809} camps just south of {area:362}. Sit by his campfire (/sit) until the {spell:1229451} buff appears. With a profession learned, {npc:265809} also offers its Camping 101, which its trainer takes: in {area:362} or in {zone:1454} at the start of the next guide."] = "{npc:265809} campe juste au sud de {area:362}. Asseyez-vous près de son feu de camp (/sit) jusqu'à ce que l'effet {spell:1229451} apparaisse. Si vous avez appris un métier, {npc:265809} propose aussi sa quête Camping 101, que reçoit le maître de ce métier : à {area:362} ou à {zone:1454}, au début du guide suivant.",
		["{npc:265809}'s campfire"] = "Feu de camp de {npc:265809}",
		["{npc:265809}: for Jandi"] = "{npc:265809} : pour Jandi",
		["{npc:265809}: for Jhag"] = "{npc:265809} : pour Jhag",
		["{npc:265809}: for Karolek"] = "{npc:265809} : pour Karolek",
		["{npc:265809}: for Snang"] = "{npc:265809} : pour Snang",
		["{npc:265809}: for Thuwd"] = "{npc:265809} : pour Thuwd",
		["{npc:265809}: for {npc:11025}"] = "{npc:265809} : pour {npc:11025}",
		["{npc:265809}: for {npc:11046}"] = "{npc:265809} : pour {npc:11046}",
		["{npc:265809}: for {npc:3175}"] = "{npc:265809} : pour {npc:3175}",
		["{npc:265809}: for {npc:5943}"] = "{npc:265809} : pour {npc:5943}",
		["{npc:266881}: enchanters only, the residue is disenchanted from Hexed Pendants"] = "{npc:266881} : enchanteurs uniquement, le résidu s'obtient en désenchantant des Pendentifs maléficiés",
		["{npc:266940}, inside"] = "{npc:266940}, à l'intérieur",
		["{npc:266940}, on the east side of town; inside"] = "{npc:266940}, du côté est de la ville ; à l'intérieur",
		["{npc:275657} stands on the shore east of {area:362}. The trident, banner and dagger lie on the beach around him."] = "{npc:275657} se tient sur le rivage à l'est de {area:362}. Le trident, la bannière et la dague traînent sur la plage autour de lui.",
		["{npc:275666}, a young sea giant, walks {zone:1411}'s north coast, north of the naga beach. {npc:275666} is elite: grouping up is advised."] = "{npc:275666}, un jeune géant des mers, arpente la côte nord de {zone:1411}, au nord de la plage des nagas. {npc:275666} est élite : il est conseillé de se grouper.",
		["{npc:3034} in {zone:1412}; {area:362} has no druid trainer"] = "{npc:3034} ({zone:1412}) ; {area:362} n'a pas de maître des druides",
		["{npc:3034} in {zone:1412}; {area:363} has no druid trainer"] = "{npc:3034} ({zone:1412}) ; {area:363} n'a pas de maître des druides",
		["{npc:3102} hooves"] = "Sabots de {npc:3102}",
		["{npc:3142}, back in {area:362}"] = "{npc:3142}, de retour à {area:362}",
		["{npc:3142}: {npc:275666}, an elite sea giant"] = "{npc:3142} : {npc:275666}, un géant des mers élite",
		["{npc:3143} stands just inside the cave mouth; {npc:3159} at the back of the cave behind him."] = "{npc:3143} se tient juste à l'entrée de la grotte ; {npc:3159} au fond de la grotte, derrière lui.",
		["{npc:3143} waits inside the Den, the building just west of {npc:10176}."] = "{npc:3143} attend dans l'Antre, le bâtiment juste à l'ouest de {npc:10176}.",
		["{npc:3143}, inside"] = "{npc:3143}, à l'intérieur",
		["{npc:3147}, in the watchtower"] = "{npc:3147}, dans la tour de guet",
		["{npc:3153}, the warrior trainer beside the Den"] = "{npc:3153}, le maître des guerriers à côté de l'Antre",
		["{npc:3154}, the hunter trainer beside the Den"] = "{npc:3154}, le maître des chasseurs à côté de l'Antre",
		["{npc:3155}, the rogue trainer in the Den"] = "{npc:3155}, le maître des voleurs dans l'Antre",
		["{npc:3156}, the warlock trainer at the back of the cave"] = "{npc:3156}, le maître des démonistes au fond de la grotte",
		["{npc:3157}, the shaman trainer beside the Den"] = "{npc:3157}, le maître des chamans à côté de l'Antre",
		["{npc:3159}, at the back of the cave; below ground"] = "{npc:3159}, au fond de la grotte ; sous terre",
		["{npc:3171}: {npc:3352} in {zone:1454} teaches {spell:5149}"] = "{npc:3171} : {npc:3352}, à {zone:1454}, enseigne {spell:5149}",
		["{npc:3175} takes it once your {skill:186} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:3175} prend la quête une fois votre compétence {skill:186} à 20 : récoltez ou fabriquez d'ici là, le guide continue en attendant.",
		["{npc:3191}: Camping 101 asks you to learn it"] = "{npc:3191} : la quête Camping 101 vous demande de l'apprendre",
		["{npc:3192} waits at the top of the keep; his key opens the chest beside him, which holds the {item:4881}."] = "{npc:3192} attend au sommet du donjon ; sa clé ouvre le coffre à côté de lui, qui contient la {item:4881}.",
		["{npc:3287} lies wounded at the foot of the hills north-west of the Den."] = "{npc:3287} gît blessé au pied des collines au nord-ouest de l'Antre.",
		["{npc:5875} stands in the {object:172960}, the canyon under the {object:172982}. Hand him the {item:6535}, then use the {item:7464} on the summoning circle beside him and defeat the voidwalker to bind it.\nCareful: the voidwalker you summon hits hard and it is the fight Warlocks die to most in {zone:1454}: start at full health and mana, send your imp in, keep Corruption and Immolate on it, and use a healthstone if you have one."] = "{npc:5875} se tient dans {object:172960}, le canyon sous {object:172982}. Remettez-lui {item:6535}, puis utilisez les {item:7464} sur le cercle d'invocation à côté de lui et vainquez le marcheur du Vide pour le lier.\nAttention : le marcheur du Vide que vous invoquez frappe fort et c'est le combat où les Démonistes meurent le plus à {zone:1454} : commencez avec toute votre vie et tout votre mana, envoyez votre diablotin, maintenez Corruption et Immolation sur lui, et utilisez une pierre de soins si vous en avez une.",
		["{npc:5880}, the mage trainer in Sen'jin"] = "{npc:5880}, le maître des mages de Sen'jin",
		["{npc:5884}, the mage trainer, at the entrance to the Den"] = "{npc:5884}, le maître des mages, à l'entrée de l'Antre",
		["{npc:5887} stands outside the Den. {area:639} is the hill just south of it: drink the {item:6635} there to see the {npc:5891}, then take the {item:6656} back to {npc:5887}."] = "{npc:5887} se tient devant l'Antre. {area:639} est la colline juste au sud : buvez-y le {item:6635} pour voir la {npc:5891}, puis rapportez le {item:6656} à {npc:5887}.",
		["{npc:5887}: {npc:5873} and your {item:5175}"] = "{npc:5887} : {npc:5873} et votre {item:5175}",
		["{npc:5891}, on {area:639}"] = "{npc:5891}, sur {area:639}",
		["{npc:5943} takes it once your {skill:129} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:5943} prend la quête une fois votre compétence {skill:129} à 20 : récoltez ou fabriquez d'ici là, le guide continue en attendant.",
		["{npc:6786} stands on the road at the valley's eastern exit."] = "{npc:6786} se tient sur la route, à la sortie est de la vallée.",
		["{npc:6928}, inside"] = "{npc:6928}, à l'intérieur",
		["{npc:9796}, by the cooking fire"] = "{npc:9796}, près du feu de cuisine",
		["{quest:790}, a large scorpid (level 4), prowls the slope just west of the Den, below {npc:3287}, on the way north to the {area:365}."] = "{quest:790}, un grand scorpide (niveau 4), rôde sur la pente juste à l'ouest de l'Antre, en contrebas de {npc:3287}, sur la route du nord vers {area:365}.",
		["{quest:828} camps on the hill west of the naga beach, south of {quest:827}."] = "{quest:828} campe sur la colline à l'ouest de la plage des nagas, au sud de {quest:827}.",
		["{zone:1454}'s main gate is just west of {area:817}. {npc:5875} stands in the {object:172960}, the canyon under the {object:172982}."] = "La porte principale d'{zone:1454} se trouve juste à l'ouest de {area:817}. {npc:5875} se tient dans {object:172960}, le canyon sous {object:172982}.",
		["{zone:1454}'s {object:172982}"] = "{object:172982} d'{zone:1454}",
} end)()
t.guides["forever/horde/skyborne/01-zephras-isle"] = (function() return {
		["/sit by {npc:263664}'s campfire until you get {spell:1229451}"] = "/sit près du feu de camp de {npc:263664} jusqu'à obtenir {spell:1229451}",
		["Aanders and the fallen guards are just south-west of the tower. Take Raani's feather and the Shadowsong signet from the bodies."] = "Aanders et les gardes tombés sont juste au sud-ouest de la tour. Prenez la Plume porte-bonheur de Raani et la chevalière Shadowsong sur les corps.",
		["Back at {quest:92529}: Stormcallers and {npc:251662} fill the village, the Supply Caches stand among the houses and {npc:251966} waits at its south-east end."] = "De retour à {quest:92529} : des Mande-foudre al'aketh et {npc:251662} emplissent le village, les Caches de fournitures ({object:576179}) se trouvent entre les maisons et {npc:251966} attend à son extrémité sud-est.",
		["Back to Boro in {area:16635} with the Signet."] = "Retournez voir Boro à {area:16635} avec la Chevalière.",
		["Back to {area:16635}"] = "Retour à {area:16635}",
		["Back to {area:16638}"] = "Retour à {area:16638}",
		["Back to {npc:268592}. Wait for him to light the {npc:268762}, then carry the flame straight to the {npc:268679} beside {npc:252382} in {area:16638} before the timer runs out."] = "Retournez voir {npc:268592}. Attendez qu'il allume {npc:268762}, puis portez la flamme directement jusqu'à {npc:268679}, à côté de {npc:252382} à {area:16638}, avant la fin du temps imparti.",
		["Back up from the den to {npc:257551} and {npc:251366} in the village before heading south-west to {npc:252095}: the road from her camp leads on south to Shen'dar."] = "Remontez de la tanière jusqu'à {npc:257551} et {npc:251366}, au village, avant de partir vers le sud-ouest voir {npc:252095} : la route qui part de son camp continue vers le sud jusqu'à Shen'dar.",
		["Below ground"] = "Sous terre",
		["Boro and {npc:251373}, while you stand beside them"] = "Boro et {npc:251373}, en restant à côté d'eux",
		["Cast {spell:1259686} near the {object:460001}"] = "Lancez {spell:1259686} près de la Convergence élémentaire",
		["Class trainer"] = "Maître de classe",
		["Find {npc:258130}"] = "Trouvez {npc:258130}",
		["Follow the road south to {area:16624}, in the middle of the isle. {npc:251523} stands on its east side, {npc:251902} in the middle, {npc:254089} just north-west of her, {npc:263664} by the campfire on the west side. With a profession learned, {npc:263664} also offers its Camping 101: its trainer stands in the village."] = "Suivez la route vers le sud jusqu'à {area:16624}, au milieu de l'île. {npc:251523} se tient du côté est, {npc:251902} au milieu, {npc:254089} juste au nord-ouest d'elle, {npc:263664} près du feu de camp du côté ouest. Une fois un métier appris, {npc:263664} propose aussi la quête Camping 101 correspondante : son maître se tient dans le village.",
		["Head north into {area:16631}; {npc:257944} camps at its southern edge."] = "Allez vers le nord dans la {area:16631} ; {npc:257944} campe à sa lisière sud.",
		["Head north-east to the {area:17675}. The Al'Aketh camp is just west of it, with {npc:252666} at its north end. Every cultist can drop a windstone charm."] = "Dirigez-vous vers le nord-est jusqu'à {area:17675}. Le camp al'aketh se trouve juste à l'ouest, avec {npc:252666} à son extrémité nord. Chaque sectateur peut lâcher un charme de pierre de vent.",
		["Head south-west to the {area:17674}. {npc:252155} is at the top; the {item:254871} lies beside him."] = "Allez au sud-ouest jusqu'à la {area:17674}. {npc:252155} est au sommet ; {item:254871} se trouve à côté de lui.",
		["Heal the injured druids in the Nightfang Den"] = "Soignez les druides blessés dans la tanière des Crocs-de-la-nuit",
		["Hungry Bandits"] = "Bandits affamés",
		["Innkeeper {npc:255940}, by the west gate"] = "L'aubergiste {npc:255940}, près de la porte ouest",
		["Into {zone:1412}"] = "Vers {zone:1412}",
		["Into {zone:1413}"] = "Vers les {zone:1413}",
		["Jump off the top of the watchtower and use {spell:1259416} to float down to {npc:251361}, west of the tower."] = "Sautez du haut de la tour de guet et utilisez {spell:1259416} pour descendre en planant jusqu'à {npc:251361}, à l'ouest de la tour.",
		["Learn the flight path from {npc:3615} on the tower platform. {area:380}' own quests come after {zone:1421}, in the {zone:1413} guide."] = "Apprenez le trajet aérien auprès de {npc:3615}, sur la plateforme de la tour. Les quêtes de {area:380} elle-même viennent après la {zone:1421}, dans le guide des {zone:1413}.",
		["Leave {zone:2521} to {zone:1412}"] = "Quittez {zone:2521} pour {zone:1412}",
		["Listen to {npc:252448}'s story"] = "Écoutez l'histoire de {npc:252448}",
		["Listen to {npc:256083}"] = "Écoutez {npc:256083}",
		["Northern {zone:1412}"] = "Nord de {zone:1412}",
		["On the road south-east to {area:16638}, {npc:273017} watches the {quest:98512} just north of him."] = "Sur la route du sud-est vers {area:16638}, {npc:273017} surveille les {quest:98512} juste au nord de lui.",
		["On your way north from Valennia, {npc:255853} waits by the falls north-east of you, just north of the {area:17675}: from the ridge above them, glide down with {spell:1259416}."] = "En repartant vers le nord depuis Valennia, {npc:255853} attend près des chutes au nord-est, juste au nord de {area:17675} : depuis la crête qui les surplombe, descendez en planant avec {spell:1259416}.",
		["Pesky Cirrusflies and {npc:250873} roam the grove just south-east of the village."] = "Des Mouches-cirrus agaçantes et des {npc:250873} parcourent le bosquet juste au sud-est du village.",
		["Portal to {area:16630}"] = "Portail vers {area:16630}",
		["Prideclaws and Galestriders share the meadows around {area:16624}; the Galestriders graze thickest just west of it. They drop both the Small Eggs and the {item:5469} for {npc:251905}."] = "Fièregriffes et Trotteurs des trombes se partagent les prairies autour de {area:16624} ; les Trotteurs des trombes sont les plus nombreux juste à l'ouest. Ils lâchent à la fois les Petits œufs et la {item:5469} pour {npc:251905}.",
		["Raw Windstones"] = "Pierres de vent brutes ({object:613286})",
		["Ripe Stormapples"] = "Pommes d’orage mûres",
		["Shen'dar bounty board"] = "Tableau des primes de Shen'dar",
		["Skyhoppers"] = "Sauteciels",
		["Skyhoppers hop about the fields just west of Valennia."] = "Des Sauteciels ({npc:251727}) sautillent dans les champs juste à l'ouest de Valennia.",
		["Spread the {item:278078} off {area:1641}"] = "Répandez l'{item:278078} depuis {area:1641}",
		["Stormapples and flutterfly dust lie all over the orchard; Hungry Bandits raid it. Galestriders graze in the fields east of it. The broken construct floats at the orchard's north edge."] = "Des Pommes d’orage mûres et de la Poussière de voltemouche jonchent le verger ; des Bandits affamés ({npc:252802}) le pillent. Des trotteurs des trombes paissent dans les champs à l'est. L'assemblage brisé flotte à la lisière nord du verger.",
		["Take the Portal to {area:16630} in the shrine up to the heights. Fight east along the ledge to the Peacekeepers at its end, ride the wind current up to the upper terrace and tell {npc:252475} you are ready. Leave the {object:617084} up there alone until Rohash has withdrawn; then it takes you straight back to town."] = "Prenez le portail vers {area:16630} dans le sanctuaire pour monter sur les hauteurs. Frayez-vous un chemin vers l'est le long de la corniche jusqu'aux Gardiens de la paix au bout, empruntez le courant d'air jusqu'à la terrasse supérieure et dites à {npc:252475} que vous êtes prêt. Ne touchez pas au portail vers Valanaar là-haut tant que Rohash ne s'est pas retiré ; ensuite, il vous ramène directement en ville.",
		["Take {item:277267} to {npc:268592} at the Shrine of Flames, south-west of {area:16638}, then head west into the {area:16623}: {npc:268605}'s home is in the hills south of the Windsong Crawlers' lakes."] = "Apportez {item:277267} à {npc:268592} au sanctuaire des Flammes, au sud-ouest de {area:16638}, puis partez vers l'ouest dans {area:16623} : la demeure de {npc:268605} se trouve dans les collines au sud des lacs des Clampants chantevent.",
		["Take {zone:1456}'s west lift down: the road at its foot runs south-east across {zone:1412} to the {zone:1413}."] = "Descendez par l'ascenseur ouest des {zone:1456} : la route à son pied traverse {zone:1412} vers le sud-est jusqu'aux {zone:1413}.",
		["Tame {npc:250874}"] = "Apprivoisez : {npc:250874}",
		["Tame {npc:251707}"] = "Apprivoisez : {npc:251707}",
		["Tame {npc:254588}"] = "Apprivoisez : {npc:254588}",
		["Tell {npc:252800} you're ready"] = "Dites à {npc:252800} que vous êtes prêt",
		["The Al'Aketh camp"] = "Le camp al'aketh",
		["The Enchanted Gyrozephyrs lie under water far to the north, east of {area:16624} and south-west of {area:16625}."] = "Les Gyrozéphyrs enchantés reposent sous l'eau loin au nord, à l'est de {area:16624} et au sud-ouest de {area:16625}.",
		["The Highwayman Bandits hold the hills north of {area:16663}; they drop the Blood-Stained Bandit Masks."] = "Les Bandits de grand chemin tiennent les collines au nord de {area:16663} ; ils lâchent les Masques de bandit tachés de sang.",
		["The Raw Windstones are blue crystals on the slopes around the village."] = "Les Pierres de vent brutes ({object:613286}) sont des cristaux bleus sur les pentes autour du village.",
		["The apprentices practise north-east of the village.\nThe bandit camps are north-east of the village; \"Badwind\" Bennic holds the top camp. Bandits carry the stolen windstones."] = "Les apprentis s'entraînent au nord-est du village.\nLes camps de bandits se trouvent au nord-est du village ; \"Badwind\" Bennic tient le camp du haut. Les bandits portent les pierres de vent volées.",
		["The hermit lives at {area:16625}'s west shore."] = "L'ermite vit sur la rive ouest du {area:16625}.",
		["The hippogryph nests are north-west of the {area:17674}, west of {quest:92529}. The Matriarch sits at their western end; {item:263493} lies on the ground around the nests."] = "Les nids d'hippogriffes se trouvent au nord-ouest de {area:17674}, à l'ouest de {quest:92529}. La Matriarche se tient à leur extrémité ouest ; {item:263493} jonche le sol autour des nids.",
		["The orchard"] = "Le verger",
		["The queen hovers at the south-east end of the grove, on your way back from the stones."] = "La reine plane à l'extrémité sud-est du bosquet, sur le chemin du retour depuis les pierres.",
		["The road from {zone:1412} meets the {area:458} at {area:378}: {npc:10378}, the wind rider master, stands beside {npc:3418} on your way north to the Crossroads."] = "La route de {zone:1412} rejoint la {area:458} au {area:378} : {npc:10378}, le maître des coursiers du vent, se tient à côté de {npc:3418} sur votre chemin vers le nord, jusqu'à la Croisée.",
		["The standing stones"] = "Les pierres dressées",
		["The turncoat"] = "Le traître",
		["The turncoat's house is in the {area:16626} north-west of {area:16638}, just north of {npc:273017}."] = "La maison du traître se trouve dans les {area:16626}, au nord-ouest de {area:16638}, juste au nord de {npc:273017}.",
		["The {area:16629}"] = "{area:16629}",
		["The {area:16629} is north of {area:16638}. Fight through the guards up to {npc:253576} at its east side."] = "Le {area:16629} est au nord de {area:16638}. Frayez-vous un chemin à travers les gardes jusqu'à {npc:253576}, du côté est.",
		["The {area:17674}"] = "{area:17674}",
		["The {area:17675}"] = "{area:17675}",
		["The {item:260881} lies in a cave in the hills north-west of {npc:256083}."] = "{item:260881} se trouve dans une grotte des collines au nord-ouest de {npc:256083}.",
		["The {object:148418}"] = "{object:148418}",
		["To {zone:1454}"] = "Vers {zone:1454}",
		["Underwater"] = "Sous l'eau",
		["Upstairs"] = "À l'étage",
		["Use the {item:278078} at the ceremonial mat and burner on the south-facing cliff of {area:1641}."] = "Utilisez l'{item:278078} sur le tapis et le brûleur de cérémonie, sur la falaise sud de {area:1641}.",
		["Valennia asks you to hear out both leaders: {npc:251968} of the Horde and {npc:252475} of the Alliance. {npc:252475}'s name shows red to you, but he talks to you all the same, and the quest needs both."] = "Valennia vous demande d'écouter les deux chefs : {npc:251968} pour la Horde et {npc:252475} pour l'Alliance. Le nom de {npc:252475} apparaît en rouge pour vous, mais il vous parle quand même, et la quête requiert les deux.",
		["Warlock trainer"] = "Maître des démonistes",
		["While you're here: learn Staves from {npc:11869} (10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Tant que vous y êtes : apprenez les Bâtons auprès de {npc:11869} (10 pièces d'argent) ; l'arme de mêlée d'un chasseur compte surtout pour ses caractéristiques, et les armes à deux mains en apportent le plus.",
		["While you're here: learn {spell:199} from {npc:11869} (10 silver); two-handers level a Warrior fastest."] = "Tant que vous y êtes : apprenez {spell:199} auprès de {npc:11869} (10 pièces d'argent) ; les armes à deux mains font monter un guerrier le plus vite.",
		["You leave the isle for good. {npc:259119} waits where the airship lands."] = "Vous quittez l'île pour de bon. {npc:259119} attend là où se pose le dirigeable.",
		["You wake in {area:16635}, in the north of the isle. {npc:251362} stands by the path, {npc:251361} at the village centre."] = "Vous vous réveillez à {area:16635}, au nord de l'île. {npc:251362} se tient près du chemin, {npc:251361} au centre du village.",
		["drink the {item:6635} at the {area:16988}, just east of the village, to see the {npc:251166}"] = "buvez {item:6635} à {area:16988}, juste à l'est du village, pour voir la {npc:251166}",
		["search the dead cultist in the house"] = "fouillez le cultiste mort dans la maison",
		["search the wardrobe"] = "fouillez l'armoire",
		["talk to {npc:251684}"] = "parlez à {npc:251684}",
		["talk to {npc:251902}"] = "parlez à {npc:251902}",
		["talk to {npc:251968}"] = "parlez à {npc:251968}",
		["talk to {npc:252155}"] = "parlez à {npc:252155}",
		["talk to {npc:252476}"] = "parlez à {npc:252476}",
		["talk to {npc:253844}"] = "parlez à {npc:253844}",
		["talk to {npc:257554}"] = "parlez à {npc:257554}",
		["tame one with {npc:252389}'s first {item:15908} while you are among them"] = "apprivoisez-en un avec le premier {item:15908} de {npc:252389} pendant que vous êtes parmi eux",
		["the bounty board"] = "le tableau des primes",
		["{area:16622}: kill these as you meet them"] = "{area:16622} : tuez-les au passage",
		["{area:16623}: kill these as you meet them"] = "{area:16623} : tuez-les au passage",
		["{area:16624} hand-ins"] = "Quêtes à rendre à {area:16624}",
		["{area:16624} turn-ins"] = "Quêtes à rendre à {area:16624}",
		["{area:16624}: kill these as you meet them"] = "{area:16624} : tuez-les au passage",
		["{area:16626}: kill these as you meet them"] = "{area:16626} : tuez-les au passage",
		["{area:16631}: kill these as you meet them"] = "{area:16631} : tuez-les au passage",
		["{area:16635} turn-ins"] = "Quêtes à rendre à {area:16635}",
		["{area:16663} is west of {area:16638} along the coast road."] = "Le {area:16663} est à l'ouest de {area:16638}, sur la route côtière.",
		["{item:251924}: the Al'Aketh in {npc:252095}'s camp carry it"] = "{item:251924} : les Al'aketh du camp près de {npc:252095} le portent",
		["{item:257128} cones grow south of the hermit; the Wind Hollows drift east of the lake and also drop the Wind Hollow Essences for {npc:254344}'s {quest:93736}. The refugees' belongings lie along the north shore of {area:16625}; {npc:259013} is at its north-west end."] = "Les cônes de {item:257128} poussent au sud de l'ermite ; les Creux du vent dérivent à l'est du lac et laissent aussi tomber les Essences de creux du vent pour {quest:93736} de {npc:254344}. Les affaires des réfugiés se trouvent le long de la rive nord du {area:16625} ; {npc:259013} est à son extrémité nord-ouest.",
		["{item:265105} grows around {npc:257944}'s camp and Shriekings fly over it. The Al'Aketh camp east of her holds the {item:265141}."] = "{item:265105} pousse autour du camp d'{npc:257944} et des criailleuses le survolent. Le camp al'aketh à l'est d'elle contient {item:265141}.",
		["{item:278079}, from {npc:3014}"] = "{item:278079}, chez {npc:3014}",
		["{item:278080}, from {npc:3012}"] = "{item:278080}, chez {npc:3012}",
		["{item:278081}, from {npc:3005}"] = "{item:278081}, chez {npc:3005}",
		["{item:278083}, from {npc:3027}"] = "{item:278083}, chez {npc:3027}",
		["{npc:2127} in {zone:1420}; {area:16638} has no warlock trainer"] = "{npc:2127} ({zone:1420}) ; {area:16638} n'a pas de maître des démonistes",
		["{npc:249363} stands at the {area:17678}, east of the village. {npc:251143} and Al'Aketh Converts gather just north of her. The {object:460001} is just north-east of her: cast your {spell:1259686} racial ability next to it."] = "{npc:249363} se tient près de {area:17678}, à l'est du village. Des {npc:251143} et des Convertis al'aketh se rassemblent juste au nord d'elle. La Convergence élémentaire se trouve juste au nord-est d'elle : lancez votre technique raciale {spell:1259686} à côté.",
		["{npc:250926} prowl the slopes south-west of the village, on the way to {npc:252095}.\nThe Ursera den is west of the village. {npc:251115}, their matriarch, sits at its far end."] = "Des {npc:250926} rôdent sur les pentes au sud-ouest du village, sur le chemin de {npc:252095}.\nLa tanière des Ursera se trouve à l'ouest du village. {npc:251115}, leur matriarche, se tient tout au fond.",
		["{npc:251361}'s errands"] = "Les commissions de {npc:251361}",
		["{npc:251361}: a note from your trainer"] = "{npc:251361} : un mot de votre maître",
		["{npc:251361}: examine the {item:282418}"] = "{npc:251361} : examinez {item:282418}",
		["{npc:251361}: read the {item:9547}"] = "{npc:251361} : lisez {item:9547}",
		["{npc:251361}: the {item:4100}"] = "{npc:251361} : {item:4100}",
		["{npc:251373}, the druid trainer, on the ground floor of the tree behind {npc:251361}"] = "{npc:251373}, le maître des druides, au rez-de-chaussée de l'arbre derrière {npc:251361}",
		["{npc:251374}, beside {npc:251361}"] = "{npc:251374}, à côté de {npc:251361}",
		["{npc:251374}: {npc:5873} and your {item:5175}"] = "{npc:251374} : {npc:5873} et votre {item:5175}",
		["{npc:251376}, beside {npc:251361}"] = "{npc:251376}, à côté de {npc:251361}",
		["{npc:251389}, in the watchtower"] = "{npc:251389}, dans la tour de guet",
		["{npc:251523} waits in {area:16624} for what you found in the wardrobe."] = "{npc:251523} attend à {area:16624} ce que vous avez trouvé dans l'armoire.",
		["{npc:251905}, {npc:251906}, {npc:251991}, {npc:252172} and {npc:251523} all stand in {area:16624}. If you are still short of {item:5469}, the Galestriders graze just west of the village; the Al'Aketh camps south and south-east of it are a level or two higher."] = "{npc:251905}, {npc:251906}, {npc:251991}, {npc:252172} et {npc:251523} se tiennent tous à {area:16624}. S'il vous manque encore de la {item:5469}, les Trotteurs des trombes paissent juste à l'ouest du village ; les camps Al'Aketh au sud et au sud-est sont d'un niveau ou deux de plus.",
		["{npc:251905}: Camping 101 asks you to learn it"] = "{npc:251905} : la quête Camping 101 vous demande de l'apprendre",
		["{npc:251913} takes it once your {skill:164} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:251913} prend la quête une fois votre compétence {skill:164} à 20 : récoltez ou fabriquez d'ici là, le guide continue en attendant.",
		["{npc:251964}, in the watchtower"] = "{npc:251964}, dans la tour de guet",
		["{npc:251968} sends you on to Kalimdor. Once you have trained, board the skycutter at the dock on {area:16638}'s south-west edge: it flies to northern {zone:1412}, where {npc:259119} waits."] = "{npc:251968} vous envoie vers Kalimdor. Une fois entraîné, montez à bord du coupe-ciel au quai, à la lisière sud-ouest de {area:16638} : il vole jusqu'au nord de {zone:1412}, où {npc:259119} vous attend.",
		["{npc:251992} takes it once your {skill:356} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:251992} prend la quête une fois votre compétence {skill:356} à 20 : récoltez ou fabriquez d'ici là, le guide continue en attendant.",
		["{npc:251993} takes it once your {skill:165} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:251993} prend la quête une fois votre compétence {skill:165} à 20 : récoltez ou fabriquez d'ici là, le guide continue en attendant.",
		["{npc:252095} waits in {area:16622}, south-west of the village. The Al'Aketh camp is just beyond her; {npc:256935} leads it.\nCareful: {npc:256935} casts shocks; drag him clear of the other cultists before fighting so they don't join in."] = "{npc:252095} attend à {area:16622}, au sud-ouest du village. Le camp al'aketh se trouve juste derrière elle ; {npc:256935} le dirige.\nAttention : {npc:256935} lance des horions ; éloignez-le des autres sectateurs avant de le combattre pour qu'ils ne s'en mêlent pas.",
		["{npc:252359} stands on {area:16638}'s east side. {npc:255853} waits by the falls just north of the {area:17675}: leave town to the north, climb the ridge east of the road and glide down to him with {spell:1259416}."] = "{npc:252359} se tient du côté est de {area:16638}. {npc:255853} attend près des chutes juste au nord de {area:17675} : quittez la ville par le nord, grimpez sur la crête à l'est de la route et descendez en planant jusqu'à lui avec {spell:1259416}.",
		["{npc:252377} stands beside {npc:256083}, just north-west of {area:16638}."] = "{npc:252377} se tient à côté de {npc:256083}, juste au nord-ouest de {area:16638}.",
		["{npc:252377}, beside {npc:256083}: {quest:94003}"] = "{npc:252377}, à côté de {npc:256083} : {quest:94003}",
		["{npc:252382}, beside {npc:251968}: {quest:97243}"] = "{npc:252382}, à côté de {npc:251968} : {quest:97243}",
		["{npc:252382}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:252382} : {npc:2523}, votre {item:5176} et {item:263412}",
		["{npc:252383}, upstairs"] = "{npc:252383}, à l'étage",
		["{npc:252389} takes back the first {item:15908} and hands you two more, one at a time: Ornery Galestriders and Vuldren Alphas roam the fields just north of her. Tame each with its rod and bring the rod back to her. {npc:254411}, beside her, teaches {spell:5149}."] = "{npc:252389} reprend le premier {item:15908} et vous en donne deux autres, l'un après l'autre : des Trotteurs des trombes hargneux et des Alphas vuldrènes parcourent les champs juste au nord d'elle. Apprivoisez chacun avec son bâtonnet et rapportez-lui le bâtonnet. {npc:254411}, à côté d'elle, enseigne {spell:5149}.",
		["{npc:252389}, a few steps west of {npc:257006}: {quest:94978}, the first rod"] = "{npc:252389}, à quelques pas à l'ouest de {npc:257006} : {quest:94978}, le premier bâtonnet",
		["{npc:252448} and {npc:256083}"] = "{npc:252448} et {npc:256083}",
		["{npc:252476}, upstairs"] = "{npc:252476}, à l'étage",
		["{npc:253372}, inside"] = "{npc:253372}, à l'intérieur",
		["{npc:253590}, upstairs"] = "{npc:253590}, à l'étage",
		["{npc:253622}, {npc:258130} and {npc:258134} are in the cult camp east of {npc:257944}. {npc:254151} stands at its edge. Haalien also drops a {quest:94490}: read it to start the next quest. For {quest:94489}, enter the Nightfang Den, heal 7 injured druids and find {npc:258130}."] = "{npc:253622}, {npc:258130} et {npc:258134} sont dans le camp du culte à l'est d'{npc:257944}. {npc:254151} se tient à sa lisière. Haalien lâche aussi {quest:94490} : lisez-la pour commencer la quête suivante. Pour {quest:94489}, entrez dans la tanière des Crocs-de-la-nuit, soignez 7 druides blessés et trouvez {npc:258130}.",
		["{npc:254344}, beside {npc:251968}"] = "{npc:254344}, à côté de {npc:251968}",
		["{npc:254589} lurks south of the village, among the Prideclaws. {npc:254589} is elite: grouping up is advised."] = "{npc:254589} rôde au sud du village, parmi les Fièregriffes. {npc:254589} est un élite : mieux vaut être en groupe.",
		["{npc:256083} stands in the {area:16626} just north-west of town."] = "{npc:256083} se tient dans les {area:16626}, juste au nord-ouest de la ville.",
		["{npc:256247} waits on the road north of {area:16638}, towards the {area:16629}."] = "{npc:256247} attend sur la route au nord de {area:16638}, en direction du {area:16629}.",
		["{npc:257006} and {npc:252448}"] = "{npc:257006} et {npc:252448}",
		["{npc:257006} waits inside a house on {area:16638}'s western edge; {npc:252448} is close by."] = "{npc:257006} attend dans une maison à la lisière ouest de {area:16638} ; {npc:252448} est tout près.",
		["{npc:257006}, inside"] = "{npc:257006}, à l'intérieur",
		["{npc:257018} takes it once your {skill:129} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:257018} prend la quête une fois votre compétence {skill:129} à 20 : récoltez ou fabriquez d'ici là, le guide continue en attendant.",
		["{npc:257019} takes it once your {skill:171} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:257019} prend la quête une fois votre compétence {skill:171} à 20 : récoltez ou fabriquez d'ici là, le guide continue en attendant.",
		["{npc:257022} takes it once your {skill:186} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:257022} prend la quête une fois votre compétence {skill:186} à 20 : récoltez ou fabriquez d'ici là, le guide continue en attendant.",
		["{npc:257024} takes it once your {skill:393} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:257024} prend la quête une fois votre compétence {skill:393} à 20 : récoltez ou fabriquez d'ici là, le guide continue en attendant.",
		["{npc:257196} holds the {item:263993} on the west side of the shrine."] = "{npc:257196} tient {item:263993} du côté ouest du sanctuaire.",
		["{npc:257554} and {npc:263113} stand at the top of the watchtower, a few steps north-east of {npc:251368}."] = "{npc:257554} et {npc:263113} se tiennent au sommet de la tour de guet, à quelques pas au nord-est de {npc:251368}.",
		["{npc:257944} again"] = "De nouveau {npc:257944}",
		["{npc:257944}, last time"] = "{npc:257944}, une dernière fois",
		["{npc:258443} has her lair in a cave in the bluffs just south of the turncoat's house, where the {area:16623} meet the {area:16626}."] = "{npc:258443} a son repaire dans une grotte des falaises juste au sud de la maison du traître, là où {area:16623} rejoignent {area:16626}.",
		["{npc:259118}, by the landing: for {npc:3033} in {zone:1456}"] = "{npc:259118}, près de l'aire d'atterrissage : pour {npc:3033} à {zone:1456}",
		["{npc:259119}: keep it: Thrall in {zone:1454}, at the start of the next guide"] = "{npc:259119} : gardez-la : Thrall à {zone:1454}, au début du guide suivant",
		["{npc:268592}, at the Shrine of Flames just south-east of the orchard"] = "{npc:268592}, au sanctuaire des Flammes juste au sud-est du verger",
		["{npc:268602}, on the hill west of the falls just north of the watchtower"] = "{npc:268602}, sur la colline à l'ouest des chutes, juste au nord de la tour de guet",
		["{npc:269068} wants tauren incense: buy its four parts from {npc:3014} the herbalist, {npc:3012} the enchanting supplier, {npc:3005} the leatherworking supplier and {npc:3027} the cooking supplier, then combine them into {item:278078}."] = "{npc:269068} veut de l'encens tauren : achetez ses quatre ingrédients à {npc:3014} l'herboriste, {npc:3012} la fournisseuse en enchantement, {npc:3005} le fournisseur en travail du cuir et {npc:3027} le fournisseur en cuisine, puis combinez-les en {item:278078}.",
		["{npc:5543} stands in the {area:2197}, the cave under {area:1640}: go down inside, the arrow cannot tell the floors apart."] = "{npc:5543} se tient dans les {area:2197}, la grotte sous le {area:1640} : descendez par l'intérieur, la flèche ne distingue pas les étages.",
		["{quest:92529} lies south of Shen'dar. {npc:257065} meets you at its edge; search the wardrobe in the house behind him."] = "{quest:92529} se trouve au sud de Shen’dar. {npc:257065} vous attend à son entrée ; fouillez l'armoire de la maison derrière lui.",
		["{zone:1454}'s {object:172982}"] = "{object:172982} d'{zone:1454}",
} end)()
t.guides["forever/horde/tauren/01-mulgore"] = (function() return {
		["/sit by Kaga's campfire until you get {spell:1229451}"] = "/sit près du feu de camp de Kaga jusqu'à obtenir {spell:1229451}",
		["Back east to {area:358}: the Bristleback Shamans stand among the quilboar there."] = "Retournez à l'est jusqu'à {area:358} : les Chamans Dos-hirsute s'y tiennent parmi les huran.",
		["Back north-west up to {area:221}."] = "Remontez vers le nord-ouest jusqu'à {area:221}.",
		["Back to {npc:5888} in the camp. The {npc:5891} waits on the mesa east of the camp: drink the {item:6635} there to see it, then take the {item:6656} back to the Seer."] = "Retournez voir {npc:5888} au camp. La {npc:5891} attend sur la mesa à l'est du camp : buvez-y le {item:6635} pour la voir, puis rapportez le {item:6656} à la prophétesse.",
		["Back west to the camp."] = "Retournez à l'ouest jusqu'au camp.",
		["Battleboars graze north of the shrine; the Bristleback quilboar hold the ravine to the north-east. {npc:8554} stands at its eastern end, and the {object:3076} lies on the ground in the camp."] = "Les Sangliers de guerre paissent au nord du sanctuaire ; les huran Dos-hirsute tiennent le ravin au nord-est. {npc:8554} se tient à son extrémité est, et la {object:3076} gît par terre dans le camp.",
		["Below ground"] = "Sous terre",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}; the {quest:5930} sits in the north-western woods. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Lancez {spell:18960}. {npc:11802} se trouve à {area:2361} ; {quest:5930} se trouve dans les bois du nord-ouest. {npc:11802} se tient à l'étage de son bâtiment : montez par l'intérieur, la flèche ne distingue pas les étages.",
		["Class trainer"] = "Maître de classe",
		["Class turn-in in {area:1638}"] = "Quête de classe à rendre à {area:1638}",
		["Cross north-west past {zone:1456} to the {area:398} in the far north of {zone:1412}."] = "Traversez vers le nord-ouest au-delà de {zone:1456} jusqu'au {area:398}, à l'extrême nord de {zone:1412}.",
		["Cross to {area:1639}."] = "Traversez jusqu'au {area:1639}.",
		["Deathskip to {area:220}"] = "Mort volontaire jusqu'à {area:220}",
		["Die to the mobs at 63.7,78.4 ({npc:2954}): a death there sends you to this graveyard. Release your spirit and take the {npc:6491}'s resurrection."] = "Laissez-vous tuer par les monstres en 63.7,78.4 ({npc:2954}) : mourir là vous envoie à ce cimetière. Libérez votre esprit et acceptez la résurrection du {npc:6491}.",
		["Follow the road north out of {area:220}. {npc:265810} waits on the road just south of {area:222}; /sit by her campfire until you get {spell:1229451}. With a profession learned, Kaga also offers its Camping 101, which its trainer takes: in Bloodhoof or on the {zone:1456} stop."] = "Suivez la route vers le nord pour quitter {area:220}. {npc:265810} attend sur la route juste au sud de {area:222} ; /sit près de son feu de camp jusqu'à obtenir {spell:1229451}. Si vous avez appris un métier, Kaga propose aussi sa quête Camping 101, que reçoit le maître de ce métier : à Sabot-de-Sang ou lors de l'étape à {zone:1456}.",
		["From {area:1639}, take {zone:1456}'s north lift down: at its foot the way runs east along the ledge, then south-east across {zone:1412} to the {zone:1413}."] = "Depuis la {area:1639}, descendez par l'ascenseur nord des {zone:1456} : à son pied, le chemin longe la corniche vers l'est, puis traverse {zone:1412} vers le sud-est jusqu'aux {zone:1413}.",
		["Galak centaurs"] = "Centaures galak",
		["Head north to {area:225}, east of {zone:1456}. {npc:3233} stands at the foot of the rocks; the Bristleback Interlopers dig at the burial ground and the {npc:2994} waits on top."] = "Allez au nord jusqu'à {area:225}, à l'est de {zone:1456}. {npc:3233} se tient au pied des rochers ; les Intrus Dos-hirsute creusent dans le cimetière et l'{npc:2994} attend au sommet.",
		["Inside"] = "À l'intérieur",
		["Into {zone:1412}"] = "Vers {zone:1412}",
		["Into {zone:1413}"] = "Vers les {zone:1413}",
		["Leave {zone:1412} by the south-eastern pass and follow the road to the Crossroads. {npc:3448} stands at the south gate, {quest:860} by the inn, {npc:3615} on the tower platform. {area:380}' own quests come after {zone:1421}, in the {zone:1413} guide."] = "Quittez {zone:1412} par le col du sud-est et suivez la route jusqu'à la Croisée. {npc:3448} se tient à la porte sud, {quest:860} près de l'auberge, {npc:3615} sur la plateforme de la tour. Les quêtes de {area:380} elle-même viennent après la {zone:1421}, dans le guide des {zone:1413}.",
		["Over the bridge below {area:379} and south along the {zone:1411} bank of the river to where a narrow trail climbs the mountain: {npc:5900} keeps the shrine at the top. Mind the edges on the way up, and come back down the same trail."] = "Passez le pont sous le {area:379} et longez vers le sud la rive de la rivière côté {zone:1411} jusqu'à l'endroit où un sentier étroit grimpe dans la montagne : {npc:5900} garde le sanctuaire au sommet. Attention aux bords en montant, et redescendez par le même sentier.",
		["Plainstriders roam the mesa all around the camp: take their meat and feathers on the way back to {npc:2980}."] = "Des trotteurs des plaines parcourent la mesa tout autour du camp : prenez leur viande et leurs plumes en revenant voir {npc:2980}.",
		["Prairie Wolves, Wiry Swoops and Adult Plainstriders roam the plains around the village; the plains just south of it, toward the well, hold them without the Elder Plainstriders (8-9) and Prairie Wolf Alphas (9-10) that roam farther out."] = "Loups des prairies, Rapaces nerveux et Trotteurs des plaines adultes parcourent les plaines autour du village ; les plaines juste au sud, vers le puits, en abritent sans les Vieux trotteurs des plaines (8-9) ni les Loups Alpha des prairies (9-10) qui rôdent plus loin.",
		["Ride a lift up to the mesas. {npc:2995} keeps the wind riders on the central rise; {npc:3057} stands in the great tent there."] = "Prenez un ascenseur jusqu'aux mesas. {npc:2995} s'occupe des coursiers du vent sur le piton central ; {npc:3057} se tient dans la grande tente.",
		["Rogue trainer"] = "Maître des voleurs",
		["Spread the {item:278078} off {area:1641}"] = "Répandez l'{item:278078} depuis {area:1641}",
		["Tame it with the {item:15908}"] = "Apprivoisez-le avec le {item:15908}",
		["The Palemane gnolls hold {area:818}, south of the digsite and west of Bloodhoof. {npc:272203} is held in their camp: lead him out."] = "Les gnolls crin-pâle tiennent {area:818}, au sud du site de fouilles et à l'ouest de Sabot-de-Sang. {npc:272203} est retenu dans leur camp : escortez-le dehors.",
		["The Seer's tent stands at the foot of the cougars' hills."] = "La tente du prophète se dresse au pied des collines des pumas.",
		["The Windfury harpies hold {area:819}, north and west of the well."] = "Les harpies Furie-des-vents tiennent {area:819}, au nord et à l'ouest du puits.",
		["The dwarves of the {area:404} carry the Prospector's Picks. Smash them at the dwarves' forge in the digsite."] = "Les nains du {area:404} portent les Piolets de prospecteur. Brisez-les à la forge des nains, sur le site de fouilles.",
		["The incense burns out in ten minutes: run straight east along the southern hills to the {object:660739}."] = "L'encens se consume en dix minutes : courez tout droit vers l'est le long des collines du sud jusqu'au {object:660739}.",
		["The shrine of An'she and Mu'sha"] = "Le sanctuaire d'An'she et Mu'sha",
		["The stone stands in the pass out of {zone:1412}, on your way east. Use the {item:15710} there and defeat Lunaclaw."] = "La pierre se dresse dans le col qui sort de {zone:1412}, sur votre route vers l'est. Utilisez-y la {item:15710} et vainquez Lunegriffe.",
		["The well lies north of the village. Adult Plainstriders graze around it: they drop the {item:287505} for Kyle."] = "Le puits se trouve au nord du village. Des Trotteurs des plaines adultes paissent autour : ils laissent tomber la {item:287505} pour Kyle.",
		["The well lies south-east of the village. {npc:2988} camps beside it, and {quest:99079} stands on the {area:821} a little east."] = "Le puits se trouve au sud-est du village. {npc:2988} campe à côté, et {quest:99079} se tient sur les {area:821}, un peu à l'est.",
		["The {object:177525}"] = "{object:177525}",
		["Thunder Lizards and Lightning Hides graze on {area:369}, beside the road north to {zone:1454}; any of them can drop a {item:6486}. {npc:5810} takes them when the next guide passes {area:379}.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "Des Lézards-tonnerre et des Peaux-d'éclair paissent sur la {area:369}, à côté de la route du nord vers {zone:1454} ; n'importe lequel peut lâcher une {item:6486}. {npc:5810} les prend quand le prochain guide passe au {area:379}.\nAttention : Halikor, un élite de niveau 12, rôde sur la {area:369} parmi les lézards : repérez-le avant d'attaquer.",
		["Thunder lizards on the way north"] = "Lézards-tonnerre sur la route du nord",
		["To {zone:1454}"] = "Vers {zone:1454}",
		["Use the {item:278078} at the ceremonial mat and burner on the south-facing cliff of {area:1641}."] = "Utilisez l'{item:278078} sur le tapis et le brûleur de cérémonie, sur la falaise sud de {area:1641}.",
		["Warlock trainer"] = "Maître des démonistes",
		["While you're here: learn Staves from {npc:11869} (10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Tant que vous y êtes : apprenez les Bâtons auprès de {npc:11869} (10 pièces d'argent) ; l'arme de mêlée d'un chasseur compte surtout pour ses caractéristiques, et les armes à deux mains en apportent le plus.",
		["While you're here: learn {spell:199} from {npc:11869} (10 silver); two-handers level a Warrior fastest."] = "Tant que vous y êtes : apprenez {spell:199} auprès de {npc:11869} (10 pièces d'argent) ; les armes à deux mains font monter un guerrier le plus vite.",
		["You start on the mesa of {area:221}. {npc:2980} and the chief stand by the big tent in the middle."] = "Vous commencez sur la mesa de {area:221}. {npc:2980} et le chef se tiennent près de la grande tente au centre.",
		["{area:220}: kill these as you meet them"] = "{area:220} : tuez-les au passage",
		["{area:221}: kill these as you meet them"] = "{area:221} : tuez-les au passage",
		["{area:379} sits above the {area:814} bridge on the road to {zone:1454}: {npc:5810} stands beside {npc:3337}."] = "Le {area:379} domine le pont de la {area:814}, sur la route d'{zone:1454} : {npc:5810} se tient à côté de {npc:3337}.",
		["{item:278079}, from {npc:3014}"] = "{item:278079}, chez {npc:3014}",
		["{item:278080}, from {npc:3012}"] = "{item:278080}, chez {npc:3012}",
		["{item:278081}, from {npc:3005}"] = "{item:278081}, chez {npc:3005}",
		["{item:278083}, from {npc:3027}"] = "{item:278083}, chez {npc:3027}",
		["{item:4703}, at the digsite forge"] = "{item:4703}, à la forge du site de fouilles",
		["{item:5203}: Flatland Prowlers roam the plains around {area:225}"] = "{item:5203} : les Rôdeurs des basses plaines parcourent les plaines autour de {area:225}",
		["{npc:10278} takes it once your {skill:164} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:10278} prend la quête une fois votre compétence {skill:164} à 20 : récoltez ou fabriquez d'ici là, le guide continue en attendant.",
		["{npc:10378}, beside {npc:3418}"] = "{npc:10378}, à côté de {npc:3418}",
		["{npc:11047} takes it once your {skill:171} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:11047} prend la quête une fois votre compétence {skill:171} à 20 : récoltez ou fabriquez d'ici là, le guide continue en attendant.",
		["{npc:11051} takes it once your {skill:197} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:11051} prend la quête une fois votre compétence {skill:197} à 20 : récoltez ou fabriquez d'ici là, le guide continue en attendant.",
		["{npc:11071} takes it once your {skill:333} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:11071} prend la quête une fois votre compétence {skill:333} à 20 : récoltez ou fabriquez d'ici là, le guide continue en attendant.",
		["{npc:265810}: for {npc:10278}"] = "{npc:265810} : pour {npc:10278}",
		["{npc:265810}: for {npc:11047}"] = "{npc:265810} : pour {npc:11047}",
		["{npc:265810}: for {npc:11051}"] = "{npc:265810} : pour {npc:11051}",
		["{npc:265810}: for {npc:11071}"] = "{npc:265810} : pour {npc:11071}",
		["{npc:265810}: for {npc:3001}"] = "{npc:265810} : pour {npc:3001}",
		["{npc:265810}: for {npc:3013}"] = "{npc:265810} : pour {npc:3013}",
		["{npc:265810}: for {npc:3069}"] = "{npc:265810} : pour {npc:3069}",
		["{npc:265810}: for {npc:5938}"] = "{npc:265810} : pour {npc:5938}",
		["{npc:265810}: for {npc:5939}"] = "{npc:265810} : pour {npc:5939}",
		["{npc:265810}: for {npc:6290}"] = "{npc:265810} : pour {npc:6290}",
		["{npc:269068} wants tauren incense: buy its four parts from {npc:3014} the herbalist, {npc:3012} the enchanting supplier, {npc:3005} the leatherworking supplier and {npc:3027} the cooking supplier, then combine them into {item:278078}."] = "{npc:269068} veut de l'encens tauren : achetez ses quatre ingrédients à {npc:3014} l'herboriste, {npc:3012} la fournisseuse en enchantement, {npc:3005} le fournisseur en travail du cuir et {npc:3027} le fournisseur en cuisine, puis combinez-les en {item:278078}.",
		["{npc:277154} runs around the village: give him the {item:287505}"] = "{npc:277154} court dans le village : donnez-lui {item:287505}",
		["{npc:277182} stands at the north edge of the village. Kyle wants {item:287505} from plainstriders."] = "{npc:277182} se tient au bord nord du village. Kyle veut de la {item:287505} prise sur les trotteurs des plaines.",
		["{npc:277182}, at the north end of the village"] = "{npc:277182}, à l'extrémité nord du village",
		["{npc:2948}, for Hamuul in {zone:1456}"] = "{npc:2948}, pour Hamuul à {zone:1456}",
		["{npc:2950} walks around {area:16677}: look inside the circle on the map"] = "{npc:2950} se promène autour de {area:16677} : cherchez dans le cercle sur la carte",
		["{npc:2951}, below ground"] = "{npc:2951}, sous terre",
		["{npc:2981}, inside"] = "{npc:2981}, à l'intérieur",
		["{npc:2984} stands at the edge of the {area:404}, south of the well."] = "{npc:2984} se tient au bord du {area:404}, au sud du puits.",
		["{npc:2987}, beside {npc:269068}"] = "{npc:2987}, à côté de {npc:269068}",
		["{npc:2988} walks around here: look inside the circle on the map"] = "{npc:2988} se promène par ici : cherchez dans le cercle sur la carte",
		["{npc:2991} sits by the tent on the camp's eastern edge; the {object:2907} stands next to her."] = "{npc:2991} est assise près de la tente au bord est du camp ; {object:2907} est posée à côté d'elle.",
		["{npc:2993}, for {npc:3057} in {zone:1456}"] = "{npc:2993}, pour {npc:3057} à {zone:1456}",
		["{npc:3001} takes it once your {skill:186} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:3001} prend la quête une fois votre compétence {skill:186} à 20 : récoltez ou fabriquez d'ici là, le guide continue en attendant.",
		["{npc:3013} takes it once your {skill:182} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:3013} prend la quête une fois votre compétence {skill:182} à 20 : récoltez ou fabriquez d'ici là, le guide continue en attendant.",
		["{npc:3033} trains druids in the Cenarion Circle's tent on {area:1639}."] = "{npc:3033} entraîne les druides dans la tente du Cercle cénarien sur {area:1639}.",
		["{npc:3039}, beside {npc:3041}"] = "{npc:3039}, à côté de {npc:3041}",
		["{npc:3057}'s tent"] = "La tente de {npc:3057}",
		["{npc:3059}, the warrior trainer; inside"] = "{npc:3059}, le maître des guerriers ; à l'intérieur",
		["{npc:3060}, the druid trainer beside him"] = "{npc:3060}, le maître des druides à côté de lui",
		["{npc:3061}, the hunter trainer"] = "{npc:3061}, la maîtresse des chasseurs",
		["{npc:3062}, the shaman trainer in camp"] = "{npc:3062}, la maîtresse des chamans au camp",
		["{npc:3063}'s quest: beat three Novice Warriors (or players in duels) next to him."] = "Quête de {npc:3063} : battez trois Guerriers novices (ou des joueurs en duel) à côté de lui.",
		["{npc:3065} stands at the north end of {area:222}. Tame with the {item:15908}: an {npc:2956} on the plains, a {npc:2959} north of the village, a {npc:2970} to the north-west."] = "{npc:3065} se tient à l'extrémité nord de {area:222}. Apprivoisez avec {item:15908} : un {npc:2956} dans les plaines, un {npc:2959} au nord du village, un {npc:2970} au nord-ouest.",
		["{npc:3067}: Camping 101 asks you to learn it"] = "{npc:3067} : la quête Camping 101 vous demande de l'apprendre",
		["{npc:3069} takes it once your {skill:165} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:3069} prend la quête une fois votre compétence {skill:165} à 20 : récoltez ou fabriquez d'ici là, le guide continue en attendant.",
		["{npc:3069}, beside {npc:3067}: {quest:97934}"] = "{npc:3069}, à côté de {npc:3067} : {quest:97934}",
		["{npc:3155} in {zone:1411}; {zone:1412} has no rogue trainer"] = "{npc:3155} ({zone:1411}) ; {zone:1412} n'a pas de maître des voleurs",
		["{npc:3156} in {zone:1411}; {zone:1412} has no warlock trainer"] = "{npc:3156} ({zone:1411}) ; {zone:1412} n'a pas de maître des démonistes",
		["{npc:3209} walks around {area:221}: look inside the circle on the map"] = "{npc:3209} se promène autour de {area:221} : cherchez dans le cercle sur la carte",
		["{npc:3209}, next to {npc:2980}; walks around {area:221}: look inside the circle on the map"] = "{npc:3209}, à côté de {npc:2980} ; se promène dans {area:221} : cherchez à l'intérieur du cercle sur la carte",
		["{npc:3222} walks around {area:222}: look inside the circle on the map"] = "{npc:3222} se promène autour de {area:222} : cherchez dans le cercle sur la carte",
		["{npc:3418} stands at {area:378}, where the road from {zone:1412} meets the {area:458} north to the Crossroads."] = "{npc:3418} se tient au {area:378}, là où la route venant de {zone:1412} rejoint la {area:458} qui monte au nord vers la Croisée.",
		["{npc:3418}: for {npc:3429} at the Crossroads"] = "{npc:3418} : pour {npc:3429} à la Croisée",
		["{npc:3429}, by the wind rider tower"] = "{npc:3429}, près de la tour des coursiers du vent",
		["{npc:3441}: for {quest:860} at the Crossroads"] = "{npc:3441} : pour {quest:860} à la Croisée",
		["{npc:3483} sells armor on the north side of the Crossroads. His bundle goes to {npc:3615}, who sends it with you on the flight to {zone:1456} you take for {npc:3033} anyway."] = "{npc:3483} vend des armures du côté nord de la Croisée. Son paquet va à {npc:3615}, qui vous le confie pour le vol vers {zone:1456} que vous prenez de toute façon pour {npc:3033}.",
		["{npc:3615}, the wind rider master"] = "{npc:3615}, le maître des coursiers du vent",
		["{npc:5543} stands in the {area:2197}, the cave under {area:1640}: go down inside, the arrow cannot tell the floors apart."] = "{npc:5543} se tient dans les {area:2197}, la grotte sous le {area:1640} : descendez par l'intérieur, la flèche ne distingue pas les étages.",
		["{npc:5769}: for {npc:3448} at the Crossroads"] = "{npc:5769} : pour {npc:3448} à la Croisée",
		["{npc:5888} stands in {area:221}. {quest:1519} needs level 4, which you reach with the turn-ins here."] = "{npc:5888} se tient au {area:221}. {quest:1519} requiert le niveau 4, que vous atteignez avec les quêtes rendues ici.",
		["{npc:5888}: {npc:5873} and your {item:5175}"] = "{npc:5888} : {npc:5873} et votre {item:5175}",
		["{npc:5906}, a few steps from {npc:5543} on {area:1640}"] = "{npc:5906}, à quelques pas de {npc:5543} sur {area:1640}",
		["{npc:5907} stands alone on the ridge above the Razormane camp, north-east of the Crossroads on the road to {area:379}."] = "{npc:5907} se tient seul sur la crête au-dessus du camp Tranchecrin, au nord-est de la Croisée sur la route du {area:379}.",
		["{npc:5938} takes it once your {skill:356} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:5938} prend la quête une fois votre compétence {skill:356} à 20 : récoltez ou fabriquez d'ici là, le guide continue en attendant.",
		["{npc:5939} takes it once your {skill:129} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:5939} prend la quête une fois votre compétence {skill:129} à 20 : récoltez ou fabriquez d'ici là, le guide continue en attendant.",
		["{npc:6290} takes it once your {skill:393} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:6290} prend la quête une fois votre compétence {skill:393} à 20 : récoltez ou fabriquez d'ici là, le guide continue en attendant.",
		["{npc:6290}, beside {npc:3067}: {quest:97936}"] = "{npc:6290}, à côté de {npc:3067} : {quest:97936}",
		["{npc:6746}, at the south end of the central rise: the hearth from {quest:5922} brings you back here"] = "{npc:6746}, à l'extrémité sud du piton central : la pierre de foyer après {quest:5922} vous ramène ici",
		["{npc:6746}: {quest:5926}, for {npc:3033} on {area:1639}"] = "{npc:6746} : {quest:5926}, pour {npc:3033} sur {area:1639}",
		["{npc:6775} stands at the west end of the camp, at the north-west corner of the hills where the Mountain Cougars prowl: take his quest, then hunt the cougars south through the hills towards the Seer's tent at their foot."] = "{npc:6775} se tient à l'extrémité ouest du camp, à l'angle nord-ouest des collines où rôdent les Pumas des montagnes : prenez sa quête, puis chassez les pumas vers le sud à travers les collines, jusqu'à la tente du prophète à leur pied.",
		["{npc:8359}, by the wind riders on the central rise"] = "{npc:8359}, près des coursiers du vent sur le piton central",
		["{object:2910}, 170 yd east"] = "{object:2910}, à 170 m à l'est",
		["{zone:1412}: kill these as you meet them"] = "{zone:1412} : tuez-les au passage",
		["{zone:1454}'s {object:172982}"] = "{object:172982} d'{zone:1454}",
} end)()
t.guides["forever/horde/troll/01-durotar"] = (function() return {
		["Armored Scorpids crawl over the plains west of {area:362}. Tame one, then return to {npc:3171}."] = "Les Scorpides blindés rampent dans les plaines à l'ouest de {area:362}. Apprivoisez-en un, puis retournez voir {npc:3171}.",
		["Back east to Sen'jin on the way to the {area:368}."] = "Retournez à l'est à Sen'jin en route vers {area:368}.",
		["Back north-west to {area:362}: {npc:3139} first, then {npc:3147} in the watchtower, then {npc:3142} and {npc:266940} on the way out east to the shore."] = "Retournez au nord-ouest à {area:362} : d'abord {npc:3139}, puis {npc:3147} dans la tour de guet, puis {npc:3142} et {npc:266940} en sortant vers l'est, vers le rivage.",
		["Back over the bridge and south along the {zone:1411} bank of the river to where a narrow trail climbs the mountain: {npc:5900} keeps the shrine at the top. Mind the edges on the way up, and come back down the same trail."] = "Repassez le pont et descendez vers le sud le long de la rive du fleuve côté {zone:1411}, jusqu'à l'endroit où un sentier étroit grimpe la montagne : {npc:5900} garde le sanctuaire au sommet. Attention aux bords en montant, et redescendez par le même sentier.",
		["Back to the Den"] = "Retour à l'Antre",
		["Back to the Den: {npc:3143} takes {quest:804}'s claw and {npc:5887}, just outside, has {quest:1516} now that you are level 4."] = "Retournez à l'Antre : {npc:3143} prend la griffe de {quest:804}, et {npc:5887}, juste dehors, propose {quest:1516} maintenant que vous êtes niveau 4.",
		["Back to {area:362}: {npc:3139}, then {npc:3142}."] = "Retour à {area:362} : {npc:3139}, puis {npc:3142}.",
		["Back to {zone:1411}"] = "Retour en {zone:1411}",
		["Below ground"] = "Sous terre",
		["Burning Blade cultists hold the caves of {quest:827}; any of them drops a {item:4871}. {npc:3204}, a level 14 warlock, stands deep inside and drops the {item:4903}.\nCareful: voidwalkers fight beside the Burning Blade cultists in {quest:827} and {npc:3204} (14) waits at the back with his own: pull one cultist at a time near the entrance for the collars. The {item:4903} is optional: leave {npc:3204} unless you are 13 or have a friend."] = "Les sectateurs de la Lame ardente tiennent les grottes de {quest:827} ; chacun d'eux peut laisser tomber un {item:4871}. {npc:3204}, un démoniste de niveau 14, se tient au fond et laisse tomber l'{item:4903}.\nAttention : des marcheurs du Vide combattent aux côtés des sectateurs de la Lame ardente dans {quest:827} et {npc:3204} (14) attend au fond avec le sien : attirez un sectateur à la fois près de l'entrée pour les colliers. L'objet {item:4903} est facultatif : laissez {npc:3204} tranquille sauf si vous êtes niveau 13 ou accompagné.",
		["Class trainer"] = "Maître de classe",
		["Deathskip to Northern Durotar"] = "Mort volontaire jusqu'au nord de Durotar",
		["Die to the mobs at 52.0,21.4 ({npc:3118}): a death there sends you to this graveyard. Release your spirit and take the {npc:6491}'s resurrection."] = "Laissez-vous tuer par les monstres en 52.0,21.4 ({npc:3118}) : mourir là vous envoie à ce cimetière. Libérez votre esprit et acceptez la résurrection du {npc:6491}.",
		["Druid trainer"] = "Maître des druides",
		["Felstalkers roam the slope below the cave, on the valley's north side."] = "Les Traqueurs corrompus parcourent la pente sous la grotte, du côté nord de la vallée.",
		["Fizzle holds the Burning Blade camp on {area:369}, just north of Misha's hut. Hunters: tame a {npc:3099} with the {item:15908} on the way.\nCareful: Burning Blade cultists surround Fizzle, some linked so they aggro in pairs, and they respawn quickly.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "Fizzle tient le camp de la Lame ardente sur {area:369}, juste au nord de la hutte de Misha. Chasseurs : apprivoisez un {npc:3099} avec {item:15908} en chemin.\nAttention : des sectateurs de la Lame ardente entourent Fizzle, certains liés pour attaquer par paires, et ils réapparaissent vite.\nAttention : Halikor, un élite de niveau 12, rôde sur {area:369} parmi les lézards : repérez-le avant d'attirer quoi que ce soit.",
		["Follow the road east out of the valley to {area:367} on the coast.\nCareful: Ukorsbane (8) is elite and walks among the Ridgeshade spiders in the camp south of {area:362}: pull the spiders away from him."] = "Suivez la route vers l'est hors de la vallée jusqu'au {area:367}, sur la côte.\nAttention : Ukorsbane (8) est un élite et se promène parmi les araignées Ridgeshade du camp au sud de {area:362} : attirez les araignées loin de lui.",
		["Free {npc:275811} and see her safely out of the crag"] = "Libérez {npc:275811} et escortez-la hors de la Combe",
		["Head north-east to the road toward {zone:1454}. {npc:3293} camps beside it; the stolen sacks lie along the road south of him."] = "Allez vers le nord-est jusqu'à la route d'{zone:1454}. {npc:3293} campe à côté ; les sacs volés sont éparpillés le long de la route au sud de lui.",
		["Head south through the isles. The Loa idols lie all over the southern isles; Voodoo and Hexed Trolls hold them and drop the Hexed Pendants. {quest:826} and Minshina's cage are on the southernmost isle.\nCareful: the trolls stand close together and the Voodoo Trolls cast from range: pull one at a time. {quest:826} himself is level 10.\nWade back west to the shore south of Sen'jin when the isles are done."] = "Dirigez-vous vers le sud à travers les îles. Les idoles de Loa sont éparpillées sur toutes les îles du sud ; les Trolls vaudous et les Trolls maléficiés les gardent et lâchent les Pendentifs maléficiés. {quest:826} et la cage de Minshina se trouvent sur l'île la plus au sud.\nAttention : les trolls sont serrés et les Trolls vaudous lancent des sorts à distance : attirez-les un par un. {quest:826} lui-même est niveau 10.\nUne fois les îles terminées, revenez à gué vers l'ouest jusqu'au rivage au sud de Sen'jin.",
		["Heal and fortify {npc:12430}"] = "Soignez et fortifiez {npc:12430}",
		["Inside"] = "À l'intérieur",
		["Inside the cave, go straight on at the first split, then right and follow the stream on your left to the waterfall: the pick glows by the water, behind a column of rock."] = "Dans la grotte, allez tout droit à la première bifurcation, puis à droite, et suivez le ruisseau sur votre gauche jusqu'à la cascade : la pioche brille près de l'eau, derrière une colonne de roche.",
		["Inside the cave, keep to the right wall all the way round, over the stream: {npc:3183} waits at the end."] = "Dans la grotte, longez la paroi de droite tout du long, en passant le ruisseau : {npc:3183} attend au fond.",
		["Level 10"] = "Niveau 10",
		["Level 11"] = "Niveau 11",
		["Level 7"] = "Niveau 7",
		["Level 9"] = "Niveau 9",
		["Makrura and surf crawlers line the beaches north-east of Sen'jin; the Taillasher eggs sit in nests along the beach.\nThe gnomish toolboxes lie in the wreckage along the shore east and south-east of {area:362}. Follow the shore south to Sen'jin."] = "Makruras et clampants de l'écume bordent les plages au nord-est de Sen'jin ; les œufs de Fouette-queue reposent dans des nids le long de la plage.\nLes boîtes à outils gnomes se trouvent dans les épaves le long du rivage, à l'est et au sud-est de {area:362}. Suivez le rivage vers le sud jusqu'à Sen'jin.",
		["Misha's hut stands south of the lizards. The crocolisks along the {area:814} to the west carry {item:4891}."] = "La hutte de Misha se trouve au sud des lézards. Les crocilisques le long de {area:814}, à l'ouest, portent l'{item:4891}.",
		["North-east to the beach below {area:370}, north of {npc:275657}: Spitelash Scouts and Attendants hold it. Hunters: tame a {npc:3107} on the beach."] = "Au nord-est jusqu'à la plage sous {area:370}, au nord de {npc:275657} : les Eclaireurs et les Domestiques fouette-bile la tiennent. Chasseurs : apprivoisez un {npc:3107} sur la plage.",
		["Paladin trainer"] = "Maître des paladins",
		["Quilboars and scouts hold the huts west of town, where the prickly pears grow; dustrunners and battleguards hold the camps farther west."] = "Les Hurans et les Éclaireurs Tranchecrin tiennent les huttes à l'ouest de la ville, là où poussent les figues de Barbarie ; les Lève-poussière et les Gardes de guerre tiennent les camps plus à l'ouest.",
		["Savages and Storm Witches nest in {area:370}, east of {npc:3293}. A Storm Witch drops the {item:277661}. Shamans: the Burning Blade Cultists by {area:371}, at the ravine's south end, drop the {item:6652}."] = "Sauvages et Sorcières des tempêtes Terrevent nichent dans {area:370}, à l'est de {npc:3293}. Une Sorcière des tempêtes lâche {item:277661}. Chamans : les Sectateurs de la Lame ardente près de {area:371}, au bout sud du ravin, lâchent {item:6652}.",
		["Spitelash naga"] = "Nagas Fouette-bile",
		["Tame it with the {item:15908}"] = "Apprivoisez-le avec le {item:15908}",
		["The Scorpid Workers roam the slope south of {npc:3287}; pick the Cactus Apples by the cactuses on the way.\nThe {quest:792} swarm the slope below the {area:365}, the cave on the valley's north side."] = "Les Scorpides ouvriers parcourent la pente au sud de {npc:3287} ; cueillez les Pommes de cactus près des cactus en chemin.\n{quest:792} grouillent sur la pente sous l'{area:365}, la grotte du côté nord de la vallée.",
		["The cattails and speargrass grow along the water in the {object:172958}, east of the Drag."] = "Les massettes et les herbes-lances poussent au bord de l'eau dans {object:172958}, à l'est de la Herse.",
		["The keep stands on the coast south-east of {area:362}. The raiders' axe, bow and shield lie on its outskirts. Sailors and marines drop the {item:4870}."] = "Le donjon se dresse sur la côte au sud-est de {area:362}. La hache, l'arc et le bouclier des pillards traînent aux abords. Les Marins et Soldats de marine de Kul Tiras laissent tomber les {item:4870}.",
		["The weapons lie around the Den and the training grounds; the Mottled Boars roam the whole valley floor."] = "Les armes traînent autour de l'Antre et du terrain d'entraînement ; les Sangliers tachetés parcourent tout le fond de la vallée.",
		["The {object:58595} stands in {area:817}, among the cultists you just fought."] = "La {object:58595} se trouve dans {area:817}, parmi les sectateurs que vous venez de combattre.",
		["Through Sen'jin on the way west to {area:366}: {npc:3304} takes the eyes and mucus now."] = "Passez par Sen'jin en allant vers l'ouest à {area:366} : {npc:3304} prend maintenant les yeux et le mucus.",
		["Thunder Lizards and Lightning Hides graze on {area:369}, beside the road north to {zone:1454}; any of them can drop a {item:6486}. {npc:5810} takes it when the next guide passes {area:379}.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "Les Lézards-tonnerre et les Foudroyants paissent sur {area:369}, à côté de la route du nord vers {zone:1454} ; chacun d'eux peut laisser tomber une {item:6486}. {npc:5810} la prend quand le guide suivant passe par {area:379}.\nAttention : Halikor, un élite de niveau 12, rôde sur {area:369} parmi les lézards : repérez-le avant d'attirer quoi que ce soit.",
		["Thunder Lizards and Lightning Hides graze on {area:369}, just west and south-west of {npc:3293}.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "Lézards-tonnerre et Foudroyants paissent sur {area:369}, juste à l'ouest et au sud-ouest de {npc:3293}.\nAttention : Halikor, un élite de niveau 12, rôde sur {area:369} parmi les lézards : repérez-le avant d'attirer quoi que ce soit.",
		["Thunder lizards on the way north"] = "Lézards-tonnerre sur la route du nord",
		["To {zone:1454}"] = "Vers {zone:1454}",
		["Top up here to level 11 before {npc:3203} (12) and his imp: the Thunder Lizards (9-10) graze on the ridge just west of Misha's hut."] = "Montez ici jusqu'au niveau 11 avant {npc:3203} (12) et son diablotin : les Lézards-tonnerre (9-10) paissent sur la crête juste à l'ouest de la hutte de Misha.",
		["Top up here to level 7 before {npc:3192} (8) and the marines at the top of the keep."] = "Montez ici jusqu'au niveau 7 avant {npc:3192} (8) et les soldats de marine au sommet du donjon.",
		["Top up here to level 9 before the southern isles: the Voodoo and Hexed Trolls there are 8-9 and {quest:826} is 10."] = "Montez ici jusqu'au niveau 9 avant les îles du sud : les Trolls vaudous et Trolls maléficiés y sont niveau 8-9 et {quest:826} est niveau 10.",
		["Training weapons and boars"] = "Armes d'entraînement et sangliers",
		["Underwater"] = "Sous l'eau",
		["Upstairs"] = "À l'étage",
		["Wade across to the northern Echo Isle. The Matriarch prowls among the raptors there; Durotar Tigers roam the isle and the shore south of Sen'jin."] = "Traversez à gué jusqu'à l'île de l'Écho la plus au nord. La Matriarche y rôde parmi les raptors ; des Tigres de Durotar parcourent l'île et le rivage au sud de Sen'jin.",
		["Wake {quest:5441} with the {item:16114}"] = "Réveillez {quest:5441} avec la {item:16114}",
		["West from {area:362} over the {area:814} bridge: {npc:3337} and {npc:5810} stand together at {area:379} above it. From there the road north through {zone:1411} leads to {zone:1454}."] = "Vers l'ouest depuis {area:362}, par le pont de la {area:814} : {npc:3337} et {npc:5810} se tiennent ensemble à {area:379}, au-dessus. De là, la route vers le nord à travers {zone:1411} mène à {zone:1454}.",
		["West over the {area:814} bridge, past {area:379} and on along the ridge: {npc:5907} stands alone above the Razormane camp."] = "Allez vers l'ouest par le pont de {area:814}, passez {area:379} et continuez le long de la crête : {npc:5907} se tient seul au-dessus du camp Tranchecrin.",
		["West over the {area:814} bridge: {npc:3337} stands at {area:379} above it, on your way to {npc:5907}."] = "À l'ouest par le pont de la {area:814} : {npc:3337} se tient au {area:379}, au-dessus, sur votre chemin vers {npc:5907}.",
		["While you're here: learn Staves from {npc:2704} ({object:172958}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Tant que vous y êtes : apprenez les Bâtons auprès de {npc:2704} ({object:172958}, 10 pièces d'argent) ; l'arme de mêlée d'un chasseur compte surtout pour ses caractéristiques, et les armes à deux mains en apportent le plus.",
		["While you're here: learn Staves from {npc:2704} ({object:172958}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "Tant que vous y êtes : apprenez les Bâtons auprès de {npc:2704} ({object:172958}, 10 pièces d'argent) ; un bâton apporte plus de caractéristiques de sorts qu'une arme à une main pendant la montée de niveau.",
		["grind on {npc:3111}"] = "tuez en boucle : {npc:3111}",
		["grind on {npc:3121}"] = "tuez en boucle : {npc:3121}",
		["grind on {npc:3128}"] = "tuez en boucle : {npc:3128}",
		["grind on {npc:3130}"] = "tuez des {npc:3130}",
		["the {object:654925} on the ground beside her"] = "le {object:654925} par terre à côté d'elle",
		["{area:363}: kill these as you meet them"] = "{area:363} : tuez-les au passage",
		["{area:366} lies west of Sen'jin. The three attack plans sit on the ground among the centaur tents. {npc:275811} is held at the crag as well."] = "{area:366} se trouve à l'ouest de Sen'jin. Les trois plans d'attaque sont posés au sol parmi les tentes des centaures. {npc:275811} est aussi retenue à la Combe.",
		["{area:368}: kill these as you meet them"] = "{area:368} : tuez-les au passage",
		["{area:369}: kill these as you meet them"] = "{area:369} : tuez-les au passage",
		["{area:373}: kill these as you meet them"] = "{area:373} : tuez-les au passage",
		["{area:817}'s mouth"] = "Entrée de {area:817}",
		["{npc:10176}, where you start"] = "{npc:10176}, à votre point de départ",
		["{npc:11025} takes it once your {skill:202} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:11025} prend la quête une fois votre compétence {skill:202} à 20 : récoltez ou fabriquez d'ici là, le guide continue en attendant.",
		["{npc:11378} first, just east of the Den as you come down from the cave; then inside the Den ({npc:3143}, your trainer, {npc:3707}), and {npc:3145} and {npc:5887} at the entrance on the way out east to {npc:6786}."] = "D'abord {npc:11378}, juste à l'est de l'Antre en descendant de la grotte ; puis dans l'Antre ({npc:3143}, votre maître, {npc:3707}), et {npc:3145} et {npc:5887} à l'entrée en repartant vers l'est jusqu'à {npc:6786}.",
		["{npc:11378}, at the lumber pile east of the Den"] = "{npc:11378}, près du tas de bois à l'est de l'Antre",
		["{npc:12430} kneels behind the rocks just off the road south of {area:362}, on your way to the keep. Cast {spell:613} (Rank 2) on her, then {spell:1243}: Rank 1 of {spell:613} does not count."] = "{npc:12430} est agenouillée derrière les rochers juste à côté de la route au sud de {area:362}, sur le chemin du donjon. Lancez-lui {spell:613} (rang 2), puis {spell:1243} : le rang 1 de {spell:613} ne compte pas.",
		["{npc:246344} in {zone:1456}; {area:362} has no paladin trainer"] = "{npc:246344} ({zone:1456}) ; {area:362} n'a pas de maître des paladins",
		["{npc:246344} in {zone:1456}; {area:363} has no paladin trainer"] = "{npc:246344} ({zone:1456}) ; {area:363} n'a pas de maître des paladins",
		["{npc:265809} camps just south of {area:362}. Sit by his campfire (/sit) until the {spell:1229451} buff appears. With a profession learned, {npc:265809} also offers its Camping 101, which its trainer takes: in {area:362} or in {zone:1454} at the start of the next guide."] = "{npc:265809} campe juste au sud de {area:362}. Asseyez-vous près de son feu de camp (/sit) jusqu'à ce que l'effet {spell:1229451} apparaisse. Si vous avez appris une profession, {npc:265809} propose aussi sa quête Camping 101, que reçoit le maître de cette profession : à {area:362} ou à {zone:1454} au début du guide suivant.",
		["{npc:265809}'s campfire"] = "Feu de camp de {npc:265809}",
		["{npc:265809}: for Jandi"] = "{npc:265809} : pour Jandi",
		["{npc:265809}: for Jhag"] = "{npc:265809} : pour Jhag",
		["{npc:265809}: for Karolek"] = "{npc:265809} : pour Karolek",
		["{npc:265809}: for Snang"] = "{npc:265809} : pour Snang",
		["{npc:265809}: for Thuwd"] = "{npc:265809} : pour Thuwd",
		["{npc:265809}: for {npc:11025}"] = "{npc:265809} : pour {npc:11025}",
		["{npc:265809}: for {npc:11046}"] = "{npc:265809} : pour {npc:11046}",
		["{npc:265809}: for {npc:3175}"] = "{npc:265809} : pour {npc:3175}",
		["{npc:265809}: for {npc:5943}"] = "{npc:265809} : pour {npc:5943}",
		["{npc:266881}: enchanters only, the residue is disenchanted from Hexed Pendants"] = "{npc:266881} : enchanteurs uniquement, le résidu s'obtient en désenchantant des Pendentifs maléficiés",
		["{npc:266940}, inside"] = "{npc:266940}, à l'intérieur",
		["{npc:266940}, on the east side of town; inside"] = "{npc:266940}, du côté est de la ville ; à l'intérieur",
		["{npc:275657} stands on the shore east of {area:362}. The trident, banner and dagger lie on the beach around him."] = "{npc:275657} se tient sur le rivage à l'est de {area:362}. Le trident, la bannière et la dague traînent sur la plage autour de lui.",
		["{npc:275666}, a young sea giant, walks {zone:1411}'s north coast, north of the naga beach. {npc:275666} is elite: grouping up is advised."] = "{npc:275666}, un jeune géant des mers, arpente la côte nord de {zone:1411}, au nord de la plage des nagas. {npc:275666} est élite : il est conseillé de se grouper.",
		["{npc:3034} in {zone:1412}; {area:362} has no druid trainer"] = "{npc:3034} ({zone:1412}) ; {area:362} n'a pas de maître des druides",
		["{npc:3034} in {zone:1412}; {area:363} has no druid trainer"] = "{npc:3034} ({zone:1412}) ; {area:363} n'a pas de maître des druides",
		["{npc:3102} hooves"] = "Sabots de {npc:3102}",
		["{npc:3142}, back in {area:362}"] = "{npc:3142}, de retour à {area:362}",
		["{npc:3142}: {npc:275666}, an elite sea giant"] = "{npc:3142} : {npc:275666}, un géant des mers élite",
		["{npc:3143} stands just inside the cave mouth; {npc:3159} at the back of the cave behind him."] = "{npc:3143} se tient juste à l'entrée de la grotte ; {npc:3159} au fond de la grotte, derrière lui.",
		["{npc:3143} waits inside the Den, the building just west of {npc:10176}."] = "{npc:3143} attend dans l'Antre, le bâtiment juste à l'ouest de {npc:10176}.",
		["{npc:3143}, inside"] = "{npc:3143}, à l'intérieur",
		["{npc:3147}, in the watchtower"] = "{npc:3147}, dans la tour de guet",
		["{npc:3159}, at the back of the cave; below ground"] = "{npc:3159}, au fond de la grotte ; sous terre",
		["{npc:3171}: {npc:3352} in {zone:1454} teaches {spell:5149}"] = "{npc:3171} : {npc:3352}, à {zone:1454}, enseigne {spell:5149}",
		["{npc:3175} takes it once your {skill:186} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:3175} prend la quête une fois votre compétence {skill:186} à 20 : récoltez ou fabriquez d'ici là, le guide continue en attendant.",
		["{npc:3191}: Camping 101 asks you to learn it"] = "{npc:3191} : la quête Camping 101 vous demande de l'apprendre",
		["{npc:3192} waits at the top of the keep; his key opens the chest beside him, which holds the {item:4881}."] = "{npc:3192} attend au sommet du donjon ; sa clé ouvre le coffre à côté de lui, qui contient la {item:4881}.",
		["{npc:3287} lies wounded at the foot of the hills north-west of the Den."] = "{npc:3287} gît blessé au pied des collines au nord-ouest de l'Antre.",
		["{npc:3706}, beside {npc:266940}: the {item:16606}"] = "{npc:3706}, à côté de {npc:266940} : la {item:16606}",
		["{npc:3706}, for {npc:6018} in {zone:1454}: keep it"] = "{npc:3706}, pour {npc:6018} à {zone:1454} : gardez-la",
		["{npc:3706}, in the barracks beside {npc:266940}"] = "{npc:3706}, dans la caserne à côté de {npc:266940}",
		["{npc:3707}, the priest trainer at the Den"] = "{npc:3707}, le maître des prêtres à l'Antre",
		["{npc:3707}, the priest trainer at the Den: for {npc:3706} in {area:362}"] = "{npc:3707}, le maître des prêtres à l'Antre : pour {npc:3706} à {area:362}",
		["{npc:5875} stands in the {object:172960}, the canyon under the {object:172982}. Hand him the {item:6535}, then use the {item:7464} on the summoning circle beside him and defeat the voidwalker to bind it.\nCareful: the voidwalker you summon hits hard and it is the fight Warlocks die to most in {zone:1454}: start at full health and mana, send your imp in, keep Corruption and Immolate on it, and use a healthstone if you have one."] = "{npc:5875} se tient dans {object:172960}, le canyon sous {object:172982}. Remettez-lui {item:6535}, puis utilisez les {item:7464} sur le cercle d'invocation à côté de lui et vainquez le marcheur du Vide pour le lier.\nAttention : le marcheur du Vide que vous invoquez frappe fort et c'est le combat où les Démonistes meurent le plus à {zone:1454} : commencez avec toute votre vie et tout votre mana, envoyez votre diablotin, maintenez Corruption et Immolation sur lui, et utilisez une pierre de soins si vous en avez une.",
		["{npc:5880}, the mage trainer in Sen'jin"] = "{npc:5880}, le maître des mages de Sen'jin",
		["{npc:5887} stands outside the Den. {area:639} is the hill just south of it: drink the {item:6635} there to see the {npc:5891}, then take the {item:6656} back to {npc:5887}."] = "{npc:5887} se tient devant l'Antre. {area:639} est la colline juste au sud : buvez-y le {item:6635} pour voir la {npc:5891}, puis rapportez le {item:6656} à {npc:5887}.",
		["{npc:5887}: {npc:5873} and your {item:5175}"] = "{npc:5887} : {npc:5873} et votre {item:5175}",
		["{npc:5891}, on {area:639}"] = "{npc:5891}, sur {area:639}",
		["{npc:5943} takes it once your {skill:129} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:5943} prend la quête une fois votre compétence {skill:129} à 20 : récoltez ou fabriquez d'ici là, le guide continue en attendant.",
		["{npc:6786} stands on the road at the valley's eastern exit."] = "{npc:6786} se tient sur la route, à la sortie est de la vallée.",
		["{npc:6928}, inside"] = "{npc:6928}, à l'intérieur",
		["{npc:9796} stands just outside the Den's entrance."] = "{npc:9796} se tient juste devant l'entrée de l'Antre.",
		["{npc:9796}, by the cooking fire"] = "{npc:9796}, près du feu de cuisine",
		["{quest:790}, a large scorpid (level 4), prowls the slope just west of the Den, below {npc:3287}, on the way north to the {area:365}."] = "{quest:790}, un grand scorpide (niveau 4), rôde sur la pente juste à l'ouest de l'Antre, en contrebas de {npc:3287}, sur la route du nord vers {area:365}.",
		["{quest:828} camps on the hill west of the naga beach, south of {quest:827}."] = "{quest:828} campe sur la colline à l'ouest de la plage des nagas, au sud de {quest:827}.",
		["{zone:1454}'s main gate is just west of {area:817}. {npc:5875} stands in the {object:172960}, the canyon under the {object:172982}."] = "La porte principale d'{zone:1454} se trouve juste à l'ouest de {area:817}. {npc:5875} se tient dans {object:172960}, le canyon sous {object:172982}.",
		["{zone:1454}'s {object:172982}"] = "{object:172982} d'{zone:1454}",
} end)()
t.guides["forever/horde/undead/01-tirisfal-glades"] = (function() return {
		["/sit by her campfire until you get {spell:1229451}"] = "/sit près de son feu de camp jusqu'à obtenir {spell:1229451}",
		["Ask {npc:10666} for his report"] = "Demandez son rapport à {npc:10666}",
		["Ask {npc:1496} for his report"] = "Demandez son rapport à {npc:1496}",
		["Ask {npc:251001} for his report"] = "Demandez son rapport à {npc:251001}",
		["Back east along the road to {area:159}. {npc:2128} (mages), {npc:2129} (priests), {npc:2127} (warlocks) and {npc:2130} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "Retournez vers l'est par la route jusqu'à {area:159}. {npc:2128} (mages), {npc:2129} (prêtres), {npc:2127} (démonistes) et {npc:2130} (voleurs) se tiennent à l'étage de l'auberge : prenez l'escalier intérieur, la flèche ne distingue pas les étages.",
		["Back to the church"] = "Retour à l'église",
		["Back to {area:154}"] = "Retour à {area:154}",
		["Back to {zone:1420}"] = "Retour à {zone:1420}",
		["Back up the road and through {area:159} to its west end."] = "Remontez la route et traversez {area:159} jusqu'à son extrémité ouest.",
		["Back up the road to {area:159}. {npc:2128} (mages), {npc:2129} (priests), {npc:2127} (warlocks) and {npc:2130} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "Remontez la route jusqu'à {area:159}. {npc:2128} (mages), {npc:2129} (prêtres), {npc:2127} (démonistes) et {npc:2130} (voleurs) se tiennent à l'étage de l'auberge : prenez l'escalier intérieur, la flèche ne distingue pas les étages.",
		["Back up to the forest's edge south of the keep's gate: {npc:246389} and {npc:259190} take the bones and the crystal."] = "Remontez jusqu'à la lisière de la forêt au sud de la porte du donjon : {npc:246389} et {npc:259190} prennent les os et le cristal.",
		["Beat {npc:6784} in the duel"] = "Battez {npc:6784} en duel",
		["Below ground"] = "Sous terre",
		["Crusader's Outpost"] = "Avant-poste des Croisés",
		["Dry Branches"] = "Dry Branches",
		["Eleanor camps just south-west of town. With a profession learned, she also offers its Camping 101, which its trainer takes: in {area:159}, at Linnea's camp, or in the {zone:1458} in the next guide."] = "Eleanor campe juste au sud-ouest du village. Si vous avez appris un métier, elle propose aussi sa quête Camping 101 correspondante, que son maître prend en charge : à {area:159}, au camp de Linnea, ou à {zone:1458} dans le guide suivant.",
		["Eleanor: for {npc:2114}"] = "Eleanor : pour {npc:2114}",
		["Eleanor: for {npc:2132}"] = "Eleanor : pour {npc:2132}",
		["Eleanor: for {npc:3523}"] = "Eleanor : pour {npc:3523}",
		["Eleanor: for {npc:3549}"] = "Eleanor : pour {npc:3549}",
		["Eleanor: for {npc:4586}"] = "Eleanor : pour {npc:4586}",
		["Eleanor: for {npc:4598}"] = "Eleanor : pour {npc:4598}",
		["Eleanor: for {npc:4605}"] = "Eleanor : pour {npc:4605}",
		["Eleanor: for {npc:5695}"] = "Eleanor : pour {npc:5695}",
		["Eleanor: for {npc:5759}"] = "Eleanor : pour {npc:5759}",
		["Eleanor: for {npc:6289}"] = "Eleanor : pour {npc:6289}",
		["Escort {npc:275954} out of the outpost"] = "Escortez {npc:275954} hors de l'avant-poste",
		["Everything here is inside the inn, through its door on the south side: {npc:5688} at the bar, {npc:265944} at the north end of the ground floor, the {npc:1931} in the cellar under that end, and {npc:2128} (mages), {npc:2129} (priests), {npc:2127} (warlocks) and {npc:2130} (rogues) upstairs: take the stairs inside, the arrow cannot tell the floors apart."] = "Tout se trouve dans l'auberge, par sa porte du côté sud : {npc:5688} au comptoir, {npc:265944} au bout nord du rez-de-chaussée, le {npc:1931} dans la cave sous ce bout, et {npc:2128} (mages), {npc:2129} (prêtres), {npc:2127} (démonistes) et {npc:2130} (voleurs) à l'étage : prenez l'escalier intérieur, la flèche ne distingue pas les étages.",
		["Follow the path north into {area:154}; Sarvis stands in front of the church."] = "Suivez le chemin vers le nord jusqu'à {area:154} ; Sarvis se tient devant l'église.",
		["Follow the road east past the cult's farm. Bleeding Horrors and Wandering Spirits haunt the graves on the east side of the farmstead, where the {quest:99142} grows: Linnea wants eight of each.\nThe Scarlet Friars camp just north-east of the graves; {npc:1664} stands among them.\nThe spiders lurk in the woods at the far east end of the glades.\nCareful: Riptear (13) is elite and prowls west and north of the Scarlet Friars' camp: watch for him before you pull."] = "Suivez la route vers l'est au-delà de la ferme du culte. Les Horreurs sanguinolentes et les Esprits vagabonds hantent les tombes à l'est de la ferme, là où poussent {quest:99142} : Linnea en veut huit de chaque.\nLes Frères écarlates campent juste au nord-est des tombes ; {npc:1664} se tient parmi eux.\nLes araignées rôdent dans les bois à l'extrémité est des clairières.\nAttention : Riptear (13) est élite et rôde à l'ouest et au nord du camp des Frères écarlates : repérez-le avant d'attirer.",
		["Follow the road north-west to {area:157}. {npc:1657} walks the graveyard south of the mills; Nissa, Gregor and {npc:1656} haunt the mills themselves. Rattlecage and Cracked Skull Soldiers drop the ribs, Darkeye Bonecasters the skulls, and any of them may drop {item:2839}.\nCareful: Rotting undead and Darkeye Bonecasters near the Agamands can join a fight as adds."] = "Suivez la route au nord-ouest jusqu'à {area:157}. {npc:1657} arpente le cimetière au sud des moulins ; Nissa, Gregor et {npc:1656} hantent les moulins eux-mêmes. Les Soldats Cliquethorax et les Soldats Squelettes lâchent les côtes, les Ossomanciens Sombroeil les crânes, et chacun d'eux peut lâcher {item:2839}.\nAttention : les morts-vivants pourrissants et les Ossomanciens Sombroeil près des Agamand peuvent se joindre au combat.",
		["Follow the road south-east from {area:159} past the zeppelin towers."] = "Suivez la route vers le sud-est depuis {area:159}, au-delà des tours des zeppelins.",
		["Follow the road south-east from {area:159} past the zeppelin towers. Linnea, Kristof and {npc:3549} camp by the road."] = "Suivez la route au sud-est de {area:159} au-delà des tours des zeppelins. Linnea, Kristof et {npc:3549} campent au bord de la route.",
		["Follow the road south-west from {area:159} to the Scarlet Crusade camp. {npc:1662} stands at its south end; every Scarlet there can drop a ring."] = "Suivez la route au sud-ouest de {area:159} jusqu'au camp de la Croisade écarlate. {npc:1662} se tient à son extrémité sud ; chaque membre de la Croisade écarlate peut y lâcher un anneau.",
		["Free the {npc:271961}"] = "Libérez les {npc:271961}",
		["From level 10 {npc:1738} offers {quest:96895}: {npc:267009} waits at Linnea's camp, the next stop. Below 10 it waits for the {area:159} visit after {area:157}."] = "À partir du niveau 10, {npc:1738} propose {quest:96895} : {npc:267009} attend au camp de Linnea, la prochaine étape. En dessous de 10, elle attend la visite de {area:159} après {area:157}.",
		["From level 7 {npc:2132}, beside Johaan in the apothecary's house, offers her elixir quest; below 7 it waits for the next {area:159} visit."] = "À partir du niveau 7, {npc:2132}, à côté de Johaan dans la maison de l'apothicaire, propose sa quête d'élixir ; en dessous de 7, elle attend la prochaine visite de {area:159}.",
		["Head west to the cave. The Young Night Web Spiders sit outside; the Night Web Spiders and the cocooned {npc:271961} are inside.\nCareful: A low-level character can die quickly if it pulls several Night Web Spiders in the cave at the same time."] = "Allez vers l'ouest jusqu'à la grotte. Les Jeunes Tisse-nuit se tiennent dehors ; les Araignées Tisse-nuit et les {npc:271961} dans leurs cocons sont à l'intérieur.\nAttention : un personnage de bas niveau peut mourir vite s'il attire plusieurs Araignées Tisse-nuit à la fois dans la grotte.",
		["Heal and fortify {npc:12428}"] = "Soignez et fortifiez {npc:12428}",
		["Holland walks around the north side of {area:159}, a few steps from Dillinger."] = "Holland se promène du côté nord de {area:159}, à quelques pas de Dillinger.",
		["Inside"] = "À l'intérieur",
		["Leave {area:154} by the road north-east. {npc:6784} stands by the farmhouse at the {area:156}; {npc:1519} stands by the road just past it."] = "Quittez {area:154} par la route du nord-est. {npc:6784} se tient près de la ferme : {area:156} ; {npc:1519} se tient au bord de la route juste après.",
		["Level 6"] = "Niveau 6",
		["Listen to Leonid and {npc:246378}, then talk to him again"] = "Écoutez Leonid et {npc:246378}, puis reparlez-lui",
		["Mindless Zombies"] = "Zombies lunatiques",
		["Offer aid to the {npc:246143}"] = "Proposez votre aide : {npc:246143}",
		["On the way back west, the Cult of the Damned holds the farm just south-east of {npc:1495}'s camp. The Necrotic Crystal Fragments lie on the ground among the cultists, and the cultists carry some too.\nCareful: the cultists (10-12) stand close together and the Neophytes cast: pull one at a time from the edge of the farm."] = "En revenant vers l'ouest, le Culte des damnés tient la ferme juste au sud-est du camp de {npc:1495}. Les Fragments de cristal nécrotique sont au sol parmi les cultistes, et les cultistes en portent aussi.\nAttention : les cultistes (10-12) sont proches les uns des autres et les Néophytes lancent des sorts : attirez-les un par un depuis le bord de la ferme.",
		["Only if the letter dropped"] = "Seulement si vous avez obtenu la lettre",
		["Paladin: {quest:91285}"] = "Paladin : {quest:91285}",
		["Paladin: {quest:96899}"] = "Paladin : {quest:96899}",
		["Rattlecage Skeletons wander the ruined houses in the north half of {area:154}. Young Scavengers and Duskbats roam all around the village; the Ragged Scavengers and Mangy Duskbats are on its east side. {npc:1661} wants their paws and wings: kill them as you meet them while you clear the skeletons."] = "Les Squelettes Cliquethorax errent dans les maisons en ruine de la moitié nord de {area:154}. Les Jeunes charognards et les Chauves-souris du crépuscule rôdent tout autour du village ; les Charognards pouilleux et les Chauves-souris du crépuscule galeuses sont du côté est. {npc:1661} veut leurs pattes et leurs ailes : tuez-les au passage en nettoyant les squelettes.",
		["Scarlet Warriors guard the outpost north-west of the pumpkin fields. {npc:275954} is held inside: talk to him and stay with him until he is out.\nCareful: Scarlet Warriors are level 6-7 and not elite. Once their health falls to 15% they run off to bring help, so more of them may join the fight."] = "Des Guerriers écarlates gardent l'avant-poste au nord-ouest des champs de potirons. {npc:275954} est retenu à l'intérieur : parlez-lui et restez avec lui jusqu'à ce qu'il soit sorti.\nAttention : les Guerriers écarlates sont de niveau 6-7 et pas élites. Quand leur vie tombe à 15 %, ils s'enfuient chercher de l'aide, d'autres peuvent donc rejoindre le combat.",
		["Still in the inn: from level 7 {npc:1500} on the ground floor and {npc:1521} upstairs offer their quests; below 7 they wait for the next {area:159} visit."] = "Toujours dans l'auberge : à partir du niveau 7, {npc:1500} au rez-de-chaussée et {npc:1521} à l'étage proposent leurs quêtes ; en dessous de 7, ils attendent la prochaine visite de {area:159}.",
		["The Dry Branches lie on the ground around the south-west edge of {area:159}."] = "Les Dry Branches sont au sol autour de la lisière sud-ouest de {area:159}.",
		["The Scarlet Converts and Initiates hold the farm east of {area:154}. {npc:1919} wanders between the farmhouses: his remains are for {quest:6395}."] = "Les Convertis écarlates et les Initiés écarlates tiennent la ferme à l'est de {area:154}. {npc:1919} erre entre les bâtiments : sa dépouille sert pour {quest:6395}.",
		["The Scarlet camp"] = "Le camp écarlate",
		["The Scarlet farm"] = "La ferme écarlate",
		["The Vile Fin murlocs lurk on the bluffs just east of the keep and in the camps around the lake to the south-west, on the way down to {area:16881}."] = "Les murlocs Aileron noir rôdent sur les falaises juste à l'est du donjon et dans les camps autour du lac au sud-ouest, en descendant vers {area:16881}.",
		["The Wanted poster beside Zygand"] = "L'avis de recherche à côté de Zygand",
		["The next guide walks south from {area:159} into {zone:1421}."] = "Le guide suivant part vers le sud depuis {area:159} jusque dans la {zone:1421}.",
		["The pumpkins grow in the Scarlet-held fields just north-west of the farmhouse.\nCareful: Farmers stand close to the pumpkins, so you can pull more than one at once. Scarlet mobs are found around the edges of the farm and a bit to the northwest. {npc:1936} (8, rare) walks the field."] = "Les potirons poussent dans les champs tenus par les Écarlates, juste au nord-ouest de la ferme.\nAttention : des Fermiers se tiennent près des potirons, vous pouvez donc en attirer plusieurs à la fois. Des Écarlates se trouvent autour de la ferme et un peu au nord-ouest. {npc:1936} (8, rare) arpente le champ.",
		["The zombies shamble around the graveyard and the houses just east of the church."] = "Les zombies errent autour du cimetière et des maisons juste à l'est de l'église.",
		["The {area:154} trainers stand around the church"] = "Les maîtres de {area:154} se tiennent autour de l'église",
		["The {area:159} trainers are in the inn ({npc:2131} downstairs, the rest upstairs); {npc:246152}, the Paladin trainer, by the square"] = "Les maîtres de {area:159} sont dans l'auberge ({npc:2131} en bas, les autres à l'étage) ; {npc:246152}, la maîtresse des paladins, près de la place",
		["The {npc:1931}, in the inn's cellar"] = "{npc:1931}, dans la cave de l'auberge",
		["The {npc:2211}, in the inn's cellar"] = "Le {npc:2211}, dans la cave de l'auberge",
		["The {npc:246143}"] = "{npc:246143}",
		["The {object:164662} lie beside the ruined houses in the north of {area:154}."] = "Les {object:164662} se trouvent à côté des maisons en ruine au nord de {area:154}.",
		["Tirisfal Pumpkins"] = "Potirons de Tirisfal",
		["Top up here to level 6 before the pumpkins: the Tirisfal Farmers and Scarlet Warriors in the fields are 6-7. The Decrepit Darkhounds (5-6) roam the hills just east of the farm."] = "Montez ici jusqu'au niveau 6 avant les citrouilles : les Fermiers de Tirisfal et les Guerriers écarlates dans les champs sont 6-7. Les Sombredogues décrépits (5-6) rôdent dans les collines juste à l'est de la ferme.",
		["Use the {item:286176} on five idle Deathguards around town"] = "Utilisez {item:286176} sur cinq gardes noirs oisifs dans le village",
		["Vile Fin Attackers"] = "Attaquants aileron noir",
		["Vile Fin Seers"] = "Oracles aileron noir",
		["Walk south from {area:159} to the {area:153} and down into the {area:1497}. {npc:4568} stands in the {object:36082}. The Scarlet camp is just west of the ruins."] = "Marchez vers le sud depuis {area:159} jusqu'aux {area:153} et descendez à {area:1497}. {npc:4568} se tient dans le {object:36082}. Le camp écarlate est juste à l'ouest des ruines.",
		["Walk south from {area:159} to the {area:153} and down into the {area:1497}. {npc:5675} stands in the {object:36082}. The Scarlet camp is just west of the ruins."] = "Marchez vers le sud depuis {area:159} jusqu'aux {area:153} et descendez à {area:1497}. {npc:5675} se tient dans le {object:36082}. Le camp écarlate est juste à l'ouest des ruines.",
		["You rise in the crypt at the south end of {area:154}. {npc:1568} waits just outside."] = "Vous vous relevez dans la crypte au sud de {area:154}. {npc:1568} attend juste devant.",
		["attack the cocoons inside the cave to free them; below ground"] = "attaquez les cocons dans la grotte pour les libérer ; sous terre",
		["grind on {npc:1547}"] = "tuez des {npc:1547}",
		["the Shadowvale Lurchers and Mystics drop the bones; below ground"] = "les Titubeurs et les Mystiques d'Ombreval lâchent les os ; sous terre",
		["the basement under the ruined house"] = "la cave sous la maison en ruine",
		["the {item:286269}, at the basement's south end"] = "{item:286269}, à l'extrémité sud de la cave",
		["{area:154}: kill these as you meet them"] = "{area:154} : tuez-les au passage",
		["{area:165}: kill these as you meet them"] = "{area:165} : tuez-les au passage",
		["{area:166}: kill these as you meet them"] = "{area:166} : tuez-les au passage",
		["{area:16881} is the hollow at the west edge of the glades, south-west of the {area:16616}. Go down into the big basement under the ruined house (only a floor and a few pillars left, not the two-storey house): the bottles lie on its floor among the Shadowvale Lurchers and Mystics."] = "{area:16881} est le creux à la lisière ouest des clairières, au sud-ouest de {area:16616}. Descendez dans la grande cave sous la maison en ruine (il n'en reste qu'un plancher et quelques piliers, pas la maison à deux étages) : les flacons sont au sol parmi les Titubeurs et les Mystiques d'Ombreval.",
		["{item:16333}, from {npc:1919}"] = "{item:16333}, sur {npc:1919}",
		["{item:2320} from {npc:2118}, for Gretchen"] = "{item:2320} auprès de {npc:2118}, pour Gretchen",
		["{item:2839}, a rare drop"] = "{item:2839}, butin rare",
		["{item:3635}; inside"] = "{item:3635} ; à l'intérieur",
		["{item:7227}, in the farmstead's garden"] = "{item:7227}, dans le jardin de la ferme",
		["{npc:10665} walks around {area:159}: look inside the circle on the map"] = "{npc:10665} se promène autour de {area:159} : cherchez dans le cercle sur la carte",
		["{npc:10666} walks the long road west of {area:159}, past {area:166}, and back: the arrow follows his road west until you meet him."] = "{npc:10666} parcourt la longue route à l'ouest de {area:159}, au-delà de {area:166}, puis revient : la flèche suit sa route vers l'ouest jusqu'à ce que vous le croisiez.",
		["{npc:10666}, the big abomination, walks the road from here east past {area:166} almost to {area:159}, and back: if he isn't at the arrow, follow the road east until you meet him. The {item:12737} grows along the road around him."] = "{npc:10666}, la grosse abomination, parcourt la route d'ici vers l'est au-delà de {area:166}, presque jusqu'à {area:159}, puis revient : s'il n'est pas à la flèche, suivez la route vers l'est jusqu'à le croiser. {item:12737} pousse le long de la route autour de lui.",
		["{npc:12428} kneels by the north gate of {area:159}'s graveyard, on your way north. Cast {spell:613} (Rank 2) on him, then {spell:1243}: Fortitude first does not count."] = "{npc:12428} est agenouillé près de la porte nord du cimetière de {area:159}, sur votre chemin vers le nord. Lancez-lui {spell:613} (rang 2), puis {spell:1243} : la Robustesse en premier ne compte pas.",
		["{npc:1495}'s camp"] = "Camp de {npc:1495}",
		["{npc:1496} and {npc:1742} stand at the west end of {area:159}, where the road from Solliden comes in."] = "{npc:1496} et {npc:1742} se tiennent à l'extrémité ouest de {area:159}, là où arrive la route de Solliden.",
		["{npc:1499}, in the town hall"] = "{npc:1499}, dans l'hôtel de ville",
		["{npc:1499}, inside"] = "{npc:1499}, à l'intérieur",
		["{npc:1500} and {npc:1521}"] = "{npc:1500} et {npc:1521}",
		["{npc:1500}, in the inn"] = "{npc:1500}, dans l'auberge",
		["{npc:1515}, in front of the inn"] = "{npc:1515}, devant l'auberge",
		["{npc:1518} is in the apothecary's house on the west side of the square, {npc:1515} in front of the inn with the Wanted poster beside him, {npc:1499} in the town hall on the square's north side. The inn comes last, in one go."] = "{npc:1518} est dans la maison de l'apothicaire, du côté ouest de la place, {npc:1515} devant l'auberge avec l'avis de recherche à côté de lui, {npc:1499} dans l'hôtel de ville, du côté nord de la place. L'auberge vient en dernier, en une seule fois.",
		["{npc:1518}, inside"] = "{npc:1518}, à l'intérieur",
		["{npc:1518}: for Renferrel at the {area:228}"] = "{npc:1518} : pour Renferrel au {area:228}",
		["{npc:1521}, upstairs"] = "{npc:1521}, à l'étage",
		["{npc:1525} and Ravaged Corpses shamble through the fields just west of {area:159}; Decrepit Darkhounds roam there and on west along the road toward {npc:10666}. Johaan wants their blood, {npc:3549} their hides."] = "Des {npc:1525} et des Cadavres ravagés errent dans les champs juste à l'ouest de {area:159} ; des Sombredogues décrépits rôdent là et plus à l'ouest le long de la route, vers {npc:10666}. Johaan veut leur sang, {npc:3549} leurs peaux.",
		["{npc:1537} walks around here: look inside the circle on the map"] = "{npc:1537} se promène par ici : cherchez dans le cercle sur la carte",
		["{npc:1560}, in the inn"] = "{npc:1560}, dans l'auberge",
		["{npc:1569}, inside"] = "{npc:1569}, à l'intérieur",
		["{npc:1569}: the scroll for {npc:244808}"] = "{npc:1569} : le parchemin pour {npc:244808}",
		["{npc:1570}, in the church"] = "{npc:1570}, dans l'église",
		["{npc:1655}; upstairs"] = "{npc:1655} ; à l'étage",
		["{npc:1661}, beside the church; inside"] = "{npc:1661}, à côté de l'église ; à l'intérieur",
		["{npc:1661}, inside"] = "{npc:1661}, à l'intérieur",
		["{npc:1667} stands at the south end of the Scarlet farm.\nCareful: He is flanked by two Scarlet guards, one a convert and the other an initiate, who may join the fight."] = "{npc:1667} se tient à l'extrémité sud de la ferme écarlate.\nAttention : il est flanqué de deux gardes écarlates, un converti et un initié, qui peuvent rejoindre le combat.",
		["{npc:1675} walks around {area:164}: look inside the circle on the map"] = "{npc:1675} se promène autour de {area:164} : cherchez dans le cercle sur la carte",
		["{npc:1738}, if you were below 10 on the last {area:159} visit"] = "{npc:1738}, si vous étiez en dessous du niveau 10 lors de la dernière visite de {area:159}",
		["{npc:1742}, beside Dillinger"] = "{npc:1742}, à côté de Dillinger",
		["{npc:2114} takes it once your {skill:182} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:2114} prend la quête une fois votre compétence {skill:182} à 20 : récoltez ou fabriquez d'ici là, le guide continue en attendant.",
		["{npc:2114}, beside Johaan: {quest:97957}"] = "{npc:2114}, à côté de Johaan : {quest:97957}",
		["{npc:2119}, the warrior trainer; inside"] = "{npc:2119}, le maître des guerriers ; à l'intérieur",
		["{npc:2122}, the rogue trainer"] = "{npc:2122}, maître des voleurs",
		["{npc:2123}, the priest trainer in the church"] = "{npc:2123}, maître des prêtres, dans l'église",
		["{npc:2123}, the priest trainer in the church, sends you to {npc:2129} in {area:159}. Train {spell:613} (Rank 2) from him now: the wounded guard Beryl sends you to needs it."] = "{npc:2123}, maître des prêtres dans l'église, vous envoie voir {npc:2129} à {area:159}. Apprenez dès maintenant {spell:613} (rang 2) auprès de lui : le garde blessé vers qui Beryl vous envoie en a besoin.",
		["{npc:2123}: for {npc:2129} in {area:159}"] = "{npc:2123} : pour {npc:2129} à {area:159}",
		["{npc:2124}, the mage trainer, in the church"] = "{npc:2124}, maître des mages, dans l'église",
		["{npc:2126}, the warlock trainer"] = "{npc:2126}, maître des démonistes",
		["{npc:2128} (mages), {npc:2129} (priests), {npc:2127} (warlocks) and {npc:2130} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "{npc:2128} (mages), {npc:2129} (prêtres), {npc:2127} (démonistes) et {npc:2130} (voleurs) se tiennent à l'étage de l'auberge : prenez l'escalier intérieur, la flèche ne distingue pas les étages.",
		["{npc:2128}: {npc:4568} in the {zone:1458} takes it"] = "{npc:2128} : {npc:4568}, à {zone:1458}, s'en charge",
		["{npc:2129}, upstairs"] = "{npc:2129}, à l'étage",
		["{npc:2129}, upstairs: the {item:16607}"] = "{npc:2129}, à l'étage : {item:16607}",
		["{npc:2132} takes it once your {skill:171} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:2132} prend la quête une fois votre compétence {skill:171} à 20 : récoltez ou fabriquez d'ici là, le guide continue en attendant.",
		["{npc:2132}, beside Johaan: {quest:97951}"] = "{npc:2132}, à côté de Johaan : {quest:97951}",
		["{npc:2132}, beside Johaan; inside"] = "{npc:2132}, à côté de Johaan ; à l'intérieur",
