		["Small Thorium: {zone:1448} (245-275)"] = "Petit filon de thorium : {zone:1448} (245-275)",
		["Tin"] = "Étain",
		["Tin, Copper"] = "Étain, Cuivre",
		["Tin: {zone:1424} (65-125)"] = "Étain : {zone:1424} (65-125)",
